// Message deduplication cache - stores message IDs for 24 hours
const processedMessages = new Map<string, number>();

// Middleware to capture raw request body for webhook signature verification
function captureRawBody(req: any, res: any, next: any) {
  let data = '';
  req.setEncoding('utf8');
  req.on('data', (chunk: string) => {
    data += chunk;
  });
  req.on('end', () => {
    req.rawBody = data;
    next();
  });

}

// Raw body capture middleware for specific webhook endpoints
const rawBodyCapture = express.raw({ type: '*/*', limit: '10mb' });

// Clean up old processed messages every hour
setInterval(() => {
  const oneDayAgo = Date.now() - (24 * 60 * 60 * 1000);
  for (const [messageId, timestamp] of Array.from(processedMessages.entries())) {
    if (timestamp < oneDayAgo) {
      processedMessages.delete(messageId);
    }
  }
}, 60 * 60 * 1000);

// Check if a message has already been processed
function isMessageAlreadyProcessed(messageId: string): boolean {
  return processedMessages.has(messageId);
}

// Mark a message as processed (only call after successful verification and persistence)
function markMessageAsProcessed(messageId: string): void {
  processedMessages.set(messageId, Date.now());
}

// Extract deterministic provider message ID
function getProviderMessageId(body: any, channel: 'email' | 'sms'): string | null {
  if (channel === 'email') {
    // SendGrid provides Message-ID in headers object
    const headers = body.headers || {};
    return headers['Message-ID'] || headers['Message-Id'] || 
           body['Message-Id'] || body.msg_id || body.message_id || body.messageId || null;
  } else if (channel === 'sms') {
    // Twilio provides MessageSid
    return body.MessageSid || body.SmsSid || null;
  }
  return null;
}

// Generate deterministic message ID for email based on content
function generateDeterministicEmailId(emailData: any): string {
  const crypto = require('crypto');
  const from = emailData.from || '';
  const subject = emailData.subject || '';
  // CRITICAL FIX (Dec 9, 2025): Use STABLE content for hash, NOT new Date()
  // SendGrid may retry the same email multiple times - we need consistent hash
  // Priority: 1) SendGrid Message-ID, 2) Email body text content, 3) First 500 chars of raw
  const stableContent = emailData.messageId || 
                        emailData['Message-ID'] ||
                        emailData.text?.substring(0, 500) || 
                        emailData.rawText?.substring(0, 500) ||
                        emailData.html?.substring(0, 500) ||
                        '';
  
  // Create hash from from+subject+content for consistent ID across retries
  const hash = crypto.createHash('sha256')
    .update(`${from}|${subject}|${stableContent}`)
    .digest('hex')
    .substring(0, 32);
  
  return `email_${hash}`;
}

// Generate deterministic message ID for SMS based on content
function generateDeterministicSMSId(smsData: any): string {
  const crypto = require('crypto');
  const from = smsData.From || '';
  const body = smsData.Body || '';
  // CRITICAL FIX (Dec 9, 2025): Use Twilio MessageSid for stable ID, NOT new Date()
  // Twilio may retry the same SMS multiple times - we need consistent hash
  const stableId = smsData.MessageSid || smsData.SmsSid || '';
  
  // Create hash from from+body+sid for consistent ID across retries
  const hash = crypto.createHash('sha256')
    .update(`${from}|${body}|${stableId}`)
    .digest('hex')
    .substring(0, 32);
  
  return `sms_${hash}`;
}

// Helper functions for market analysis
function getMarketCycleDescription(cycle: string): string {
  const descriptions = {
    'Recovery': 'Market is recovering from a downturn, with increasing demand and stabilizing prices. Good entry point for value investments.',
    'Expansion': 'Market is growing with strong demand and rising rents. Prime time for development and acquisition.',
    'Peak': 'Market is at its highest point with maximum rents but may face oversupply. Consider selling or holding.',
    'Contraction': 'Market is declining with decreasing demand and falling rents. Exercise caution and focus on value plays.'
  };
  return descriptions[cycle as keyof typeof descriptions] || 'Market cycle assessment unavailable';
}

function getTimingReasoning(marketData: any): string {
  const factors = [];
  
  if (marketData.economicIndicators.jobGrowth > 2) {
    factors.push('strong job growth supports rental demand');
  }
  if (marketData.demographicProfile.populationGrowth > 1) {
    factors.push('population growth indicates market expansion');
  }
  if (marketData.supplyDemandAnalysis.rentGrowth > 3) {
    factors.push('rent growth above inflation suggests strong fundamentals');
  }
  if (marketData.supplyDemandAnalysis.vacancyRate < 5) {
    factors.push('low vacancy rates indicate tight supply');
  }
  
  return factors.length > 0 ? factors.join(', ') : 'market conditions are mixed';
}

// Enhanced AI Analysis with OpenAI
async function performAIAnalysis(deal: any) {
  try {
    const openaiService = new OpenAIService();
    const analysis = await openaiService.analyzeProperty(deal);
    
    // Map OpenAI classification to internal status
    const statusMapping: Record<string, "high_priority" | "potentially" | "clear_no"> = {
      'green': 'high_priority',
      'yellow': 'potentially', 
      'red': 'clear_no'
    };
    
    const status = statusMapping[analysis.classification] || 'potentially';
    
    return {
      analysis: {
        zoning: {
          status: analysis.classification === 'green' ? 'good' : analysis.classification === 'yellow' ? 'fair' : 'poor',
          value: deal.zoning || 'Unknown'
        },
        sewer: {
          status: deal.sewerAvailable === true ? 'good' : deal.sewerAvailable === false ? 'poor' : 'fair',
          value: deal.sewerAvailable === true ? 'Available' : deal.sewerAvailable === false ? 'Not Available' : 'Unknown'
        },
        size: {
          status: parseFloat(deal.sizeAcres) >= 2 ? 'good' : parseFloat(deal.sizeAcres) >= 1 ? 'fair' : 'poor',
          value: `${deal.sizeAcres} acres`
        },
        comparables: {
          status: 'fair',
          value: deal.topRentPSF ? `$${deal.topRentPSF}/SF` : 'Researching...'
        },
        aiInsights: {
          confidence: analysis.confidence,
          reasoning: analysis.reasoning,
          marketPotential: analysis.marketPotential,
          riskFactors: analysis.riskFactors,
          opportunities: analysis.opportunities,
          estimatedValue: analysis.estimatedValue,
          developmentTimeframe: analysis.developmentTimeframe
        }
      },
      classification: analysis.classification,
      status
    };
  } catch (error) {
    // AI analysis failed, falling back to rule-based analysis
    
    // Fallback to original logic if AI fails
    const analysis = {
      zoning: {
        status: deal.zoning === "R-4" ? "good" : deal.zoning === "R-2" ? "fair" : "poor",
        value: deal.zoning || "Unknown",
      },
      sewer: {
        status: deal.sewerAvailable === true ? "good" : deal.sewerAvailable === false ? "poor" : "fair",
        value: deal.sewerAvailable === true ? "Available" : deal.sewerAvailable === false ? "Not Available" : "Unknown",
      },
      size: {
        status: parseFloat(deal.sizeAcres) >= 2 ? "good" : parseFloat(deal.sizeAcres) >= 1 ? "fair" : "poor",
        value: `${deal.sizeAcres} acres`,
      },
      comparables: {
        status: "fair",
        value: deal.topRentPSF ? `$${deal.topRentPSF}/SF` : "Researching...",
      },
    };

    const goodCount = Object.values(analysis).filter(item => item.status === "good").length;
    const poorCount = Object.values(analysis).filter(item => item.status === "poor").length;

    let classification: "red" | "yellow" | "green";
    let status: "clear_no" | "potentially" | "high_priority";

    if (poorCount >= 2) {
      classification = "red";
      status = "clear_no";
    } else if (goodCount >= 3) {
      classification = "green";
      status = "high_priority";
    } else {
      classification = "yellow";
      status = "potentially";
    }

    return { analysis, classification, status };
  }
}

