// Enhanced deal parsing with multi-property, complex descriptions, and PDF support
async function parseDealFromText(text: string, source: "sms" | "email" = "sms", attachments: any[] = []) {
  const extractedInfo: any = {
    submissionMethod: source,
    rawText: text,
    attachmentData: [],
    multipleProperties: []
  };

  // CRITICAL FIX: Use deterministic address parser for BOTH SMS and EMAIL
  // This ensures city/state/ZIP are extracted before any other processing
  try {
    console.log(`📍 [ADDRESS-PARSER] Calling deterministic address parser for ${source}...`);
    const { parseOrFallback } = await import('./smsAddressParser');
    const parsedAddress = await parseOrFallback(text);
    
    // Merge parser results into extractedInfo if successful
    if (parsedAddress && parsedAddress.street && parsedAddress.city && parsedAddress.state) {
      console.log('✅ [ADDRESS-PARSER] Deterministic parser returned:', {
        street: parsedAddress.street,
        city: parsedAddress.city,
        state: parsedAddress.state,
        zip: parsedAddress.zip
      });
      
      // Map parsed fields to extractedInfo (using both naming conventions for compatibility)
      extractedInfo.address = parsedAddress.street;
      extractedInfo.city = parsedAddress.city;
      extractedInfo.state = parsedAddress.state;
      extractedInfo.zip = parsedAddress.zip;
      extractedInfo.zipCode = parsedAddress.zip; // Also set zipCode for backward compatibility
      
      console.log('📋 [ADDRESS-PARSER] Merged into extractedInfo:', {
        address: extractedInfo.address,
        city: extractedInfo.city,
        state: extractedInfo.state,
        zip: extractedInfo.zip
      });
    } else {
      console.log('⚠️ [ADDRESS-PARSER] Deterministic parser did not find complete address - will use fallback AI parsing');
    }
  } catch (error) {
    console.error('❌ [ADDRESS-PARSER] Failed to call address parser:', error);
    // Continue with fallback parsing if address parser fails
  }

  // STEP 1: Process PDF attachments if available
  let combinedText = text;
  if (attachments && attachments.length > 0) {
    console.log(`🔍 Processing ${attachments.length} attachments for data extraction...`);
    
    for (const attachment of attachments) {
      if (attachment.contentType?.includes('pdf') || attachment.filename?.toLowerCase().endsWith('.pdf')) {
        try {
          console.log(`📄 Extracting text from PDF: ${attachment.filename}`);
          
          // Convert base64 content to buffer if needed
          let buffer: Buffer;
          if (typeof attachment.content === 'string') {
            buffer = Buffer.from(attachment.content, 'base64');
          } else if (Buffer.isBuffer(attachment.content)) {
            buffer = attachment.content;
          } else {
            console.log('⚠️ Unsupported PDF content format, skipping');
            continue;
          }

          // Dynamically import pdf-parse to avoid startup issues
          const pdfParse = (await import('pdf-parse')).default;
          
          // Parse PDF and extract text
          const pdfData = await pdfParse(buffer);
          const pdfText = pdfData.text?.trim();
          
          if (pdfText && pdfText.length > 10) {
            console.log(`✅ Extracted ${pdfText.length} characters from PDF: ${attachment.filename}`);
            combinedText += `\n\nPDF CONTENT FROM ${attachment.filename}:\n${pdfText}`;
            extractedInfo.attachmentData.push({
              filename: attachment.filename,
              type: 'pdf',
              content: pdfText,
              length: pdfText.length
            });
          }
        } catch (error) {
          console.error(`❌ Failed to parse PDF ${attachment.filename}:`, error);
        }
      }
    }
  }

  // STEP 2: Detect multiple properties in the text
  const multiPropertyIndicators = [
    /property\s+#?\d+/gi,
    /listing\s+#?\d+/gi,
    /deal\s+#?\d+/gi,
    /option\s+#?\d+/gi,
    /\d+\)\s*[^\n]*(?:address|property|location|site)/gi,
    /site\s+[a-z]:|property\s+[a-z]:/gi
  ];
  
  let hasMultipleProperties = false;
  for (const indicator of multiPropertyIndicators) {
    const matches = combinedText.match(indicator);
    if (matches && matches.length > 1) {
      hasMultipleProperties = true;
      console.log(`🏘️ Detected multiple properties: ${matches.length} matches for pattern`);
      break;
    }
  }

  // STEP 3: Handle forwarded emails - detect and clean
  const forwardPatterns = [
    /(?:forwarded\s+message|forwarded\s+from|original\s+message)/i,
    /from:\s*([^<\n]+(?:<[^>]+>)?)/gi,
    /sent:\s*[^\n]+/gi,
    /to:\s*[^\n]+/gi,
    /subject:\s*[^\n]+/gi,
    /---+\s*forwarded\s+message\s*---+/gi,
    /begin\s+forwarded\s+message/gi
  ];
  
  let isForwardedEmail = false;
  let originalSenderInfo = null;
  
  for (const pattern of forwardPatterns) {
    if (pattern.test(combinedText)) {
      isForwardedEmail = true;
      if (pattern.source.includes('from:')) {
        const pattern = /from:\s*([^<\n]+(?:<[^>]+>)?)/gi;
        const matches = [];
        let match;
        while ((match = pattern.exec(combinedText)) !== null) {
          matches.push(match);
        }
        if (matches.length > 0) {
          originalSenderInfo = matches[matches.length - 1][1].trim(); // Get the last/most recent sender
        }
      }
      break;
    }
  }
  
  if (isForwardedEmail) {
    console.log('📧 Detected forwarded email format');
    if (originalSenderInfo) {
      console.log(`👤 Original sender identified: ${originalSenderInfo}`);
      extractedInfo.originalSender = originalSenderInfo;
    }
  }

  // State name to abbreviation mapping
  function normalizeStateName(text: string): string {
    const stateMap: Record<string, string> = {
      'alabama': 'AL', 'alaska': 'AK', 'arizona': 'AZ', 'arkansas': 'AR', 'california': 'CA',
      'colorado': 'CO', 'connecticut': 'CT', 'delaware': 'DE', 'florida': 'FL', 'georgia': 'GA',
      'hawaii': 'HI', 'idaho': 'ID', 'illinois': 'IL', 'indiana': 'IN', 'iowa': 'IA',
      'kansas': 'KS', 'kentucky': 'KY', 'louisiana': 'LA', 'maine': 'ME', 'maryland': 'MD',
      'massachusetts': 'MA', 'michigan': 'MI', 'minnesota': 'MN', 'mississippi': 'MS', 'missouri': 'MO',
      'montana': 'MT', 'nebraska': 'NE', 'nevada': 'NV', 'new hampshire': 'NH', 'new jersey': 'NJ',
      'new mexico': 'NM', 'new york': 'NY', 'north carolina': 'NC', 'north dakota': 'ND', 'ohio': 'OH',
      'oklahoma': 'OK', 'oregon': 'OR', 'pennsylvania': 'PA', 'rhode island': 'RI', 'south carolina': 'SC',
      'south dakota': 'SD', 'tennessee': 'TN', 'texas': 'TX', 'utah': 'UT', 'vermont': 'VT',
      'virginia': 'VA', 'washington': 'WA', 'west virginia': 'WV', 'wisconsin': 'WI', 'wyoming': 'WY'
    };
    
    let normalized = text;
    for (const [fullName, abbr] of Object.entries(stateMap)) {
      // Replace full state names (case insensitive, word boundary)
      const regex = new RegExp(`\\b${fullName}\\b`, 'gi');
      normalized = normalized.replace(regex, abbr);
    }
    return normalized;
  }

  // STEP 4: Enhanced address extraction with multiple patterns and formats
  function extractAddress(text: string): { value: string | null, confidence: number } {
    console.log(`🔍 [ADDRESS-DEBUG] Input text for extraction (first 200 chars): "${text.substring(0, 200)}"`);
    console.log(`🔍 [ADDRESS-DEBUG] Full text length: ${text.length}`);
    
    // CRITICAL FIX: Remove email signatures and footers BEFORE address extraction
    // This prevents office addresses from being picked up instead of property addresses
    let cleanedText = text;
    
    // Common signature indicators - remove everything after these
    const signatureIndicators = [
      /(?:best\s+regards|sincerely|thanks|thank\s+you|regards|cheers|warmly|respectfully)/i,
      /(?:^|\n)[-_]{3,}/,  // Signature separator lines (---, ___)
      /(?:^|\n)sent\s+from\s+my\s+(?:iphone|ipad|android)/i,
      /(?:^|\n)get\s+outlook\s+for/i,
      // Contact block patterns - name, title, company, phone number sequences
      /(?:^|\n)([A-Z][a-z]+\s+[A-Z][a-z]+)\s*\n\s*(?:Managing Director|Director|Vice President|President|Broker|Agent|Senior)/i,
      // Northmarq office signature
      /(?:^|\n)(?:Northmarq|northmarq)\s*\n/i
    ];
    
    for (const indicator of signatureIndicators) {
      const match = cleanedText.match(indicator);
      if (match && match.index !== undefined) {
        console.log(`✂️ [ADDRESS-FIX] Removing signature after: "${match[0]}"`);
        cleanedText = cleanedText.substring(0, match.index);
      }
    }
    
    const patterns = [
      // Explicit address labels  - captures everything after label including commas
      /(?:address|location|property):?\s*(.+?)(?=\n\n|\n[A-Z][a-z]+:|$)/i,
      
      // Full address with city, state, ZIP with commas: "200 W 28th St, Charlotte, NC 28206"
      /(\d+\s+[a-zA-Z0-9\s]+(?:st|street|ave|avenue|rd|road|dr|drive|ln|lane|way|blvd|boulevard|ct|court|pl|place|pkwy|parkway|cir|circle),?\s+[a-zA-Z\s]+,?\s+[A-Z]{2}\s*,?\s*\d{5}(?:-\d{4})?)/i,
      
      // Full address with city, state (no ZIP): "200 W 28th St, Charlotte, NC"
      /(\d+\s+[a-zA-Z0-9\s]+(?:st|street|ave|avenue|rd|road|dr|drive|ln|lane|way|blvd|boulevard|ct|court|pl|place|pkwy|parkway|cir|circle),?\s+[a-zA-Z\s]+,?\s+[A-Z]{2})/i,
      
      // Street only with optional city/state/ZIP: "200 W 28th St" or "200 W 28th St Charlotte NC 28206"
      /(\d+\s+[a-zA-Z0-9\s]+(?:st|street|ave|avenue|rd|road|dr|drive|ln|lane|way|blvd|boulevard|ct|court|pl|place|pkwy|parkway|cir|circle)(?:,?\s+[a-zA-Z\s]+)?(?:,?\s+[A-Z]{2})?(?:,?\s*\d{5}(?:-\d{4})?)?)/i,
      
      // Simple format without explicit street type - but NOT if preceded by $ or comma (to avoid matching dollar amounts)
      /(?<![,$])\b(\d{1,5})\s+([a-zA-Z][a-zA-Z\s]{2,}[a-zA-Z])\b/
    ];

    for (let i = 0; i < patterns.length; i++) {
      const match = cleanedText.match(patterns[i]);
      if (match) {
        console.log(`✅ [ADDRESS-DEBUG] Pattern ${i} matched! Full match: "${match[0]}"`);
        let address: string;
        
        // For the simple format pattern (index 4, last pattern), combine capture groups and validate
        if (i === 4) {
          const streetNumber = match[1];
          const streetName = match[2];
          address = `${streetNumber} ${streetName}`.trim();
          
          // Reject if the street name is just common words like "and", "or", "for"
          const commonWords = /^(and|or|for|the|with|plus|total|asking)$/i;
          if (commonWords.test(streetName.trim())) {
            continue; // Skip this match, try next pattern
          }
          
          // Reject if street number is too large (likely part of a dollar amount)
          if (parseInt(streetNumber) > 99999) {
            continue;
          }
        } else {
          address = match[i === 0 ? 1 : 0].trim();
        }
        
        // CRITICAL FIX: Check if city/state/ZIP are on separate lines and combine them
        if (address && !address.match(/,\s*[A-Z]{2}\s*\d{5}/) && !address.match(/,\s*[a-zA-Z\s]+,?\s*[A-Z]{2}/)) {
          // Address doesn't have city/state/zip, look for them on nearby lines
          const lines = cleanedText.split('\n').map(l => l.trim()).filter(l => l.length > 0);
          const addressIndex = lines.findIndex(l => l.includes(address));
          
          if (addressIndex >= 0 && addressIndex < lines.length - 1) {
            let cityStateZip = '';
            
            // Check next 1-2 lines for city, state, ZIP
            for (let j = addressIndex + 1; j < Math.min(addressIndex + 3, lines.length); j++) {
              const nextLine = lines[j];
              
              // STRICT VALIDATION: Only accept lines that look like city/state/ZIP
              // Must have: (City Name, ST ZIP) or (City Name ST) or (ST ZIP) patterns
              const cityStateZipPattern = /^([a-zA-Z\s]+,?\s+)?([A-Z]{2})(\s+\d{5}(-\d{4})?)?$/;
              const validCityState = nextLine.match(cityStateZipPattern);
              
              if (validCityState) {
                if (cityStateZip) {
                  cityStateZip += ' ' + nextLine;
                } else {
                  cityStateZip = nextLine;
                }
              } else {
                // Not a valid city/state/ZIP line - stop looking
                console.log(`⚠️ [ADDRESS-MULTILINE] Skipping invalid line: "${nextLine}"`);
                break;
              }
            }
            
            if (cityStateZip) {
              // Clean up and combine
              cityStateZip = cityStateZip.replace(/\s+/g, ' ').trim();
              // Normalize state names in city/state/zip component
              cityStateZip = normalizeStateName(cityStateZip);
              address = `${address}, ${cityStateZip}`;
              console.log(`🔧 [ADDRESS-FIX] Combined multi-line address: ${address}`);
            }
          }
        }
        
        // VALIDATION: Ensure address has minimum viable components
        // Must have at least a street number (1-5 digits) at the start
        if (!address.match(/^\d{1,5}\s+/)) {
          console.log(`❌ [ADDRESS-VALIDATION] Rejected - no valid street number: "${address}"`);
          continue; // Try next pattern
        }
        
        // CLEANUP: Remove any trailing incomplete text (single letters, fragments)
        address = address.replace(/,?\s+[A-Z](?:\s+[A-Z])?$/i, '').trim();
        
        // VALIDATION: Reject if address is too short or looks corrupted
        if (address.length < 10 || address.match(/^[^a-zA-Z]*$/)) {
          console.log(`❌ [ADDRESS-VALIDATION] Rejected - too short or corrupted: "${address}"`);
          continue;
        }
        
        // NORMALIZE: Convert full state names to abbreviations (Tennessee → TN)
        const normalizedAddress = normalizeStateName(address);
        if (normalizedAddress !== address) {
          console.log(`📝 [ADDRESS-NORMALIZE] Converted state name: "${address}" → "${normalizedAddress}"`);
          address = normalizedAddress;
        }
        
        // Confidence scores based on completeness:
        // 0: Label-based (0.95) - explicit label
        // 1: Full with state+ZIP (0.95) - complete address
        // 2: State only (0.85) - partial address
        // 3: Street only (0.75) - minimal address
        // 4: Simple format (0.70) - fallback
        const confidence = i === 0 ? 0.95 : i === 1 ? 0.95 : i === 2 ? 0.85 : i === 3 ? 0.75 : 0.70;
        console.log(`📍 [ADDRESS-DEBUG] Final extracted address: "${address}" (confidence: ${confidence})`);
        return { value: address, confidence };
      }
    }

    // Fallback: if short text without price/acreage, assume it's an address
    if (cleanedText.length < 100 && !cleanedText.includes('$') && !/(acre|ac)\b/i.test(cleanedText)) {
      return { value: cleanedText.trim(), confidence: 0.60 };
    }

    return { value: null, confidence: 0 };
  }

  // Enhanced acreage extraction with multiple formats
  function extractAcreage(text: string): { value: number | null, confidence: number } {
    const patterns = [
      // Various acre formats: 10 ac, 10 acres, ±10, 10.5 acres, ~10 ac
      /([±~]?\s*\d+(?:\.\d+)?)\s*(?:acre|acres|ac)\b/i,
      /([±~]?\s*\d+(?:\.\d+)?)\s*ac\b/i,
      /([±~]?\s*\d+(?:\.\d+)?)\s*acres?\b/i,
      // Format like "5.5-acre" or "10-acre"
      /([±~]?\s*\d+(?:\.\d+)?)-acres?/i,
      // Size indicators
      /size:?\s*([±~]?\s*\d+(?:\.\d+)?)\s*(?:acre|ac|acres)/i
    ];

    for (let i = 0; i < patterns.length; i++) {
      const match = text.match(patterns[i]);
      if (match) {
        const acreageStr = match[1].replace(/[±~\s]/g, '');
        const acreage = parseFloat(acreageStr);
        if (!isNaN(acreage) && acreage > 0) {
          const confidence = i === 0 ? 0.90 : i === 4 ? 0.95 : 0.85;
          return { value: acreage, confidence };
        }
      }
    }

    return { value: null, confidence: 0 };
  }

  // Enhanced price extraction with multiple formats
  function extractPrice(text: string): { 
    value: number | null, 
    pricingType: 'total' | 'per_acre' | null, 
    confidence: number 
  } {
    const patterns = [
      // Enhanced per acre pricing: $250k/ac, $2.5M/acre, $500K/acre, $2.5mm/ac, $1.2mil/acre
      /\$(\d+(?:,\d{3})*(?:\.\d+)?)\s*([kmb]?|mm|mil|million)\s*\/\s*(acre|ac)\b/i,
      // Per acre variants: per ac, per acre, /ac, /acre
      /\$(\d+(?:,\d{3})*(?:\.\d+)?)\s*([kmb]?|mm|mil|million)\s*(?:\/|per)\s*(acre|ac)\b/i,
      // Millimeter format per acre: 2.5mm/ac, 1.2mil/acre
      /(\d+(?:\.\d+)?)\s*(mm|mil|million)\s*\/\s*(acre|ac)\b/i,
      
      // Large amounts: $2.5M, 2.5mm, $2,500,000
      /\$(\d+(?:,\d{3})*(?:\.\d+)?)\s*([kmb])(?!\/)/i,
      /(\d+(?:\.\d+)?)\s*(mm|mil|million)\b(?!\/)/i,
      
      // Standard dollar amounts: $2,500,000, $250,000
      /\$(\d{1,3}(?:,\d{3})+)/,
      /\$(\d+(?:\.\d+)?)/,
      
      // Price labels
      /(?:price|asking|value):?\s*\$(\d+(?:,\d{3})*(?:\.\d+)?)\s*([kmb]?)/i
    ];

    for (let i = 0; i < patterns.length; i++) {
      const match = text.match(patterns[i]);
      if (match) {
        let price: number;
        let pricingType: 'total' | 'per_acre' | null = null;
        let confidence: number;

        if (i === 0 || i === 1 || i === 2) {
          // Per acre pricing (all variants)
          const baseAmount = parseFloat(match[1].replace(/,/g, ''));
          const multiplier = match[2] ? getMultiplier(match[2].toLowerCase()) : 1;
          price = baseAmount * multiplier;
          pricingType = 'per_acre';
          confidence = 0.95;
        } else if (i === 3) {
          // Large amounts with multipliers (total price)
          const baseAmount = parseFloat(match[1].replace(/,/g, ''));
          const multiplier = getMultiplier(match[2].toLowerCase());
          price = baseAmount * multiplier;
          pricingType = 'total';
          confidence = 0.90;
        } else if (i === 4) {
          // Million format
          const baseAmount = parseFloat(match[1]);
          price = baseAmount * 1000000;
          pricingType = 'total';
          confidence = 0.90;
        } else {
          // Standard dollar amounts
          price = parseFloat(match[1].replace(/,/g, ''));
          pricingType = 'total';
          confidence = i === 5 ? 0.85 : i === 6 ? 0.80 : 0.85;
        }

        if (!isNaN(price) && price > 0) {
          return { value: price, pricingType, confidence };
        }
      }
    }

    return { value: null, pricingType: null, confidence: 0 };
  }

  function getMultiplier(unit: string): number {
    const multipliers: Record<string, number> = {
      'k': 1000,
      'm': 1000000,
      'mm': 1000000,
      'mil': 1000000,
      'million': 1000000,
      'b': 1000000000
    };
    return multipliers[unit] || 1;
  }

  // Split multiple properties from a single text submission
  function splitMultipleProperties(text: string): string[] {
    console.log('🔍 Attempting to split multiple properties...');
    
    // Try different splitting strategies
    const splittingStrategies = [
      // Strategy 1: Numbered properties (1. Property A, 2. Property B)
      {
        name: 'numbered',
        pattern: /(?:^|\n)\s*(\d+[\.\)]\s*[^\n]*(?:\n(?!\s*\d+[\.\)]).)*)/gm,
        test: (text: string) => (text.match(/^\s*\d+[\.\)]/gm) || []).length > 1
      },
      
      // Strategy 2: Lettered properties (A. Property A, B. Property B)  
      {
        name: 'lettered',
        pattern: /(?:^|\n)\s*([A-Z][\.\)]\s*[^\n]*(?:\n(?!\s*[A-Z][\.\)]).)*)/gm,
        test: (text: string) => (text.match(/^\s*[A-Z][\.\)]/gm) || []).length > 1
      },
      
      // Strategy 3: Property/Site labels
      {
        name: 'labeled',
        pattern: /(?:property\s*[#\d]*[:\-]|site\s*[a-z\d]*[:\-]|location\s*[#\d]*[:\-])(.*?)(?=(?:property\s*[#\d]*[:\-]|site\s*[a-z\d]*[:\-]|location\s*[#\d]*[:\-])|$)/gi,
        test: (text: string) => (text.match(/(?:property|site|location)\s*[#\d]*[:\-]/gi) || []).length > 1
      },
      
      // Strategy 4: Address-based splitting (multiple street addresses) - FIXED: Include digits in street name
      {
        name: 'addresses',
        pattern: /(\d+\s+[a-zA-Z0-9\s]+(?:st|street|ave|avenue|rd|road|dr|drive|ln|lane|way|blvd|boulevard|ct|court|pl|place).*?)(?=\d+\s+[a-zA-Z0-9\s]+(?:st|street|ave|avenue|rd|road|dr|drive|ln|lane|way|blvd|boulevard|ct|court|pl|place)|$)/gi,
        test: (text: string) => (text.match(/\d+\s+[a-zA-Z0-9\s]+(?:st|street|ave|avenue|rd|road|dr|drive|ln|lane|way|blvd|boulevard|ct|court|pl|place)/gi) || []).length > 1
      },
      
      // Strategy 5: Deal/Option separators
      {
        name: 'deals',
        pattern: /(?:deal\s*[#\d]*[:\-]|option\s*[#\d]*[:\-])(.*?)(?=(?:deal\s*[#\d]*[:\-]|option\s*[#\d]*[:\-])|$)/gi,
        test: (text: string) => (text.match(/(?:deal|option)\s*[#\d]*[:\-]/gi) || []).length > 1
      }
    ];
    
    // Try each strategy until we find one that works
    for (const strategy of splittingStrategies) {
      if (strategy.test(text)) {
        console.log(`📋 Using ${strategy.name} splitting strategy`);
        const matches = [];
        const pattern = strategy.pattern;
        let match;
        while ((match = pattern.exec(text)) !== null) {
          matches.push(match);
        }
        
        if (matches.length > 1) {
          const segments = matches.map((match, index) => {
            let segment = match[1] || match[0];
            
            // Clean up the segment
            segment = segment.trim();
            
            // Add context prefix for better parsing
            if (strategy.name === 'numbered' || strategy.name === 'lettered') {
              // Keep the numbering for context
              segment = match[0].trim();
            }
            
            return segment;
          }).filter(segment => segment.length > 20); // Filter out very short segments
          
          if (segments.length > 1) {
            console.log(`✅ Split into ${segments.length} property segments using ${strategy.name} strategy`);
            return segments;
          }
        }
      }
    }
    
    // Fallback: Try paragraph splitting if other methods fail
    const paragraphs = text.split(/\n\s*\n/).filter(p => p.trim().length > 50);
    if (paragraphs.length > 1) {
      // Check if each paragraph has property-like content - FIXED: Include digits in street name
      const propertyParagraphs = paragraphs.filter(p => 
        /\d+\s+[a-zA-Z0-9\s]+(?:st|street|ave|avenue|rd|road)/i.test(p) ||
        /\$\d+/i.test(p) ||
        /\d+(?:\.\d+)?\s*(?:acre|ac)/i.test(p)
      );
      
      if (propertyParagraphs.length > 1) {
        console.log(`📄 Using paragraph-based splitting: ${propertyParagraphs.length} property paragraphs`);
        return propertyParagraphs;
      }
    }
    
    console.log('❌ Could not reliably split into multiple properties');
    return [text]; // Return original text as single property
  }

  // Enhanced property description parsing for complex details
  function extractComplexPropertyDetails(text: string): any {
    const details: any = {};
    
    // Unit mix extraction (e.g., "24 units (12 1BR, 12 2BR)", "Mixed: 50% 1BR, 50% 2BR")
    const unitMixPatterns = [
      /(\d+)\s*units?.*?(?:\(([^)]+)\)|:([^.\n]+))/i,
      /(?:unit\s*mix|units?):?\s*([^.\n]+)/i,
      /(\d+)\s*(?:1br|2br|3br|studio)/gi,
      /mixed:?\s*([^.\n]+)/i
    ];
    
    for (const pattern of unitMixPatterns) {
      const match = text.match(pattern);
      if (match) {
        details.unitMix = match[1] || match[2] || match[3];
        console.log(`🏠 Found unit mix: ${details.unitMix}`);
        break;
      }
    }
    
    // Development details (e.g., "Phase 1 of 3", "Future development potential")
    const developmentPatterns = [
      /phase\s+(\d+)\s+of\s+(\d+)/i,
      /development\s+potential:?\s*([^.\n]+)/i,
      /future\s+(?:development|build|construction):?\s*([^.\n]+)/i,
      /(?:expansion|additional|more)\s+(?:units?|development):?\s*([^.\n]+)/i
    ];
    
    for (const pattern of developmentPatterns) {
      const match = text.match(pattern);
      if (match) {
        details.developmentInfo = match[0];
        console.log(`🏗️ Found development info: ${details.developmentInfo}`);
        break;
      }
    }
    
    // Financial projections (e.g., "NOI $150K", "Cap rate 6.5%", "Revenue $200K/year")
    const financialPatterns = [
      /(?:noi|net\s+operating\s+income):?\s*\$?([0-9,]+(?:[km])?)/i,
      /(?:cap\s+rate|capitalization):?\s*([0-9.]+)%?/i,
      /(?:revenue|income|gross):?\s*\$?([0-9,]+(?:[km])?)\s*(?:\/year|annually|per\s+year)?/i,
      /(?:rent\s+roll|rental\s+income):?\s*\$?([0-9,]+(?:[km])?)/i
    ];
    
    financialPatterns.forEach((pattern, index) => {
      const match = text.match(pattern);
      if (match) {
        const types = ['noi', 'capRate', 'revenue', 'rentRoll'];
        details[types[index]] = match[1];
        console.log(`💰 Found ${types[index]}: ${match[1]}`);
      }
    });
    
    // Property condition and features
    const conditionPatterns = [
      /(?:condition|state):?\s*(excellent|good|fair|poor|needs?\s+work|renovation\s+needed)/i,
      /(?:amenities|features):?\s*([^.\n]+)/i,
      /(?:parking|garage):?\s*(\d+)\s*(?:spaces?|spots?|cars?)/i,
      /(?:square\s*feet|sq\s*ft|sqft):?\s*([0-9,]+)/i
    ];
    
    conditionPatterns.forEach((pattern, index) => {
      const match = text.match(pattern);
      if (match) {
        const types = ['condition', 'amenities', 'parking', 'squareFootage'];
        details[types[index]] = match[1];
        console.log(`🏡 Found ${types[index]}: ${match[1]}`);
      }
    });
    
    return Object.keys(details).length > 0 ? details : null;
  }

  // STEP 5: If multiple properties detected, attempt to split them
  // CRITICAL FIX: Only run legacy email parser for email submissions
  // SMS submissions use the new hybrid parser which correctly splits address components
  if (hasMultipleProperties && source === 'email') {
    console.log('🏘️ Processing multiple properties from single submission...');
    
    const propertySegments = splitMultipleProperties(combinedText);
    if (propertySegments.length > 1) {
      console.log(`✅ Successfully split into ${propertySegments.length} properties`);
      
      extractedInfo.multipleProperties = [];
      for (let i = 0; i < propertySegments.length; i++) {
        const segment = propertySegments[i];
        console.log(`🏠 Processing property ${i + 1}: ${segment.substring(0, 100)}...`);
        
        const addressResult = extractAddress(segment);
        const acreageResult = extractAcreage(segment);
        const priceResult = extractPrice(segment);
        
        const propertyData = {
          index: i + 1,
          segment: segment,
          address: addressResult.value,
          acres: acreageResult.value,
          price: priceResult.value,
          pricingType: priceResult.pricingType,
          addressConfidence: addressResult.confidence,
          acreageConfidence: acreageResult.confidence,
          priceConfidence: priceResult.confidence
        };
        
        extractedInfo.multipleProperties.push(propertyData);
      }
      
      // Return the multi-property data for separate deal creation
      extractedInfo.isMultiProperty = true;
      extractedInfo.primaryProperty = extractedInfo.multipleProperties[0];
      return extractedInfo;
    }
  }

  // STEP 6: Single property processing - extract data using enhanced patterns
  // CRITICAL FIX: Always run extraction for diagnostics, but only APPLY results for email
  // or when SMS-parsed fields are empty (preserves SMS hybrid parser authority)
  const addressResult = extractAddress(combinedText);
  const acreageResult = extractAcreage(combinedText);
  const priceResult = extractPrice(combinedText);

  // STEP 7: Extract complex property details (unit mixes, development plans, financials)
  const complexDetails = extractComplexPropertyDetails(combinedText);
  if (complexDetails) {
    console.log(`🏗️ Extracted complex property details: ${Object.keys(complexDetails).join(', ')}`);
    extractedInfo.complexDetails = complexDetails;
  }

  // Extract additional data (existing logic + enhanced patterns)
  const zoningMatch = combinedText.match(/(?:zoning|zoned):?\s*(R-?[0-9]+|[A-Z]+-?[0-9]+)/i);
  const sewerMatch = combinedText.match(/sewer|utilities/i);
  
  // Enhanced contact extraction from forwarded emails or complex descriptions
  if (!extractedInfo.originalSender) {
    const contactPatterns = [
      /(?:contact|call|email):?\s*([a-zA-Z\s]+)\s*(?:at\s*)?([^<\s]+@[^<\s]+|[\d\(\)-\.\s]{10,})/i,
      /(?:from|broker|agent):?\s*([a-zA-Z\s]+)\s*-?\s*([^<\s]+@[^<\s]+|[\d\(\)-\.\s]{10,})/i,
      /([a-zA-Z\s]{2,30})\s*<([^<>]+@[^<>]+)>/,
      /([a-zA-Z\s]{2,30})\s*([^<\s]+@[^<\s]+)/
    ];
    
    for (const pattern of contactPatterns) {
      const match = combinedText.match(pattern);
      if (match && match[1] && match[2]) {
        extractedInfo.brokerName = match[1].trim();
        extractedInfo.brokerContact = match[2].trim();
        console.log(`👤 Found contact info: ${extractedInfo.brokerName} - ${extractedInfo.brokerContact}`);
        break;
      }
    }
  }

  // Store raw extraction data for all sources (preserves diagnostics/logging)
  extractedInfo.addressExtraction = addressResult;
  extractedInfo.acreageExtraction = acreageResult;
  extractedInfo.priceExtraction = priceResult;

  // Calculate total price if per-acre pricing and acreage available
  let finalPrice = priceResult.value;
  let finalPricingType = priceResult.pricingType;
  
  if (priceResult.value && priceResult.pricingType === 'per_acre' && acreageResult.value) {
    finalPrice = priceResult.value * acreageResult.value;
    finalPricingType = 'total';
    extractedInfo.calculatedTotal = {
      perAcrePrice: priceResult.value,
      acreage: acreageResult.value,
      totalPrice: finalPrice
    };
  }

  // Determine confidence level based on finalized result data (called after enrichment)
  function calculateConfidenceFromFinalData(finalResult: any): 'high' | 'medium' | 'low' {
    const scores = [];
    
    // Address confidence
    if (finalResult.address) {
      if (finalResult.enrichmentMetadata?.sources?.some((s: string) => s.includes('HelloData'))) {
        scores.push(0.95); // Boost confidence for verified data providers
      } else {
        scores.push(addressResult.confidence || 0.80);
      }
    }
    
    // Acreage confidence
    if (finalResult.userSizeAcres) {
      if (finalResult.enrichmentMetadata?.sources?.some((s: string) => s.includes('HelloData'))) {
        scores.push(0.95); // Boost confidence for verified data providers
      } else {
        scores.push(acreageResult.confidence || 0.80);
      }
    }
    
    // Price confidence
    if (finalResult.userAskingPrice) {
      if (finalResult.enrichmentMetadata?.sources?.some((s: string) => s.includes('HelloData'))) {
        scores.push(0.95); // Boost confidence for verified data providers
      } else {
        scores.push(priceResult.confidence || 0.80);
      }
    }

    if (scores.length === 0) return 'low';
    
    const avgConfidence = scores.reduce((sum, score) => sum + score, 0) / scores.length;
    const dataCompleteness = scores.length / 3; // 3 key fields
    const overallScore = (avgConfidence * 0.7) + (dataCompleteness * 0.3);

    if (overallScore >= 0.8 && scores.length >= 2) return 'high';
    if (overallScore >= 0.6 || scores.length >= 2) return 'medium';
    return 'low';
  }

  // Identify missing fields from finalized result data (called after enrichment)
  function getMissingFieldsFromFinalData(finalResult: any): string[] {
    const missing: string[] = [];
    if (!finalResult.address) missing.push('address');
    if (!finalResult.sizeAcres) missing.push('acreage');
    if (!finalResult.askingPrice) missing.push('price');
    return missing;
  }

  // Build enhanced return object - confidence and missing fields will be calculated after enrichment
  // CRITICAL FIX: Only apply legacy extraction results when:
  // (1) Source is 'email', OR (2) SMS didn't provide the field
  // This preserves SMS hybrid parser authority while providing email fallback coverage
  const result = {
    address: (source === 'email' || !extractedInfo.address) ? addressResult.value : extractedInfo.address,
    sizeAcres: (source === 'email' || !extractedInfo.sizeAcres) ? acreageResult.value : extractedInfo.sizeAcres,
    askingPrice: (source === 'email' || !extractedInfo.askingPrice) ? finalPrice : extractedInfo.askingPrice,
    pricingType: finalPricingType,
    confidence: 'low' as 'high' | 'medium' | 'low', // Will be recalculated after enrichment
    missingFields: [] as string[], // Will be recalculated after enrichment
    extractedInfo: {
      rawText: text,
      submissionMethod: source,
      addressConfidence: addressResult.confidence,
      acreageConfidence: acreageResult.confidence,
      priceConfidence: priceResult.confidence,
      originalPrice: priceResult.value,
      originalPricingType: priceResult.pricingType,
      zoning: zoningMatch ? zoningMatch[1] : null,
      sewerAvailable: sewerMatch ? true : null, // Only set to true if explicitly mentioned, otherwise null
      brokerNotes: text.substring(0, 500)
    }
  };

  // Legacy support - add to extractedInfo for backward compatibility
  // CRITICAL FIX: Only update if we used the legacy extraction (email source or field was empty)
  if (source === 'email' || !extractedInfo.address) {
    extractedInfo.address = result.address;
  }
  if (source === 'email' || !extractedInfo.sizeAcres) {
    extractedInfo.sizeAcres = result.sizeAcres;
  }
  if (source === 'email' || !extractedInfo.askingPrice) {
    extractedInfo.askingPrice = result.askingPrice;
  }
  extractedInfo.zoning = result.extractedInfo.zoning;
  extractedInfo.sewerAvailable = result.extractedInfo.sewerAvailable;
  extractedInfo.brokerNotes = result.extractedInfo.brokerNotes;

  // If we have an address, try ACCURATE DATA ONLY enrichment for missing fields
  if (result.address) {
    try {
      console.log('🎯 Using intelligent data accuracy service for:', result.address);
      const { dataAccuracyService } = await import('./dataAccuracyService');
      const accurateData = await dataAccuracyService.getAccuratePropertyData(result.address);
      
      if (accurateData) {
        console.log(`✅ Accurate data retrieved - Quality: ${accurateData.dataQualityScore}%, Sources: ${accurateData.sourcesUsed.join(', ')}`);
        
        // Fill in ONLY missing data with VERIFIED ACCURATE information
        if (!result.sizeAcres && accurateData.acreage) {
          result.sizeAcres = accurateData.acreage;
          extractedInfo.sizeAcres = accurateData.acreage;
          console.log(`📏 Added accurate acreage: ${accurateData.acreage} acres from ${accurateData.sourcesUsed.filter(s => s.includes('acreage') || s.includes('HelloData'))[0] || 'verified source'}`);
        }
        if (!result.askingPrice && accurateData.marketValue) {
          result.askingPrice = accurateData.marketValue;
          extractedInfo.askingPrice = accurateData.marketValue;
          console.log(`💰 Added accurate market value: $${accurateData.marketValue} from ${accurateData.sourcesUsed.filter(s => s.includes('market') || s.includes('HelloData'))[0] || 'verified source'}`);
        }
        if (!result.extractedInfo.zoning && accurateData.zoning) {
          result.extractedInfo.zoning = accurateData.zoning;
          extractedInfo.zoning = accurateData.zoning;
          console.log(`🏗️ Added accurate zoning: ${accurateData.zoning} from ${accurateData.sourcesUsed.filter(s => s.includes('zoning'))[0] || 'verified source'}`);
        }
        
        // Add enrichment metadata to extractedInfo
        extractedInfo.enrichmentMetadata = {
          sources: accurateData.sourcesUsed,
          dataQualityScore: accurateData.dataQualityScore,
          conflictsResolved: accurateData.conflictsDetected?.length || 0,
          lastUpdated: new Date().toISOString(),
          accuracyService: 'v1.0'
        };
        
        // CRITICAL FIX: Handle price recalculation when enrichment adds acreage to per-acre pricing
        if (priceResult.pricingType === 'per_acre' && !acreageResult.value && result.sizeAcres) {
          console.log(`💰 Recalculating price: $${priceResult.value!}/ac * ${result.sizeAcres} ac = $${priceResult.value! * result.sizeAcres}`);
          result.askingPrice = priceResult.value! * result.sizeAcres;
          result.pricingType = 'total';
          extractedInfo.askingPrice = result.askingPrice;
          extractedInfo.calculatedTotal = {
            perAcrePrice: priceResult.value,
            acreage: result.sizeAcres,
            totalPrice: result.askingPrice
          };
        }
        
        // Update missing fields after enrichment using finalized data
        result.missingFields = getMissingFieldsFromFinalData(result);
        
        // Update confidence after enrichment using finalized data with provider boosts
        result.confidence = calculateConfidenceFromFinalData(result);
      }
    } catch (error: any) {
      console.log('Comprehensive enrichment failed:', error.message);
      // Continue without enrichment
    }
  }

  // CRITICAL FIX: Ensure confidence and missing fields are calculated if enrichment failed or didn't happen
  if (result.confidence === 'low' && result.missingFields.length === 0) {
    result.missingFields = getMissingFieldsFromFinalData(result);
    result.confidence = calculateConfidenceFromFinalData(result);
  }

  console.log(`📊 Parsing completed - Confidence: ${result.confidence}, Missing: [${result.missingFields.join(', ')}]`);
  
  // Return enhanced object (new format) but also populate legacy fields for backward compatibility
  Object.assign(extractedInfo, result);
  return extractedInfo;
}

// Comprehensive property data enrichment using HelloData API and ATTOM Data
async function enrichPropertyData(address: string, dealData: any = {}) {
  try {
    console.log(`🔍 Comprehensive enrichment for: ${address}`);
    
    const enrichedData: any = {
      source: 'Multi-Source Enhancement',
      confidence: 0,
      dataSources: [],
      coverage: 0
    };

    // Step 1: HelloData API (Primary for multifamily)
    try {
      // HelloData service removed per user request
      const hellodataResponse = { success: false, error: 'HelloData service removed per user request' };
      
      if (hellodataResponse && hellodataResponse.success && (hellodataResponse as any).data) {
        const property = (hellodataResponse as any).data;
        console.log(`✅ HelloData: Retrieved property data for ${address}`);
        
        // Fill comprehensive data from HelloData
        if (property.lotSize) enrichedData.acreage = (property.lotSize / 43560).toFixed(2);
        if (property.marketValue || property.assessedValue) enrichedData.estimatedValue = property.marketValue || property.assessedValue;
        if (property.units) enrichedData.unitCount = property.units;
        if (property.rentData?.averageRent) enrichedData.topRentPSF = property.rentData.averageRent;
        if (property.rentData?.rentPerSqFt) enrichedData.rentPerSqFt = property.rentData.rentPerSqFt;
        if (property.squareFootage) enrichedData.unitSize = property.squareFootage;
        if (property.yearBuilt) enrichedData.yearBuilt = property.yearBuilt;
        if (property.qualityScore) enrichedData.qualityScore = property.qualityScore;
        if (property.managementCompany) enrichedData.managementCompany = property.managementCompany;
        if (property.amenities) enrichedData.amenities = property.amenities;
        
        enrichedData.dataSources.push('HelloData.ai');
        enrichedData.confidence = Math.max(enrichedData.confidence, 0.90);
        
        // Get enhanced comparables for market context (3-5 recent properties within 1-3 miles)
        // Get enhanced comparables for market context (3-5 recent properties within 1 mile)
        // HelloData comparables service removed per user request
        const comparablesResult = { success: false, error: 'HelloData service removed per user request' };
        if (comparablesResult.success && (comparablesResult as any).data) {
          enrichedData.comparables = (comparablesResult as any).data;
          enrichedData.dataSources.push('HelloData Enhanced Comparables');
          if ((comparablesResult as any).metadata) {
            enrichedData.comparablesMetadata = (comparablesResult as any).metadata;
          }
        }
      }
    } catch (error) {
      console.log('HelloData error:', error);
    }

    // Step 2: ATTOM Data API - DISABLED per user request (using HelloData only)
    // Using HelloData as primary and only data source

    // Step 3: Calculate derived fields if we have base data
    if (enrichedData.acreage && dealData.productTypes) {
      const productType = Array.isArray(dealData.productTypes) ? dealData.productTypes[0] : dealData.productTypes;
      if (!enrichedData.unitCount) {
        enrichedData.unitCount = estimateUnitCountFromAcreage(parseFloat(enrichedData.acreage), productType);
        enrichedData.dataSources.push('Unit Count Estimation');
      }
    }

    // Step 4: AI enrichment for missing critical fields
    if (enrichedData.coverage < 80) {
      try {
        await addAIEnrichmentToData(enrichedData, address, dealData.productTypes);
      } catch (error) {
        console.log('AI enrichment error:', error);
      }
    }

    // Step 5: Financial projections if we have rent and unit data
    if (enrichedData.rentPerSqFt && enrichedData.unitSize && enrichedData.unitCount) {
      const annualRentPerUnit = enrichedData.rentPerSqFt * enrichedData.unitSize * 12;
      const totalAnnualRent = annualRentPerUnit * enrichedData.unitCount;
      enrichedData.projectedNOI = totalAnnualRent * 0.90; // 90% occupancy
      enrichedData.dataSources.push('Financial Projections');
    }

    // Step 6: Calculate final data coverage
    const totalPossibleFields = ['acreage', 'estimatedValue', 'zoning', 'utilities', 'unitCount', 'topRentPSF', 'unitSize', 'yearBuilt'];
    const filledFields = totalPossibleFields.filter(field => enrichedData[field] !== null && enrichedData[field] !== undefined);
    enrichedData.coverage = Math.round((filledFields.length / totalPossibleFields.length) * 100);

    if (enrichedData.dataSources.length > 0) {
      console.log(`✅ Multi-source enrichment completed: ${enrichedData.dataSources.join(', ')} - ${enrichedData.coverage}% coverage`);
      return enrichedData;
    } else {
      console.log(`❌ No live data available for ${address} - using backup`);
      const locationInfo = extractLocationInfo(address);
      return await backupPropertyEnrichment(address, locationInfo);
    }
  } catch (error) {
    console.log('Comprehensive enrichment error:', error);
    const locationInfo = extractLocationInfo(address);
    return await backupPropertyEnrichment(address, locationInfo);
  }
}

// NO UNIT COUNT ESTIMATION - Removed density assumptions per user requirement
function estimateUnitCountFromAcreage(acres: number, productType: string): number | null {
  // User preference: Never make base assumptions on data, leave blank if not available from API
  console.log(`⚠️ No density mapping data available from HelloData API for ${productType} on ${acres} acres. Leaving unit count empty to avoid assumptions.`);
  return null; // Return null instead of making assumptions - analysts will handle this manually
}

