async function addAIEnrichmentToData(enrichedData: any, address: string, productTypes?: string[]): Promise<void> {
  let startTime = Date.now();
  try {
    console.log(`🤖 AI: Analyzing property for missing field enrichment: ${address}`);

    const OpenAI = (await import('openai')).default;
    const openai = new OpenAI({ apiKey: process.env.OPENAI_API_KEY });

    // Determine what fields are missing
    const missingFields = [];
    if (!enrichedData.acreage) missingFields.push('property size');
    if (!enrichedData.unitCount) missingFields.push('unit count');
    if (!enrichedData.topRentPSF) missingFields.push('rent comparable');
    if (!enrichedData.rentPerSqFt) missingFields.push('rent per sq ft');
    if (!enrichedData.unitSize) missingFields.push('unit size');
    if (!enrichedData.zoning) missingFields.push('zoning');

    if (missingFields.length === 0) return;

    const prompt = `
Analyze this real estate property and provide realistic estimates for missing data:

PROPERTY: ${address}
DEVELOPMENT TYPE: ${productTypes?.join(', ') || 'Not specified'}

EXISTING DATA:
- Size: ${enrichedData.acreage ? `${enrichedData.acreage} acres` : 'Unknown'}
- Units: ${enrichedData.unitCount || 'Unknown'}
- Rent: ${enrichedData.topRentPSF ? `$${enrichedData.topRentPSF}` : 'Unknown'}
- Rent/SF: ${enrichedData.rentPerSqFt ? `$${enrichedData.rentPerSqFt}` : 'Unknown'}
- Unit Size: ${enrichedData.unitSize ? `${enrichedData.unitSize} sq ft` : 'Unknown'}
- Zoning: ${enrichedData.zoning || 'Unknown'}

MISSING: ${missingFields.join(', ')}

Provide realistic estimates based on property location, development type, and market conditions.

Respond with JSON:
{
  "estimates": {
    "acreage": number,
    "unitCount": number,
    "topRentPSF": number,
    "rentPerSqFt": number,
    "unitSize": number,
    "zoning": "string"
  },
  "confidence": {
    "acreage": number (0-100),
    "unitCount": number (0-100),
    "topRentPSF": number (0-100),
    "rentPerSqFt": number (0-100),
    "unitSize": number (0-100),
    "zoning": number (0-100)
  }
}
`;

    startTime = Date.now();
    const response = await openai.chat.completions.create({
      model: "gpt-4", // the newest OpenAI model is "gpt-5" which was released August 7, 2025. do not change this unless explicitly requested by the user
      messages: [
        {
          role: "system",
          content: "You are a real estate expert. Provide realistic property estimates based on location and market data."
        },
        {
          role: "user",
          content: prompt
        }
      ],
      // response_format: { type: "json_object" }, // Removed - not supported with all models
      temperature: 0.3,
      max_completion_tokens: 1000
    });
    const responseTime = Date.now() - startTime;
    apiCallTracker.logCall('OpenAI', 'estimatePropertyData', true, responseTime);

    const responseContent = response.choices[0].message.content || '{}';
    
    // Validate that the response is valid JSON before parsing
    let aiData;
    try {
      // Check if response starts with error messages and skip if so
      if (responseContent.trim().startsWith("I'm sorry") || 
          responseContent.trim().startsWith("I cannot") ||
          responseContent.trim().startsWith("I apologize")) {
        console.log('🤖 AI returned an error message instead of JSON, skipping enrichment');
        return;
      }
      
      aiData = JSON.parse(responseContent);
      
      // Validate the expected structure
      if (!aiData.estimates || !aiData.confidence) {
        console.log('🤖 AI returned invalid JSON structure, skipping enrichment');
        return;
      }
    } catch (parseError) {
      console.log('🤖 AI returned invalid JSON, skipping enrichment:', responseContent.substring(0, 100) + '...');
      return;
    }
    
    // Apply AI estimates only for missing fields with high confidence
    let fieldsEnriched = 0;
    
    if (!enrichedData.acreage && aiData.estimates?.acreage && aiData.confidence?.acreage >= 70) {
      enrichedData.acreage = aiData.estimates.acreage;
      fieldsEnriched++;
    }
    
    if (!enrichedData.unitCount && aiData.estimates?.unitCount && aiData.confidence?.unitCount >= 75) {
      enrichedData.unitCount = aiData.estimates.unitCount;
      fieldsEnriched++;
    }
    
    if (!enrichedData.topRentPSF && aiData.estimates?.topRentPSF && aiData.confidence?.topRentPSF >= 70) {
      enrichedData.topRentPSF = aiData.estimates.topRentPSF;
      fieldsEnriched++;
    }
    
    if (!enrichedData.rentPerSqFt && aiData.estimates?.rentPerSqFt && aiData.confidence?.rentPerSqFt >= 70) {
      enrichedData.rentPerSqFt = aiData.estimates.rentPerSqFt;
      fieldsEnriched++;
    }
    
    if (!enrichedData.unitSize && aiData.estimates?.unitSize && aiData.confidence?.unitSize >= 65) {
      enrichedData.unitSize = aiData.estimates.unitSize;
      fieldsEnriched++;
    }
    
    if (!enrichedData.zoning && aiData.estimates?.zoning && aiData.confidence?.zoning >= 60) {
      enrichedData.zoning = aiData.estimates.zoning;
      fieldsEnriched++;
    }

    if (fieldsEnriched > 0) {
      enrichedData.dataSources.push(`AI Analysis (${fieldsEnriched} fields)`);
      console.log(`✅ AI: Enhanced ${fieldsEnriched} fields for ${address}`);
    }

  } catch (error) {
    const responseTime = Date.now() - startTime;
    apiCallTracker.logCall('OpenAI', 'estimatePropertyData', false, responseTime, {
      errorMessage: error instanceof Error ? error.message : String(error)
    });
    console.error('AI enrichment error:', error);
  }
}

function extractLocationInfo(address: string) {
  const stateMatch = address.match(/\b([A-Z]{2})\b/);
  const cityMatch = address.match(/,\s*([^,]+)(?:,\s*[A-Z]{2})?$/);
  
  return {
    state: stateMatch ? stateMatch[1] : null,
    city: cityMatch ? cityMatch[1].trim() : null,
    fullAddress: address
  };
}

async function backupPropertyEnrichment(address: string, locationInfo: any) {
  console.log(`🔄 Attempting REAL DATA ONLY enrichment for: ${address}`);
  
  // Try only real data sources - NO FAKE DATA ALLOWED  
  // ATTOM disabled per user request - using HelloData only
  const sources = [
    { name: 'HelloData', fn: tryHelloDataAPI }
  ];
  
  for (const source of sources) {
    try {
      console.log(`🔍 Trying ${source.name} for ${address}...`);
      const result = await source.fn(address, locationInfo);
      if (result && result.source.includes('Live Data')) {
        console.log(`✅ ${source.name}: REAL LIVE data retrieved for ${address}`);
        return result;
      }
    } catch (error: any) {
      console.log(`❌ ${source.name} failed: ${error.message}`);
    }
  }
  
  // REAL DATA ONLY POLICY: Return null if no live data available
  console.log(`❌ NO LIVE DATA AVAILABLE for ${address} - leaving fields blank per user override`);
  return {
    acreage: null,
    estimatedValue: null,
    zoning: null,
    utilities: null,
    source: 'No Live Data Available - Fields Left Blank',
    confidence: 0
  };
}

// Try HelloData API (REAL DATA ONLY)
async function tryHelloDataAPI(address: string, locationInfo: any) {
  if (!process.env.HELLODATA_API_KEY) {
    console.log('❌ HelloData API key not available - skipping');
    return null;
  }

  try {
    // Import HelloData service
    // HelloData service removed per user request
    
    // Get property data from HelloData
    // HelloData service removed per user request
    const hellodataResponse = { success: false, error: 'HelloData service removed per user request' };
    
    if (hellodataResponse && hellodataResponse.success && 'data' in hellodataResponse && hellodataResponse.data) {
      const property = hellodataResponse.data as any;
      // ONLY return data if it's actually available from API
      return {
        acreage: property.lotSize ? (property.lotSize / 43560).toFixed(2) : null,
        estimatedValue: property.marketValue || property.assessedValue || null,
        zoning: null, // HelloData doesn't provide zoning info directly
        utilities: null, // HelloData doesn't provide utilities info directly
        source: 'HelloData.ai API - Live Data',
        confidence: 0.90,
        propertyDetails: {
          bedrooms: property.bedrooms || null,
          bathrooms: property.bathrooms || null,
          squareFootage: property.squareFootage || null,
          yearBuilt: property.yearBuilt || null,
          propertyType: property.propertyType || null,
          units: property.units || null,
          managementCompany: property.managementCompany || null,
          qualityScore: property.qualityScore || null
        },
        rentData: property.rentData,
        availability: property.availability,
        amenities: property.amenities,
        fees: property.fees,
        reviews: property.reviews
      };
    }
  } catch (error) {
    console.log('HelloData API unavailable:', error);
  }
  return null;
}

