  // User Management API Endpoints (Super Admin Only)
  
  // Get all users (Super Admin only)
  app.get('/api/users', isAuthenticated, async (req: any, res) => {
    try {
      const user = req.user;
      const userEmail = user?.email || user?.claims?.email || '';
      
      // Only super admin (jack@apexresi.com) can access user management
      if (userEmail !== 'jack@apexresi.com') {
        return res.status(401).json({ message: "Unauthorized - Super admin access required" });
      }

      const users = await storage.getAllUsers();
      
      // Enrich users with broker-specific fields if they have broker profiles
      const enrichedUsers = await Promise.all(users.map(async (u) => {
        if (u.role === 'BROKER') {
          const broker = await storage.getBrokerByUserId(u.id);
          if (broker) {
            return {
              ...u,
              phone: broker.phone,
              marketsCovered: broker.marketsCovered,
              brokerage: broker.brokerage
            };
          }
        }
        return u;
      }));
      
      res.json({ users: enrichedUsers });
    } catch (error) {
      console.error("Error fetching users:", error);
      res.status(500).json({ message: "Failed to fetch users" });
    }
  });

  // Create new user (Super Admin only)
  app.post('/api/users', isAuthenticated, async (req: any, res) => {
    try {
      const user = req.user;
      const userEmail = user?.email || user?.claims?.email || '';
      
      // Only super admin can create users
      if (userEmail !== 'jack@apexresi.com') {
        return res.status(401).json({ message: "Unauthorized - Super admin access required" });
      }

      const { email, firstName, lastName, password, role } = req.body;
      
      if (!email || !firstName || !lastName || !password) {
        return res.status(400).json({ message: "Missing required fields" });
      }

      // Check if user already exists
      const existingUser = await storage.getUserByEmail(email);
      if (existingUser) {
        return res.status(400).json({ message: "User with this email already exists" });
      }

      // Hash the password
      const { hashPassword } = await import('./auth');
      const hashedPassword = await hashPassword(password);

      // Create the user
      const newUser = await storage.createUser({
        email,
        password: hashedPassword,
        firstName,
        lastName
      });

      // Remove password from response
      const { password: _, ...userResponse } = newUser;
      res.status(201).json({ user: userResponse });
    } catch (error) {
      console.error("Error creating user:", error);
      res.status(500).json({ message: "Failed to create user" });
    }
  });

  // Update user (Super Admin only)
  app.patch('/api/users/:userId', isAuthenticated, async (req: any, res) => {
    try {
      const user = req.user;
      const userEmail = user?.email || user?.claims?.email || '';
      
      // Only super admin can update users
      if (userEmail !== 'jack@apexresi.com') {
        return res.status(401).json({ message: "Unauthorized - Super admin access required" });
      }

      const { userId } = req.params;
      const updates = req.body;

      // Remove sensitive fields that shouldn't be updated this way
      delete updates.password;
      delete updates.id;

      // Extract and remove broker-specific fields (they go to brokers table, not users table)
      const brokerFields: { phone?: string | null; marketsCovered?: string[]; brokerage?: string | null } = {};
      if (updates.phone !== undefined) {
        // Allow empty/null phone (optional field)
        brokerFields.phone = updates.phone || null;
        delete updates.phone;
      }
      if (updates.marketsCovered !== undefined) {
        // Convert to array if needed, allow empty/null values (optional field)
        if (updates.marketsCovered === null || updates.marketsCovered === '') {
          brokerFields.marketsCovered = [];
        } else if (typeof updates.marketsCovered === 'string') {
          // Handle string input - split by comma and trim
          brokerFields.marketsCovered = updates.marketsCovered
            .split(',')
            .map((m: string) => m.trim())
            .filter(Boolean);
        } else if (Array.isArray(updates.marketsCovered)) {
          brokerFields.marketsCovered = updates.marketsCovered;
        } else {
          return res.status(400).json({ message: "marketsCovered must be an array or comma-separated string" });
        }
        delete updates.marketsCovered;
      }
      if (updates.brokerage !== undefined) {
        // Allow empty/null brokerage (optional field)
        brokerFields.brokerage = updates.brokerage || null;
        delete updates.brokerage;
      }

      // Update user record (without broker-specific fields)
      const updatedUser = await storage.updateUser(userId, updates);
      if (!updatedUser) {
        return res.status(404).json({ message: "User not found" });
      }

      // Sync broker-specific fields to broker profile if user is a broker
      if (updatedUser.role === 'BROKER' && Object.keys(brokerFields).length > 0) {
        await storage.updateBrokerFromUser(userId, brokerFields);
      }

      res.json({ user: updatedUser });
    } catch (error) {
      console.error("Error updating user:", error);
      res.status(500).json({ message: "Failed to update user" });
    }
  });

