  // Helper function to normalize marketsCovered field
  function normalizeMarketsCovered(marketsCovered: any): string[] | null {
    if (!marketsCovered || marketsCovered === '') {
      return null;
    }
    
    if (typeof marketsCovered === 'string') {
      // Convert comma-separated string to array
      const markets = marketsCovered
        .split(',')
        .map((m: string) => m.trim())
        .filter((m: string) => m.length > 0);
      
      return markets.length > 0 ? markets : null;
    }
    
    if (Array.isArray(marketsCovered)) {
      // Already an array, just clean it up
      const markets = marketsCovered
        .map((m: string) => m.trim())
        .filter((m: string) => m.length > 0);
      
      return markets.length > 0 ? markets : null;
    }
    
    return null;
  }

  // Broker registration
  app.post("/api/brokers", authLimiter, async (req, res) => {
    try {
      const brokerData = insertBrokerSchema.parse(req.body);
      
      // Normalize marketsCovered if present
      if ('marketsCovered' in brokerData) {
        (brokerData as any).marketsCovered = normalizeMarketsCovered(brokerData.marketsCovered);
      }
      
      // Check if broker already exists by email or phone
      if (brokerData.email) {
        const existingBrokerByEmail = await storage.getBrokerByEmail(brokerData.email as unknown as string);
        if (existingBrokerByEmail) {
          return res.status(400).json({ message: "Broker with this email already exists" });
        }
      }
      
      if (brokerData.phone) {
        const existingBrokerByPhone = await storage.getBrokerByPhone(brokerData.phone as unknown as string);
        if (existingBrokerByPhone) {
          return res.status(400).json({ message: "Broker with this phone number already exists" });
        }
      }

      // Handle SMS consent: convert to smsOptIn with timestamp
      const { smsConsent, ...brokerDataToSave } = brokerData;
      const finalBrokerData = {
        ...brokerDataToSave,
        smsOptIn: smsConsent === true,
        smsOptInDate: smsConsent === true ? new Date() : null,
      };

      const broker = await storage.createBroker(finalBrokerData);

      // Return success immediately - notifications sent in background
      res.status(201).json(broker);
      
      // Send welcome communications in background using fire-and-forget pattern
      // Registration MUST succeed even if notifications fail
      (async () => {
        try {
          console.log(`📧 [REGISTRATION] Starting welcome notification dispatch for broker: ${broker.firstName} ${broker.lastName} (${broker.email})`);
          console.log(`📧 [REGISTRATION] SMS opt-in: ${broker.smsOptIn}, Phone: ${broker.phone || 'not provided'}`);
          
          const { EventDispatchService } = await import('./eventDispatch');
          const result = await EventDispatchService.brokerRegistered({
            brokerName: `${broker.firstName} ${broker.lastName}`,
            brokerEmail: broker.email || '',
            brokerPhone: broker.phone || undefined,
            brokerId: broker.id
          });
          
          console.log(`✅ [REGISTRATION] Broker registration events dispatched successfully!`);
          console.log(`   Email sent: ${result?.emailSent}`);
          console.log(`   SMS sent: ${result?.smsSent}`);
          if (result?.error) {
            console.log(`   Error details: ${result.error}`);
          }
          
          // Log communications that were sent (defensive null checks)
          if (result?.emailSent && broker.email) {
            await storage.createCommunication({
              brokerId: broker.id,
              channel: "email",
              direction: "outbound",
              rawText: "Welcome email sent via template system",
              subject: "Welcome to LandLinq - Your Land Deal Pipeline Starts Here!",
              message: "Welcome email sent via template system",
            });
          }
          
          if (result?.smsSent && broker.phone) {
            await storage.createCommunication({
              brokerId: broker.id,
              channel: "sms",
              direction: "outbound",
              rawText: "Registration confirmation SMS sent via template system",
              message: "Registration confirmation SMS sent via template system",
            });
          }
        } catch (dispatchError: any) {
          // Log error but DO NOT propagate - registration already succeeded
          console.error('❌ [REGISTRATION ERROR] Failed to dispatch broker registration notifications');
          console.error('❌ Error type:', dispatchError?.name);
          console.error('❌ Error message:', dispatchError?.message);
          console.error('❌ Stack trace:', dispatchError?.stack);
          console.error('⚠️  Broker account created successfully, but notifications not sent');
          console.error('⚠️  Check logs above for specific error details');
        }
      })().catch(err => {
        // Defensive outer catch to prevent any unhandled rejections
        console.error('❌ [REGISTRATION FATAL] Unhandled error in broker registration notification dispatch:', err);
      });
    } catch (error) {
      console.error("Error creating broker:", error);
      if (error instanceof z.ZodError) {
        return res.status(400).json({ message: "Invalid broker data", errors: error.errors });
      }
      res.status(500).json({ message: "Failed to create broker" });
    }
  });

  // Batch operations for brokers
  app.post("/api/brokers/batch", isAuthenticated, async (req, res) => {
    try {
      const { operation, brokers, data } = req.body;
      
      if (!operation) {
        return res.status(400).json({ error: "Operation type is required" });
      }

      let results = [];
      let successCount = 0;
      let errorCount = 0;

      switch (operation) {
        case 'create':
          if (!Array.isArray(brokers)) {
            return res.status(400).json({ error: "Brokers array is required for batch creation" });
          }
          
          // Batch create brokers
          for (const brokerData of brokers) {
            try {
              const validatedData = insertBrokerSchema.parse(brokerData);
              const newBroker = await storage.createBroker(validatedData);
              results.push({ success: true, broker: newBroker });
              successCount++;
            } catch (error) {
              results.push({ 
                success: false, 
                error: error instanceof Error ? error.message : 'Unknown error',
                brokerData: brokerData.email 
              });
              errorCount++;
            }
          }
          break;

        case 'update':
          if (!Array.isArray(data?.updates)) {
            return res.status(400).json({ error: "Updates array is required for batch update" });
          }
          
          // Batch update brokers
          for (const update of data.updates) {
            try {
              const { id, ...updateData } = update;
              
              // Normalize marketsCovered if present
              if ('marketsCovered' in updateData) {
                updateData.marketsCovered = normalizeMarketsCovered(updateData.marketsCovered);
              }
              
              const updatedBroker = await storage.updateBroker(id, updateData);
              results.push({ success: true, broker: updatedBroker });
              successCount++;
            } catch (error) {
              results.push({ 
                success: false, 
                error: error instanceof Error ? error.message : 'Unknown error',
                brokerId: update.id 
              });
              errorCount++;
            }
          }
          break;

        case 'activate':
        case 'deactivate':
          if (!Array.isArray(data?.brokerIds)) {
            return res.status(400).json({ error: "Broker IDs array is required" });
          }
          
          const isActive = operation === 'activate';
          for (const brokerId of data.brokerIds) {
            try {
              const updatedBroker = await storage.updateBroker(brokerId, { isActive: isActive });
              results.push({ success: true, broker: updatedBroker });
              successCount++;
            } catch (error) {
              results.push({ 
                success: false, 
                error: error instanceof Error ? error.message : 'Unknown error',
                brokerId 
              });
              errorCount++;
            }
          }
          break;

        default:
          return res.status(400).json({ error: "Invalid operation type" });
      }

      res.json({
        success: true,
        operation,
        results,
        summary: {
          total: results.length,
          successful: successCount,
          failed: errorCount
        },
        timestamp: new Date().toISOString()
      });

    } catch (error) {
      console.error("Broker batch operation error:", error);
      res.status(500).json({ error: "Failed to perform batch operation" });
    }
  });

