  // Update individual broker
  app.put("/api/brokers/:id", isAuthenticated, async (req, res) => {
    try {
      const { id } = req.params;
      const updates = req.body;
      
      // Validate update data
      const validFields = ['firstName', 'lastName', 'email', 'phone', 'marketsCovered', 'brokerage', 'yearsExperience', 'isActive', 'smsOptIn'];
      const filteredUpdates: any = {};
      
      Object.keys(updates).forEach(key => {
        if (validFields.includes(key)) {
          filteredUpdates[key] = updates[key];
        }
      });

      // Normalize marketsCovered if present
      if ('marketsCovered' in filteredUpdates) {
        filteredUpdates.marketsCovered = normalizeMarketsCovered(filteredUpdates.marketsCovered);
      }

      // Handle SMS opt-in changes with timestamps
      if ('smsOptIn' in filteredUpdates) {
        if (filteredUpdates.smsOptIn === true) {
          filteredUpdates.smsOptInDate = new Date();
          filteredUpdates.smsOptOutDate = null;
        } else if (filteredUpdates.smsOptIn === false) {
          filteredUpdates.smsOptOutDate = new Date();
        }
      }

      // Check if broker exists
      const existingBroker = await storage.getBrokerById(id);
      if (!existingBroker) {
        return res.status(404).json({ message: "Broker not found" });
      }

      // If updating email, check for duplicates
      if (filteredUpdates.email && filteredUpdates.email !== existingBroker.email) {
        const existingBrokerByEmail = await storage.getBrokerByEmail(filteredUpdates.email);
        if (existingBrokerByEmail && existingBrokerByEmail.id !== id) {
          return res.status(400).json({ message: "Broker with this email already exists" });
        }
      }

      // If updating phone, check for duplicates  
      if (filteredUpdates.phone && filteredUpdates.phone !== existingBroker.phone) {
        const existingBrokerByPhone = await storage.getBrokerByPhone(filteredUpdates.phone);
        if (existingBrokerByPhone && existingBrokerByPhone.id !== id) {
          return res.status(400).json({ message: "Broker with this phone number already exists" });
        }
      }

      const updatedBroker = await storage.updateBroker(id, filteredUpdates);
      res.json(updatedBroker);
    } catch (error) {
      console.error("Error updating broker:", error);
      res.status(500).json({ message: "Failed to update broker" });
    }
  });

