  app.get("/api/brokers/:id/statistics", isAuthenticated, async (req, res) => {
    try {
      const { id } = req.params;
      
      // Initialize statistics with all possible values set to 0
      // This ensures the response always matches the BrokerStatistics type
      const stats = {
        totalDeals: 0,
        byClassification: {
          red: 0,
          yellow: 0,
          green: 0,
          unclassified: 0,
        },
        bySubmissionMethod: {
          email: 0,
          sms: 0,
          form: 0,
        }
      };
      
      // Get all deals for this broker
      const allDeals = await storage.getAllDeals();
      const brokerDeals = allDeals.filter((deal: any) => deal.brokerId === id);
      
      // Calculate statistics
      stats.totalDeals = brokerDeals.length;
      
      // Count by classification
      brokerDeals.forEach((deal: any) => {
        const classification = deal.classification || 'unclassified';
        if (classification in stats.byClassification) {
          stats.byClassification[classification as keyof typeof stats.byClassification]++;
        }
      });
      
      // Count by submission method
      brokerDeals.forEach((deal: any) => {
        const method = deal.submissionMethod;
        if (method && method in stats.bySubmissionMethod) {
          stats.bySubmissionMethod[method as keyof typeof stats.bySubmissionMethod]++;
        }
      });
      
      res.json(stats);
    } catch (error) {
      console.error("Error fetching broker statistics:", error);
      res.status(500).json({ message: "Failed to fetch broker statistics" });
    }
  });

