  app.get("/api/crm/geo-options", isAuthenticated, async (req, res) => {
    try {
      const [marketRows, dealStateRows, dealCountyRows, assignedToRows, brokerageRows] = await Promise.all([
        db.selectDistinct({ state: acquisitionMarkets.state, msa: acquisitionMarkets.msaName, county: acquisitionMarkets.county })
          .from(acquisitionMarkets)
          .where(eq(acquisitionMarkets.isActive, true))
          .orderBy(acquisitionMarkets.state, acquisitionMarkets.msaName),
        db.selectDistinct({ state: deals.state }).from(deals).where(sql`${deals.state} IS NOT NULL`),
        db.selectDistinct({ county: deals.county }).from(deals).where(sql`${deals.county} IS NOT NULL`),
        db.selectDistinct({ assignedTo: (brokers as any).assignedTo }).from(brokers).where(sql`assigned_to IS NOT NULL AND assigned_to != ''`),
        db.selectDistinct({ brokerage: brokers.brokerage }).from(brokers).where(sql`brokerage IS NOT NULL AND brokerage != ''`),
      ]);

      // Build state list: union of acquisition markets states + deal states
      const statesFromMarkets = [...new Set(marketRows.map(r => r.state))].sort();
      const statesFromDeals = [...new Set(dealStateRows.map(r => r.state).filter(Boolean))].sort();
      const allStates = [...new Set([...statesFromMarkets, ...statesFromDeals])].sort();

      // Build MSA map: state → [msa names]
      const msasByState: Record<string, string[]> = {};
      for (const r of marketRows) {
        if (!msasByState[r.state]) msasByState[r.state] = [];
        if (!msasByState[r.state].includes(r.msa)) msasByState[r.state].push(r.msa);
      }

      // Counties per MSA and per state
      const countiesByMsa: Record<string, string[]> = {};
      for (const r of marketRows) {
        if (!countiesByMsa[r.msa]) countiesByMsa[r.msa] = [];
        if (!countiesByMsa[r.msa].includes(r.county)) countiesByMsa[r.msa].push(r.county);
      }
      const allCounties = [...new Set([
        ...marketRows.map(r => r.county),
        ...dealCountyRows.map(r => r.county).filter(Boolean),
      ])].sort();

      const assignedTos = [...new Set(assignedToRows.map(r => (r as any).assignedTo).filter(Boolean))].sort();
      const brokerageNames = new Map<string, string>();
      for (const row of brokerageRows) {
        const name = row.brokerage?.trim();
        if (name && !brokerageNames.has(name.toLowerCase())) brokerageNames.set(name.toLowerCase(), name);
      }
      const brokerages = Array.from(brokerageNames.values()).sort((a, b) => a.localeCompare(b));

      res.json({ states: allStates, msasByState, countiesByMsa, counties: allCounties, assignedTos, brokerages });
    } catch (err: any) {
      res.status(500).json({ message: err.message });
    }
  });

  // GET /api/crm/contacts — paginated list with search + tag/market/sms/geo filters
  app.get("/api/crm/contacts", isAuthenticated, async (req, res) => {
    try {
      const page = parseInt(req.query.page as string) || 1;
      const limit = parseInt(req.query.limit as string) || 50;
      const search = (req.query.search as string || '').trim();
      const tag = req.query.tag as string;
      const market = req.query.market as string;
      const smsFilter = req.query.sms as string; // 'opted_in' | 'opted_out' | 'all'
      const stateFilter = (req.query.state as string || '').trim().toUpperCase();
      const msaFilter = (req.query.msa as string || '').trim();
      const countyFilter = (req.query.county as string || '').trim();
      const assignedToFilter = (req.query.assignedTo as string || '').trim();
      const brokerageFilter = (req.query.brokerage as string || '').trim();
      const multiCampaignTagFilter = req.query.multiCampaignTag === 'true';
      const offset = (page - 1) * limit;

      // For geo filters: build set of county names that match the requested state/MSA
      let geoCountySet: Set<string> | null = null;
      let geoMsaSet: Set<string> | null = null;
      if (stateFilter || msaFilter || countyFilter) {
        let q = db.select({ county: acquisitionMarkets.county, msa: acquisitionMarkets.msaName, state: acquisitionMarkets.state })
          .from(acquisitionMarkets);
        const conditions: any[] = [];
        if (stateFilter) conditions.push(eq(acquisitionMarkets.state, stateFilter));
        if (msaFilter) conditions.push(eq(acquisitionMarkets.msaName, msaFilter));
        if (countyFilter) conditions.push(eq(acquisitionMarkets.county, countyFilter));
        const geoRows = await (conditions.length ? (q as any).where(and(...conditions)) : q);
        geoCountySet = new Set(geoRows.map((r: any) => r.county.toLowerCase()));
        geoMsaSet = new Set(geoRows.map((r: any) => r.msa.toLowerCase()));
      }

      // If geo filter active: also get broker IDs with deals in matching state/county
      let brokerIdsFromDeals: Set<string> | null = null;
      if (stateFilter || msaFilter || countyFilter) {
        const dealConditions: any[] = [];
        if (stateFilter) dealConditions.push(eq(deals.state, stateFilter));
        if (countyFilter) dealConditions.push(sql`LOWER(${deals.county}) = LOWER(${countyFilter})`);
        if (msaFilter) dealConditions.push(eq(deals.msaName, msaFilter));
        const matchingDeals = await db.select({ brokerId: deals.brokerId }).from(deals)
          .where(and(...dealConditions.map(c => c)));
        brokerIdsFromDeals = new Set(matchingDeals.map((d: any) => d.brokerId).filter(Boolean));
      }

      // Fetch all brokers then filter — brokers table is typically < 10k rows
      const allBrokers: any[] = await db.select({
        id: brokers.id,
        firstName: brokers.firstName,
        lastName: brokers.lastName,
        email: brokers.email,
        phone: brokers.phone,
        brokerage: brokers.brokerage,
        marketsCovered: brokers.marketsCovered,
        smsOptIn: brokers.smsOptIn,
        isActive: brokers.isActive,
        assignedTo: (brokers as any).assignedTo,
        crmTags: (brokers as any).crmTags,
        crmNotes: (brokers as any).crmNotes,
        lastContactedAt: (brokers as any).lastContactedAt,
        stateRegion: (brokers as any).stateRegion,
        createdAt: brokers.createdAt,
      }).from(brokers).orderBy(desc(brokers.createdAt));

      const companyMemberCounts = allBrokers.reduce((counts: Record<string, number>, broker: any) => {
        const key = String(broker.brokerage || "").trim().toLowerCase();
        if (key) counts[key] = (counts[key] || 0) + 1;
        return counts;
      }, {});

      // Apply filters
      let filtered = allBrokers;
      if (search) {
        const q = search.toLowerCase();
        filtered = filtered.filter(b =>
          `${b.firstName} ${b.lastName}`.toLowerCase().includes(q) ||
          (b.email || '').toLowerCase().includes(q) ||
          (b.phone || '').includes(q) ||
          (b.brokerage || '').toLowerCase().includes(q) ||
          (b.assignedTo || '').toLowerCase().includes(q)
        );
      }
      if (tag) {
        filtered = filtered.filter(b => Array.isArray(b.crmTags) && b.crmTags.includes(tag));
      }
      if (market) {
        filtered = filtered.filter(b => Array.isArray(b.marketsCovered) && b.marketsCovered.some((m: string) => m.toLowerCase().includes(market.toLowerCase())));
      }
      if (stateFilter && !msaFilter && !countyFilter) {
        // Simple state filter — match directly on state_region column OR deals in that state
        filtered = filtered.filter(b =>
          (b.stateRegion || '').toUpperCase() === stateFilter ||
          (brokerIdsFromDeals ? brokerIdsFromDeals.has(b.id) : false)
        );
      } else if (geoCountySet && geoCountySet.size > 0) {
        // MSA/county geo filter — match via marketsCovered or deals
        filtered = filtered.filter(b => {
          const covered = (b.marketsCovered || []).map((m: string) => m.toLowerCase());
          const matchesCovered = covered.some((m: string) =>
            (geoCountySet!.size > 0 && [...geoCountySet!].some(c => m.includes(c))) ||
            (geoMsaSet!.size > 0 && [...geoMsaSet!].some(msa => m.includes(msa)))
          );
          const matchesDeal = brokerIdsFromDeals ? brokerIdsFromDeals.has(b.id) : false;
          return matchesCovered || matchesDeal;
        });
      }
      if (smsFilter === 'opted_in') {
        filtered = filtered.filter(b => b.smsOptIn);
      } else if (smsFilter === 'opted_out') {
        filtered = filtered.filter(b => !b.smsOptIn);
      }
      if (assignedToFilter) {
        filtered = filtered.filter(b => (b.assignedTo || '').toLowerCase() === assignedToFilter.toLowerCase());
      }
      if (brokerageFilter) {
        filtered = filtered.filter(b => (b.brokerage || '').toLowerCase() === brokerageFilter.toLowerCase());
      }
      if (multiCampaignTagFilter) {
        // Get all outreach campaign trigger tags from active templates
        const outreachTagRows = await db.execute(sql`
          SELECT hubspot_trigger_tag FROM outreach_campaign_templates
          WHERE is_active = true AND hubspot_trigger_tag IS NOT NULL
        `);
        const outreachTagSet = new Set((outreachTagRows as any).rows.map((r: any) => r.hubspot_trigger_tag as string));
        filtered = filtered.filter(b => {
          const appliedOutreachTags = (b.crmTags || []).filter((t: string) => outreachTagSet.has(t));
          return appliedOutreachTags.length > 1;
        });
      }

      // Enrich with deal counts
      const brokerIds = filtered.map(b => b.id);
      let dealCounts: Record<string, number> = {};
      if (brokerIds.length > 0) {
        const rawDeals = await db.select({ brokerId: deals.brokerId }).from(deals);
        rawDeals.forEach((d: any) => {
          if (d.brokerId) dealCounts[d.brokerId] = (dealCounts[d.brokerId] || 0) + 1;
        });
      }

      const total = filtered.length;
      const paginated = filtered.slice(offset, offset + limit).map(b => ({
        ...b,
        dealCount: dealCounts[b.id] || 0,
        companyMemberCount: companyMemberCounts[String(b.brokerage || "").trim().toLowerCase()] || 0,
      }));

      res.json({
        contacts: paginated,
        pagination: {
          page,
          limit,
          total,
          totalPages: Math.ceil(total / limit),
          hasNextPage: offset + limit < total,
          hasPrevPage: page > 1,
        }
      });
    } catch (error) {
      console.error("CRM contacts error:", error);
      res.status(500).json({ message: "Failed to fetch contacts" });
    }
  });

  // GET /api/crm/tags — list all unique tags across all contacts + registry
  app.get("/api/crm/tags", isAuthenticated, async (req, res) => {
    try {
      const [contactResult, registryResult] = await Promise.all([
        db.select({ crmTags: (brokers as any).crmTags }).from(brokers),
        db.select({ name: crmTagRegistry.name }).from(crmTagRegistry),
      ]);
      const tagSet = new Set<string>();
      contactResult.forEach((r: any) => {
        if (Array.isArray(r.crmTags)) r.crmTags.forEach((t: string) => tagSet.add(t));
      });
      registryResult.forEach((r) => tagSet.add(r.name));
      res.json(Array.from(tagSet).sort());
    } catch (error) {
      res.status(500).json({ message: "Failed to fetch tags" });
    }
  });

  // GET /api/crm/tag-registry — list tags in the registry
  app.get("/api/crm/tag-registry", isAuthenticated, async (req, res) => {
    try {
      const rows = await db.select().from(crmTagRegistry).orderBy(crmTagRegistry.name);
      res.json(rows);
    } catch (error) {
      res.status(500).json({ message: "Failed to fetch tag registry" });
    }
  });

  // POST /api/crm/tag-registry — create a new tag
  app.post("/api/crm/tag-registry", isAuthenticated, async (req, res) => {
    try {
      const { name } = req.body;
      if (!name || typeof name !== "string" || !name.trim()) {
        return res.status(400).json({ message: "Tag name is required" });
      }
      const [row] = await db.insert(crmTagRegistry).values({ name: name.trim() }).onConflictDoNothing().returning();
      res.json(row || { name: name.trim() });
    } catch (error) {
      res.status(500).json({ message: "Failed to create tag" });
    }
  });

  // DELETE /api/crm/tags/:tag — remove tag from registry and all contacts
  app.delete("/api/crm/tags/:tag", isAuthenticated, async (req, res) => {
    try {
      const tag = decodeURIComponent(req.params.tag);
      // Remove from registry
      await db.delete(crmTagRegistry).where(eq(crmTagRegistry.name, tag));
      // Remove from all contacts that have this tag
      await db.execute(sql`
        UPDATE brokers
        SET crm_tags = array_remove(crm_tags, ${tag}::text),
            updated_at = NOW()
        WHERE crm_tags @> ARRAY[${tag}::text]
      `);
      res.json({ success: true });
    } catch (error) {
      res.status(500).json({ message: "Failed to delete tag" });
    }
  });

  // POST /api/crm/normalize-names — title-case all contact first/last names
  app.post("/api/crm/normalize-names", isAuthenticated, async (req, res) => {
    try {
      const result = await db.execute(sql`
        UPDATE brokers
        SET
          first_name = initcap(first_name),
          last_name  = initcap(last_name),
          updated_at = NOW()
        WHERE
          first_name IS NOT NULL OR last_name IS NOT NULL
      `);
      res.json({ success: true, updated: (result as any).rowCount ?? 0 });
    } catch (error) {
      res.status(500).json({ message: "Failed to normalize names" });
    }
  });

  // POST /api/crm/backfill-assigned-to — set assignedTo from tag prefixes (e.g. "AJ - Known Sophisticated" → AJ Klenk)
  app.post("/api/crm/backfill-assigned-to", isAuthenticated, async (req, res) => {
    try {
      // 1. Build prefix → full-name map from existing assigned_to data (most reliable source)
      const existingReps = await db.execute(sql`
        SELECT DISTINCT assigned_to FROM brokers
        WHERE assigned_to IS NOT NULL AND assigned_to <> ''
      `).then(r => r.rows as any[]);

      const prefixToRep = new Map<string, string>();
      for (const row of existingReps) {
        const full: string = row.assigned_to || "";
        const prefix = full.split(/\s/)[0].toLowerCase(); // "AJ Klenk" → "aj", "Brian Ford" → "brian"
        if (prefix) prefixToRep.set(prefix, full);
      }

      // 2. Fill gaps from users table (reps who haven't been assigned to anyone yet)
      const teamUsers = await db.execute(sql`
        SELECT first_name, last_name, email FROM users
        WHERE email ILIKE '%@catalystcp.com%' AND first_name IS NOT NULL
      `).then(r => r.rows as any[]);

      for (const u of teamUsers) {
        const fn = (u.first_name || "").trim();
        if (!fn) continue;
        const prefix = fn.toLowerCase();
        if (prefixToRep.has(prefix)) continue; // already have canonical name
        let ln = (u.last_name || "").trim();
        if (!ln) {
          // Derive last name from email local part (e.g. ford@catalystcp.com → Ford)
          const local = (u.email || "").split("@")[0];
          ln = local.charAt(0).toUpperCase() + local.slice(1);
        }
        prefixToRep.set(prefix, ln ? `${fn} ${ln}` : fn);
      }

      if (prefixToRep.size === 0) {
        return res.json({ success: true, updated: 0, message: "No rep data found" });
      }

      // 3. Get all contacts that have tags but no assigned rep
      const unassigned = await db.execute(sql`
        SELECT id, crm_tags FROM brokers
        WHERE (assigned_to IS NULL OR assigned_to = '')
          AND crm_tags IS NOT NULL
          AND array_length(crm_tags, 1) > 0
      `).then(r => r.rows as any[]);

      // 4. Match each contact's tags to a rep by prefix
      const repToIds = new Map<string, string[]>();
      for (const contact of unassigned) {
        const tags: string[] = contact.crm_tags || [];
        for (const tag of tags) {
          // Tags follow pattern "[Name] - [Type]" e.g. "AJ - Known Sophisticated"
          const prefix = tag.split(/[\s\-]/)[0].toLowerCase().trim();
          if (prefixToRep.has(prefix)) {
            const rep = prefixToRep.get(prefix)!;
            if (!repToIds.has(rep)) repToIds.set(rep, []);
            repToIds.get(rep)!.push(contact.id);
            break; // first matching tag wins
          }
        }
      }

      // 5. Update in one batch per rep
      let totalUpdated = 0;
      for (const [rep, ids] of repToIds) {
        if (!ids.length) continue;
        const idList = ids.map(id => `'${id}'`).join(",");
        const result = await db.execute(sql.raw(`
          UPDATE brokers
          SET assigned_to = '${rep.replace(/'/g, "''")}',
              updated_at  = NOW()
          WHERE id IN (${idList})
            AND (assigned_to IS NULL OR assigned_to = '')
        `));
        totalUpdated += (result as any).rowCount ?? 0;
      }

      res.json({ success: true, updated: totalUpdated });
    } catch (error) {
      console.error("Backfill assigned-to error:", error);
      res.status(500).json({ message: "Failed to backfill assigned-to" });
    }
  });

  // GET /api/crm/queue-stats — enrollment queue health dashboard
  app.get("/api/crm/queue-stats", isAuthenticated, async (req, res) => {
    try {
      const [queueSummary, todayStats, byTemplate, byStatus, crmTaggedNotEnrolled] = await Promise.all([
        // Overall queue depth
        db.execute(sql`
          SELECT
            COUNT(*) FILTER (WHERE status IN ('pending','in_progress')) AS total_active,
            COUNT(*) FILTER (WHERE status = 'completed') AS total_completed,
            COUNT(*) FILTER (WHERE next_send_at::date = CURRENT_DATE AND status IN ('pending','in_progress')) AS sending_today,
            COUNT(*) FILTER (WHERE next_send_at < NOW() AND status IN ('pending','in_progress')) AS overdue,
            MIN(next_send_at) FILTER (WHERE status IN ('pending','in_progress')) AS next_send,
            MAX(next_send_at) FILTER (WHERE status IN ('pending','in_progress')) AS last_scheduled
          FROM drip_campaign_enrollments
        `),
        // Emails sent today
        db.execute(sql`
          SELECT COUNT(*) AS cnt FROM drip_campaign_enrollments
          WHERE last_sent_at >= CURRENT_DATE
        `),
        // Active enrollments per campaign
        db.execute(sql`
          SELECT ct.name, ct.hubspot_trigger_tag AS tag,
            COUNT(*) FILTER (WHERE e.status IN ('pending','in_progress')) AS active,
            COUNT(*) FILTER (WHERE e.next_send_at::date = CURRENT_DATE AND e.status IN ('pending','in_progress')) AS today,
            COUNT(*) FILTER (WHERE e.status = 'completed') AS completed
          FROM outreach_campaign_templates ct
          LEFT JOIN drip_campaign_enrollments e ON e.template_id = ct.id
          WHERE ct.is_active = true
          GROUP BY ct.id, ct.name, ct.hubspot_trigger_tag
          ORDER BY active DESC
        `),
        // By status totals
        db.execute(sql`
          SELECT status, COUNT(*) AS cnt FROM drip_campaign_enrollments GROUP BY status
        `),
        // CRM contacts tagged but NOT yet enrolled
        db.execute(sql`
          SELECT COUNT(*) AS cnt FROM brokers b
          WHERE b.crm_tags IS NOT NULL AND array_length(b.crm_tags, 1) > 0
            AND b.is_active = true
            AND NOT EXISTS (
              SELECT 1 FROM drip_campaign_enrollments e
              JOIN outreach_campaign_templates ct ON ct.id = e.template_id
              WHERE e.broker_id = b.id
                AND ct.hubspot_trigger_tag = ANY(b.crm_tags)
                AND e.status IN ('pending','in_progress')
            )
        `),
      ]);

      const q = (queueSummary.rows as any[])[0] || {};
      res.json({
        totalActive: parseInt(q.total_active || '0'),
        totalCompleted: parseInt(q.total_completed || '0'),
        sendingToday: parseInt(q.sending_today || '0'),
        overdue: parseInt(q.overdue || '0'),
        sentToday: parseInt(((todayStats.rows as any[])[0])?.cnt || '0'),
        nextSend: q.next_send || null,
        lastScheduled: q.last_scheduled || null,
        byTemplate: (byTemplate.rows as any[]).map((t: any) => ({
          name: t.name,
          tag: t.tag,
          active: parseInt(t.active || '0'),
          today: parseInt(t.today || '0'),
          completed: parseInt(t.completed || '0'),
        })),
        byStatus: Object.fromEntries((byStatus.rows as any[]).map((r: any) => [r.status, parseInt(r.cnt || '0')])),
        crmTaggedNotEnrolled: parseInt(((crmTaggedNotEnrolled.rows as any[])[0])?.cnt || '0'),
        dailyLimit: 500,
      });
    } catch (error) {
      console.error("CRM queue-stats error:", error);
      res.status(500).json({ message: "Failed to load queue stats" });
    }
  });

  // POST /api/crm/run-poll — manually trigger the CRM-native enrollment sync
  app.post("/api/crm/run-poll", isAuthenticated, async (req, res) => {
    try {
      const { processCrmTaggedContacts } = await import('./jobs/recurringOutreach');
      const result = await processCrmTaggedContacts();
      res.json({ message: "CRM poll complete", ...result });
    } catch (error) {
      console.error("CRM poll error:", error);
      res.status(500).json({ message: "Poll failed" });
    }
  });

  // GET /api/crm/outreach-tags — returns active campaign templates with trigger tags and their primary sender
  app.get("/api/crm/outreach-tags", isAuthenticated, async (req, res) => {
    try {
      const templates = await db.execute(sql`
        SELECT
          ct.id,
          ct.name,
          ct.hubspot_trigger_tag,
          (
            SELECT s.id FROM outreach_senders s
            WHERE s.is_active = true
              AND ct.hubspot_trigger_tag = ANY(s.hubspot_trigger_tags)
            ORDER BY s.created_at ASC
            LIMIT 1
          ) AS sender_id,
          (
            SELECT s.name FROM outreach_senders s
            WHERE s.is_active = true
              AND ct.hubspot_trigger_tag = ANY(s.hubspot_trigger_tags)
            ORDER BY s.created_at ASC
            LIMIT 1
          ) AS sender_name
        FROM outreach_campaign_templates ct
        WHERE ct.is_active = true
        ORDER BY ct.name
      `);
      res.json(templates.rows.map((t: any) => ({
        id: t.id,
        name: t.name,
        tag: t.hubspot_trigger_tag,
        senderId: t.sender_id || null,
        senderName: t.sender_name || null,
      })));
    } catch (error) {
      console.error("CRM outreach-tags error:", error);
      res.status(500).json({ message: "Failed to load outreach tags" });
    }
  });

  // POST /api/crm/contacts — create a new contact manually
  app.post("/api/crm/contacts", isAuthenticated, async (req, res) => {
    try {
      const { firstName, lastName, email, phone, brokerage, assignedTo, crmNotes, crmTags } = req.body;
      if (!firstName || !lastName) {
        return res.status(400).json({ message: "First name and last name are required" });
      }
      // Duplicate check
      if (email) {
        const existing = await storage.getBrokerByEmail(email.trim());
        if (existing) return res.status(400).json({ message: "A contact with this email already exists" });
      }
      if (phone) {
        const existing = await storage.getBrokerByPhone(phone.trim());
        if (existing) return res.status(400).json({ message: "A contact with this phone number already exists" });
      }
      const broker = await storage.createBroker({
        firstName: firstName.trim(),
        lastName: lastName.trim(),
        email: email?.trim() || null,
        phone: phone?.trim() || null,
        brokerage: brokerage?.trim() || null,
        assignedTo: assignedTo?.trim() || null,
        crmNotes: crmNotes?.trim() || null,
        crmTags: Array.isArray(crmTags) ? crmTags : [],
        isActive: true,
        smsOptIn: false,
      } as any);
      res.status(201).json(broker);
    } catch (error) {
      console.error("Error creating CRM contact:", error);
      res.status(500).json({ message: "Failed to create contact" });
    }
  });

  // PATCH /api/crm/contacts/:id — update tags, notes, or lastContactedAt
  app.patch("/api/crm/contacts/:id", isAuthenticated, async (req, res) => {
    try {
      const { id } = req.params;
      const { crmTags, crmNotes, lastContactedAt, assignedTo, firstName, lastName, email, phone, brokerage, addTag, removeTag } = req.body;
      if (email !== undefined && email !== null && email !== "") {
        if (typeof email !== "string" || !/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)) {
          return res.status(400).json({ message: "Enter a valid email address" });
        }
      }
      if (phone !== undefined && phone !== null && phone !== "") {
        if (typeof phone !== "string" || !/^\d{10,11}$/.test(phone.replace(/\D/g, ""))) {
          return res.status(400).json({ message: "Enter a valid phone number with 10 or 11 digits" });
        }
      }
      if (addTag !== undefined && (typeof addTag !== "string" || !addTag.trim())) {
        return res.status(400).json({ message: "addTag must be a non-empty string" });
      }
      if (removeTag !== undefined && (typeof removeTag !== "string" || !removeTag.trim())) {
        return res.status(400).json({ message: "removeTag must be a non-empty string" });
      }
      if (addTag !== undefined && removeTag !== undefined) {
        return res.status(400).json({ message: "Add or remove one tag per request" });
      }
      const updates: any = { updatedAt: new Date() };
      if (addTag !== undefined) {
        updates.crmTags = sql`array_append(COALESCE(${brokers.crmTags}, ARRAY[]::text[]), ${addTag.trim()})`;
      } else if (removeTag !== undefined) {
        updates.crmTags = sql`array_remove(COALESCE(${brokers.crmTags}, ARRAY[]::text[]), ${removeTag.trim()})`;
      } else if (crmTags !== undefined) {
        updates.crmTags = crmTags;
      }
      if (crmNotes !== undefined) updates.crmNotes = crmNotes;
      if (lastContactedAt !== undefined) updates.lastContactedAt = lastContactedAt ? new Date(lastContactedAt) : null;
      if (assignedTo !== undefined) updates.assignedTo = assignedTo || null;
      if (firstName !== undefined) updates.firstName = firstName || null;
      if (lastName !== undefined) updates.lastName = lastName || null;
      if (email !== undefined) updates.email = email || null;
      if (phone !== undefined) updates.phone = phone || null;
      if (brokerage !== undefined) updates.brokerage = brokerage || null;

      const tagCondition = addTag !== undefined
        ? sql`NOT (${addTag.trim()} = ANY(COALESCE(${brokers.crmTags}, ARRAY[]::text[])))`
        : undefined;
      const [updated] = await db.update(brokers)
        .set(updates)
        .where(tagCondition ? and(eq(brokers.id, id), tagCondition) : eq(brokers.id, id))
        .returning();
      if (!updated && addTag !== undefined) {
        const [existing] = await db.select().from(brokers).where(eq(brokers.id, id)).limit(1);
        if (existing) return res.json(existing);
      }
      if (!updated) return res.status(404).json({ message: "Contact not found" });
      res.json(updated);
    } catch (error) {
      console.error("CRM patch error:", error);
      res.status(500).json({ message: "Failed to update contact" });
    }
  });

  // Helper: build a safe PostgreSQL array literal from a list of IDs.
  // IDs must only contain alphanumeric characters and hyphens (UUID / CUID safe).
  // This avoids Drizzle's sql-template array-serialization bug (records vs varchar[]).
  function safePgArray(idList: string[]): string {
    const safe = idList.filter(id => typeof id === 'string' && /^[a-zA-Z0-9_-]+$/.test(id) && id.length <= 64);
    if (safe.length !== idList.length) throw new Error("Invalid ID format in delete request");
    return `ARRAY[${safe.map(id => `'${id}'`).join(',')}]::varchar[]`;
  }

  // DELETE /api/crm/contacts/bulk — remove multiple contacts (must be before /:id)
  app.delete("/api/crm/contacts/bulk", isAuthenticated, async (req, res) => {
    try {
      const { ids } = req.body;
      if (!Array.isArray(ids) || ids.length === 0) return res.status(400).json({ message: "ids array required" });

      const pg = safePgArray(ids);

      // Must delete in FK dependency order — brokers.id is referenced by 25+ tables without cascade
      await db.transaction(async (tx) => {
        // 1. Self-referential: nullify brokers.referred_by pointing at these brokers
        await tx.execute(sql.raw(`UPDATE brokers SET referred_by = NULL WHERE referred_by = ANY(${pg})`));

        // 2. Orphan deals — preserve deal history by setting broker_id = NULL
        await tx.execute(sql.raw(`UPDATE deals SET broker_id = NULL WHERE broker_id = ANY(${pg})`));

        // 4. Commission splits by broker direct reference (all 3 broker FK columns)
        await tx.execute(sql.raw(`DELETE FROM commission_splits WHERE broker_id = ANY(${pg}) OR primary_broker_id = ANY(${pg}) OR referrer_broker_id = ANY(${pg})`));

        // 4b. broker_points also has a referral_id FK pointing at brokers
        await tx.execute(sql.raw(`UPDATE broker_points SET referral_id = NULL WHERE referral_id = ANY(${pg})`));

        // 5. Referral chain
        await tx.execute(sql.raw(`DELETE FROM referral_activities WHERE referrer_broker_id = ANY(${pg}) OR referred_broker_id = ANY(${pg})`));
        await tx.execute(sql.raw(`DELETE FROM referral_metrics WHERE broker_id = ANY(${pg})`));
        await tx.execute(sql.raw(`DELETE FROM referral_links WHERE broker_id = ANY(${pg})`));

        // 6. Partnerships
        await tx.execute(sql.raw(`DELETE FROM broker_partnerships WHERE broker_a_id = ANY(${pg}) OR broker_b_id = ANY(${pg}) OR broker_id = ANY(${pg}) OR partner_broker_id = ANY(${pg})`));
        await tx.execute(sql.raw(`DELETE FROM preferred_partners WHERE broker_id = ANY(${pg}) OR partner_broker_id = ANY(${pg})`));
        await tx.execute(sql.raw(`DELETE FROM partnership_invitations WHERE inviter_broker_id = ANY(${pg})`));

        // 7. Gamification / viral
        await tx.execute(sql.raw(`DELETE FROM broker_achievements WHERE broker_id = ANY(${pg})`));
        await tx.execute(sql.raw(`DELETE FROM broker_points WHERE broker_id = ANY(${pg})`));
        await tx.execute(sql.raw(`DELETE FROM broker_rewards WHERE broker_id = ANY(${pg})`));
        await tx.execute(sql.raw(`DELETE FROM commission_earnings WHERE broker_id = ANY(${pg})`));
        await tx.execute(sql.raw(`DELETE FROM platform_shares WHERE broker_id = ANY(${pg})`));
        await tx.execute(sql.raw(`DELETE FROM deal_tags WHERE tagger_broker_id = ANY(${pg})`));
        await tx.execute(sql.raw(`DELETE FROM viral_signups WHERE tagger_broker_id = ANY(${pg})`));
        await tx.execute(sql.raw(`DELETE FROM valuations WHERE broker_id = ANY(${pg})`));
        await tx.execute(sql.raw(`DELETE FROM valuation_shares WHERE shared_by_broker_id = ANY(${pg})`));

        // 8. Outreach / drip / messages
        await tx.execute(sql.raw(`DELETE FROM outreach_sender_assignments WHERE broker_id = ANY(${pg})`));
        await tx.execute(sql.raw(`DELETE FROM drip_campaign_enrollments WHERE broker_id = ANY(${pg})`));
        await tx.execute(sql.raw(`DELETE FROM outreach_messages WHERE broker_id = ANY(${pg})`));

        // 9. Communications (schema-drift: DB lacks cascade despite schema declaration)
        await tx.execute(sql.raw(`DELETE FROM communications WHERE broker_id = ANY(${pg})`));

        // 10. Projects
        await tx.execute(sql.raw(`DELETE FROM projects WHERE broker_id = ANY(${pg})`));

        // 11. Delete the brokers themselves
        await tx.execute(sql.raw(`DELETE FROM brokers WHERE id = ANY(${pg})`));
      });

      res.json({ message: `${ids.length} contacts deleted` });
    } catch (error: any) {
      console.error("CRM bulk delete error:", error.message || error);
      res.status(500).json({ message: "Failed to delete contacts" });
    }
  });

