  // POST /api/crm/contacts/:id/enroll — enroll contact in a drip campaign
  app.post("/api/crm/contacts/:id/enroll", isAuthenticated, async (req, res) => {
    try {
      const { id } = req.params;
      const { templateId, senderId, targetState } = req.body;
      if (!templateId) return res.status(400).json({ message: "templateId is required" });
      // targetState: 2-letter state abbreviation (e.g. "NC") — used to split sender daily limit across geo campaigns

      // Check broker exists and get their contact info
      const [broker] = await db.select().from(brokers).where(eq(brokers.id, id));
      if (!broker) return res.status(404).json({ message: "Contact not found" });

      // Resolve sender: use provided senderId, else fall back to template's primary sender
      let resolvedSenderId = senderId || null;
      if (!resolvedSenderId) {
        const senderRow = await db.execute(sql`
          SELECT s.id FROM outreach_campaign_templates t
          JOIN outreach_senders s ON s.hubspot_trigger_tags @> ARRAY[t.hubspot_trigger_tag]::text[]
          WHERE t.id = ${templateId} AND s.is_active = true
          LIMIT 1
        `);
        resolvedSenderId = (senderRow.rows?.[0] as any)?.id || null;
      }
      if (!resolvedSenderId) return res.status(400).json({ message: "No sender available for this campaign" });

      // Check not already enrolled (by broker_id OR email, only join email condition when non-null)
      const existing = broker.email
        ? await db.execute(sql`
            SELECT id FROM drip_campaign_enrollments
            WHERE template_id = ${templateId} AND status IN ('pending', 'in_progress')
              AND (broker_id = ${id} OR contact_email = ${broker.email})
            LIMIT 1
          `)
        : await db.execute(sql`
            SELECT id FROM drip_campaign_enrollments
            WHERE template_id = ${templateId} AND status IN ('pending', 'in_progress')
              AND broker_id = ${id}
            LIMIT 1
          `);
      if ((existing.rows || []).length > 0) {
        return res.status(409).json({ message: "Contact is already enrolled in this campaign" });
      }

      // Create enrollment with all required fields
      const validTargetState = (typeof targetState === 'string' && /^[A-Z]{2}$/.test(targetState.toUpperCase()))
        ? targetState.toUpperCase() : null;
      const result = await db.execute(sql`
        INSERT INTO drip_campaign_enrollments
          (broker_id, contact_email, contact_first_name, contact_last_name, contact_phone,
           template_id, sender_id, status, current_step_index, next_send_at, created_at, target_state)
        VALUES
          (${id}, ${broker.email}, ${broker.firstName || null}, ${broker.lastName || null}, ${broker.phone || null},
           ${templateId}, ${resolvedSenderId}, 'pending', 1, NOW(), NOW(), ${validTargetState})
        RETURNING *
      `);

      res.status(201).json({ message: "Enrolled successfully", enrollment: (result as any).rows?.[0] });
    } catch (error) {
      console.error("CRM enroll error:", error);
      res.status(500).json({ message: "Failed to enroll contact" });
    }
  });

