  // POST /api/crm/bulk-tag — add/remove tag from multiple contacts at once
  app.post("/api/crm/bulk-tag", isAuthenticated, async (req, res) => {
    try {
      const { brokerIds: ids, tag, action } = req.body; // action: 'add' | 'remove'
      if (!ids?.length || !tag) return res.status(400).json({ message: "brokerIds and tag required" });

      for (const brokerId of ids) {
        const [row] = await db.select({ crmTags: (brokers as any).crmTags }).from(brokers).where(eq(brokers.id, brokerId));
        const current: string[] = Array.isArray((row as any)?.crmTags) ? (row as any).crmTags : [];
        let next: string[];
        if (action === 'add') {
          next = current.includes(tag) ? current : [...current, tag];
        } else {
          next = current.filter((t: string) => t !== tag);
        }
        await db.update(brokers).set({ crmTags: next, updatedAt: new Date() } as any).where(eq(brokers.id, brokerId));
      }
      res.json({ message: `Tag ${action === 'add' ? 'added to' : 'removed from'} ${ids.length} contact(s)` });
    } catch (error) {
      console.error("Bulk tag error:", error);
      res.status(500).json({ message: "Failed to bulk update tags" });
    }
  });

  // POST /api/crm/import-assignments — bulk assign contacts from Excel rows
  // Body: { assignments: [{ identifier: string, assignedTo: string }] }
  // identifier can be email, phone, or "firstName lastName"
  app.post("/api/crm/import-assignments", isAuthenticated, async (req, res) => {
    try {
      const { assignments } = req.body;
      if (!Array.isArray(assignments) || assignments.length === 0) {
        return res.status(400).json({ message: "assignments array required" });
      }

      // Build a map: normalized identifier → assignedTo
      const emailMap  = new Map<string, string>(); // email → assignedTo
      const phoneMap  = new Map<string, string>(); // 10-digit phone → assignedTo
      const nameMap   = new Map<string, string>(); // "first|last" → assignedTo

      for (const { identifier, assignedTo } of assignments) {
        if (!identifier || !assignedTo) continue;
        const ident = identifier.trim().toLowerCase();
        if (ident.includes('@')) {
          emailMap.set(ident, assignedTo.trim());
        } else {
          const digits = ident.replace(/\D/g, '');
          if (digits.length >= 10) {
            phoneMap.set(digits.slice(-10), assignedTo.trim());
          } else {
            const parts = ident.split(/\s+/);
            if (parts.length >= 2) {
              nameMap.set(parts[0] + '|' + parts.slice(1).join(' '), assignedTo.trim());
            }
          }
        }
      }

      // --- Single batch email lookup ---
      const emailKeys = Array.from(emailMap.keys());
      const emailRows = emailKeys.length
        ? await db.execute(sql`SELECT id, LOWER(email) AS email FROM brokers WHERE owner_developer_profile_id IS NULL AND LOWER(email) = ANY(${sql`ARRAY[${sql.join(emailKeys.map(e => sql`${e}`), sql`, `)}]::text[]`})`)
            .then(r => r.rows as any[])
        : [];

      // --- Single batch phone lookup ---
      const phoneKeys = Array.from(phoneMap.keys());
      const phoneRows = phoneKeys.length
        ? await db.execute(sql`SELECT id, REGEXP_REPLACE(COALESCE(phone,''), '[^0-9]', '', 'g') AS digits FROM brokers WHERE owner_developer_profile_id IS NULL AND REGEXP_REPLACE(COALESCE(phone,''), '[^0-9]', '', 'g') = ANY(${sql`ARRAY[${sql.join(phoneKeys.map(p => sql`${p}`), sql`, `)}]::text[]`})`)
            .then(r => r.rows as any[])
        : [];

      // Collect updates: id → assignedTo
      const updates = new Map<string, string>();
      for (const row of emailRows) {
        const at = emailMap.get(row.email);
        if (at) updates.set(row.id, at);
      }
      for (const row of phoneRows) {
        const at = phoneMap.get(row.digits);
        if (at && !updates.has(row.id)) updates.set(row.id, at);
      }

      // Name lookups (less common) — still individual but only for remainder
      for (const [key, at] of nameMap.entries()) {
        const [first, ...rest] = key.split('|');
        const last = rest.join('|');
        const found = await db.execute(sql`SELECT id FROM brokers WHERE owner_developer_profile_id IS NULL AND LOWER(first_name)=${first} AND LOWER(last_name)=${last} LIMIT 1`).then(r => r.rows as any[]);
        if (found.length) updates.set(found[0].id, at);
      }

      // Apply all updates in one shot
      let matched = 0;
      if (updates.size > 0) {
        const ids = Array.from(updates.keys());
        // Update each unique (id, assignedTo) combo — group by assignedTo for batch updates
        const byAssignee = new Map<string, string[]>();
        for (const [id, at] of updates.entries()) {
          if (!byAssignee.has(at)) byAssignee.set(at, []);
          byAssignee.get(at)!.push(id);
        }
        for (const [at, idList] of byAssignee.entries()) {
          await db.execute(sql`UPDATE brokers SET assigned_to=${at} WHERE id = ANY(${sql`ARRAY[${sql.join(idList.map(id => sql`${id}`), sql`, `)}]::text[]`})`);
          matched += idList.length;
        }
      }

      // Collect unmatched identifiers
      const matchedEmails = new Set(emailRows.map((r: any) => r.email));
      const matchedPhones = new Set(phoneRows.map((r: any) => r.digits));
      const unmatched = assignments
        .filter(({ identifier }) => {
          if (!identifier) return false;
          const ident = identifier.trim().toLowerCase();
          if (ident.includes('@')) return !matchedEmails.has(ident);
          const digits = ident.replace(/\D/g, '').slice(-10);
          if (digits.length === 10) return !matchedPhones.has(digits);
          return !updates.size; // name matches tracked separately
        })
        .map(r => r.identifier)
        .slice(0, 20);

      res.json({ message: `Assigned ${matched} contact(s)`, matched, unmatched });
    } catch (error) {
      console.error("Import assignments error:", error);
      res.status(500).json({ message: "Failed to import assignments" });
    }
  });

  // Helper: convert ALL CAPS names to Title Case
  function toTitleCase(str: string): string {
    if (!str) return str;
    // Preserve known uppercase suffixes/particles
    const keepUpper = new Set(["II", "III", "IV", "VI", "VII", "VIII", "IX"]);
    return str
      .split(/(\s+|-)/g) // split on spaces and hyphens, keeping delimiters
      .map((part) => {
        if (/^\s+$/.test(part) || part === "-") return part; // keep whitespace/hyphens as-is
        if (keepUpper.has(part.toUpperCase())) return part.toUpperCase();
        return part.charAt(0).toUpperCase() + part.slice(1).toLowerCase();
      })
      .join("");
  }

  // POST /api/crm/import-contacts — bulk upsert contacts from CSV/Excel rows
  // Body: { contacts: [{ firstName, lastName, email, phone, brokerage, assignedTo, tags }] }
  app.post("/api/crm/import-contacts", isAuthenticated, async (req, res) => {
    try {
      const { contacts: rows } = req.body;
      if (!Array.isArray(rows) || rows.length === 0) {
        return res.status(400).json({ message: "contacts array required" });
      }

      let inserted = 0;
      let updated = 0;

      for (const row of rows) {
        const firstName = toTitleCase((row.firstName || "").trim());
        const lastName = toTitleCase((row.lastName || "").trim());
        const email = (row.email || "").trim().toLowerCase() || null;
        const phone = (row.phone || "").trim() || null;
        const brokerage = (row.brokerage || "").trim() || null;
        const stateRegion = (row.stateRegion || "").trim() || null;
        const assignedTo = (row.assignedTo || "").trim() || null;
        const rawTags: string[] = (row.tags || "")
          .split(/[;,]/)
          .map((t: string) => t.trim())
          .filter(Boolean);

        if (!firstName && !lastName && !email) continue;

        if (email) {
          const existing = await db.select({ id: brokers.id, crmTags: brokers.crmTags })
            .from(brokers).where(and(
              sql`LOWER(${brokers.email}) = ${email}`,
              isNull(brokers.ownerDeveloperProfileId),
            )).limit(1);

          if (existing.length) {
            const mergedTags = rawTags.length
              ? Array.from(new Set([...(existing[0].crmTags || []), ...rawTags]))
              : existing[0].crmTags;
            await db.update(brokers).set({
              assignedTo: assignedTo || undefined,
              brokerage: brokerage || undefined,
              stateRegion: stateRegion || undefined,
              crmTags: mergedTags,
              isActive: true,
              updatedAt: new Date(),
            } as any).where(eq(brokers.id, existing[0].id));
            updated++;
          } else {
            await db.insert(brokers).values({
              firstName: firstName || "Unknown",
              lastName,
              email,
              phone,
              brokerage,
              stateRegion,
              assignedTo,
              crmTags: rawTags.length ? rawTags : null,
              isActive: true,
            } as any);
            inserted++;
          }
        } else {
          await db.insert(brokers).values({
            firstName: firstName || "Unknown",
            lastName,
            email,
            phone,
            brokerage,
            stateRegion,
            assignedTo,
            crmTags: rawTags.length ? rawTags : null,
            isActive: true,
          } as any);
          inserted++;
        }
      }

      res.json({ message: `Imported ${inserted + updated} contact(s)`, inserted, updated });
    } catch (error) {
      console.error("Import contacts error:", error);
      res.status(500).json({ message: "Failed to import contacts" });
    }
  });

  // GET /api/crm/outreach-stats — counts for the outreach CRM sync step
  app.get("/api/crm/outreach-stats", isAuthenticated, async (req, res) => {
    try {
      const totalResult = await db.execute(sql`SELECT COUNT(*) as count FROM brokers WHERE is_active = true`);
      const total = parseInt(((totalResult.rows || totalResult) as any[])[0]?.count || "0");

      const byAssigneeResult = await db.execute(sql`
        SELECT assigned_to as name, COUNT(*) as count
        FROM brokers
        WHERE is_active = true AND assigned_to IS NOT NULL AND assigned_to <> ''
        GROUP BY assigned_to ORDER BY count DESC
      `);
      const byAssignee = ((byAssigneeResult.rows || byAssigneeResult) as any[]).map(r => ({
        name: r.name, count: parseInt(r.count)
      }));

      const emailsTodayResult = await db.execute(sql`
        SELECT COUNT(*) as count FROM outreach_messages
        WHERE created_at >= CURRENT_DATE AND status NOT IN ('failed', 'bounced')
      `);
      const emailsSentToday = parseInt(((emailsTodayResult.rows || emailsTodayResult) as any[])[0]?.count || "0");

      const settingsResult = await db.execute(sql`
        SELECT hubspot_daily_sync_limit as limit FROM business_settings LIMIT 1
      `);
      const dailyLimit = parseInt(((settingsResult.rows || settingsResult) as any[])[0]?.limit || "100");

      res.json({ total, byAssignee, emailsSentToday, dailyLimit });
    } catch (error) {
      console.error("CRM outreach stats error:", error);
      res.status(500).json({ message: "Failed to fetch CRM stats" });
    }
  });

