  // Generate AI analysis for a deal
  app.post("/api/ai-analysis/:dealId/generate", isAuthenticated, async (req, res) => {
    const { dealId } = req.params;
    
    try {
      // Get deal details
      const dealResult = await pool.query(`
        SELECT d.*, b.first_name as broker_first_name, b.last_name as broker_last_name,
               b.brokerage, b.markets_covered
        FROM deals d
        LEFT JOIN brokers b ON d.broker_id = b.id
        WHERE d.id = $1
      `, [dealId]);
      
      if (!dealResult.rows[0]) {
        return res.status(404).json({ error: "Deal not found" });
      }
      
      const deal = dealResult.rows[0];
      
      // Get any training data mentions for similar properties
      const trainingResult = await pool.query(`
        SELECT extracted_pros, extracted_cons, extracted_risks, extracted_key_points,
               team_decision, decision_rationale
        FROM transcript_deal_mentions
        WHERE is_verified = true
        LIMIT 10
      `);
      
      const trainingExamples = trainingResult.rows;
      
      // Use OpenAI to generate analysis
      const openaiKey = process.env.AI_INTEGRATIONS_OPENAI_API_KEY || process.env.OPENAI_API_KEY;
      if (!openaiKey) {
        return res.status(500).json({ error: "OpenAI API key not configured" });
      }
      
      const OpenAI = (await import("openai")).default;
      const openai = new OpenAI({ apiKey: openaiKey });
      
      // Build context from training data
      let trainingContext = "";
      if (trainingExamples.length > 0) {
        trainingContext = `\n\nBased on our team's past pipeline reviews, here are typical considerations:\n`;
        trainingExamples.forEach((ex, i) => {
          if (ex.extracted_pros?.length || ex.extracted_cons?.length) {
            trainingContext += `Example ${i+1}: Pros: ${ex.extracted_pros?.join(', ') || 'N/A'}, Cons: ${ex.extracted_cons?.join(', ') || 'N/A'}, Decision: ${ex.team_decision || 'N/A'}\n`;
          }
        });
      }
      
      const analysisPrompt = `You are a real estate investment analyst for Catalyst Capital Partners. Analyze this land/multifamily development deal and provide a structured assessment.

DEAL DETAILS:
- Address: ${deal.address}
- City/State: ${deal.city || 'N/A'}, ${deal.state || 'N/A'}
- County: ${deal.county || 'N/A'}
- Size: ${deal.size_acres || 'N/A'} acres
- Asking Price: $${deal.asking_price || 'N/A'}
- Zoning: ${deal.zoning || 'N/A'}
- Product Type: ${deal.product_type || 'N/A'}
- Units Proposed: ${deal.proposed_units || 'N/A'}
- Vintage/Year Built: ${deal.vintage || 'N/A'}
- Rent PSF: $${deal.rent_psf || 'N/A'}
- QCT Status: ${deal.is_qct ? 'Yes (Qualified Census Tract)' : 'No'}
- HelloData Comparables: ${deal.hellodata_comparables_count || 0} found
- Classification: ${deal.classification || 'unclassified'}
- Classification Reason: ${deal.classification_reason || 'N/A'}
- MSA Match: ${deal.msa_match || 'N/A'}
- Median Income: $${deal.median_income || 'N/A'}

${trainingContext}

ACQUISITION CRITERIA:
- Conventional Apartments: 2020+ vintage, 150+ units, $1.75+/sqft rent
- BTR/Townhome: 2015+ vintage, 25+ units, $2,000+ gross rent
- Target Markets: NC, SC, GA, TN major MSAs
- QCT properties get special consideration for LIHTC

IMPORTANT: For every pro, con, and risk, you MUST cite the specific deal data that supports it. Reference the actual numbers, values, or missing data. Be precise - don't make generic statements. Each item should clearly link to what in the deal data led to that assessment.

Provide your analysis in this exact JSON format:
{
  "overallScore": 1-100,
  "recommendation": "pursue" | "pass" | "needs_review" | "high_priority",
  "confidenceLevel": "high" | "medium" | "low",
  "pros": [{"point": "description of positive factor", "evidence": "specific data: e.g. '5.00 acres exceeds minimum lot size' or 'Located in Charlotte, NC MSA - a target market'"}],
  "cons": [{"point": "description of concern", "evidence": "specific data: e.g. 'No asking price provided' or 'Product type not specified - cannot evaluate against criteria'"}],
  "risks": [{"point": "description of risk", "evidence": "specific data: e.g. '0 HelloData comparables found - no market validation' or 'State: TX - outside target markets (NC, SC, GA, TN)'"}],
  "keyConsiderations": ["array of 2-3 important considerations for the team"],
  "quickSummary": "1-2 sentence summary of the opportunity"
}`;

      const completion = await openai.chat.completions.create({
        model: "gpt-4o",
        messages: [{ role: "user", content: analysisPrompt }],
        response_format: { type: "json_object" },
        max_tokens: 1500
      });
      
      const responseText = completion.choices[0]?.message?.content || '{}';
      let analysis: any;
      
      try {
        analysis = JSON.parse(responseText);
      } catch (parseError) {
        console.error("Error parsing AI analysis:", parseError);
        return res.status(500).json({ error: "Failed to parse AI response" });
      }
      
      const normalizePCR = (items: any[]) => {
        if (!items) return [];
        return items.map((item: any) => {
          if (typeof item === 'string') return item;
          if (item.point && item.evidence) return `${item.point} [Evidence: ${item.evidence}]`;
          if (item.point) return item.point;
          return String(item);
        });
      };

      const structuredPros = analysis.pros || [];
      const structuredCons = analysis.cons || [];
      const structuredRisks = analysis.risks || [];

      await pool.query(`
        INSERT INTO ai_deal_analysis 
        (deal_id, overall_score, recommendation, confidence_level, pros, cons, risks,
         key_considerations, quick_summary, model_version)
        VALUES ($1, $2, $3, $4, $5, $6, $7, $8, $9, 'gpt-4o')
        ON CONFLICT (deal_id) DO UPDATE SET
          overall_score = $2, recommendation = $3, confidence_level = $4,
          pros = $5, cons = $6, risks = $7, key_considerations = $8,
          quick_summary = $9, model_version = 'gpt-4o',
          generated_at = NOW(), updated_at = NOW()
      `, [
        dealId,
        analysis.overallScore || 50,
        analysis.recommendation || 'needs_review',
        analysis.confidenceLevel || 'medium',
        normalizePCR(structuredPros),
        normalizePCR(structuredCons),
        normalizePCR(structuredRisks),
        analysis.keyConsiderations || [],
        analysis.quickSummary || ''
      ]);
      
      res.json({
        success: true,
        dealId,
        overallScore: analysis.overallScore,
        recommendation: analysis.recommendation,
        confidenceLevel: analysis.confidenceLevel,
        pros: normalizePCR(structuredPros),
        cons: normalizePCR(structuredCons),
        risks: normalizePCR(structuredRisks),
        keyConsiderations: analysis.keyConsiderations,
        quickSummary: analysis.quickSummary,
        generatedAt: new Date().toISOString(),
        dealUpdatedAt: deal.updated_at
      });
      
    } catch (error: any) {
      console.error("Error generating AI analysis:", error);
      res.status(500).json({ error: "Failed to generate AI analysis" });
    }
  });

