  // Batch operations for deals
  app.post("/api/deals/batch", isAuthenticated, async (req, res) => {
    try {
      const { operation, deals, data } = req.body;
      
      if (!operation) {
        return res.status(400).json({ error: "Operation type is required" });
      }

      let results = [];
      let successCount = 0;
      let errorCount = 0;

      switch (operation) {
        case 'create':
          if (!Array.isArray(deals)) {
            return res.status(400).json({ error: "Deals array is required for batch creation" });
          }
          
          // Batch create deals
          for (const dealData of deals) {
            try {
              const validatedData = insertDealSchema.parse(dealData);
              const newDeal = await storage.createDeal(validatedData);
              results.push({ success: true, deal: newDeal });
              successCount++;
            } catch (error) {
              results.push({ 
                success: false, 
                error: error instanceof Error ? error.message : 'Unknown error',
                dealData: dealData.address || 'Unknown property'
              });
              errorCount++;
            }
          }
          break;

        case 'update':
          if (!Array.isArray(data?.updates)) {
            return res.status(400).json({ error: "Updates array is required for batch update" });
          }
          
          // Batch update deals
          for (const update of data.updates) {
            try {
              const { id, ...updateData } = update;
              const updatedDeal = await storage.updateDeal(id, updateData);
              results.push({ success: true, deal: updatedDeal });
              successCount++;
            } catch (error) {
              results.push({ 
                success: false, 
                error: error instanceof Error ? error.message : 'Unknown error',
                dealId: update.id 
              });
              errorCount++;
            }
          }
          break;

        case 'classify':
          if (!Array.isArray(data?.dealIds) || !data?.classification) {
            return res.status(400).json({ error: "Deal IDs array and classification are required" });
          }
          
          // Batch classification
          for (const dealId of data.dealIds) {
            try {
              const updatedDeal = await storage.updateDeal(dealId, { 
                classification: data.classification,
                status: data.status || 'pending_review',
                reviewedAt: new Date()
              });
              results.push({ success: true, deal: updatedDeal });
              successCount++;
            } catch (error) {
              results.push({ 
                success: false, 
                error: error instanceof Error ? error.message : 'Unknown error',
                dealId 
              });
              errorCount++;
            }
          }
          break;

        default:
          return res.status(400).json({ error: "Invalid operation type" });
      }

      res.json({
        success: true,
        operation,
        results,
        summary: {
          total: results.length,
          successful: successCount,
          failed: errorCount
        },
        timestamp: new Date().toISOString()
      });

    } catch (error) {
      console.error("Deal batch operation error:", error);
      res.status(500).json({ error: "Failed to perform batch operation" });
    }
  });

