  app.get("/api/deals", isAuthenticated, async (req, res) => {
    try {
      const page = parseInt(req.query.page as string) || 1;
      const limit = parseInt(req.query.limit as string) || 25;
      const offset = (page - 1) * limit;
      const search = req.query.search as string || '';
      // Dec 15, 2025: Support multi-select classification filter (comma-separated)
      const classificationsParam = req.query.classifications as string || '';
      const classifications = classificationsParam ? classificationsParam.split(',').filter(c => c.trim()) : [];
      // Jan 5, 2026: Support multi-select priority filter (comma-separated)
      const prioritiesParam = req.query.priorities as string || '';
      const priorities = prioritiesParam ? prioritiesParam.split(',').filter(p => p.trim()) : [];
      // Jan 7, 2026: Support multi-select deal type filter (land/acquisition)
      const dealTypesParam = req.query.dealTypes as string || '';
      const dealTypes = dealTypesParam ? dealTypesParam.split(',').filter(d => d.trim()) : [];
      // Jul 6, 2026: Support Apex checkbox filter (yes/no)
      const apexParam = req.query.apex as string || '';
      const apexValues = apexParam ? apexParam.split(',').filter(a => a.trim()) : [];
      console.log(`🔍 [DEAL-FILTER] dealTypesParam='${dealTypesParam}', parsed dealTypes:`, dealTypes);
      const sortBy = req.query.sortBy as string || '';
      const sortOrder = (req.query.sortOrder as string || 'asc') as 'asc' | 'desc';
      
      // Log audit trail for data access
      const userId = (req as any).user?.claims?.sub;
      await logAuditTrail({
        userId,
        action: 'VIEW_DEALS',
        entityType: 'DEALS',
        tableName: 'deals',
        recordId: 'multiple',
        changedBy: userId || 'anonymous',
        details: { page, limit, search, classifications, sortBy, sortOrder },
        userAgent: req.get('User-Agent'),
        ipAddress: req.ip
      });

      let allDeals = await storage.getDealsWithBrokers();

      // Demo sandbox: scope to demo user's deals only
      const reqUserEmail = ((req as any).user?.claims?.email || (req as any).user?.email || '').toLowerCase();
      if (reqUserEmail === 'demo@catalystcp.com') {
        const demoUser = await storage.getUserByEmail('demo@catalystcp.com');
        if (demoUser) {
          const demoBroker = await storage.getBrokerByUserId(demoUser.id);
          if (demoBroker) {
            allDeals = allDeals.filter(d => d.brokerId === demoBroker.id);
          } else {
            allDeals = [];
          }
        } else {
          allDeals = [];
        }
      }
      
      // Simple pagination implementation
      const filteredDeals = allDeals.filter(deal => {
        // NOTE: Manual Entry broker is intentionally used by Quick Add form when no broker data is provided
        // Do NOT filter these out - they are legitimate analyst-submitted deals
        
        const searchLower = search.toLowerCase();
        const matchesSearch = !search || 
          deal.address?.toLowerCase().includes(searchLower) ||
          deal.city?.toLowerCase().includes(searchLower) ||
          deal.state?.toLowerCase().includes(searchLower) ||
          deal.zip?.toLowerCase().includes(searchLower) ||
          deal.propertyName?.toLowerCase().includes(searchLower) ||
          deal.msa?.toLowerCase().includes(searchLower) ||
          deal.broker?.firstName?.toLowerCase().includes(searchLower) ||
          deal.broker?.lastName?.toLowerCase().includes(searchLower) ||
          deal.broker?.email?.toLowerCase().includes(searchLower);
        // Dec 15, 2025: Handle multi-select classification filter (array of classifications)
        // Empty array = no filter (show all)
        // pending_address uses addressConfidence instead of classification
        let matchesClassification = true;
        if (classifications.length > 0) {
          matchesClassification = classifications.some(c => 
            c === 'pending_address' ? deal.addressConfidence === 'pending' : deal.classification === c
          );
        }
        // Jan 5, 2026: Handle multi-select priority filter (array of priorities)
        let matchesPriority = true;
        if (priorities.length > 0) {
          matchesPriority = priorities.includes(deal.priority);
        }
        // Jan 7, 2026: Handle multi-select deal type filter (land/acquisition)
        let matchesDealType = true;
        if (dealTypes.length > 0) {
          // Default to 'land' if dealType not set
          const dealDealType = (deal as any).dealType || 'land';
          matchesDealType = dealTypes.includes(dealDealType);
        }
        // Jul 6, 2026: Handle Apex checkbox filter (yes/no)
        let matchesApex = true;
        if (apexValues.length > 0) {
          const dealApex = (deal as any).apex ? 'yes' : 'no';
          matchesApex = apexValues.includes(dealApex);
        }
        const matches = matchesSearch && matchesClassification && matchesPriority && matchesDealType && matchesApex;
        return matches;
      });
      
      // Apply sorting if sortBy is specified
      let sortedDeals = filteredDeals;
      if (sortBy) {
        sortedDeals = [...filteredDeals].sort((a: any, b: any) => {
          let aValue = a[sortBy];
          let bValue = b[sortBy];
          
          // Handle null/undefined values
          if (aValue == null && bValue == null) return 0;
          if (aValue == null) return 1;
          if (bValue == null) return -1;
          
          // Handle numeric values
          if (typeof aValue === 'number' && typeof bValue === 'number') {
            return sortOrder === 'asc' ? aValue - bValue : bValue - aValue;
          }
          
          // Handle string values (case-insensitive)
          const aStr = String(aValue).toLowerCase();
          const bStr = String(bValue).toLowerCase();
          
          if (aStr < bStr) return sortOrder === 'asc' ? -1 : 1;
          if (aStr > bStr) return sortOrder === 'asc' ? 1 : -1;
          return 0;
        });
      }
      
      const total = sortedDeals.length;
      const deals = sortedDeals.slice(offset, offset + limit);
      
      // DEBUG: Log demographics data being returned
      const dealsWithDemographics = deals.filter((d: any) => d.population55Plus5Mile || d.income75Plus55Plus);
      console.log(`📊 [API-DEALS-DEBUG] Returning ${deals.length} deals, ${dealsWithDemographics.length} have demographics data`);
      if (dealsWithDemographics.length > 0) {
        console.log(`📊 [API-DEALS-DEBUG] Sample deals with demographics:`, 
          dealsWithDemographics.slice(0, 3).map((d: any) => ({
            id: d.id,
            address: d.address?.substring(0, 30),
            population55Plus5Mile: d.population55Plus5Mile,
            income75Plus55Plus: d.income75Plus55Plus
          }))
        );
      } else {
        console.log(`⚠️ [API-DEALS-DEBUG] NO deals have demographics data populated!`);
        console.log(`⚠️ [API-DEALS-DEBUG] Sample deal fields (first deal):`, 
          deals.length > 0 ? Object.keys(deals[0]).filter(k => k.includes('population') || k.includes('income') || k.includes('demo')) : 'No deals'
        );
      }
      
      // Transform deals to include coordinates object for map view
      const dealsWithCoordinates = deals.map((deal: any) => {
        const coordinates = deal.latitude && deal.longitude 
          ? { lat: parseFloat(deal.latitude), lng: parseFloat(deal.longitude) }
          : null;
        
        return {
          ...deal,
          coordinates
        };
      });
      
      // Calculate classification totals across ALL deals (not just filtered)
      // NOTE: Include deals with Manual Entry broker - these are legitimate analyst-submitted deals
      const classificationSummary = {
        green: allDeals.filter(deal => deal.classification === 'green').length,
        yellow: allDeals.filter(deal => deal.classification === 'yellow').length,
        red: allDeals.filter(deal => deal.classification === 'red').length,
        lost: allDeals.filter(deal => deal.classification === 'lost').length,
        unclassified: allDeals.filter(deal => deal.classification === 'unclassified').length,
        pending_address: allDeals.filter(deal => (deal as any).addressConfidence === 'pending').length,
        total: allDeals.length
      };

      // Map to expected frontend format
      const counts = {
        pursuing: classificationSummary.green,
        reviewing: classificationSummary.yellow,
        passed: classificationSummary.red,
        underReview: classificationSummary.unclassified
      };
      
      res.json({
        deals: dealsWithCoordinates,
        pagination: {
          page,
          limit,
          total,
          totalPages: Math.ceil(total / limit),
          hasNextPage: page * limit < total,
          hasPrevPage: page > 1
        },
        classificationSummary,
        counts
      });
    } catch (error) {
      console.error("Error fetching deals:", error);
      res.status(500).json({ message: "Failed to fetch deals" });
    }
  });

