  // Helper function to calculate rent per unit from available data
  function calculateRentPerUnit(deal: any): number | null {
    // Try multiple approaches to calculate rent per unit
    
    // Approach 1: Use projectedRentPerSF * unitSize
    if (deal.projectedRentPerSF && deal.unitSize) {
      const rentPSF = parseFloat(deal.projectedRentPerSF.toString());
      const unitSizeSF = parseFloat(deal.unitSize.toString());
      return rentPSF * unitSizeSF;
    }
    
    // Approach 2: Use estimatedRentPSF * unitSize  
    if (deal.estimatedRentPSF && deal.unitSize) {
      const rentPSF = parseFloat(deal.estimatedRentPSF.toString());
      const unitSizeSF = parseFloat(deal.unitSize.toString());
      return rentPSF * unitSizeSF;
    }
    
    // Approach 3: Use topRentPSF * assumed average unit size (800-1200 sq ft for multifamily)
    if (deal.topRentPSF) {
      const rentPSF = parseFloat(deal.topRentPSF.toString());
      const assumedUnitSize = 1000; // Average unit size assumption
      return rentPSF * assumedUnitSize;
    }
    
    return null; // No data available to calculate rent per unit
  }

