  app.post("/api/admin/backfill-census", isAuthenticated, async (req, res) => {
    try {
      const userEmail = (req.user as any)?.email?.toLowerCase();
      const isAdmin = userEmail?.endsWith('@apexresi.com');
      
      if (!isAdmin) {
        console.log(`🚫 [CENSUS-BACKFILL] Unauthorized access attempt by ${userEmail}`);
        return res.status(403).json({ message: 'Forbidden: Admin access required' });
      }

      console.log('\n' + '='.repeat(100));
      console.log('🔄 [CENSUS-BACKFILL] STARTING CENSUS DEMOGRAPHICS BACKFILL FOR ALL DEALS');
      console.log(`   Requested by: ${userEmail}`);
      console.log('='.repeat(100));

      const allDeals = await storage.getAllDealsWithBrokers();
      console.log(`📊 [CENSUS-BACKFILL] Total deals found: ${allDeals.length}`);

      // Filter deals missing Census data (with or without coordinates - we'll geocode if needed)
      const dealsNeedingCensus = allDeals.filter(deal => 
        deal.address && 
        (deal as any).censusTotalPopulation == null && 
        (deal as any).censusMedianIncome == null
      );
      console.log(`🎯 [CENSUS-BACKFILL] Deals needing Census data: ${dealsNeedingCensus.length}`);

      if (dealsNeedingCensus.length === 0) {
        return res.json({
          success: true,
          message: 'All deals already have Census data',
          processed: 0,
          skipped: allDeals.length
        });
      }

      const results = {
        processed: 0,
        succeeded: 0,
        failed: 0,
        geocoded: 0,
        geocodeFailed: 0,
        errors: [] as any[]
      };

      let consecutiveErrors = 0;
      const MAX_CONSECUTIVE_ERRORS = 5;
      
      // Import services
      const { geocodioService } = await import('./geocodioService');
      const { getCensusDemographics } = await import('./censusService');
      
      for (const deal of dealsNeedingCensus) {
        try {
          console.log(`\n📍 [CENSUS-BACKFILL] Processing deal ${deal.id} - ${deal.address}`);
          
          let lat = deal.latitude ? parseFloat(String(deal.latitude)) : null;
          let lng = deal.longitude ? parseFloat(String(deal.longitude)) : null;
          
          // Step 1: Geocode if no coordinates
          if (!lat || !lng) {
            // Build full address from separate fields
            const fullAddress = [
              deal.address,
              deal.city,
              deal.state,
              deal.zipCode
            ].filter(Boolean).join(', ');
            
            console.log(`   🌍 Geocoding address: ${fullAddress}`);
            try {
              const geoResult = await geocodioService.geocodeAddress(fullAddress);
              if (geoResult && geoResult.latitude && geoResult.longitude) {
                lat = geoResult.latitude;
                lng = geoResult.longitude;
                // Save coordinates to deal
                await storage.updateDeal(deal.id, {
                  latitude: String(lat),
                  longitude: String(lng),
                  city: geoResult.city || deal.city,
                  state: geoResult.state || deal.state,
                  county: geoResult.county || deal.county,
                  zipCode: geoResult.zip || deal.zipCode,
                });
                results.geocoded++;
                console.log(`   ✅ Geocoded: ${lat}, ${lng} (${geoResult.city}, ${geoResult.state})`);
              } else {
                results.geocodeFailed++;
                console.log(`   ⚠️ Geocoding failed - no results`);
                continue;
              }
            } catch (geoError) {
              results.geocodeFailed++;
              console.log(`   ⚠️ Geocoding error: ${geoError}`);
              continue;
            }
          }

          // Step 2: Fetch Census data using coordinates
          const censusData = await getCensusDemographics(lat!, lng!
          );
          
          if (censusData && (censusData.totalPopulation || censusData.medianIncome || censusData.medianAge)) {
            const censusUpdate = {
              censusTotalPopulation: censusData.totalPopulation,
              censusMedianIncome: censusData.medianIncome,
              censusMedianAge: censusData.medianAge != null ? String(censusData.medianAge) : null,
              censusVacancyRate: censusData.vacancyRate != null ? String(censusData.vacancyRate) : null,
              censusRenterRate: censusData.renterRate != null ? String(censusData.renterRate) : null,
              censusTractId: censusData.tractId,
            };
            await storage.updateDeal(deal.id, censusUpdate);
            results.succeeded++;
            consecutiveErrors = 0;
            console.log(`   ✅ Census data saved: Pop=${censusData.totalPopulation}, Income=$${censusData.medianIncome}, Age=${censusData.medianAge}`);
          } else {
            results.failed++;
            console.log(`   ⚠️ No Census data available`);
          }
          
          results.processed++;
          
          // Rate limiting delay
          const delay = 300 + (consecutiveErrors * 100);
          await new Promise(resolve => setTimeout(resolve, delay));
          
        } catch (error) {
          results.failed++;
          consecutiveErrors++;
          results.errors.push({
            dealId: deal.id,
            address: deal.address,
            error: error instanceof Error ? error.message : 'Unknown error'
          });
          console.error(`   ❌ Error processing deal ${deal.id}:`, error);
          
          if (consecutiveErrors >= MAX_CONSECUTIVE_ERRORS) {
            console.error(`\n⚠️ [CENSUS-BACKFILL] Stopping after ${MAX_CONSECUTIVE_ERRORS} consecutive errors`);
            break;
          }
          
          await new Promise(resolve => setTimeout(resolve, 1000));
        }
      }

      console.log('\n' + '='.repeat(100));
      console.log('✅ [CENSUS-BACKFILL] BACKFILL COMPLETE');
      console.log(`   Total Processed: ${results.processed}`);
      console.log(`   Geocoded: ${results.geocoded}`);
      console.log(`   Geocode Failed: ${results.geocodeFailed}`);
      console.log(`   Census Succeeded: ${results.succeeded}`);
      console.log(`   Census Failed: ${results.failed}`);
      console.log('='.repeat(100) + '\n');

      res.json({
        success: true,
        message: `Census backfill complete`,
        ...results
      });

    } catch (error) {
      console.error('❌ [CENSUS-BACKFILL] Backfill error:', error);
      res.status(500).json({
        message: "Failed to backfill Census data",
        error: error instanceof Error ? error.message : 'Unknown error'
      });
    }
  });

  // USDA NRCS Soil Data for a lat/lng point
  app.get("/api/soil-data", isAuthenticated, async (req, res) => {
    const lat = parseFloat(req.query.lat as string);
    const lng = parseFloat(req.query.lng as string);

    if (isNaN(lat) || isNaN(lng)) {
      return res.status(400).json({ error: "Valid lat and lng query params are required" });
    }

    try {
      const { fetchSoilData } = await import('./usdaSoilService');
      const soilData = await fetchSoilData(lat, lng);

      if (!soilData) {
        return res.status(200).json({ soilData: null, message: "No soil data available for this location (may be water body or non-surveyed area)" });
      }

      return res.json({ soilData });
    } catch (error: any) {
      console.error("❌ [SOIL-ROUTE] Error:", error.message);
      return res.status(500).json({ error: "Failed to fetch soil data", detail: error.message });
    }
  });

  // ADMIN: Backfill QCT status for all deals using stored FIPS or geocoding
  app.post("/api/admin/backfill-qct-status", isAuthenticated, async (req, res) => {
    try {
      const { qctService } = await import('./qctService');
      const { geocodioService } = await import('./geocodioService');
      const allDeals = (await db.execute(sql`SELECT * FROM deals`).then(r => r.rows)) as any[];

      let updatedFips = 0;   // had FIPS, just needed QCT check
      let updatedGeocode = 0; // needed geocode to get FIPS
      let skipped = 0;

      for (const deal of allDeals) {
        try {
          let fips = (deal as any).censusTractFips as string | undefined;

          // If we already have a FIPS, skip geocoding
          if (fips) {
            const qctCheck = await qctService.checkQCTStatus(fips);
            const newStatus = qctCheck.isQCT ? 'YES' : 'NO';
            await storage.updateDeal(deal.id, { qctStatus: newStatus });
            console.log(`✅ [QCT-BACKFILL] Deal ${deal.id}: FIPS ${fips} → ${newStatus}`);
            updatedFips++;
            continue;
          }

          // No FIPS — try to geocode
          const addressParts: string[] = [];
          if (deal.address) addressParts.push(deal.address);
          if (deal.city) addressParts.push(deal.city);
          if (deal.state) addressParts.push(deal.state);
          if (deal.zip) addressParts.push(deal.zip);
          if (addressParts.length < 2) { skipped++; continue; }

          let geocodeResult: any;
          if (deal.latitude && deal.longitude) {
            geocodeResult = await geocodioService.reverseGeocode(
              parseFloat(String(deal.latitude)),
              parseFloat(String(deal.longitude))
            );
          } else {
            geocodeResult = await geocodioService.geocodeAddress(addressParts.join(', '));
          }

          if (!geocodeResult.success || !geocodeResult.fips) { skipped++; continue; }

          fips = geocodeResult.fips;
          const qctCheck = await qctService.checkQCTStatus(fips!);
          const newStatus = qctCheck.isQCT ? 'YES' : 'NO';
          await storage.updateDeal(deal.id, {
            qctStatus: newStatus,
            censusTractFips: fips,
            ...(geocodeResult.lat && !deal.latitude ? { latitude: String(geocodeResult.lat) } : {}),
            ...(geocodeResult.lng && !deal.longitude ? { longitude: String(geocodeResult.lng) } : {}),
          });
          console.log(`✅ [QCT-BACKFILL] Deal ${deal.id}: geocoded FIPS ${fips} → ${newStatus}`);
          updatedGeocode++;
        } catch (err) {
          console.warn(`⚠️ [QCT-BACKFILL] Deal ${deal.id} failed:`, err);
          skipped++;
        }
      }

      res.json({
        message: `QCT backfill complete: ${updatedFips} updated (stored FIPS), ${updatedGeocode} updated (geocoded), ${skipped} skipped`,
        updatedFips,
        updatedGeocode,
        skipped,
        total: allDeals.length,
      });
    } catch (error) {
      console.error('❌ [QCT-BACKFILL] Error:', error);
      res.status(500).json({ message: 'Failed to backfill QCT status', error: error instanceof Error ? error.message : 'Unknown error' });
    }
  });

  // ADMIN: Backfill OZ status for deals that have a census FIPS code but no OZ status.
  // Pass { force: true } in the request body to re-geocode ALL deals from their lat/lng
  // coordinates (refreshes FIPS codes, fixing any decimal-in-tract-code construction bugs)
  // and then re-check OZ status for every deal.
  app.post("/api/admin/backfill-oz-status", isAuthenticated, async (req, res) => {
    try {
      const { ozService } = await import('./ozService');
      const { geocodioService } = await import('./geocodioService');
      const force: boolean = req.body?.force === true;
      const allDeals = (await db.execute(sql`SELECT * FROM deals`).then(r => r.rows)) as any[];

      // When force=true: re-geocode every deal that has coordinates or an address,
      // refresh the stored censusTractFips, then re-run the OZ check.
      // When force=false (default): process all deals missing OZ status (will geocode if no FIPS).
      const toUpdate = force
        ? allDeals
        : allDeals.filter((d: any) => !d.ozStatus || d.ozStatus === '' || d.ozStatus === 'N/A');

      let updated = 0;
      let reGeocoded = 0;
      let skipped = 0;

      for (const deal of toUpdate) {
        try {
          let fips: string | undefined = (deal as any).censusTractFips as string | undefined;

          if (force || !fips) {
            // Try to get FIPS via reverse-geocode (preferred) or forward-geocode
            let geocodeResult: any = null;
            if (deal.latitude && deal.longitude) {
              geocodeResult = await geocodioService.reverseGeocode(
                parseFloat(String(deal.latitude)),
                parseFloat(String(deal.longitude))
              );
            } else {
              const parts: string[] = [];
              if (deal.address) parts.push(deal.address);
              if (deal.city) parts.push(deal.city);
              if (deal.state) parts.push(deal.state);
              if (deal.zip) parts.push(deal.zip);
              if (parts.length >= 2) {
                geocodeResult = await geocodioService.geocodeAddress(parts.join(', '));
              }
            }

            if (geocodeResult?.success && geocodeResult.fips) {
              fips = geocodeResult.fips;
              reGeocoded++;
            }
          }

          if (!fips) { skipped++; continue; }

          const ozResult = await ozService.checkOZStatus(fips);
          await storage.updateDeal(deal.id, {
            ozStatus: ozResult.isOZ ? 'YES' : 'NO',
            censusTractFips: fips,
          });
          console.log(`✅ [OZ-BACKFILL] Deal ${deal.id}: FIPS ${fips} → ${ozResult.isOZ ? 'YES' : 'NO'}${force ? ' (re-geocoded)' : ''}`);
          updated++;
        } catch (err) {
          console.warn(`⚠️ [OZ-BACKFILL] Deal ${deal.id} failed:`, err);
          skipped++;
        }
      }

      res.json({
        message: `OZ backfill complete: ${updated} updated (${reGeocoded} re-geocoded), ${skipped} skipped`,
        updated,
        reGeocoded,
        skipped,
        total: toUpdate.length,
        force,
      });
    } catch (error) {
      console.error('❌ [OZ-BACKFILL] Error:', error);
      res.status(500).json({ message: 'Failed to backfill OZ status', error: error instanceof Error ? error.message : 'Unknown error' });
    }
  });

  // ADMIN: Backfill DDA status for all deals using 2026 HUD DDA data (bulk SQL)
  app.post("/api/admin/backfill-dda-status", isAuthenticated, async (req, res) => {
    try {
      const { checkDDA, extractZipFromAddress } = await import('./ddaLookupService');
      const force: boolean = req.body?.force === true;

      const result = await db.execute(sql`
        SELECT id, state, county, address, zip FROM deals
        ${force ? sql`` : sql`WHERE dda_status IS NULL OR dda_status = 'N/A' OR dda_status = ''`}
        ORDER BY created_at DESC
      `);
      const rows = (result.rows || result) as any[];

      if (rows.length === 0) {
        return res.json({ message: 'All deals already have DDA status.', updated: 0, total: 0 });
      }

      const valuePairs: string[] = [];
      for (const row of rows) {
        const zip = (row.zip as string | null) || extractZipFromAddress((row.address as string) || '');
        const ddaResult = checkDDA(row.state as string, row.county as string, zip);
        const status = ddaResult.isDDA ? ddaResult.ddaType! : 'NO';
        const safeId = String(row.id).replace(/'/g, '');
        const safeStatus = status.replace(/'/g, '');
        valuePairs.push(`('${safeId}', '${safeStatus}')`);
      }

      await db.execute(sql.raw(`
        UPDATE deals AS d
        SET dda_status = v.status
        FROM (VALUES ${valuePairs.join(',')}) AS v(id, status)
        WHERE d.id::text = v.id
      `));

      console.log(`✅ [DDA-BACKFILL] Updated ${valuePairs.length} deals`);
      res.json({ message: `DDA backfill complete: ${valuePairs.length} deals updated`, updated: valuePairs.length, total: rows.length, force });
    } catch (error) {
      console.error('❌ [DDA-BACKFILL] Error:', error);
      res.status(500).json({ message: 'Failed to backfill DDA status', error: error instanceof Error ? error.message : 'Unknown error' });
    }
  });

  // ADMIN: Backfill communications - link orphaned communications to deals
  app.post("/api/admin/backfill-communications", isAuthenticated, async (req, res) => {
    try {
      // SECURITY: Ensure only admin users can run this
      const userEmail = (req.user as any)?.email?.toLowerCase();
      const isAdmin = userEmail?.endsWith('@apexresi.com');
      
      if (!isAdmin) {
        console.log(`🚫 [COMM-BACKFILL] Unauthorized access attempt by ${userEmail}`);
        return res.status(403).json({ message: 'Forbidden: Admin access required' });
      }

      console.log('\n' + '='.repeat(100));
      console.log('🔄 [COMM-BACKFILL] STARTING COMMUNICATION LINKAGE BACKFILL');
      console.log(`   Requested by: ${userEmail}`);
      console.log('='.repeat(100));

      // Get all email/SMS deals
      const allDeals = await db.select({
        id: deals.id,
        address: deals.address,
        brokerId: deals.brokerId,
        createdAt: deals.createdAt,
        submissionMethod: deals.submissionMethod
      })
      .from(deals)
      .where(
        or(
          eq(deals.submissionMethod, 'email'),
          eq(deals.submissionMethod, 'sms')
        )
      );
      
      console.log(`📊 [COMM-BACKFILL] Total email/SMS deals found: ${allDeals.length}`);

      const results = {
        processed: 0,
        linkedByDealId: 0,
        linkedByBrokerId: 0,
        linkedByEmail: 0,
        alreadyLinked: 0,
        noMatch: 0,
        errors: [] as any[]
      };

      for (const deal of allDeals) {
        try {
          results.processed++;
          
          // Check if already has linked communication
          const existing = await db.select({ id: communications.id })
            .from(communications)
            .where(eq(communications.relatedDealId, deal.id))
            .limit(1);
          
          if (existing.length > 0) {
            results.alreadyLinked++;
            continue;
          }

          const dealTime = deal.createdAt ? new Date(deal.createdAt) : null;
          if (!dealTime) {
            console.log(`⚠️ [COMM-BACKFILL] Deal ${deal.id} has no createdAt, skipping`);
            results.noMatch++;
            continue;
          }

          // Use wider time window (60 minutes) for better matching
          const sixtyMinBefore = new Date(dealTime.getTime() - 60 * 60 * 1000);
          const sixtyMinAfter = new Date(dealTime.getTime() + 60 * 60 * 1000);
          const channel = deal.submissionMethod === 'email' ? 'email' : 'sms';

          // Get broker info for searching (works even if broker lookup fails later)
          let brokerEmail: string | null = null;
          let brokerPhone: string | null = null;
          if (deal.brokerId) {
            const broker = await db.select({ email: brokers.email, phone: brokers.phone })
              .from(brokers)
              .where(eq(brokers.id, deal.brokerId))
              .limit(1);
            if (broker.length > 0) {
              brokerEmail = broker[0].email;
              brokerPhone = broker[0].phone;
            }
          }

          // STRATEGY 1: Try to find by brokerId within time window
          if (deal.brokerId) {
            const byBroker = await db.select()
              .from(communications)
              .where(
                and(
                  eq(communications.brokerId, deal.brokerId),
                  eq(communications.direction, 'inbound'),
                  eq(communications.channel, channel),
                  sql`${communications.relatedDealId} IS NULL`,
                  gte(communications.createdAt, sixtyMinBefore),
                  lte(communications.createdAt, sixtyMinAfter)
                )
              )
              .orderBy(desc(communications.createdAt))
              .limit(1);
            
            if (byBroker.length > 0) {
              await db.update(communications)
                .set({ relatedDealId: deal.id })
                .where(eq(communications.id, byBroker[0].id));
              results.linkedByBrokerId++;
              console.log(`✅ [COMM-BACKFILL] Linked comm ${byBroker[0].id} to deal ${deal.id} (by brokerId)`);
              continue;
            }
          }

          // STRATEGY 2: For EMAIL deals - search by email address (even without brokerId)
          if (channel === 'email' && brokerEmail) {
            const byEmail = await db.select()
              .from(communications)
              .where(
                and(
                  eq(communications.email, brokerEmail),
                  eq(communications.direction, 'inbound'),
                  eq(communications.channel, 'email'),
                  sql`${communications.relatedDealId} IS NULL`,
                  gte(communications.createdAt, sixtyMinBefore),
                  lte(communications.createdAt, sixtyMinAfter)
                )
              )
              .orderBy(desc(communications.createdAt))
              .limit(1);
            
            if (byEmail.length > 0) {
              await db.update(communications)
                .set({ relatedDealId: deal.id, brokerId: deal.brokerId })
                .where(eq(communications.id, byEmail[0].id));
              results.linkedByEmail++;
              console.log(`✅ [COMM-BACKFILL] Linked comm ${byEmail[0].id} to deal ${deal.id} (by email)`);
              continue;
            }
          }

          // STRATEGY 3: For SMS deals - search by phone number (even without brokerId)
          if (channel === 'sms' && brokerPhone) {
            const byPhone = await db.select()
              .from(communications)
              .where(
                and(
                  eq(communications.phone, brokerPhone),
                  eq(communications.direction, 'inbound'),
                  eq(communications.channel, 'sms'),
                  sql`${communications.relatedDealId} IS NULL`,
                  gte(communications.createdAt, sixtyMinBefore),
                  lte(communications.createdAt, sixtyMinAfter)
                )
              )
              .orderBy(desc(communications.createdAt))
              .limit(1);
            
            if (byPhone.length > 0) {
              await db.update(communications)
                .set({ relatedDealId: deal.id, brokerId: deal.brokerId })
                .where(eq(communications.id, byPhone[0].id));
              (results as any).linkedByPhone = ((results as any).linkedByPhone || 0) + 1;
              console.log(`✅ [COMM-BACKFILL] Linked comm ${byPhone[0].id} to deal ${deal.id} (by phone)`);
              continue;
            }
          }

          // No match found - log and continue
          results.noMatch++;
          
        } catch (error) {
          results.errors.push({
            dealId: deal.id,
            error: error instanceof Error ? error.message : 'Unknown error'
          });
        }
      }

      console.log('\n' + '='.repeat(100));
      console.log('✅ [COMM-BACKFILL] BACKFILL COMPLETE');
      console.log(`   Total Processed: ${results.processed}`);
      console.log(`   Already Linked: ${results.alreadyLinked}`);
      console.log(`   Linked by BrokerId: ${results.linkedByBrokerId}`);
      console.log(`   Linked by Email: ${results.linkedByEmail}`);
      console.log(`   Linked by Phone: ${(results as any).linkedByPhone || 0}`);
      console.log(`   No Match Found: ${results.noMatch}`);
      console.log('='.repeat(100) + '\n');

      res.json({
        success: true,
        message: 'Communication linkage backfill complete',
        ...results,
        linkedByPhone: (results as any).linkedByPhone || 0
      });

    } catch (error) {
      console.error('❌ [COMM-BACKFILL] Backfill error:', error);
      res.status(500).json({
        message: "Failed to backfill communications",
        error: error instanceof Error ? error.message : 'Unknown error'
      });
    }
  });

  // Update deal status (analyst actions)
  app.patch("/api/deals/:id", isAuthenticated, async (req, res) => {
    try {
      const { id } = req.params;
      const userId = (req.user as any)?.id;
      const updateData = req.body;

      // Debug logging for productTypes updates
      if ('productTypes' in updateData) {
        console.log(`🔧 PATCH /api/deals/${id} - productTypes update requested:`, updateData.productTypes);
      }

      const deal = await storage.getDealById(id);
      
      // Debug logging for dealType updates
      if ('dealType' in updateData) {
        console.log(`🔄 PATCH /api/deals/${id} - dealType update requested:`, {
          currentDealType: deal?.dealType,
          newDealType: updateData.dealType,
          triggerReclassification: updateData.triggerReclassification
        });
      }
      if (!deal) {
        return res.status(404).json({ message: "Deal not found" });
      }
      
      // DEAL TYPE CHANGE DETECTION: Clear rejection reason and reset classification
      // When switching between Land <-> Acquisition, the old rejection reasons don't apply
      const dealTypeIsChanging = 'dealType' in updateData && updateData.dealType !== deal.dealType;
      if (dealTypeIsChanging) {
        console.log(`🔄 DEAL TYPE CHANGE DETECTED for deal ${id}:`);
        console.log(`   Old Type: ${deal.dealType} → New Type: ${updateData.dealType}`);
        console.log(`   Current Classification: ${deal.classification}`);
        console.log(`   Current Rejection Reason: ${deal.rejectionReason ? deal.rejectionReason.substring(0, 50) + '...' : 'None'}`);
        
        // Clear rejection reason since it was based on old deal type criteria
        if (deal.rejectionReason) {
          console.log(`   ✅ Clearing old rejection reason (was for ${deal.dealType} deal)`);
          updateData.rejectionReason = null;
        }
        
        // Reset classification to unclassified for re-evaluation with new criteria
        if (deal.classification && deal.classification !== 'unclassified') {
          console.log(`   ✅ Resetting classification from '${deal.classification}' to 'unclassified'`);
          updateData.classification = 'unclassified';
          updateData.classificationDisplay = 'UNCLASSIFIED';
        }
        
        console.log(`   ℹ️ Deal will be re-evaluated with ${updateData.dealType} criteria`);
      }

      // Allowed fields for analyst editing
      const allowedFields = [
        'unitCount', 'assignedAnalyst', 'assignedJrAnalyst', 'assignedDeveloper', 'assignedPartner',
        'developer', 'partner', 'productType', 'productTypes', 'msa', 'acreage', 'dua', 'zoning', 'askingPrice',
        'rentsPerUnit', 'totalCost', 'marginsPerUnit', 'irr',
        'brokerName', 'brokerEmail', 'brokerPhone', 'marketsCovered', 'markets', 'brokerId',
        'brokerFirstName', 'brokerLastName',
        'suiDate', 'siteEntryDate', 'statusNotes',
        'status', 'analystNotes', 'classification', 'address', 'sizeAcres', 
        'sewerAvailable', 'hasEntitlements', 'topRentPSF', 'brokerNotes',
        // Missing fields that were being filtered out
        'nextSteps', 'population55Plus5Mile', 'income75Plus55Plus', 'demographicsNotes',
        'yieldOnCost', 'automatedYoc', 'underwritingState', 'propertyName', 'projectedRentPerSF', 'rejectionReason', 'documentUrls',
        'qctStatus', 'analystDocumentUrls',
        // Dec 9, 2025: Pending details workflow fields
        'addressConfidence', 'dealRoomUrl', 'city', 'state', 'zip',
        // Dec 15, 2025: Next Assignee and Deal Step dropdown fields
        'nextAssignee', 'dealStep',
        // Dec 16, 2025: Manual coordinate override for geocoding errors
        'manualLatitude', 'manualLongitude', 'manualCoordsReason',
        // Dec 22, 2025: Priority rating (1-5)
        'priority',
        // Jan 7, 2026: Deal type (land/acquisition)
        'dealType', 'yearBuilt', 'vintage',
        // Jan 9, 2026: Classification display for deal type changes
        'classificationDisplay',
        // Mar 2026: Excel/SharePoint model link
        'excelModelUrl',
        // Mar 2026: Opportunity Zone status (manual override)
        'ozStatus',
        // Apex deal flag + notes
        'apex', 'apexNotes',
        // Developer summary for partner emails
        'developerSummary',
        // Wetland/environmental notes for developer deal packets
        'wetlandNotes',
        // Net developable acres (analyst-entered, excludes wetlands/easements)
        'netDevelopableAcres',
        // IC memo deal summary narrative
        'dealSummary',
        // Max units allowed by zoning (analyst-entered)
        'maxUnitsByZoning',
        // Excel-extracted underwriting fields
        'marketCapRate', 'seniorLoanPct',
      ];

      // Filter updates to only allowed fields
      const filteredUpdates: any = {};
      Object.keys(updateData).forEach(key => {
        if (allowedFields.includes(key)) {
          // Special handling for array fields that need sanitization
          if (key === 'documentUrls') {
            filteredUpdates[key] = sanitizeStringArray(updateData[key] || []);
          } else if (key === 'productTypes') {
            filteredUpdates[key] = sanitizeStringArray(updateData[key] || []);
          } else if (key === 'analystDocumentUrls') {
            filteredUpdates[key] = sanitizeStringArray(updateData[key] || []);
          } else {
            filteredUpdates[key] = updateData[key];
          }
        }
      });

      // Debug logging for assignedJrAnalyst specifically
      if ('assignedJrAnalyst' in updateData) {
        console.log(`🔧 DEBUG: assignedJrAnalyst update for deal ${id}:`, {
          originalValue: deal.assignedJrAnalyst,
          newValue: updateData.assignedJrAnalyst,
          inFilteredUpdates: filteredUpdates.assignedJrAnalyst
        });
      }

      // Debug logging for productTypes filtering
      if ('productTypes' in updateData) {
        console.log(`🔧 productTypes included in allowedFields: ${allowedFields.includes('productTypes')}`);
        console.log(`🔧 productTypes in filteredUpdates:`, filteredUpdates.productTypes);
      }
      
      // FIX (Jan 15, 2026): Debug logging for vintage updates
      if ('vintage' in updateData) {
        console.log(`🗓️ PATCH /api/deals/${id} - vintage update:`, {
          originalValue: updateData.vintage,
          type: typeof updateData.vintage,
          inFilteredUpdates: filteredUpdates.vintage,
          isInAllowedFields: allowedFields.includes('vintage')
        });
      }

      await logAuditTrail({
        userId,
        action: `Updated deal ${id}`,
        entityType: 'DEAL',
        tableName: 'deals',
        recordId: id,
        changedBy: userId || 'anonymous',
        entityId: id,
        details: {
          dealId: id,
          updatedFields: Object.keys(filteredUpdates),
          updateData: filteredUpdates
        }
      });

      // Add tracking fields
      filteredUpdates.reviewedBy = userId;
      filteredUpdates.reviewedAt = new Date();
      filteredUpdates.updatedAt = new Date();

      // AUTO-ASSIGN TEAM BASED ON PRODUCT TYPE CHANGE
      if ('productTypes' in filteredUpdates && filteredUpdates.productTypes) {
        console.log(`🎯 Product type changed for deal ${id}, auto-assigning team...`);
        
        // Map frontend values to backend routing values
        const mappedProductTypes = filteredUpdates.productTypes.map((type: string) => {
          switch(type.toLowerCase()) {
            case 'conventional': return 'Conventional Apartments';
            case 'active-adult': return 'Active Adult';
            case 'btr': return 'BTR';
            case 'lot': return 'Lot Development';
            default: return type;
          }
        });
        
        const routing = await getAutomaticRouting(mappedProductTypes, deal.address || '');
        
        // Auto-assign team members if not manually set
        if (routing.analyst && !filteredUpdates.assignedAnalyst) {
          filteredUpdates.assignedAnalyst = routing.analyst;
        }
        if (routing.developer && !filteredUpdates.assignedDeveloper) {
          filteredUpdates.assignedDeveloper = routing.developer;
        }
        if (routing.partner && !filteredUpdates.assignedPartner) {
          filteredUpdates.assignedPartner = routing.partner;
        }
        
        console.log(`✅ Team auto-assigned: Analyst=${routing.analyst}, Developer=${routing.developer}, Partner=${routing.partner}`);
      }

      // USER FIX (Dec 11): Austin assigned to ALL deals (green, yellow, red)
      // Green deals also get same team assignments as yellow
      if ('classification' in filteredUpdates && (filteredUpdates.classification === 'yellow' || filteredUpdates.classification === 'green')) {
        console.log(`🎯 Classification changed to ${filteredUpdates.classification} for deal ${id}, auto-assigning Austin Blondell as senior analyst...`);
        filteredUpdates.assignedAnalyst = 'Austin Blondell';
        console.log(`✅ Austin Blondell auto-assigned as senior analyst`);
      }
      
      // Always assign Austin to red deals too
      if ('classification' in filteredUpdates && filteredUpdates.classification === 'red') {
        console.log(`🎯 Classification changed to red for deal ${id}, auto-assigning Austin Blondell...`);
        filteredUpdates.assignedAnalyst = 'Austin Blondell';
        console.log(`✅ Austin Blondell auto-assigned to red deal`);
      }

      // Handle broker field updates - these update the broker record, not the deal
      const brokerFieldsToUpdate: any = {};
      if ('brokerEmail' in filteredUpdates) {
        brokerFieldsToUpdate.email = filteredUpdates.brokerEmail || null;
        delete filteredUpdates.brokerEmail;
      }
      if ('brokerPhone' in filteredUpdates) {
        brokerFieldsToUpdate.phone = filteredUpdates.brokerPhone || null;
        delete filteredUpdates.brokerPhone;
      }
      if ('marketsCovered' in filteredUpdates) {
        // Normalize marketsCovered to array
        const markets = filteredUpdates.marketsCovered;
        if (!markets || markets === '') {
          brokerFieldsToUpdate.marketsCovered = [];
        } else if (typeof markets === 'string') {
          brokerFieldsToUpdate.marketsCovered = markets.split(',').map((m: string) => m.trim()).filter(Boolean);
        } else if (Array.isArray(markets)) {
          brokerFieldsToUpdate.marketsCovered = markets;
        }
        delete filteredUpdates.marketsCovered;
      }
      if ('brokerFirstName' in filteredUpdates) {
        brokerFieldsToUpdate.firstName = filteredUpdates.brokerFirstName || null;
        delete filteredUpdates.brokerFirstName;
      }
      if ('brokerLastName' in filteredUpdates) {
        brokerFieldsToUpdate.lastName = filteredUpdates.brokerLastName || null;
        delete filteredUpdates.brokerLastName;
      }
      if ('brokerName' in filteredUpdates && !brokerFieldsToUpdate.firstName) {
        // Parse broker name into first/last
        const nameParts = (filteredUpdates.brokerName || '').trim().split(' ');
        brokerFieldsToUpdate.firstName = nameParts[0] || null;
        brokerFieldsToUpdate.lastName = nameParts.slice(1).join(' ') || null;
        delete filteredUpdates.brokerName;
      }

      // Update broker if there are broker fields to update
      // Broker record is shared by brokerId across ALL of that broker's deals, so
      // updating it here (rather than the individual deal row) automatically keeps
      // every other deal from this broker in sync — they all read from this same record.
      if (Object.keys(brokerFieldsToUpdate).length > 0) {
        if (deal.brokerId) {
          console.log(`🔧 Updating broker ${deal.brokerId} with fields:`, brokerFieldsToUpdate);
          try {
            await storage.updateBroker(deal.brokerId, brokerFieldsToUpdate);
            console.log(`✅ Broker ${deal.brokerId} updated successfully`);
          } catch (brokerError) {
            console.error(`⚠️ Failed to update broker ${deal.brokerId}:`, brokerError);
          }
        } else if (brokerFieldsToUpdate.firstName || brokerFieldsToUpdate.email || brokerFieldsToUpdate.phone) {
          // No broker on this deal yet — create one and link it
          console.log(`🆕 No broker on deal ${id} — creating new broker:`, brokerFieldsToUpdate);
          try {
            const newBroker = await storage.createBroker({
              firstName: brokerFieldsToUpdate.firstName || '',
              lastName: brokerFieldsToUpdate.lastName || '',
              email: brokerFieldsToUpdate.email || null,
              phone: brokerFieldsToUpdate.phone || null,
              marketsCovered: brokerFieldsToUpdate.marketsCovered || [],
            });
            filteredUpdates.brokerId = newBroker.id;
            console.log(`✅ New broker created: ${newBroker.id} — linking to deal ${id}`);
          } catch (createError) {
            console.error(`⚠️ Failed to create broker for deal ${id}:`, createError);
          }
        }
      }

      let updatedDeal;
      try {
        updatedDeal = await storage.updateDeal(id, filteredUpdates);

        // Debug logging for productTypes after database update
        if ('productTypes' in updateData) {
          console.log(`✅ Database update completed for deal ${id} - productTypes in response:`, updatedDeal.productTypes);
        }
        
        // Debug logging for dealType after database update
        if ('dealType' in updateData) {
          console.log(`✅ PATCH /api/deals/${id} - dealType update completed:`, {
            requestedValue: updateData.dealType,
            actualValueInDB: updatedDeal.dealType,
            wasInFilteredUpdates: 'dealType' in filteredUpdates,
            filteredUpdatesKeys: Object.keys(filteredUpdates)
          });
        }

        // Debug logging for assignedJrAnalyst after database update
        if ('assignedJrAnalyst' in updateData) {
          console.log(`✅ DEBUG: assignedJrAnalyst database update completed for deal ${id}:`, {
            requestedValue: updateData.assignedJrAnalyst,
            actualValue: updatedDeal.assignedJrAnalyst
          });
        }
      } catch (error) {
        console.error(`❌ Database update failed for deal ${id}:`, error);
        if ('assignedJrAnalyst' in updateData) {
          console.error(`❌ DEBUG: assignedJrAnalyst update failed for deal ${id}:`, {
            requestedValue: updateData.assignedJrAnalyst,
            error: (error as Error).message
          });
        }
        return res.status(500).json({ 
          message: "Failed to update deal", 
          error: (error as Error).message,
          field: 'assignedJrAnalyst' in updateData ? 'assignedJrAnalyst' : 'unknown'
        });
      }

      // INSTANT RESPONSE - Return immediately to frontend for fast UI updates
      // Include reclassificationPending flag if deal type change triggered reclassification
      const dealTypeChanged = 'dealType' in filteredUpdates && filteredUpdates.dealType !== deal.dealType;
      const willReclassify = dealTypeChanged || updateData.triggerReclassification;
      
      res.json({
        ...updatedDeal,
        reclassificationPending: willReclassify ? true : undefined
      });

      // BACKGROUND PROCESSING - Handle slow operations asynchronously without blocking the response
      setImmediate(async () => {
        try {
          // DEAL TYPE CHANGE - Trigger re-classification with appropriate criteria
          if (willReclassify) {
            console.log(`🔄 Deal type changed for deal ${id} from ${deal.dealType} to ${filteredUpdates.dealType}, triggering re-classification...`);
            try {
              const { AutoClassificationEngine } = await import('./autoClassificationEngine');
              const freshDeal = await storage.getDealById(id);
              if (freshDeal) {
                const result = await AutoClassificationEngine.classifyDeal(freshDeal);
                console.log(`✅ Re-classification complete for deal ${id}:`, {
                  newClassification: result.classification,
                  reason: result.rejectionReason || 'N/A'
                });
                // Update deal with new classification
                await storage.updateDeal(id, {
                  classification: result.classification,
                  classificationReason: result.rejectionReason || null,
                  aiExplanatoryNotes: result.aiExplanatoryNotes || null
                });
              }
            } catch (classifyError) {
              console.error(`❌ Re-classification failed for deal ${id}:`, classifyError);
            }
          }
          
          const statusChanged = filteredUpdates.status && filteredUpdates.status !== deal.status;
          const classificationChanged = filteredUpdates.classification && filteredUpdates.classification !== deal.classification;
          
          // Handle status/classification change notifications
          if ((statusChanged || classificationChanged) && deal.brokerId) {
            const broker = await storage.getBrokerById(deal.brokerId);
            if (broker) {
              const { EventDispatchService } = await import('./eventDispatch');
              
              // Get product type and analyst info for template variables
              const { getAnalystInfo } = await import('./landLinqTemplates');
              const productTypes = (updatedDeal.productTypes as string[]) || [];
              const primaryProductType = productTypes[0] || 'Conventional Apartments';
              const analystInfo = getAnalystInfo(updatedDeal.classification || 'yellow', primaryProductType);
              
              const eventPayload = {
                brokerName: broker.firstName ? `${broker.firstName} ${broker.lastName}` : broker.brokerage || 'Broker',
                brokerEmail: broker.email || '',
                brokerPhone: broker.phone || undefined,
                propertyAddress: updatedDeal.address || 'Property',
                address: updatedDeal.address || 'Property', // Add both address formats for template compatibility
                dealValue: 'TBD', // askingPrice removed from schema
                dealId: updatedDeal.id,
                brokerId: broker.id,
                productType: primaryProductType, // FIXED: Add product type for template
                analystName: analystInfo.analystName, // FIXED: Add analyst name for template
                classification: updatedDeal.classification,
                rejectionReason: updatedDeal.rejectionReason || 'Does not meet acquisition criteria'
              };
              
              // Determine which event to dispatch based on status/classification
              // Normalise to canonical colours (handle high_priority/clear_no/potential aliases)
              const newClass = filteredUpdates.classification;
              const oldClass = deal.classification;
              const isRed = newClass === 'red' || newClass === 'clear_no';
              const isGreen = newClass === 'green' || newClass === 'high_priority';
              const isYellow = newClass === 'yellow' || newClass === 'yellow_potential' || newClass === 'potential';
              const wasRed = oldClass === 'red' || oldClass === 'clear_no';
              const wasGreen = oldClass === 'green' || oldClass === 'high_priority';
              const wasYellow = oldClass === 'yellow' || oldClass === 'yellow_potential' || oldClass === 'potential';

              let eventToDispatch: string | null = null;

              if (isRed && !wasRed) {
                eventToDispatch = 'status_rejected';
              } else if (isGreen && !wasGreen) {
                eventToDispatch = 'status_pursuing';
              } else if (isYellow && !wasYellow) {
                eventToDispatch = 'status_under_review';
              } else if (newClass === 'unclassified' && oldClass !== 'unclassified') {
                eventToDispatch = 'status_unclassified';
              } else if (filteredUpdates.status === 'contract_negotiation' && deal.status !== 'contract_negotiation') {
                eventToDispatch = 'loi_sent';
              }
              
              if (eventToDispatch) {
                console.log(`🎯 Dispatching ${eventToDispatch} event for deal ${id}`);
                const result = await EventDispatchService.emit(eventToDispatch as any, eventPayload);
                console.log(`✅ Deal status event dispatched: email=${result.emailSent}, sms=${result.smsSent}`);
                
                // Log communications that were sent
                if (result.emailSent && broker.email) {
                  await storage.createCommunication({
                    brokerId: broker.id,
                    relatedDealId: updatedDeal.id,
                    channel: "email",
                    direction: "outbound",
                    rawText: `${eventToDispatch} notification sent via template system`,
                    subject: `Deal Update - ${updatedDeal.address}`,
                    message: `${eventToDispatch} notification sent via template system`,
                  });
                }
                
                if (result.smsSent && broker.phone) {
                  await storage.createCommunication({
                    brokerId: broker.id,
                    relatedDealId: updatedDeal.id,
                    channel: "sms",
                    direction: "outbound",
                    rawText: `${eventToDispatch} SMS notification sent via template system`,
                    message: `${eventToDispatch} SMS notification sent via template system`,
                  });
                }
              }
            }
          }

          // Check if broker made changes to deal details (not just status/classification updates)
          const brokerMadeChanges = updateData.address !== undefined || updateData.price !== undefined || 
            updateData.sizeAcres !== undefined || updateData.zoning !== undefined || updateData.sewerAvailable !== undefined || 
            updateData.hasEntitlements !== undefined || updateData.topRentPSF !== undefined || updateData.brokerNotes !== undefined;

          // If broker made changes, notify team members (analyst, developer, partner)
          if (brokerMadeChanges) {
            const teamNotifications = [];
            
            if (deal.assignedAnalyst) {
              teamNotifications.push({
                email: deal.assignedAnalyst,
                role: "Analyst"
              });
            }
            if (deal.assignedDeveloper) {
              teamNotifications.push({
                email: deal.assignedDeveloper,
                role: "Developer"
              });
            }
            if (deal.assignedPartner) {
              teamNotifications.push({
                email: deal.assignedPartner,
                role: "Partner"
              });
            }

            // Send notifications to team members
            for (const teamMember of teamNotifications) {
              const teamTemplate = {
                subject: `Deal Update Alert - ${deal.address}`,
                message: `Hello,\n\nA deal has been updated by the broker:\n\n` +
                  `Property: ${updatedDeal.address}\n` +
                  `Broker: ${deal.brokerId}\n` +
                  `Updated: ${new Date().toLocaleString()}\n\n` +
                  `Changes may include updates to pricing, property details, or additional notes. ` +
                  `Please review the updated deal details in your dashboard.\n\n` +
                  `Best regards,\nCatalyst Acquisitions`
              };

              await storage.createCommunication({
                brokerId: deal.brokerId,
                relatedDealId: deal.id,
                channel: "email",
                direction: "outbound",
                rawText: teamTemplate.message,
                subject: teamTemplate.subject,
                message: teamTemplate.message,
                recipientEmail: teamMember.email,
              });
            }
          }
          
          console.log(`🔄 Background processing completed for deal update ${id}`);
        } catch (backgroundError) {
          console.error(`❌ Background processing failed for deal ${id}:`, backgroundError);
        }
      });

      console.log(`✅ Deal update completed for ${id} - response sent immediately, notifications processing in background`);
    } catch (error) {
      console.error("Error updating deal:", error);
      res.status(500).json({ message: "Failed to update deal" });
    }
  });

