  // Batch public listing validation for multiple deals
  app.post("/api/deals/public-listing-batch", isAuthenticated, async (req, res) => {
    try {
      const { dealIds } = req.body;
      const user = req.user as any;
      const isAnalyst = (user?.claims?.email || user?.email || '').endsWith('@apexresi.com');
      
      if (!isAnalyst) {
        return res.status(403).json({ error: "Access denied" });
      }

      if (!dealIds || !Array.isArray(dealIds)) {
        return res.status(400).json({ error: "dealIds array is required" });
      }

      if (dealIds.length > 10) {
        return res.status(400).json({ error: "Maximum 10 deals can be processed at once" });
      }

      console.log(`🔄 Starting batch public listing validation for ${dealIds.length} deals`);

      const results = [];
      const errors = [];

      for (const dealId of dealIds) {
        try {
          const deal = await storage.getDealById(dealId);
          if (!deal) {
            errors.push({ dealId, error: "Deal not found" });
            continue;
          }

          const validationResult = await publicListingValidationService.validateDealPublicListings(
            dealId,
            {
              forceRefresh: false,
              triggeredBy: 'batch_validation',
              triggeredByUserId: user.id
            }
          );

          results.push({
            dealId,
            address: deal.address,
            validationResult,
            summary: {
              isPubliclyListed: validationResult.flags.isPubliclyListed,
              confidence: validationResult.flags.publicListingConfidence,
              platformsFound: validationResult.flags.platformsFound,
              marketExposure: validationResult.flags.marketExposure
            }
          });

        } catch (error) {
          console.error(`❌ Validation failed for deal ${dealId}:`, error);
          errors.push({ 
            dealId, 
            error: error instanceof Error ? error.message : "Unknown error" 
          });
        }
      }

      console.log(`✅ Batch validation completed: ${results.length} successful, ${errors.length} errors`);

      res.json({
        success: true,
        processed: dealIds.length,
        successful: results.length,
        errorCount: errors.length,
        results,
        errors: errors
      });

    } catch (error) {
      console.error(`❌ Batch public listing validation failed:`, error);
      res.status(500).json({ 
        error: "Batch validation failed",
        message: error instanceof Error ? error.message : "Unknown error"
      });
    }
  });

