  // Batch operations for communications
  app.post("/api/communications/batch", isAuthenticated, async (req, res) => {
    try {
      const { operation, communications, data } = req.body;
      
      if (!operation) {
        return res.status(400).json({ error: "Operation type is required" });
      }

      let results = [];
      let successCount = 0;
      let errorCount = 0;

      switch (operation) {
        case 'create':
          if (!Array.isArray(communications)) {
            return res.status(400).json({ error: "Communications array is required for batch creation" });
          }
          
          // Batch create communications
          for (const commData of communications) {
            try {
              const validatedData = insertCommunicationSchema.parse(commData);
              const newComm = await storage.createCommunication(validatedData);
              results.push({ success: true, communication: newComm });
              successCount++;
            } catch (error) {
              results.push({ 
                success: false, 
                error: error instanceof Error ? error.message : 'Unknown error',
                brokerId: commData.brokerId 
              });
              errorCount++;
            }
          }
          break;

        case 'bulk-notify':
          // Send bulk notifications to multiple brokers
          if (!Array.isArray(data?.brokerIds) || !data?.template) {
            return res.status(400).json({ error: "Broker IDs array and template are required" });
          }
          
          for (const brokerId of data.brokerIds) {
            try {
              const commData = {
                brokerId,
                channel: (data.template.type === 'sms' ? 'sms' : 'email') as 'email' | 'sms',
                direction: 'outbound' as const,
                rawText: data.template.message || '',
                subject: data.template.subject,
                message: data.template.message,
                email: data.template.recipientEmail
              };
              
              const newComm = await storage.createCommunication(commData);
              results.push({ success: true, communication: newComm });
              successCount++;
            } catch (error) {
              results.push({ 
                success: false, 
                error: error instanceof Error ? error.message : 'Unknown error',
                brokerId 
              });
              errorCount++;
            }
          }
          break;

        case 'status-update':
          // Batch update communication status (mark as sent, delivered, etc.)
          if (!Array.isArray(data?.communicationIds) || !data?.status) {
            return res.status(400).json({ error: "Communication IDs array and status are required" });
          }
          
          for (const commId of data.communicationIds) {
            try {
              // Note: This would require implementing updateCommunication in storage
              // For now, we'll just track the attempt
              results.push({ 
                success: true, 
                communicationId: commId,
                status: data.status 
              });
              successCount++;
            } catch (error) {
              results.push({ 
                success: false, 
                error: error instanceof Error ? error.message : 'Unknown error',
                communicationId: commId 
              });
              errorCount++;
            }
          }
          break;

        default:
          return res.status(400).json({ error: "Invalid operation type" });
      }

      res.json({
        success: true,
        operation,
        results,
        summary: {
          total: results.length,
          successful: successCount,
          failed: errorCount
        },
        timestamp: new Date().toISOString()
      });

    } catch (error) {
      console.error("Communication batch operation error:", error);
      res.status(500).json({ error: "Failed to perform batch operation" });
    }
  });

  // MESSAGING DASHBOARD ROUTES - Two-way SMS conversations
  
