  type ListingReviewScope = {
    isPlatformAdmin: boolean;
    userId: string;
    assignedProfileIds: string[];
  };

  async function getListingReviewScope(req: any, res: any): Promise<ListingReviewScope | null> {
    const email = String(req.user?.email || req.user?.claims?.email || "").trim().toLowerCase();
    const userId = String(req.user?.id || req.user?.claims?.sub || "").trim();
    if (email.endsWith("@apexresi.com")) {
      return { isPlatformAdmin: true, userId, assignedProfileIds: [] };
    }
    if (String(req.user?.role || "").toUpperCase() !== "ANALYST" || !userId) {
      res.status(403).json({ error: "Listing Review access requires an assigned analyst account" });
      return null;
    }
    const assignments = await db.execute(sql`
      SELECT developer_profile_id
      FROM analyst_profile_assignments
      WHERE user_id = ${userId}
    `);
    return {
      isPlatformAdmin: false,
      userId,
      assignedProfileIds: (assignments.rows as any[]).map((row) => String(row.developer_profile_id)),
    };
  }

  app.get("/api/admin/master-pipeline", isAuthenticated, requirePlatformAdmin, async (req: any, res) => {
    try {
      const profileId = String(req.query.profileId || "").trim();
      const state = String(req.query.state || "").trim();
      const county = String(req.query.county || "").trim();
      const search = String(req.query.search || "").trim();
      const classification = String(req.query.classification || "").trim().toLowerCase();
      const conditions: any[] = [];

      if (profileId && profileId !== "all") {
        conditions.push(eq(partnerDeveloperSends.developerProfileId, profileId));
      }
      if (state && state !== "all") {
        conditions.push(sql`LOWER(COALESCE(${deals.state}, '')) = LOWER(${state})`);
      }
      if (county && county !== "all") {
        conditions.push(sql`LOWER(COALESCE(${deals.county}, '')) = LOWER(${county})`);
      }
      if (search) {
        const term = `%${search}%`;
        conditions.push(sql`(
          ${deals.address} ILIKE ${term}
          OR COALESCE(${deals.propertyName}, '') ILIKE ${term}
          OR COALESCE(${deals.city}, '') ILIKE ${term}
        )`);
      }
      if (classification === "pursuing") {
        conditions.push(eq(partnerDeveloperSends.greenFlaggedByDeveloper, true));
      } else if (classification === "review") {
        conditions.push(eq(partnerDeveloperSends.classification, "review"));
      } else if (classification === "passed") {
        conditions.push(sql`(
          ${partnerDeveloperSends.id} IS NOT NULL
          AND COALESCE(${partnerDeveloperSends.greenFlaggedByDeveloper}, false) = false
          AND COALESCE(${partnerDeveloperSends.classification}, '') <> 'review'
        )`);
      }

      const [rows, profiles] = await Promise.all([
        db
          .select({
            dealId: deals.id,
            dealNumber: deals.dealNumber,
            propertyName: deals.propertyName,
            address: deals.address,
            city: deals.city,
            county: deals.county,
            state: deals.state,
            askingPrice: deals.askingPrice,
            sizeAcres: deals.sizeAcres,
            unitCount: deals.unitCount,
            maxUnitsByZoning: deals.maxUnitsByZoning,
            dealType: deals.dealType,
            productTypes: deals.productTypes,
            dealStatus: deals.status,
            dealClassification: deals.classification,
            dealCreatedAt: deals.createdAt,
            dealUpdatedAt: deals.updatedAt,
            sendId: partnerDeveloperSends.id,
            sendStatus: partnerDeveloperSends.status,
            sendClassification: partnerDeveloperSends.classification,
            sentAt: partnerDeveloperSends.sentAt,
            matchedAt: partnerDeveloperSends.matchedAt,
            greenFlaggedByDeveloper: partnerDeveloperSends.greenFlaggedByDeveloper,
            greenFlaggedAt: partnerDeveloperSends.greenFlaggedAt,
            profileId: developerProfiles.id,
            profileCompanyName: developerProfiles.companyName,
            profileSlug: developerProfiles.slug,
            profileIsActive: developerProfiles.isActive,
          })
          .from(deals)
          .leftJoin(partnerDeveloperSends, eq(partnerDeveloperSends.dealId, deals.id))
          .leftJoin(developerProfiles, eq(developerProfiles.id, partnerDeveloperSends.developerProfileId))
          .where(conditions.length ? and(...conditions) : undefined)
          .orderBy(desc(deals.createdAt), desc(partnerDeveloperSends.sentAt)),
        db
          .select({
            id: developerProfiles.id,
            companyName: developerProfiles.companyName,
            slug: developerProfiles.slug,
            isActive: developerProfiles.isActive,
          })
          .from(developerProfiles)
          .orderBy(developerProfiles.companyName),
      ]);

      const masterPipeline = rows.map((row) => {
        const hasSend = Boolean(row.sendId);
        const pipelineStatus = !hasSend
          ? "not_sent"
          : row.greenFlaggedByDeveloper
            ? "pursuing"
            : row.sendClassification === "review"
              ? "review"
              : "passed";

        return {
          id: row.sendId || row.dealId,
          pipelineStatus,
          classification: row.sendClassification || null,
          dealClassification: row.dealClassification || null,
          sent: hasSend,
          deal: {
            id: row.dealId,
            dealNumber: row.dealNumber,
            propertyName: row.propertyName,
            address: row.address,
            city: row.city,
            county: row.county,
            state: row.state,
            askingPrice: row.askingPrice,
            sizeAcres: row.sizeAcres,
            unitCount: row.unitCount,
            maxUnitsByZoning: row.maxUnitsByZoning,
            dealType: row.dealType,
            productTypes: row.productTypes,
            status: row.dealStatus,
            classification: row.dealClassification,
            createdAt: row.dealCreatedAt,
            updatedAt: row.dealUpdatedAt,
          },
          send: hasSend
            ? {
                id: row.sendId,
                status: row.sendStatus,
                classification: row.sendClassification,
                sentAt: row.sentAt,
                matchedAt: row.matchedAt,
                greenFlaggedByDeveloper: row.greenFlaggedByDeveloper,
                greenFlaggedAt: row.greenFlaggedAt,
              }
            : null,
          profile: row.profileId
            ? {
                id: row.profileId,
                companyName: row.profileCompanyName,
                slug: row.profileSlug,
                isActive: row.profileIsActive,
              }
            : null,
        };
      });

      return res.json({
        deals: masterPipeline,
        total: masterPipeline.length,
        profiles,
        filters: {
          states: Array.from(new Set(rows.map((row) => row.state).filter(Boolean))).sort(),
          counties: Array.from(new Set(rows.map((row) => row.county).filter(Boolean))).sort(),
        },
      });
    } catch (error: any) {
      console.error("[admin master pipeline GET] Error:", error);
      return res.status(500).json({ error: "Failed to load the master pipeline" });
    }
  });

  app.get("/api/admin/analytics/by-profile", isAuthenticated, requirePlatformAdmin, async (_req: any, res) => {
    try {
      const result = await db.execute(sql`
        WITH scoped_sends AS (
          SELECT
            pds.*,
            COALESCE(pds.developer_profile_id, pd.developer_profile_id) AS resolved_profile_id
          FROM partner_developer_sends pds
          LEFT JOIN partner_developers pd ON pd.id = pds.developer_id
          WHERE COALESCE(pds.developer_profile_id, pd.developer_profile_id) IS NOT NULL
        )
        SELECT
          p.id,
          p.company_name,
          p.slug,
          p.logo_url,
          p.is_active,
          COALESCE(deal_stats.total_deals, 0) AS total_deals,
          COALESCE(deal_stats.passed_deals, 0) AS passed_deals,
          COALESCE(deal_stats.review_deals, 0) AS review_deals,
          COALESCE(deal_stats.pursuing_deals, 0) AS pursuing_deals,
          COALESCE(deal_stats.bulk_imported_deals, 0) AS bulk_imported_deals,
          COALESCE(deal_stats.sourced_deals, 0) AS sourced_deals,
          COALESCE(contact_stats.crm_contact_count, 0) AS crm_contact_count,
          COALESCE(outreach_stats.sent, 0) AS outreach_sent,
          COALESCE(outreach_stats.opens, 0) AS outreach_opens,
          COALESCE(outreach_stats.clicks, 0) AS outreach_clicks,
          COALESCE(outreach_stats.replies, 0) AS outreach_replies,
          GREATEST(
            p.updated_at,
            deal_stats.last_deal_activity,
            contact_stats.last_contact_activity,
            outreach_stats.last_outreach_activity,
            user_stats.last_user_activity
          ) AS last_activity_at
        FROM developer_profiles p
        LEFT JOIN LATERAL (
          SELECT
            COUNT(*) AS total_deals,
            COUNT(*) FILTER (
              WHERE COALESCE(s.green_flagged_by_developer, false) = false
                AND COALESCE(s.classification, '') <> 'review'
            ) AS passed_deals,
            COUNT(*) FILTER (
              WHERE COALESCE(s.green_flagged_by_developer, false) = false
                AND COALESCE(s.classification, '') = 'review'
            ) AS review_deals,
            COUNT(*) FILTER (
              WHERE COALESCE(s.green_flagged_by_developer, false) = true
            ) AS pursuing_deals,
            COUNT(*) FILTER (
              WHERE d.source = 'developer_import' OR d.submission_method = 'developer_import'
            ) AS bulk_imported_deals,
            COUNT(*) FILTER (
              WHERE COALESCE(d.source, '') <> 'developer_import'
                AND COALESCE(d.submission_method, '') <> 'developer_import'
            ) AS sourced_deals,
            MAX(COALESCE(s.green_flagged_at, s.sent_at, s.matched_at, d.updated_at, d.created_at)) AS last_deal_activity
          FROM scoped_sends s
          INNER JOIN deals d ON d.id = s.deal_id
          WHERE s.resolved_profile_id = p.id
        ) deal_stats ON true
        LEFT JOIN LATERAL (
          SELECT
            COUNT(*) AS crm_contact_count,
            MAX(COALESCE(b.last_contacted_at, b.updated_at, b.created_at)) AS last_contact_activity
          FROM brokers b
          WHERE b.owner_developer_profile_id = p.id
            AND COALESCE(b.is_archived, false) = false
        ) contact_stats ON true
        LEFT JOIN LATERAL (
          SELECT
            COUNT(*) FILTER (WHERE ev.event_type = 'sent') AS sent,
            COUNT(*) FILTER (WHERE ev.event_type = 'opened') AS opens,
            COUNT(*) FILTER (WHERE ev.event_type = 'clicked') AS clicks,
            COUNT(*) FILTER (WHERE ev.event_type = 'replied') AS replies,
            MAX(ev.event_timestamp) AS last_outreach_activity
          FROM outreach_message_events ev
          INNER JOIN outreach_senders sender ON sender.id = ev.sender_id
          INNER JOIN outreach_campaigns campaign ON campaign.id = ev.campaign_id
          WHERE sender.developer_profile_id = p.id
            AND campaign.developer_profile_id = p.id
            AND COALESCE(campaign.is_archived, false) = false
        ) outreach_stats ON true
        LEFT JOIN LATERAL (
          SELECT MAX(u.updated_at) AS last_user_activity
          FROM users u
          WHERE u.developer_profile_id = p.id
            AND UPPER(COALESCE(u.role, '')) = 'DEVELOPER'
        ) user_stats ON true
        ORDER BY p.company_name ASC
      `);

      const profiles = (result.rows || []).map((row: any) => {
        const sent = Number(row.outreach_sent) || 0;
        const opens = Number(row.outreach_opens) || 0;
        const replies = Number(row.outreach_replies) || 0;
        return {
          id: row.id,
          companyName: row.company_name,
          slug: row.slug,
          logoUrl: row.logo_url,
          isActive: row.is_active === true,
          deals: {
            total: Number(row.total_deals) || 0,
            passed: Number(row.passed_deals) || 0,
            review: Number(row.review_deals) || 0,
            pursuing: Number(row.pursuing_deals) || 0,
          },
          sources: {
            bulkImported: Number(row.bulk_imported_deals) || 0,
            sourced: Number(row.sourced_deals) || 0,
          },
          outreach: {
            sent,
            opens,
            clicks: Number(row.outreach_clicks) || 0,
            replies,
            openRate: sent ? opens / sent * 100 : 0,
            replyRate: sent ? replies / sent * 100 : 0,
          },
          crmContactCount: Number(row.crm_contact_count) || 0,
          lastActivityAt: row.last_activity_at || null,
        };
      });

      return res.json({
        profiles,
        summary: profiles.reduce((summary, profile) => {
          summary.totalProfiles += 1;
          if (profile.isActive) summary.activeProfiles += 1;
          summary.totalDeals += profile.deals.total;
          summary.pursuingDeals += profile.deals.pursuing;
          summary.crmContacts += profile.crmContactCount;
          summary.outreachSent += profile.outreach.sent;
          return summary;
        }, {
          totalProfiles: 0,
          activeProfiles: 0,
          totalDeals: 0,
          pursuingDeals: 0,
          crmContacts: 0,
          outreachSent: 0,
        }),
      });
    } catch (error) {
      console.error("[admin analytics by profile] Error:", error);
      return res.status(500).json({ error: "Failed to load cross-company analytics" });
    }
  });

  function parseInvestmentCompanyPayload(body: any, partial = false) {
    const payload: Record<string, any> = {};
    const requiredString = (field: string, label: string) => {
      if (partial && body[field] === undefined) return;
      const value = String(body[field] ?? "").trim();
      if (!value) throw new Error(`${label} is required`);
      payload[field] = value;
    };
    const optionalString = (field: string) => {
      if (body[field] === undefined) return;
      const value = String(body[field] ?? "").trim();
      payload[field] = value || null;
    };
    const stringArray = (field: string, label: string) => {
      if (partial && body[field] === undefined) return;
      if (!Array.isArray(body[field]) || body[field].some((entry: unknown) => typeof entry !== "string")) {
        throw new Error(`${label} must be a list`);
      }
      payload[field] = Array.from(new Set(body[field].map((entry: string) => entry.trim()).filter(Boolean)));
    };
    const decimal = (field: string, label: string, required = false) => {
      if (partial && body[field] === undefined) return;
      if (body[field] === undefined || body[field] === null || body[field] === "") {
        if (required) throw new Error(`${label} is required`);
        payload[field] = null;
        return;
      }
      const value = Number(body[field]);
      if (!Number.isFinite(value) || value < 0) throw new Error(`${label} must be a non-negative number`);
      payload[field] = String(value);
    };

    requiredString("companyName", "Company name");
    requiredString("slug", "Slug");
    if (payload.slug && !/^[a-z0-9]+(?:-[a-z0-9]+)*$/.test(payload.slug)) {
      throw new Error("Slug must contain lowercase letters, numbers, and single hyphens only");
    }
    optionalString("logoUrl");
    for (const field of ["primaryColor", "secondaryColor"]) {
      if (partial && body[field] === undefined) continue;
      const value = String(body[field] ?? "").trim();
      if (!/^#[0-9a-fA-F]{6}$/.test(value)) throw new Error(`${field} must be a six-digit hex color`);
      payload[field] = value.toUpperCase();
    }
    if (!partial || body.rentMetric !== undefined) {
      if (!["psf", "per_unit"].includes(body.rentMetric)) throw new Error("Rent metric must be psf or per_unit");
      payload.rentMetric = body.rentMetric;
    }
    decimal("minRentPsf", "Minimum rent per square foot");
    decimal("minRentPerUnit", "Minimum rent per unit");
    decimal("minAcres", "Minimum acreage", true);
    decimal("maxAcres", "Maximum acreage");
    if (!partial || body.acreageOverridesByProductType !== undefined) {
      const raw = body.acreageOverridesByProductType ?? {};
      if (!raw || typeof raw !== "object" || Array.isArray(raw)) throw new Error("Product acreage overrides must be an object");
      const overrides: Record<string, number> = {};
      for (const [key, rawValue] of Object.entries(raw)) {
        const productType = key.trim();
        const value = Number(rawValue);
        if (!productType || !Number.isFinite(value) || value < 0) {
          throw new Error("Each product acreage override needs a product type and non-negative acreage");
        }
        overrides[productType] = value;
      }
      payload.acreageOverridesByProductType = overrides;
    }
    for (const field of [
      "qctOverridesRentMinimum", "ddaOverridesRentMinimum", "ozOverridesRentMinimum",
      "isInternal", "isActive",
    ]) {
      if (partial && body[field] === undefined) continue;
      if (typeof body[field] !== "boolean") throw new Error(`${field} must be true or false`);
      payload[field] = body[field];
    }
    stringArray("targetStates", "Target states");
    stringArray("targetCounties", "Target counties");
    stringArray("knownEmailDomains", "Known email domains");
    if ((!partial || body.maxAcres !== undefined || body.minAcres !== undefined) &&
      payload.maxAcres !== null && payload.maxAcres !== undefined &&
      Number(payload.maxAcres) < Number(payload.minAcres ?? body.minAcres)) {
      throw new Error("Maximum acreage cannot be lower than minimum acreage");
    }
    const effectiveMetric = payload.rentMetric ?? body.rentMetric;
    if (!partial && effectiveMetric === "psf" && (!payload.minRentPsf || Number(payload.minRentPsf) <= 0)) {
      throw new Error("Minimum rent per square foot is required for the primary rent metric");
    }
    if (!partial && effectiveMetric === "per_unit" && (!payload.minRentPerUnit || Number(payload.minRentPerUnit) <= 0)) {
      throw new Error("Minimum rent per unit is required for the primary rent metric");
    }
    return payload;
  }

