  // GET: debug — returns all approved deals + all broker accounts (admin only)
  app.get('/api/admin/broker-portal/debug', isAuthenticated, async (req: any, res) => {
    try {
      const deals = await db.execute(sql`
        SELECT id, address, city, state, msa_name, broker_portal_approved
        FROM deals
        WHERE broker_portal_approved = true
        ORDER BY created_at DESC
      `).then(r => r.rows as any[]);

      const accounts = await db.execute(sql`
        SELECT id, email, first_name, last_name, target_states, target_msas, target_cities, status
        FROM broker_portal_accounts
        WHERE status = 'active'
      `).then(r => r.rows as any[]);

      res.json({ approvedDeals: deals, brokerAccounts: accounts });
    } catch (err: any) {
      res.status(500).json({ error: String(err) });
    }
  });

  // GET: deals with YOC >= 6% (approval queue) — any classification, uses manual OR auto YOC
  app.get('/api/admin/broker-portal/deal-queue', isAuthenticated, async (req: any, res) => {
    try {
      const rows = await db.execute(sql`
        SELECT d.id, d.address, d.city, d.state, d.zip, d.property_name, d.asking_price,
               d.unit_count, d.max_units_by_zoning, d.size_acres, d.product_types,
               d.yield_on_cost, d.automated_yoc, d.broker_portal_approved, d.created_at,
               d.document_urls, d.analyst_document_urls, d.investment_memo_url,
               b.first_name AS broker_first_name, b.last_name AS broker_last_name,
               b.email AS broker_email, b.brokerage AS broker_brokerage, b.company AS broker_company
        FROM deals d
        LEFT JOIN brokers b ON b.id = d.broker_id
        ORDER BY d.created_at DESC
        LIMIT 500
      `).then(r => r.rows as any[]);

      // Compute bestYoc from manual yield_on_cost only — never use auto-calculated automated_yoc.
      const extractBestYoc = (deal: any): number => {
        if (!deal.yield_on_cost) return 0;
        const t = deal.yield_on_cost;
        const labeled = t.match(/YOC\s*[-:]?\s*(\d+\.?\d*)\s*%/i);
        if (labeled) return parseFloat(labeled[1]);
        const plain = t.match(/(\d+\.?\d*)\s*%/);
        return plain ? parseFloat(plain[1]) : 0;
      };

      const qualifying = rows
        .map((d: any) => ({ ...d, bestYoc: extractBestYoc(d) }))
        .filter((d: any) => d.bestYoc >= 6)
        .sort((a: any, b: any) => b.bestYoc - a.bestYoc);

      res.json(qualifying);
    } catch (err: any) {
      console.error('[broker-portal-queue] error:', err);
      res.status(500).json({ message: 'Failed to fetch deal queue' });
    }
  });

