      res.json({ id: updated.id, email: updated.email, firstName: updated.first_name, lastName: updated.last_name, brokerage: updated.brokerage, phone: updated.phone, status: updated.status, targetStates: updated.target_states || [], targetMsas: updated.target_msas || [], targetCities: updated.target_cities || [] });
