  app.post('/api/broker-portal/accounts', isAuthenticated, async (req: any, res) => {
    try {
      const { hashPassword } = await import('./auth');
      const { firstName, lastName, email, password, brokerage, phone, status, targetStates, targetMsas, targetCities, notes } = req.body;
      if (!firstName || !lastName || !email || !password) return res.status(400).json({ message: 'firstName, lastName, email, and password are required' });
      if (password.length < 8) return res.status(400).json({ message: 'Password must be at least 8 characters' });
      const passwordHash = await hashPassword(password);
      const toSqlArr = (arr: string[]) => arr?.length
        ? sql`ARRAY[${sql.join(arr.map((v: string) => sql`${v}`), sql`, `)}]`
        : sql`ARRAY[]::text[]`;
      const [account] = await db.execute(sql`
        INSERT INTO broker_portal_accounts (email, password_hash, first_name, last_name, brokerage, phone, status, target_states, target_msas, target_cities, notes)
        VALUES (${email.toLowerCase()}, ${passwordHash}, ${firstName}, ${lastName}, ${brokerage || null}, ${phone || null}, ${status || 'active'}, ${toSqlArr(targetStates || [])}, ${toSqlArr(targetMsas || [])}, ${toSqlArr(targetCities || [])}, ${notes || null})
        RETURNING id, email, first_name, last_name, brokerage, status, created_at
      `).then(r => r.rows as any[]);
      res.status(201).json({ id: account.id, email: account.email, firstName: account.first_name, lastName: account.last_name, brokerage: account.brokerage, status: account.status });
    } catch (err: any) {
      if (err.message?.includes('unique')) return res.status(409).json({ message: 'An account with this email already exists' });
      console.error('[broker-portal] create account error:', err);
      res.status(500).json({ message: 'Failed to create account' });
    }
  });

  app.put('/api/broker-portal/accounts/:id', isAuthenticated, async (req: any, res) => {
    try {
      const { firstName, lastName, email, brokerage, phone, status, targetStates, targetMsas, targetCities, notes, password } = req.body;
      const toSqlArr = (arr: string[]) => arr?.length
        ? sql`ARRAY[${sql.join(arr.map((v: string) => sql`${v}`), sql`, `)}]`
        : sql`ARRAY[]::text[]`;
      let passwordClause = sql``;
      if (password) {
        const { hashPassword } = await import('./auth');
        const hash = await hashPassword(password);
        passwordClause = sql`, password_hash = ${hash}`;
      }
      // Check prior status so we know if we need to send an approval email
      const [prior] = await db.execute(sql`SELECT status, first_name, email FROM broker_portal_accounts WHERE id = ${req.params.id}`).then(r => r.rows as any[]);
      await db.execute(sql`
        UPDATE broker_portal_accounts SET
          first_name = ${firstName}, last_name = ${lastName}, email = ${email?.toLowerCase()},
          brokerage = ${brokerage || null}, phone = ${phone || null}, status = ${status || 'active'},
          target_states = ${toSqlArr(targetStates || [])}, target_msas = ${toSqlArr(targetMsas || [])},
          target_cities = ${toSqlArr(targetCities || [])}, notes = ${notes || null}
          ${passwordClause}
        WHERE id = ${req.params.id}
      `);
      // Send approval email when status transitions to 'active'
      if (prior && prior.status !== 'active' && (status || 'active') === 'active') {
        try {
          const baseUrl = process.env.BASE_URL || 'https://landlinq.ai';
          const loginUrl = `${baseUrl}/broker-portal`;
          const approvalHtml = `
            <div style="font-family:Arial,sans-serif;max-width:600px;margin:0 auto;padding:32px 24px;color:#1e293b">
              <div style="margin-bottom:28px">
                <img src="https://landlinq.ai/assets/landlinq-email-logo.png" alt="LandLinq" style="height:32px" />
              </div>
              <h2 style="color:#0d2d4e;margin:0 0 12px">Your Partner Broker Account is Approved!</h2>
              <p style="margin:0 0 16px;color:#475569;line-height:1.6">
                Hi ${prior.first_name || firstName},<br/><br/>
                Great news — your LandLinq Partner Broker Portal account has been approved.
                You now have access to view active deals in your target markets.
              </p>
              <a href="${loginUrl}" style="display:inline-block;background:#0d2d4e;color:#fff;text-decoration:none;padding:12px 28px;border-radius:8px;font-weight:600;font-size:14px;margin:8px 0 24px">
                Sign In to Broker Portal →
              </a>
              <p style="color:#94a3b8;font-size:12px;margin:24px 0 0;border-top:1px solid #e2e8f0;padding-top:16px">
                LandLinq · Partner Broker Portal · <a href="${loginUrl}" style="color:#0d2d4e">${loginUrl}</a>
              </p>
            </div>`;
          const { sendNotificationEmail } = await import('./emailService');
          await sendNotificationEmail({ to: prior.email || email, subject: 'Your LandLinq Partner Broker Account is Approved', html: approvalHtml, type: 'broker_approval', priority: 'high' });
          console.log(`✅ Approval email sent to ${prior.email || email}`);
        } catch (emailErr) {
          console.error('⚠️ Approval email failed (account still updated):', emailErr);
        }
      }
      res.json({ success: true });
    } catch (err: any) {
      res.status(500).json({ message: 'Failed to update account' });
    }
  });

