  // Geocode All Deals - Admin utility to populate coordinates for existing deals
  app.post("/api/admin/geocode-all-deals", isAuthenticated, async (req, res) => {
    try {
      const user = req.user as any;
      
      // Check authentication
      if (!user) {
        return res.status(401).json({ message: "Authentication required", code: "NOT_AUTHENTICATED" });
      }
      
      // Check admin privileges
      if (!user.email || !user.email.endsWith('@apexresi.com')) {
        return res.status(403).json({ 
          message: "Admin access required", 
          code: "INSUFFICIENT_PRIVILEGES"
        });
      }

      console.log('🗺️ Starting bulk geocoding of all deals missing coordinates...');

      // Get all deals missing latitude or longitude
      const allDeals = await storage.getAllDeals();
      const dealsToGeocode = allDeals.filter(deal => !deal.latitude || !deal.longitude);

      console.log(`📊 Found ${dealsToGeocode.length} deals missing coordinates out of ${allDeals.length} total deals`);

      if (dealsToGeocode.length === 0) {
        return res.json({
          success: true,
          message: "All deals already have coordinates",
          processed: 0,
          successful: 0,
          failed: 0,
          results: []
        });
      }

      const results = {
        processed: 0,
        successful: 0,
        failed: 0,
        details: [] as Array<{
          dealId: string;
          dealNumber: number;
          address: string;
          success: boolean;
          coordinates?: { lat: number; lng: number };
          error?: string;
        }>
      };

      // Rate limiting: Geocodio allows 1000 calls/min
      // Process in batches of 50 with 3-second delays between batches
      const BATCH_SIZE = 50;
      const BATCH_DELAY_MS = 3000;
      
      const batches = [];
      for (let i = 0; i < dealsToGeocode.length; i += BATCH_SIZE) {
        batches.push(dealsToGeocode.slice(i, i + BATCH_SIZE));
      }

      console.log(`📦 Processing ${batches.length} batches of up to ${BATCH_SIZE} deals each`);

      // Process each batch
      for (let batchIndex = 0; batchIndex < batches.length; batchIndex++) {
        const batch = batches[batchIndex];
        console.log(`📦 Processing batch ${batchIndex + 1}/${batches.length} (${batch.length} deals)...`);

        // Process deals in current batch
        for (const deal of batch) {
          results.processed++;
          
          try {
            if (!deal.address) {
              console.log(`⚠️ Deal #${deal.dealNumber} has no address, skipping`);
              results.failed++;
              results.details.push({
                dealId: deal.id,
                dealNumber: deal.dealNumber || 0,
                address: deal.address || 'No address',
                success: false,
                error: 'No address provided'
              });
              continue;
            }

            console.log(`🔍 Geocoding Deal #${deal.dealNumber}: ${deal.address}`);
            
            // Use geocodeAddress to get full location data (city, state, ZIP, county, lat/lng)
            const geocodeResult = await geocodioService.geocodeAddress(deal.address);

            if (geocodeResult.success && geocodeResult.lat && geocodeResult.lng) {
              // Check QCT status if we have FIPS code
              let qctStatus: 'YES' | 'NO' | 'N/A' = 'N/A';
              let censusTractFips: string | null = null;
              
              if (geocodeResult.fips) {
                try {
                  const { qctService } = await import('./qctService');
                  const qctCheck = await qctService.checkQCTStatus(geocodeResult.fips);
                  qctStatus = qctCheck.isQCT ? 'YES' : 'NO';
                  censusTractFips = geocodeResult.fips;
                  console.log(`📊 QCT Status for Deal #${deal.dealNumber}: ${qctStatus} (FIPS: ${censusTractFips})`);
                } catch (qctError) {
                  console.error(`⚠️ QCT check failed for Deal #${deal.dealNumber}:`, qctError);
                  // Continue with N/A status
                }
              }
              
              // Update the deal with ALL geocoded fields + QCT status
              await storage.updateDeal(deal.id, {
                latitude: geocodeResult.lat.toString(),
                longitude: geocodeResult.lng.toString(),
                city: geocodeResult.city || null,
                state: geocodeResult.state || null,
                zip: geocodeResult.zipCode || null,
                county: geocodeResult.county || null,
                censusTractFips: censusTractFips,
                qctStatus: qctStatus
              });

              results.successful++;
              results.details.push({
                dealId: deal.id,
                dealNumber: deal.dealNumber || 0,
                address: deal.address,
                success: true,
                coordinates: { lat: geocodeResult.lat, lng: geocodeResult.lng }
              });

              console.log(`✅ Deal #${deal.dealNumber} geocoded successfully: ${geocodeResult.city}, ${geocodeResult.state} ${geocodeResult.zipCode} (${geocodeResult.lat}, ${geocodeResult.lng}) [QCT: ${qctStatus}]`);
            } else {
              results.failed++;
              results.details.push({
                dealId: deal.id,
                dealNumber: deal.dealNumber || 0,
                address: deal.address,
                success: false,
                error: geocodeResult.error || 'Unknown error'
              });

              console.log(`❌ Failed to geocode Deal #${deal.dealNumber}: ${geocodeResult.error}`);
            }

          } catch (error) {
            results.failed++;
            results.details.push({
              dealId: deal.id,
              dealNumber: deal.dealNumber || 0,
              address: deal.address || 'Unknown',
              success: false,
              error: error instanceof Error ? error.message : 'Unknown error'
            });

            console.error(`❌ Error geocoding Deal #${deal.dealNumber}:`, error);
          }
        }

        // Delay between batches to respect rate limits (except after last batch)
        if (batchIndex < batches.length - 1) {
          console.log(`⏳ Waiting ${BATCH_DELAY_MS/1000} seconds before next batch...`);
          await new Promise(resolve => setTimeout(resolve, BATCH_DELAY_MS));
        }
      }

      console.log(`🎉 Bulk geocoding complete: ${results.successful} successful, ${results.failed} failed`);

      res.json({
        success: true,
        message: `Geocoded ${results.successful} out of ${results.processed} deals`,
        ...results
      });

    } catch (error: any) {
      console.error("❌ Error in bulk geocoding:", error);
      res.status(500).json({ 
        success: false,
        message: "Failed to geocode deals",
        error: error.message 
      });
    }
  });

  // Bulk QCT Re-Check - Admin utility to re-run QCT status for all deals
  app.post("/api/admin/bulk-qct-recheck", isAuthenticated, async (req, res) => {
    try {
      const user = req.user as any;
      
      // Check authentication
      if (!user) {
        return res.status(401).json({ message: "Authentication required", code: "NOT_AUTHENTICATED" });
      }
      
      // Check admin privileges
      const userEmail = user.email || user.claims?.email || '';
      if (!userEmail.endsWith('@apexresi.com')) {
        return res.status(403).json({ 
          message: "Admin access required", 
          code: "INSUFFICIENT_PRIVILEGES"
        });
      }

      console.log('🔍 Starting bulk QCT re-check for all deals...');

      // Get all deals - optionally filter to only those needing QCT check
      const { forceAll = false } = req.body;
      const allDeals = await storage.getAllDeals();
      
      // Filter deals that need QCT checking
      const dealsToCheck = forceAll 
        ? allDeals 
        : allDeals.filter(deal => 
            !deal.qctStatus || 
            deal.qctStatus === 'N/A' || 
            deal.qctStatus === '' ||
            !deal.censusTractFips
          );

      console.log(`📊 Found ${dealsToCheck.length} deals to check QCT status (total: ${allDeals.length}, forceAll: ${forceAll})`);

      if (dealsToCheck.length === 0) {
        return res.json({
          success: true,
          message: "All deals already have QCT status",
          processed: 0,
          updated: 0,
          failed: 0,
          results: []
        });
      }

      const { qctService } = await import('./qctService');
      
      const results = {
        processed: 0,
        updated: 0,
        failed: 0,
        qctYes: 0,
        qctNo: 0,
        details: [] as Array<{
          dealId: string;
          dealNumber: number;
          address: string;
          success: boolean;
          qctStatus?: string;
          censusTractFips?: string;
          error?: string;
        }>
      };

      // Rate limiting: Process in batches of 25 with 2-second delays
      const BATCH_SIZE = 25;
      const BATCH_DELAY_MS = 2000;
      
      const batches = [];
      for (let i = 0; i < dealsToCheck.length; i += BATCH_SIZE) {
        batches.push(dealsToCheck.slice(i, i + BATCH_SIZE));
      }

      console.log(`📦 Processing ${batches.length} batches of up to ${BATCH_SIZE} deals each`);

      for (let batchIndex = 0; batchIndex < batches.length; batchIndex++) {
        const batch = batches[batchIndex];
        console.log(`📦 Processing batch ${batchIndex + 1}/${batches.length} (${batch.length} deals)...`);

        for (const deal of batch) {
          results.processed++;
          
          try {
            // First check if we already have valid coordinates
            let lat = deal.latitude ? parseFloat(deal.latitude.toString()) : null;
            let lng = deal.longitude ? parseFloat(deal.longitude.toString()) : null;
            let fipsCode = deal.censusTractFips;
            
            // If no FIPS code, we need to geocode first
            if (!fipsCode && deal.address) {
              console.log(`🔍 Geocoding Deal #${deal.dealNumber} to get FIPS code...`);
              const geocodeResult = await geocodioService.geocodeAddress(deal.address);
              
              if (geocodeResult.success && geocodeResult.fips) {
                fipsCode = geocodeResult.fips;
                lat = geocodeResult.lat || lat;
                lng = geocodeResult.lng || lng;
              } else {
                results.failed++;
                results.details.push({
                  dealId: deal.id,
                  dealNumber: deal.dealNumber || 0,
                  address: deal.address || 'Unknown',
                  success: false,
                  error: `Geocoding failed: ${geocodeResult.error || 'No FIPS code returned'}`
                });
                console.log(`❌ Deal #${deal.dealNumber}: Geocoding failed`);
                continue;
              }
            }
            
            if (!fipsCode) {
              results.failed++;
              results.details.push({
                dealId: deal.id,
                dealNumber: deal.dealNumber || 0,
                address: deal.address || 'Unknown',
                success: false,
                error: 'No FIPS code available and no address to geocode'
              });
              continue;
            }

            // Check QCT status with the FIPS code
            const qctCheck = await qctService.checkQCTStatus(fipsCode);
            const qctStatus = qctCheck.isQCT ? 'YES' : 'NO';
            
            if (qctStatus === 'YES') {
              results.qctYes++;
            } else {
              results.qctNo++;
            }

            // Update the deal with QCT status
            await storage.updateDeal(deal.id, {
              qctStatus: qctStatus,
              censusTractFips: fipsCode
            });

            results.updated++;
            results.details.push({
              dealId: deal.id,
              dealNumber: deal.dealNumber || 0,
              address: deal.address || 'Unknown',
              success: true,
              qctStatus: qctStatus,
              censusTractFips: fipsCode
            });

            console.log(`✅ Deal #${deal.dealNumber}: QCT=${qctStatus} (FIPS: ${fipsCode})`);

          } catch (error) {
            results.failed++;
            results.details.push({
              dealId: deal.id,
              dealNumber: deal.dealNumber || 0,
              address: deal.address || 'Unknown',
              success: false,
              error: error instanceof Error ? error.message : 'Unknown error'
            });

            console.error(`❌ Error checking QCT for Deal #${deal.dealNumber}:`, error);
          }
        }

        // Delay between batches
        if (batchIndex < batches.length - 1) {
          console.log(`⏳ Waiting ${BATCH_DELAY_MS/1000} seconds before next batch...`);
          await new Promise(resolve => setTimeout(resolve, BATCH_DELAY_MS));
        }
      }

      console.log(`🎉 Bulk QCT re-check complete: ${results.updated} updated, ${results.failed} failed (${results.qctYes} YES, ${results.qctNo} NO)`);

      res.json({
        success: true,
        message: `QCT re-checked ${results.updated} out of ${results.processed} deals`,
        summary: {
          qctYes: results.qctYes,
          qctNo: results.qctNo,
          failed: results.failed
        },
        ...results
      });

    } catch (error: any) {
      console.error("❌ Error in bulk QCT re-check:", error);
      res.status(500).json({ 
        success: false,
        message: "Failed to re-check QCT status",
        error: error.message 
      });
    }
  });

