  // Get comparable locations from deal's comparablesJson for map display (Dec 11, 2025)
  // Updated: Now reads from structured comparablesJson column instead of parsing notes text
  app.get("/api/deals/:dealId/comparable-locations", isAuthenticated, async (req, res) => {
    try {
      const { dealId } = req.params;
      const deal = await storage.getDealById(dealId);
      
      if (!deal) {
        return res.status(404).json({ message: "Deal not found" });
      }

      // Check for structured comparables first (new format with lat/lng)
      const comparablesJson = (deal as any).comparablesJson;
      if (comparablesJson && Array.isArray(comparablesJson) && comparablesJson.length > 0) {
        // Dec 19, 2025: Geocode comparables that don't have coordinates
        const comparableLocations: Array<{address: string; latitude: number; longitude: number; propertyName: string; units: number; yearBuilt: number; rentPSF: number; distance: number}> = [];
        
        const withCoords = comparablesJson.filter((c: any) => c.latitude && c.longitude);
        const withoutCoords = comparablesJson.filter((c: any) => !c.latitude || !c.longitude);
        
        console.log(`📍 [COMP-MAP] ${withCoords.length}/${comparablesJson.length} have coordinates, ${withoutCoords.length} need geocoding`);
        
        // Add all with existing coordinates
        for (const c of withCoords) {
          comparableLocations.push({
            address: `${c.address || ''}, ${c.city || ''}, ${c.state || ''}`.trim().replace(/^,\s*/, '').replace(/,\s*$/, ''),
            latitude: c.latitude,
            longitude: c.longitude,
            propertyName: c.propertyName,
            units: c.units,
            yearBuilt: c.yearBuilt,
            rentPSF: c.rentPSF,
            distance: c.distance
          });
        }
        
        // Geocode those without coordinates (limit to 10 to prevent excessive API calls)
        const maxToGeocode = Math.min(withoutCoords.length, 10);
        for (let i = 0; i < maxToGeocode; i++) {
          const c = withoutCoords[i];
          const fullAddress = `${c.address || ''}, ${c.city || ''}, ${c.state || ''} ${c.zipCode || ''}`.trim();
          try {
            const geocoded = await geocodioService.geocodeAddress(fullAddress);
            if (geocoded.success && geocoded.lat && geocoded.lng) {
              comparableLocations.push({
                address: fullAddress.replace(/,\s*$/, '').replace(/^\s*,/, ''),
                latitude: geocoded.lat,
                longitude: geocoded.lng,
                propertyName: c.propertyName,
                units: c.units,
                yearBuilt: c.yearBuilt,
                rentPSF: c.rentPSF,
                distance: c.distance
              });
              console.log(`   ✅ Geocoded: ${c.propertyName || fullAddress}`);
            } else {
              console.log(`   ❌ Failed to geocode: ${fullAddress}`);
            }
          } catch (geoError) {
            console.log(`   ❌ Geocode error for: ${fullAddress}`);
          }
        }
        
        console.log(`📍 [COMP-MAP] Final: ${comparableLocations.length} comparables with coordinates for map`);
        
        return res.json({
          subjectLatitude: deal.latitude ? parseFloat(deal.latitude.toString()) : null,
          subjectLongitude: deal.longitude ? parseFloat(deal.longitude.toString()) : null,
          subjectAddress: deal.address,
          comparables: comparableLocations
        });
      }

      // Fallback: Parse addresses from comparable_notes and geocode them
      // This handles older deals from before Dec 11, 2025 that don't have comparablesJson
      const comparableNotes = (deal as any).comparableNotes;
      if (comparableNotes && typeof comparableNotes === 'string') {
        console.log(`📍 [COMP-MAP] Parsing addresses from comparable_notes for deal ${dealId}`);
        console.log(`📍 [COMP-MAP] Notes preview: ${comparableNotes.substring(0, 200)}...`);
        
        // Extract addresses from notes using pattern matching
        // Format: "Address: 1234 Street Name, City, State ZIP" (may have leading whitespace)
        // More flexible pattern: matches optional whitespace, street, city, state, and 5-digit ZIP
        const addressPattern = /Address:\s*([^,\n]+,\s*[^,\n]+,\s*[A-Z]{2}\s*\d{5})/gi;
        const matches = [...comparableNotes.matchAll(addressPattern)];
        
        console.log(`📍 [COMP-MAP] Regex found ${matches.length} matches`);
        
        if (matches.length > 0) {
          console.log(`📍 [COMP-MAP] Found ${matches.length} addresses to geocode`);
          
          // Geocode each address (limit to first 5 to prevent excessive API calls)
          const comparableLocations = [];
          const maxToGeocode = Math.min(matches.length, 5);
          
          for (let i = 0; i < maxToGeocode; i++) {
            const fullAddress = matches[i][1].trim();
            try {
              const geocoded = await geocodioService.geocodeAddress(fullAddress);
              if (geocoded.success && geocoded.lat && geocoded.lng) {
                comparableLocations.push({
                  address: fullAddress,
                  latitude: geocoded.lat,
                  longitude: geocoded.lng,
                  propertyName: null,
                  units: null,
                  yearBuilt: null,
                  rentPSF: null,
                  distance: null
                });
                console.log(`   ✅ Geocoded: ${fullAddress}`);
              }
            } catch (geoError) {
              console.log(`   ❌ Failed to geocode: ${fullAddress}`);
            }
          }
          
          if (comparableLocations.length > 0) {
            console.log(`📍 [COMP-MAP] Successfully geocoded ${comparableLocations.length}/${maxToGeocode} addresses`);
            return res.json({
              subjectLatitude: deal.latitude ? parseFloat(deal.latitude.toString()) : null,
              subjectLongitude: deal.longitude ? parseFloat(deal.longitude.toString()) : null,
              subjectAddress: deal.address,
              comparables: comparableLocations
            });
          }
        }
      }
      
      // Final fallback: No structured data and couldn't parse notes - return empty
      console.log(`📍 [COMP-MAP] No comparablesJson or parseable notes for deal ${dealId} - returning empty comparables`);
      return res.json({ 
        subjectLatitude: deal.latitude ? parseFloat(deal.latitude.toString()) : null,
        subjectLongitude: deal.longitude ? parseFloat(deal.longitude.toString()) : null,
        subjectAddress: deal.address,
        comparables: [] 
      });
    } catch (error) {
      console.error("Error fetching comparable locations:", error);
      res.status(500).json({ message: "Failed to fetch comparable locations" });
    }
  });

  // Force coordinate-based comparable search when HelloData property lookup fails (Dec 11, 2025)
  app.post("/api/deals/:dealId/force-comparables", isAuthenticated, async (req, res) => {
    try {
      const { dealId } = req.params;
      const deal = await storage.getDealById(dealId);
      
      if (!deal) {
        return res.status(404).json({ message: "Deal not found" });
      }

      if (!deal.address) {
        return res.status(400).json({ message: "Deal address is required" });
      }

      console.log(`🔄 [FORCE-COMPS] Forcing coordinate-based comparable search for deal ${dealId}`);
      console.log(`📍 Address: ${deal.address}`);

      // Step 1: Get coordinates - use existing coords or geocode
      let lat = deal.latitude ? parseFloat(deal.latitude.toString()) : null;
      let lng = deal.longitude ? parseFloat(deal.longitude.toString()) : null;
      let geocodedCity = (deal as any).city || '';
      let geocodedState = (deal as any).state || '';
      let geocodedZip = (deal as any).zip || '';

      if (!lat || !lng) {
        console.log(`📍 [FORCE-COMPS] No coordinates on deal, geocoding address...`);
        const fullAddress = [deal.address, geocodedCity, geocodedState, geocodedZip].filter(Boolean).join(', ');
        
        // Dec 11, 2025: Use lenient geocoding for force-comparables (accept lower accuracy)
        // Standard geocoding has 0.7 minimum, but user explicitly wants to search
        const geocoded = await geocodioService.geocodeAddressLenient(fullAddress);
        
        if (geocoded.success && geocoded.lat && geocoded.lng) {
          lat = geocoded.lat;
          lng = geocoded.lng;
          geocodedCity = geocoded.city || geocodedCity;
          geocodedState = geocoded.state || geocodedState;
          geocodedZip = geocoded.zipCode || geocodedZip;
          console.log(`✅ [FORCE-COMPS] Geocoded to: ${lat}, ${lng} (lenient mode)`);
        } else {
          return res.status(400).json({ 
            message: "Could not geocode address. Please verify the address is correct.",
            error: geocoded.error || "Geocoding failed"
          });
        }
      }

      // Step 2: Call HelloData with coordinates directly (bypass property lookup)
      console.log(`🔎 [FORCE-COMPS] Calling HelloData with coordinates: ${lat}, ${lng}`);
      
      // Dec 30, 2025 FIX: ALWAYS save coordinates to deal regardless of comparable results
      // This ensures the subject marker shows on the map even if no qualifying comps found
      if (lat && lng) {
        await storage.updateDeal(dealId, {
          latitude: lat.toString(),
          longitude: lng.toString()
        });
        console.log(`📍 [FORCE-COMPS] Saved subject coordinates: ${lat}, ${lng}`);
      }
      
      const { hellodataService } = await import('./hellodataService');
      const developerProfileId = (req.user as any)?.developerProfileId as string | undefined;
      let searchRadius = 3;
      if (developerProfileId) {
        const { developerProfiles } = await import('@shared/schema');
        const [profile] = await db.select({
          compSearchRadiusMiles: developerProfiles.compSearchRadiusMiles,
        }).from(developerProfiles).where(and(
          eq(developerProfiles.id, developerProfileId),
          eq(developerProfiles.isActive, true),
        )).limit(1);
        const configuredRadius = Number(profile?.compSearchRadiusMiles);
        if (Number.isFinite(configuredRadius) && configuredRadius > 0) searchRadius = configuredRadius;
      }
      // Dec 17, 2025: Pass coordinates to skip geocoding
      // Jan 21, 2026: Also pass productType for dynamic filter criteria
      const result = await hellodataService.searchQualifyingComparables(
        `${deal.address}, ${geocodedCity}, ${geocodedState} ${geocodedZip}`.trim(),
        { latitude: lat!, longitude: lng!, productType: (deal as any).productType, radiusMiles: searchRadius }
      );

      // Step 3: Format and save results
      if (result.success && result.qualifyingCount > 0) {
        // Use the verbose HelloData summary as comparableNotes (preserves individual property details)
        const comparableNotes = result.summary || `Found ${result.qualifyingCount} qualifying comparables`;

        // Build comparablesJson with coordinates and isQualifying for map/table display
        const comparablesJson = result.comparables.map((comp: any) => ({
          address: comp.address,
          city: comp.city,
          state: comp.state,
          zipCode: comp.zipCode,
          latitude: comp.latitude,
          longitude: comp.longitude,
          distance: comp.distance,
          unitCount: comp.unitCount,
          avgRent: comp.avgRent,
          yearBuilt: comp.yearBuilt,
          propertyName: comp.propertyName,
          rentPSF: comp.rentPSF || comp.pricePerSqFt || null,
          isQualifying: comp.isQualifying || false,
          propertyType: comp.propertyType || null,
          vacancyRate: comp.vacancyRate ?? null,
          developer: comp.developer || null,
          owner: comp.owner || null,
          buildingSize: comp.buildingSize || 0,
          stories: comp.stories ?? null,
          unitMix: comp.unitMix ?? null,
          leasedPct: comp.leasedPct ?? null,
          leasedPctChange: comp.leasedPctChange ?? null,
          exposure: comp.exposure ?? null,
          exposureChange: comp.exposureChange ?? null,
          unitsVacant: comp.unitsVacant ?? null,
          unitsExposed: comp.unitsExposed ?? null,
          websiteUrl: comp.websiteUrl ?? null
        }));

        // Dec 16, 2025: Also fetch demographics if not already populated
        let demographicsData: any = null;
        if (!deal.population55Plus5Mile && !deal.income75Plus55Plus) {
          console.log(`📊 [FORCE-COMPS] Fetching demographics...`);
          try {
            const fullAddressForDemo = [deal.address, geocodedCity, geocodedState, geocodedZip].filter(Boolean).join(', ');
            const demoResult = await geocodioService.getDemographics(fullAddressForDemo);
            if (demoResult.success) {
              demographicsData = {
                population55Plus5Mile: demoResult.population55Plus || 0,
                income75Plus55Plus: demoResult.income75kPlus || 0
              };
              console.log(`✅ [FORCE-COMPS] Demographics: Pop 55+ = ${demographicsData.population55Plus5Mile}, Income $75k+ = ${demographicsData.income75Plus55Plus}`);
            }
          } catch (demoError) {
            console.log(`⚠️ [FORCE-COMPS] Demographics fetch failed:`, demoError);
          }
        }

        // Update deal with new comparable data including comparablesJson for map
        await storage.updateDeal(dealId, {
          comparableNotes: comparableNotes,
          comparableCount: result.qualifyingCount,
          comparablesJson: comparablesJson,
          comparablesFetchedAt: new Date(),
          avgRentPSF: result.avgRentPSF?.toString() || null,
          avgRentPerUnit: result.avgRentPerUnit?.toString() || null,
          topRentPSF: result.topRentPSF?.toString() || null,
          topRentPerUnit: result.topRentPerUnit?.toString() || null,
          latitude: lat?.toString() || null,
          longitude: lng?.toString() || null,
          // Include demographics if fetched
          ...(demographicsData ? demographicsData : {})
        });

        console.log(`✅ [FORCE-COMPS] Successfully found ${result.qualifyingCount} comparables`);
        
        res.json({
          success: true,
          message: `Found ${result.qualifyingCount} qualifying comparables`,
          comparableCount: result.qualifyingCount,
          comparableNotes: comparableNotes,
          avgRentPSF: result.avgRentPSF,
          avgRentPerUnit: result.avgRentPerUnit
        });
      } else {
        // FIX (Jan 15, 2026): Even if no QUALIFYING comps, still save ALL found comparables
        // This ensures PDF reports can show the full property list regardless of qualification
        const errorMessage = result.error || 'No qualifying comparables found within search radius';
        console.log(`⚠️ [FORCE-COMPS] ${errorMessage}`);
        
        // Build comparablesJson from all found comparables (even non-qualifying)
        if (result.comparables && result.comparables.length > 0) {
          const comparablesJsonForStorage = result.comparables.map((comp: any) => ({
            address: comp.address,
            city: comp.city,
            state: comp.state,
            zipCode: comp.zipCode,
            latitude: comp.latitude,
            longitude: comp.longitude,
            distance: comp.distance,
            unitCount: comp.unitCount,
            avgRent: comp.avgRent,
            yearBuilt: comp.yearBuilt,
            propertyName: comp.propertyName,
            rentPSF: comp.rentPSF || comp.pricePerSqFt || null,
            isQualifying: comp.isQualifying || false,
            propertyType: comp.propertyType || null,
            vacancyRate: comp.vacancyRate ?? null,
            developer: comp.developer || null,
            owner: comp.owner || null,
            buildingSize: comp.buildingSize || 0,
            stories: comp.stories ?? null,
            unitMix: comp.unitMix ?? null,
            leasedPct: comp.leasedPct ?? null,
            leasedPctChange: comp.leasedPctChange ?? null,
            exposure: comp.exposure ?? null,
            exposureChange: comp.exposureChange ?? null,
            unitsVacant: comp.unitsVacant ?? null,
            unitsExposed: comp.unitsExposed ?? null,
            websiteUrl: comp.websiteUrl ?? null
          }));
          
          await storage.updateDeal(dealId, {
            comparablesJson: comparablesJsonForStorage,
            comparablesFetchedAt: new Date(),
            comparableCount: 0,
            avgRentPSF: result.avgRentPSF?.toString() || null,
            avgRentPerUnit: result.avgRentPerUnit?.toString() || null,
            topRentPSF: result.topRentPSF?.toString() || null,
            topRentPerUnit: result.topRentPerUnit?.toString() || null
          });
          console.log(`📊 [FORCE-COMPS] Saved ${comparablesJsonForStorage.length} comparables (0 qualifying) to deal for PDF report`);
        }
        
        res.json({
          success: false,
          message: errorMessage,
          comparableCount: 0,
          summary: result.summary || result.error || 'No comparables met the qualifying criteria'
        });
      }
    } catch (error) {
      console.error("Error in force-comparables:", error);
      res.status(500).json({ message: "Failed to run comparable search" });
    }
  });

  // City-level geocoding fallback for new construction addresses
  // ENHANCEMENT (Dec 11, 2025): When exact address isn't in Geocodio (new construction),
  // allow analysts to geocode at city-level to get approximate coordinates
  app.post("/api/deals/:dealId/geocode-city-level", isAuthenticated, async (req, res) => {
    try {
      const user = req.user as any;
      const isAnalyst = (user?.claims?.email || user?.email || '').endsWith('@apexresi.com');
      
      if (!isAnalyst) {
        return res.status(403).json({ message: "Access denied. Analyst privileges required." });
      }

      const { dealId } = req.params;
      console.log(`🏙️ [CITY-GEOCODE] Requested for deal: ${dealId}`);
      
      const deal = await storage.getDealById(dealId);
      if (!deal) {
        return res.status(404).json({ message: "Deal not found" });
      }

      // Get city, state, ZIP from deal or request body
      const city = req.body.city || (deal as any).city;
      const state = req.body.state || (deal as any).state;
      const zip = req.body.zip || (deal as any).zip || (deal as any).zipCode;
      
      if (!city || !state) {
        return res.status(400).json({ 
          message: "City and state are required for city-level geocoding",
          hint: "Please update the deal with city and state information first"
        });
      }

      console.log(`📍 [ZIP-GEOCODE] Geocoding: ${zip || `${city}, ${state}`}`);
      
      const result = await geocodioService.geocodeZipOrCityLevel(city, state, zip);
      
      if (!result.success) {
        return res.status(400).json({ 
          message: `Could not geocode location: ${result.error}`,
          success: false
        });
      }

      // Update deal with approximate coordinates (ZIP center preferred, city center fallback)
      const existingNotes = (deal as any).ingestionNotes || '';
      const locationType = zip ? 'ZIP center' : 'city-center';
      const geoWarning = `⚠️ Coordinates are APPROXIMATE (${locationType}) - address not found in geocoding database (likely new construction)`;
      
      // Only append warning if not already present (idempotent)
      const newIngestionNotes = existingNotes.includes('Coordinates are APPROXIMATE') 
        ? existingNotes 
        : (existingNotes + '\n' + geoWarning).trim();
      
      const updateData: any = {
        latitude: result.lat?.toString(),
        longitude: result.lng?.toString(),
        city: result.city || city,
        state: result.state || state,
        county: result.county,
        ingestionNotes: newIngestionNotes
      };
      
      if (zip) {
        updateData.zip = result.zipCode || zip;
      }

      await storage.updateDeal(dealId, updateData);
      console.log(`✅ [ZIP-GEOCODE] Updated deal with ${locationType} coordinates: ${result.lat}, ${result.lng}`);
      
      res.json({
        success: true,
        message: zip 
          ? `Geocoded to ZIP ${zip} center (approximate location, typically within 1-2 miles)`
          : `Geocoded to ${result.city}, ${result.state} city center (approximate location)`,
        lat: result.lat,
        lng: result.lng,
        city: result.city,
        state: result.state,
        county: result.county,
        isApproximate: true,
        note: zip 
          ? "Coordinates are approximate ZIP center since exact address was not found in geocoding database"
          : "Coordinates are approximate city-center since exact address was not found in geocoding database"
      });
    } catch (error) {
      console.error("Error in city-level geocoding:", error);
      res.status(500).json({ message: "Failed to geocode at city level" });
    }
  });

  // Update deal classification and notes
  app.put("/api/analyst/deals/:dealId", isAuthenticated, async (req, res) => {
    try {
      // Check if user is a Catalyst analyst
      const user = req.user as any;
      const isAnalyst = (user?.claims?.email || user?.email || '').endsWith('@apexresi.com');
      
      if (!isAnalyst) {
        return res.status(403).json({ message: "Access denied. Analyst privileges required." });
      }

      const { dealId } = req.params;
      
      // Validate dealId is a valid UUID format
      if (!dealId || typeof dealId !== 'string') {
        return res.status(400).json({ message: "Invalid deal ID" });
      }

      const { 
        classification, 
        analystNotes,
        developerNotes,
        status,
        rejectionReason,
        // Property details
        address,
        propertyName,
        unitCount,
        sizeAcres,
        askingPrice,
        rentComparable,
        // Developer/Partner info
        developer,
        partner,
        // Workflow fields
        nextSteps,
        assignedAnalyst,
        // Demographics for Active Adult
        population55Plus5Mile,
        income75Plus55Plus,
        demographicsNotes
      } = req.body;
      
      // Validate classification values
      if (classification && !['red', 'yellow', 'green'].includes(classification)) {
        return res.status(400).json({ message: "Invalid classification value" });
      }
      
      // Validate status values (from deal_status enum)
      if (status && !['pending_review', 'under_review', 'approved', 'rejected', 'clear_no', 'potentially', 'high_priority', 'initial_review', 'due_diligence', 'financial_analysis', 'final_review', 'contract_negotiation', 'closing', 'completed'].includes(status)) {
        return res.status(400).json({ message: "Invalid status value" });
      }

      const updateData: any = {};
      if (classification) updateData.classification = classification;
      if (analystNotes !== undefined) updateData.analystNotes = analystNotes;
      if (developerNotes !== undefined) updateData.developerNotes = developerNotes;
      if (status) updateData.status = status;
      if (rejectionReason !== undefined) updateData.rejectionReason = rejectionReason;

      // When an analyst manually overrides the classification, prepend a notice to
      // ai_explanatory_notes so the AI Notes popup reflects what actually happened.
      if (classification) {
        try {
          const existingDeal = await storage.getDeal(dealId);
          const labelMap: Record<string, string> = { green: 'GREEN (High Priority)', yellow: 'YELLOW (Potential)', red: 'RED (Clear No)' };
          const label = labelMap[classification] || classification.toUpperCase();
          const analystEmail = (user?.claims?.email || user?.email || 'analyst');
          const overrideDate = new Date().toLocaleDateString('en-US', { month: 'short', day: 'numeric', year: 'numeric' });
          const overrideLine = `⚠️ Analyst manually overridden to ${label} by ${analystEmail} on ${overrideDate}.`;
          const existingNotes = (existingDeal as any)?.aiExplanatoryNotes || '';
          // Replace any previous override line so they don't stack up
          const withoutPriorOverride = existingNotes.replace(/^⚠️ Analyst manually overridden.*\n?/m, '').trim();
          updateData.aiExplanatoryNotes = withoutPriorOverride
            ? `${overrideLine}\n\n${withoutPriorOverride}`
            : overrideLine;
        } catch (_) { /* non-fatal — skip note update if deal fetch fails */ }
      }
      
      // Property details
      if (address !== undefined) updateData.address = address;
      if (propertyName !== undefined) updateData.propertyName = propertyName;
      if (unitCount !== undefined) updateData.unitCount = unitCount;
      if (sizeAcres !== undefined) updateData.sizeAcres = sizeAcres;
      if (askingPrice !== undefined) updateData.askingPrice = askingPrice;
      if (rentComparable !== undefined) updateData.topRentPSF = rentComparable;
      
      // Developer/Partner info
      if (developer !== undefined) updateData.developer = developer;
      if (partner !== undefined) updateData.partner = partner;
      
      // Workflow fields
      if (nextSteps !== undefined) updateData.nextSteps = nextSteps;
      if (assignedAnalyst !== undefined) updateData.assignedAnalyst = assignedAnalyst;
      
      // Demographics for Active Adult
      if (population55Plus5Mile !== undefined) updateData.population55Plus5Mile = population55Plus5Mile;
      if (income75Plus55Plus !== undefined) updateData.income75Plus55Plus = income75Plus55Plus;
      if (demographicsNotes !== undefined) updateData.demographicsNotes = demographicsNotes;
      
      if (user?.id) updateData.reviewedBy = user.id;
      updateData.reviewedAt = new Date();

      const updatedDeal = await storage.updateDeal(dealId, updateData);
      
      // Send notification email if deal was rejected with feedback
      if (status === "rejected" && rejectionReason) {
        try {
          const { emailAutomationService } = await import('./emailAutomation');
          await emailAutomationService.sendDealStatusUpdate(dealId, "rejected");
        } catch (emailError) {
          console.error("Failed to send rejection email:", emailError);
          // Don't fail the update if email fails
        }
      }
      
      res.json(updatedDeal);
    } catch (error) {
      console.error("Error updating deal:", error);
      res.status(500).json({ message: "Failed to update deal" });
    }
  });

  // Create new deal by analyst
  app.post("/api/analyst/deals", isAuthenticated, async (req, res) => {
    try {
      // Check if user is a Catalyst analyst
      // FIX (Dec 15, 2025): Check both user.email and user.claims.email for OIDC auth compatibility
      const user = req.user as any;
      const userEmail = user?.claims?.email || user?.email || '';
      const isAnalyst = userEmail.endsWith('@apexresi.com');
      
      console.log(`📋 [QUICK-DEAL] Auth check - User email: ${userEmail}, isAnalyst: ${isAnalyst}`);
      
      if (!isAnalyst) {
        console.warn(`⚠️ [QUICK-DEAL] ACCESS DENIED for user: ${userEmail}`);
        return res.status(403).json({ message: "Access denied. Analyst privileges required." });
      }

      const { 
        classification, 
        analystNotes, 
        status,
        // Property details
        address,
        city,
        state,
        zip,
        propertyName,
        unitCount,
        sizeAcres,
        askingPrice,
        rentComparable,
        productType,
        productTypes,
        sewerAvailable,
        zoningByRight,
        uploadedFiles,
        // Deal type (land development vs acquisition)
        dealType,
        yearBuilt,
        // Developer/Partner info (support both field name formats)
        developer,
        partner,
        assignedDeveloper,
        assignedPartner,
        suggestedDevelopmentType,
        // Workflow fields
        nextSteps,
        assignedAnalyst,
        // Demographics for Active Adult
        population55Plus5Mile,
        income75Plus55Plus,
        demographicsNotes,
        // AI Analysis data from Quick Property Evaluation
        aiAnalysisData,
        submissionMethod,
        // Broker data from Quick Deal Form
        brokerData,
        // Broker notes for the deal
        brokerNotes,
        // Manual coordinates (Dec 16, 2025) - bypasses geocoding when provided
        manualLatitude,
        manualLongitude,
        manualCoordsReason,
        parcelId,
        county
      } = req.body;
      
      // Create or find broker - prioritize brokerData from Quick Deal Form
      console.log('📋 [QUICK-DEAL] Broker data received:', brokerData);
      let brokerId: string | null = null;
      
      // USER FIX (Dec 10, 2025): Handle broker lookup by name OR email
      // Don't fall back to "Manual Entry" if user provides a name
      if (brokerData) {
        const hasEmail = brokerData.email && brokerData.email.trim();
        const hasName = (brokerData.firstName && brokerData.firstName.trim()) || 
                        (brokerData.lastName && brokerData.lastName.trim());
        const hasPhone = brokerData.phone && brokerData.phone.trim();
        
        console.log(`📋 [QUICK-DEAL] Broker info: hasEmail=${!!hasEmail}, hasName=${!!hasName}, hasPhone=${!!hasPhone}`);
        
        // Try to find/create broker if we have ANY identifying info
        if (brokerData.existingBrokerId || hasEmail || hasName || hasPhone) {
          try {
            // Priority 0: Direct broker ID from autocomplete selection — most reliable, skip all guessing
            if (brokerData.existingBrokerId) {
              const directBroker = await storage.getBrokerById(brokerData.existingBrokerId);
              if (directBroker) {
                console.log('✅ [QUICK-DEAL] Linked to selected broker directly by ID:', directBroker.id, `(${directBroker.firstName} ${directBroker.lastName})`);
                brokerId = directBroker.id;
                // If the analyst also provided updated contact info, patch the broker record
                const updates: Record<string, string> = {};
                if (hasEmail && brokerData.email !== directBroker.email) updates.email = brokerData.email;
                if (hasPhone && brokerData.phone !== directBroker.phone) updates.phone = brokerData.phone;
                if (Object.keys(updates).length > 0) {
                  await storage.updateBroker(directBroker.id, updates);
                  console.log('🔄 [QUICK-DEAL] Updated broker contact info:', updates);
                }
              }
            }

            // Priority 1: Try to find by email if provided
            if (!brokerId && hasEmail) {
              console.log('📧 [QUICK-DEAL] Attempting to find broker with email:', brokerData.email);
              const existingBroker = await storage.getBrokerByEmail(brokerData.email);
              if (existingBroker) {
                console.log('✅ [QUICK-DEAL] Found existing broker by email:', existingBroker.id);
                brokerId = existingBroker.id;
              }
            }
            
            // Priority 2: Try to find by phone if provided and not found by email
            if (!brokerId && hasPhone) {
              console.log('📱 [QUICK-DEAL] Attempting to find broker with phone:', brokerData.phone);
              const existingBroker = await storage.getBrokerByPhone(brokerData.phone);
              if (existingBroker) {
                console.log('✅ [QUICK-DEAL] Found existing broker by phone:', existingBroker.id);
                brokerId = existingBroker.id;
              }
            }
            
            // Priority 3: Create new broker with whatever info we have
            // USER FIX (Dec 11, 2025): Leave email/phone/markets blank if not provided
            // Don't generate placeholder emails - only save what user actually provided
            if (!brokerId) {
              const firstName = brokerData.firstName?.trim() || "";
              const lastName = brokerData.lastName?.trim() || "";
              // Only use email if actually provided - don't generate placeholder
              const email = hasEmail ? brokerData.email : null;
              
              console.log('🆕 [QUICK-DEAL] Creating new broker with name:', firstName, lastName);
              console.log('🆕 [QUICK-DEAL] Email provided:', hasEmail ? 'yes' : 'no (leaving blank)');
              const newBroker = await storage.createBroker({
                firstName: firstName || "Unknown",
                lastName: lastName || "Broker",
                email: email, // Can be null - user wants blank if not provided
                phone: hasPhone ? brokerData.phone : null, // Only if provided
                companyName: brokerData.companyName || null,
                marketsCovered: brokerData.marketsCovered ? [brokerData.marketsCovered] : [], // Empty array if not provided
              } as any);
              brokerId = newBroker.id;
              console.log('✅ [QUICK-DEAL] Created new broker:', brokerId, `(${firstName} ${lastName})`);
            }
          } catch (error) {
            console.error("❌ [QUICK-DEAL] Error creating/finding broker:", error);
            // Fall back to manual broker only on error
          }
        }
      }
      
      // No fallback to "Manual Entry" — if no broker info was provided, brokerId stays null
      console.log('✅ [QUICK-DEAL] Final broker ID:', brokerId ?? 'none (no broker info provided)');
      
      // Process uploaded files if provided
      let documentUrls: string[] = [];
      if (uploadedFiles && Array.isArray(uploadedFiles)) {
        documentUrls = uploadedFiles.filter((path: string) => {
          if (typeof path !== 'string') return false;
          const trimmed = path.trim();
          return trimmed.startsWith('/replit-objstore-') || trimmed.startsWith('/objects/');
        }).map((path: string) => path.trim());
        console.log(`📎 [QUICK-DEAL] Processing ${documentUrls.length} uploaded files`);
      }

      // Apply automatic routing if not manually specified
      let finalAnalyst = assignedAnalyst;
      let finalDeveloper = developer || assignedDeveloper; // Support both field names
      let finalPartner = partner || assignedPartner; // Support both field names
      
      // If analyst hasn't manually specified assignments, apply automatic routing
      if (!assignedAnalyst || (!developer && !assignedDeveloper) || (!partner && !assignedPartner)) {
        // For manual deals, try to infer product type from property name or address
        const propertyText = `${propertyName || ''} ${address || ''}`.toLowerCase();
        let inferredProductTypes: string[] = [];
        
        if (propertyText.includes('btr') || propertyText.includes('build to rent')) {
          inferredProductTypes = ['BTR'];
        } else if (propertyText.includes('lot') || propertyText.includes('subdivision')) {
          inferredProductTypes = ['Lot Development'];
        } else if (propertyText.includes('apartment') || propertyText.includes('multifamily')) {
          inferredProductTypes = ['Conventional Apartments'];
        }
        
        const routing = await getAutomaticRouting(inferredProductTypes, 'Manual Entry');
        
        // Only apply routing if not manually specified
        if (!assignedAnalyst && routing.analyst) finalAnalyst = routing.analyst;
        if (!finalDeveloper && routing.developer) finalDeveloper = routing.developer;
        if (!finalPartner && routing.partner) finalPartner = routing.partner;
      }

      // Build broker name from brokerData even if no email provided
      const brokerFullName = brokerData 
        ? `${brokerData.firstName || ''} ${brokerData.lastName || ''}`.trim() || null
        : null;

      const dealData = {
        brokerId,
        submissionMethod: submissionMethod || "manual",
        address: address || '',
        city: city || null,
        state: state || null,
        zip: zip || null,
        propertyName: propertyName || '',
        unitCount: unitCount ? parseInt(unitCount.toString()) : null,
        sizeAcres: sizeAcres !== null && sizeAcres !== undefined && sizeAcres !== '' ? parseFloat(sizeAcres.toString()) : null,
        askingPrice: askingPrice !== null && askingPrice !== undefined && askingPrice !== '' ? parseFloat(askingPrice.toString()) : null,
        topRentPSF: rentComparable !== null && rentComparable !== undefined && rentComparable !== '' ? parseFloat(rentComparable.toString()) : null,
        productTypes: productTypes && Array.isArray(productTypes) && productTypes.length > 0 
          ? productTypes 
          : (productType ? [productType] : []),
        sewerAvailable: sewerAvailable === true ? true : null, // Only save true if checked, null otherwise (unknown)
        zoning: zoningByRight === true ? 'By-Right' : null, // Only save if checked
        // Deal type and year built for acquisition deals
        dealType: dealType || 'land', // Default to 'land' for backwards compatibility
        yearBuilt: yearBuilt ? parseInt(yearBuilt.toString()) : null,
        assignedDeveloper: finalDeveloper, // Store using correct schema field name
        assignedPartner: finalPartner, // Store using correct schema field name
        nextSteps: nextSteps || '',
        assignedAnalyst: finalAnalyst,
        // Demographics for Active Adult
        population55Plus5Mile: population55Plus5Mile ? parseInt(population55Plus5Mile.toString()) : null,
        income75Plus55Plus: income75Plus55Plus ? parseInt(income75Plus55Plus.toString()) : null,
        demographicsNotes: demographicsNotes || '',
        classification: classification || 'unclassified',
        analystNotes: analystNotes || '',
        status: status || 'pending_review',
        reviewedBy: user?.id,
        reviewedAt: new Date(),
        // Add support for suggested development type from Quick Property Evaluation
        suggestedDevelopmentType: suggestedDevelopmentType || '',
        // Parcel ID / APN - allow deals submitted with only a parcel ID
        parcelId: parcelId || null,
        // County - required when using parcel ID (parcel IDs are county-specific)
        county: county || null,
        // Add AI analysis data if provided (store as JSONB, not stringified)
        ...(aiAnalysisData && { aiAnalysisData }),
        // Add uploaded document URLs - quick deal uploads are broker documents
        documentUrls: documentUrls.length > 0 ? documentUrls : [],
        // Save broker notes if provided (broker name/phone/email are stored on broker record, not deal)
        ...(brokerNotes && { brokerNotes }),
        // Manual coordinates (Dec 16, 2025) - bypasses geocoding when provided
        ...(manualLatitude && manualLongitude && { 
          manualLatitude: parseFloat(manualLatitude.toString()),
          manualLongitude: parseFloat(manualLongitude.toString()),
          manualCoordsReason: manualCoordsReason || 'Coordinates provided via Quick Add form',
          // Also set as primary coordinates so HelloData uses them directly
          latitude: parseFloat(manualLatitude.toString()),
          longitude: parseFloat(manualLongitude.toString()),
        }),
      };

      const newDeal = await storage.createDeal(dealData as any);
      
      // PERFORMANCE OPTIMIZATION: Return deal IMMEDIATELY, run classification in background
      const isAcquisitionDeal = dealType === 'acquisition';
      console.log(`⚡ [QUICK-DEAL] ${isAcquisitionDeal ? 'Acquisition' : 'Land'} deal ${newDeal.id} created instantly - queuing background classification...`);

      // Auto-score LIHTC site suitability in background (non-blocking)
      // NC deals get full scoring (amenities + neighborhood=10); all others get site-eval only.
      setImmediate(async () => {
        try {
          const dealLat = newDeal.latitude ? parseFloat(newDeal.latitude) : null;
          const dealLng = newDeal.longitude ? parseFloat(newDeal.longitude) : null;
          if (!dealLat || !dealLng) {
            console.log(`⚠️ [LIHTC-AUTO] No coordinates for deal ${newDeal.id}, skipping auto-score`);
            return;
          }
          const dealState = (newDeal.state || state || '').toString().trim().toUpperCase();
          const isNC = dealState === 'NC' || dealState === 'NORTH CAROLINA';
          console.log(`🏗️ [LIHTC-AUTO] Auto-scoring deal ${newDeal.id} (state=${dealState}, fullScore=${isNC})...`);

          if (isNC) {
            // Full LIHTC score for NC deals: amenities + neighborhood (hardcoded 10) + all criteria
            const { autoScoreLIHTC } = await import('./lihtcAutoScoreService.js');
            const result = await autoScoreLIHTC({
              lat: dealLat,
              lng: dealLng,
              address: address || newDeal.address || '',
              county: newDeal.county || null,
              state: dealState,
              qctStatus: (newDeal as any).qctStatus || null,
              totalUnits: newDeal.unitCount || null,
            });
            const evalData: any = {
              dealId: newDeal.id,
              address: address || newDeal.address || '',
              latitude: String(dealLat),
              longitude: String(dealLng),
              scoreNeighborhood: result.neighborhoodCharacter,
              scorePrimaryAmenities: result.primaryAmenities,
              scoreSecondaryAmenities: result.secondaryAmenities,
              scoreSiteSuitability: result.siteSuitability,
              scoreTransit: result.transitPoints,
              scoreNegativePoints: result.negativePoints,
              scoreIncomeRPP: result.incomeRPP,
              scoreTotal: result.total,
              amenityDetails: result.amenityDetails || [],
              evaluatedAt: new Date(),
            };
            await storage.createSiteEvaluation(evalData);
            await storage.updateDeal(newDeal.id, { lihtcScoreTotal: result.total, lihtcScorePreliminary: true, lihtcScoredAt: new Date() } as any);
            console.log(`✅ [LIHTC-AUTO] NC deal ${newDeal.id} fully scored: ${result.total} pts (neighborhood=10, amenities=${result.primaryAmenities + result.secondaryAmenities})`);
          } else {
            // Partial site-eval for non-NC deals (neighborhood hardcoded to 10)
            const { evaluateSite } = await import('./siteEvaluationService.js');
            const googleApiKey = process.env.VITE_GOOGLE_MAPS_API_KEY || process.env.GOOGLE_MAPS_API_KEY;
            const siteEval = await evaluateSite(dealLat, dealLng, googleApiKey);
            const transit = siteEval.transit?.transitScore ?? 0;
            const noIncompat = !(siteEval.incompatibleUses?.hasIncompatibleUses || siteEval.hazardousSites?.hasNearbyHazards);
            const noNeg = !(siteEval.floodZone?.isInFloodZone || siteEval.slope?.hasSteepSlope);
            let site = 0;
            if (noIncompat) site += 6;
            if (noNeg) site += 3;
            site += 3;
            const neg = noNeg ? 0 : -3;
            const total = 10 + transit + site + neg + 1; // 10 = hardcoded neighborhood
            const evalData: any = {
              dealId: newDeal.id,
              address: address || newDeal.address || '',
              latitude: String(dealLat),
              longitude: String(dealLng),
              scoreNeighborhood: 10,
              scorePrimaryAmenities: 0,
              scoreSecondaryAmenities: 0,
              scoreSiteSuitability: site,
              scoreTransit: transit,
              scoreNegativePoints: neg,
              scoreIncomeRPP: 1,
              scoreTotal: total,
              floodZoneData: siteEval.floodZone ?? null,
              hazardsData: siteEval.hazardousSites ?? null,
              slopeData: siteEval.slope ?? null,
              transitData: siteEval.transit ?? null,
              incompatibleUsesData: siteEval.incompatibleUses ?? null,
              amenityDetails: [],
              evaluatedAt: new Date(),
            };
            await storage.createSiteEvaluation(evalData);
            await storage.updateDeal(newDeal.id, { lihtcScoreTotal: total, lihtcScorePreliminary: true, lihtcScoredAt: new Date() } as any);
            console.log(`✅ [LIHTC-AUTO] Deal ${newDeal.id} scored: ${total} pts`);
          }
        } catch (lihtcErr: any) {
          console.warn(`⚠️ [LIHTC-AUTO] Auto-scoring failed for deal ${newDeal.id}: ${lihtcErr.message}`);
        }
      });
      
      // FIX (Jan 22, 2026): Send deal_submitted confirmation email immediately (using SendGrid template)
      try {
        const broker = brokerId ? await storage.getBrokerById(brokerId) : null;
        const isManualBroker = broker?.email === 'manual@catalystcp.com';
        
        if (broker && !isManualBroker && broker.email && !broker.email.includes('@temp.landlinq.ai')) {
          console.log(`📧 [QUICK-DEAL] Sending deal_submitted confirmation to broker: ${broker.email}`);
          
          const { TemplateService } = await import('./templateService');
          const { sendNotificationEmail } = await import('./emailService');
          
          const emailTemplate = await TemplateService.getEmailTemplate('deal_submitted', {
            brokerName: `${broker.firstName || ''} ${broker.lastName || ''}`.trim() || 'Broker',
            address: address,
            propertyAddress: address,
            dealId: newDeal.id,
            date: new Date().toLocaleDateString(),
            dealValue: askingPrice ? `$${Number(askingPrice).toLocaleString()}` : 'TBD',
          });
          
          if (emailTemplate) {
            // CRITICAL: Pass sendgridTemplateId for dynamic templates
            await sendNotificationEmail({
              to: broker.email,
              subject: emailTemplate.subject,
              html: emailTemplate.html,
              type: 'deal_submitted',
              sendgridTemplateId: emailTemplate.sendgridTemplateId,
              sendgridDynamicData: emailTemplate.sendgridDynamicData,
            });
            const templateMode = emailTemplate.sendgridTemplateId ? `SendGrid (${emailTemplate.sendgridTemplateId})` : 'Outreach Tab';
            console.log(`✅ [QUICK-DEAL] Confirmation email sent via ${templateMode} to: ${broker.email}`);
          } else {
            console.log(`⚠️ [QUICK-DEAL] No email template found for deal_submitted event`);
          }
        } else {
          console.log(`ℹ️ [QUICK-DEAL] Skipping confirmation email - ${isManualBroker ? 'manual broker' : 'no valid broker email'}`);
        }
        
        // FIX (Jan 29, 2026): Also send SMS confirmation if broker has phone
        if (broker && !isManualBroker && broker.phone && broker.smsOptIn !== false) {
          console.log(`📱 [QUICK-DEAL] Sending deal_submitted confirmation SMS to broker: ${broker.phone}`);
          
          const { TemplateService } = await import('./templateService');
          const { sendSMS } = await import('./smsService');
          
          const smsTemplate = await TemplateService.getSMSTemplate('deal_submitted', {
            brokerName: `${broker.firstName || ''} ${broker.lastName || ''}`.trim() || 'Broker',
            address: address,
            propertyAddress: address,
          });
          
          if (smsTemplate) {
            await sendSMS({ to: broker.phone, message: smsTemplate, brokerOverride: broker });
            console.log(`✅ [QUICK-DEAL] Confirmation SMS sent to: ${broker.phone}`);
          } else {
            console.log(`⚠️ [QUICK-DEAL] No SMS template found for deal_submitted event`);
          }
        } else if (broker && !isManualBroker && broker.phone) {
          console.log(`ℹ️ [QUICK-DEAL] Skipping confirmation SMS - broker opted out of SMS`);
        }
      } catch (emailError) {
        console.error(`⚠️ [QUICK-DEAL] Failed to send confirmation notifications:`, emailError);
        // Don't fail the request if notifications fail
      }
      
      // Queue background job for classification (non-blocking) - BOTH LAND AND ACQUISITION DEALS
      try {
        await storage.createBackgroundJob({
          jobType: 'quick_deal_enrichment',
          payload: { dealId: newDeal.id },
          status: 'pending',
          scheduledFor: new Date(), // Run immediately
        });
        console.log(`📋 [QUICK-DEAL] Background classification job queued for deal ${newDeal.id}`);
      } catch (jobError) {
        console.error(`⚠️ [QUICK-DEAL] Failed to queue background job:`, jobError);
        // Don't fail the request - deal is already created
      }
      
      // Return immediately with the new deal (classification will run in background)
      res.json({
        ...newDeal,
        _processingStatus: 'classification_pending', // Signal to frontend that classification is in progress
      });
    } catch (error) {
      console.error("Error creating deal:", error);
      res.status(500).json({ message: "Failed to create deal" });
    }
  });

  // Export deals to Excel
  // Bulk operations endpoint
  app.post("/api/analyst/deals/bulk", isAuthenticated, async (req, res) => {
    try {
      // Check if user is a Catalyst analyst or super admin
      const user = req.user as any;
      const userEmail = user?.email || user?.claims?.email || '';
      const isAnalyst = userEmail.endsWith('@apexresi.com') || userEmail === 'jack@apexresi.com';
      
      if (!isAnalyst) {
        return res.status(403).json({ message: "Access denied. Admin/analyst privileges required." });
      }

      const { dealIds, operation, data } = req.body;

      if (!Array.isArray(dealIds) || dealIds.length === 0) {
        return res.status(400).json({ message: "Deal IDs array is required" });
      }

      if (!operation) {
        return res.status(400).json({ message: "Operation type is required" });
      }

      // Perform bulk operation based on operation type
      let updateData: any = {};
      
      switch (operation) {
        case 'approve-all':
          updateData = { classification: 'green', status: 'high_priority' };
          break;
        case 'reject-all':
          updateData = { classification: 'red', status: 'clear_no' };
          break;
        case 'review-all':
          updateData = { status: 'under_review' };
          break;
        case 'auto-fill-all':
          // For auto-fill, we need to process each deal individually
          const autoFillPromises = dealIds.map(async (dealId: string) => {
            try {
              // Trigger auto-population for each deal
              // return await realDataService.performRapidDealAnalysis(dealId);
              return dealId; // Placeholder for now
            } catch (error) {
              console.error(`Auto-fill failed for deal ${dealId}:`, error);
              return null;
            }
          });
          
          const autoFillResults = await Promise.all(autoFillPromises);
          const successCount = autoFillResults.filter((result: any) => result !== null).length;
          
          return res.json({ 
            success: true, 
            processedDeals: successCount,
            message: `Auto-filled ${successCount} deals successfully` 
          });
        case 'delete-all':
          // Handle bulk delete operation with improved transaction handling
          try {
            // Log bulk delete action
            await logAuditTrail({
              userId: user?.claims?.sub || user?.id,
              action: 'BULK_DELETE_DEALS',
              entityType: 'DEALS',
              tableName: 'deals',
              recordId: `bulk-${dealIds.length}`,
              changedBy: user?.claims?.sub || user?.id || 'anonymous',
              details: { dealIds: dealIds, count: dealIds.length, userEmail },
              userAgent: req.get('User-Agent'),
              ipAddress: req.ip
            });
            
            console.log(`🗑️ Starting bulk delete of ${dealIds.length} deals`);
            const bulkDeleteResults = await storage.bulkDeleteDeals(dealIds);
            
            console.log(`🗑️ Bulk delete completed: ${bulkDeleteResults.successCount} successful, ${bulkDeleteResults.errorCount} errors`);
            
            return res.json({ 
              success: true,
              message: `Bulk delete completed. ${bulkDeleteResults.successCount} deleted successfully${bulkDeleteResults.errorCount > 0 ? `, ${bulkDeleteResults.errorCount} failed` : ''}.`,
              results: bulkDeleteResults.results,
              processedDeals: bulkDeleteResults.successCount,
              successCount: bulkDeleteResults.successCount,
              errorCount: bulkDeleteResults.errorCount
            });
          } catch (error) {
            console.error('❌ Bulk delete operation failed:', error);
            return res.status(500).json({ 
              success: false,
              message: 'Bulk delete operation failed',
              error: error instanceof Error ? error.message : 'Unknown error'
            });
          }
        default:
          return res.status(400).json({ message: "Invalid operation type" });
      }

      // Fetch current deal states before updating (needed for change detection)
      const preBulkDeals = await Promise.all(
        dealIds.map((dealId: string) => storage.getDealById(dealId))
      );

      // Update all deals with the same data
      const updatePromises = dealIds.map((dealId: string) => 
        storage.updateDeal(dealId, updateData)
      );
      await Promise.all(updatePromises);

      // Send broker notifications for classification-changing bulk ops (fire-and-forget)
      if (updateData.classification && (operation === 'approve-all' || operation === 'reject-all')) {
        const newClass: string = updateData.classification;
        const isRed = newClass === 'red' || newClass === 'clear_no';
        const isGreen = newClass === 'green' || newClass === 'high_priority';
        const isYellow = newClass === 'yellow' || newClass === 'potential';
        const eventToDispatch = isRed ? 'status_rejected' : isGreen ? 'status_pursuing' : isYellow ? 'status_under_review' : null;

        if (eventToDispatch) {
          (async () => {
            try {
              const { EventDispatchService } = await import('./eventDispatch');
              const { getAnalystInfo } = await import('./landLinqTemplates');
              for (let i = 0; i < preBulkDeals.length; i++) {
                const preDeal = preBulkDeals[i];
                if (!preDeal || !preDeal.brokerId) continue;
                // Skip if classification didn't actually change
                const oldClass = preDeal.classification;
                const wasRed = oldClass === 'red' || oldClass === 'clear_no';
                const wasGreen = oldClass === 'green' || oldClass === 'high_priority';
                const wasYellow = oldClass === 'yellow' || oldClass === 'potential';
                if (isRed && wasRed) continue;
                if (isGreen && wasGreen) continue;
                if (isYellow && wasYellow) continue;

                try {
                  const broker = await storage.getBrokerById(preDeal.brokerId);
                  if (!broker) continue;
                  const productTypes = (preDeal.productTypes as string[]) || [];
                  const primaryProductType = productTypes[0] || 'Conventional Apartments';
                  const analystInfo = getAnalystInfo(newClass || 'yellow', primaryProductType);
                  const result = await EventDispatchService.emit(eventToDispatch as any, {
                    brokerName: broker.firstName ? `${broker.firstName} ${broker.lastName}` : broker.brokerage || 'Broker',
                    brokerEmail: broker.email || '',
                    brokerPhone: broker.phone || undefined,
                    propertyAddress: preDeal.address || 'Property',
                    address: preDeal.address || 'Property',
                    dealValue: 'TBD',
                    dealId: preDeal.id,
                    brokerId: broker.id,
                    productType: primaryProductType,
                    analystName: analystInfo.analystName,
                    classification: newClass,
                    rejectionReason: preDeal.rejectionReason || 'Does not meet acquisition criteria',
                  });
                  console.log(`✅ [BULK-NOTIF] ${eventToDispatch} sent to ${broker.email || broker.phone} for deal ${preDeal.id}: email=${result.emailSent}, sms=${result.smsSent}`);
                } catch (e) {
                  console.error(`❌ [BULK-NOTIF] Failed for deal ${preBulkDeals[i]?.id}:`, e);
                }
              }
            } catch (e) {
              console.error('❌ [BULK-NOTIF] Outer error:', e);
            }
          })();
        }
      }

      res.json({ 
        success: true, 
        processedDeals: dealIds.length,
        message: `Successfully updated ${dealIds.length} deals` 
      });

    } catch (error) {
      console.error("Error performing bulk operation:", error);
      res.status(500).json({ message: "Failed to perform bulk operation" });
    }
  });

