  app.post("/api/analyst/auto-classify", isAuthenticated, async (req, res) => {
    try {
      // Check if user is a Catalyst analyst
      const user = req.user as any;
      const isAnalyst = (user?.claims?.email || user?.email || '').endsWith('@apexresi.com');
      
      if (!isAnalyst) {
        return res.status(403).json({ message: "Access denied. Analyst privileges required." });
      }

      // Get all deals that haven't been classified or are pending classification
      const deals = await storage.getAllDeals();
      const unclassifiedDeals = deals.filter(deal => 
        !deal.classification || (deal.classification as string) === '' || deal.status === 'pending_review'
      );

      let processedCount = 0;

      // Process each unclassified deal using the new enhanced classification system
      for (const deal of unclassifiedDeals) {
        try {
          // Use the new MULTI-TYPE analysis system with AUTO-ENRICHMENT - tests all development types
          const multiAnalysis = await classifyAllDevelopmentTypes(deal);
          const classification = {
            classification: multiAnalysis.bestClassification,
            reasoning: multiAnalysis.viableOptions[0]?.reasoning || [],
            conditionsMet: multiAnalysis.viableOptions[0]?.conditionsMet || [],
            conditionsNotMet: multiAnalysis.viableOptions[0]?.conditionsNotMet || [],
            insufficientData: multiAnalysis.dataQuality.missingCriticalFields
          };
          
          // Map classification to status
          let autoStatus: 'clear_no' | 'potentially' | 'high_priority' | 'pending_review' | 'under_review' | 'approved' | 'rejected';
          
          switch (classification.classification as string) {
            case 'green':
              autoStatus = 'high_priority';
              break;
            case 'yellow':
              autoStatus = 'potentially';
              break;
            case 'red':
              autoStatus = 'clear_no';
              break;
            default:
              autoStatus = 'pending_review';
          }

          // Create detailed analyst notes with classification reasoning
          const reasoningText = classification.reasoning.join('; ');
          const conditionsMetText = classification.conditionsMet.length > 0 ? 
            `✅ Met: ${classification.conditionsMet.join('; ')}` : '';
          const conditionsNotMetText = classification.conditionsNotMet.length > 0 ? 
            `❌ Not Met: ${classification.conditionsNotMet.join('; ')}` : '';
          const insufficientDataText = classification.insufficientData.length > 0 ? 
            `⚠️ Missing Data: ${classification.insufficientData.join('; ')}` : '';
          
          const newAnalystNotes = [
            `[Auto-classified: ${classification.classification.toUpperCase()}]`,
            reasoningText,
            conditionsMetText,
            conditionsNotMetText,
            insufficientDataText,
            deal.analystNotes || ''
          ].filter(Boolean).join('\n\n');

          // Update the deal with enhanced classification
          await storage.updateDeal(deal.id, {
            classification: classification.classification,
            status: autoStatus,
            analystNotes: newAnalystNotes
          });

          // Send broker notification if deal is marked red
          if (classification.classification === 'red' && deal.brokerId) {
            try {
              const broker = await storage.getBrokerById(deal.brokerId);
              if (broker?.email) {
                await sendRedDealNotification(broker, deal, classification);
              }
            } catch (notificationError) {
              console.error(`Failed to notify broker for red deal ${deal.id}:`, notificationError);
            }
          }

          // Send broker notification if deal is marked yellow  
          if (classification.classification === 'yellow' && deal.brokerId) {
            try {
              const broker = await storage.getBrokerById(deal.brokerId);
              if (broker?.email) {
                await sendYellowDealNotification(broker, deal, classification);
              }
            } catch (notificationError) {
              console.error(`Failed to notify broker for orange deal ${deal.id}:`, notificationError);
            }
          }

          processedCount++;
        } catch (error) {
          console.error(`Failed to auto-classify deal ${deal.id}:`, error);
        }
      }

      res.json({ 
        success: true, 
        processedDeals: processedCount,
        totalUnclassified: unclassifiedDeals.length,
        message: `Auto-classified ${processedCount} deals using AI analysis` 
      });

    } catch (error) {
      console.error("Error in auto-classification:", error);
      res.status(500).json({ message: "Failed to perform auto-classification" });
    }
  });

