  // Update review status and add notes
  app.patch("/api/analyst/review-queue/:reviewId/status", isAuthenticated, async (req, res) => {
    try {
      const user = req.user as any;
      const isAnalyst = user?.email?.endsWith('@apexresi.com');
      
      if (!isAnalyst) {
        return res.status(403).json({ message: "Access denied. Analyst privileges required." });
      }

      const { reviewId } = req.params;
      const { status, notes, timeSpentMinutes, resolution } = req.body;

      if (!status) {
        return res.status(400).json({ message: "Status is required" });
      }

      const updateData: any = {
        status,
        updatedAt: new Date()
      };

      if (notes) updateData.analystNotes = notes;
      if (resolution) updateData.resolution = resolution;
      
      if (status === 'in_review' && !updateData.reviewStartedAt) {
        updateData.reviewStartedAt = new Date();
      }
      
      if (status === 'completed' || status === 'approved' || status === 'rejected') {
        updateData.reviewCompletedAt = new Date();
      }

      // Update review status
      await db.update(reviewQueue)
        .set(updateData)
        .where(eq(reviewQueue.id, reviewId));

      // Apply corrections to deal if review is approved/completed and has corrections
      if ((status === 'approved' || status === 'completed') && status !== 'rejected') {
        try {
          const { reviewCorrectionService } = await import('./reviewCorrectionService');
          const hasCorrections = await reviewCorrectionService.hasUnappliedCorrections(reviewId);
          
          if (hasCorrections) {
            console.log(`🔄 Applying corrections for completed review ${reviewId}`);
            await reviewCorrectionService.applyCorrectionsToDeal(reviewId);
            
            // Log correction application
            await db.insert(reviewActions).values({
              reviewQueueId: reviewId,
              dealId: sql`(SELECT deal_id FROM review_queue WHERE id = ${reviewId})`,
              actionType: 'corrections_integrated',
              analystId: user.id,
              analystName: `${user.firstName || ''} ${user.lastName || ''}`.trim(),
              notes: 'Manual corrections applied to deal record',
              timeSpentMinutes: 1
            });
          }
        } catch (correctionError) {
          console.error(`Error applying corrections for review ${reviewId}:`, correctionError);
          // Don't fail the status update if correction application fails
        }
      }

      // Log the status change
      await db.insert(reviewActions).values({
        reviewQueueId: reviewId,
        dealId: sql`(SELECT deal_id FROM review_queue WHERE id = ${reviewId})`,
        actionType: `status_changed_${status}`,
        analystId: user.id,
        analystName: `${user.firstName || ''} ${user.lastName || ''}`.trim(),
        notes: notes || `Status changed to ${status}`,
        timeSpentMinutes: timeSpentMinutes || 0
      });

      res.json({ message: "Review status updated successfully" });

    } catch (error) {
      console.error("Error updating review status:", error);
      res.status(500).json({ message: "Failed to update review status" });
    }
  });

