  app.post("/api/analyst/review-queue/bulk", isAuthenticated, async (req, res) => {
    try {
      const user = req.user as any;
      const isAnalyst = user?.email?.endsWith('@apexresi.com');
      
      if (!isAnalyst) {
        return res.status(403).json({ message: "Access denied. Analyst privileges required." });
      }

      const { action, reviewIds, analystId } = req.body;

      if (!action || !reviewIds || !Array.isArray(reviewIds)) {
        return res.status(400).json({ message: "Action and review IDs are required" });
      }

      let results = { updated: 0, errors: 0 };

      for (const reviewId of reviewIds) {
        try {
          if (action === 'assign' && analystId) {
            await db.update(reviewQueue)
              .set({
                status: 'assigned',
                assignedAnalyst: analystId,
                assignedAt: new Date(),
                updatedAt: new Date()
              })
              .where(eq(reviewQueue.id, reviewId));

            results.updated++;
          } else if (action === 'approve') {
            await db.update(reviewQueue)
              .set({
                status: 'approved',
                resolution: 'bulk_approved',
                reviewCompletedAt: new Date(),
                updatedAt: new Date()
              })
              .where(eq(reviewQueue.id, reviewId));

            results.updated++;
          }
        } catch (error) {
          console.error(`Error processing review ${reviewId}:`, error);
          results.errors++;
        }
      }

      res.json({ 
        message: `Bulk operation completed: ${results.updated} updated, ${results.errors} errors`,
        results
      });

    } catch (error) {
      console.error("Error performing bulk operation:", error);
      res.status(500).json({ message: "Failed to perform bulk operation" });
    }
  });

  // File upload endpoint for deal documents
  
  // Ensure attached_assets directory exists
  const attachedAssetsDir = path.join(process.cwd(), 'attached_assets');
  if (!fs.existsSync(attachedAssetsDir)) {
    fs.mkdirSync(attachedAssetsDir, { recursive: true });
  }
  
  const upload = multer({ 
    storage: multer.diskStorage({
      destination: (req, file, cb) => {
        cb(null, attachedAssetsDir);
      },
      filename: (req, file, cb) => {
        // Generate unique filename with timestamp
        const uniqueSuffix = Date.now() + '-' + Math.round(Math.random() * 1E9);
        const ext = path.extname(file.originalname);
        const nameWithoutExt = path.basename(file.originalname, ext);
        cb(null, nameWithoutExt + '-' + uniqueSuffix + ext);
      }
    }),
    limits: {
      fileSize: 10 * 1024 * 1024, // 10MB limit
      files: 1 // Only allow 1 file per upload
    },
    fileFilter: (req, file, cb) => {
      // Allow common document and image types (expanded for real estate documents)
      const allowedMimes = [
        'application/pdf',
        'application/msword',
        'application/vnd.openxmlformats-officedocument.wordprocessingml.document',
        'application/vnd.ms-excel',
        'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet',
        'image/jpeg',
        'image/jpg',
        'image/png',
        'image/gif',
        'image/webp',
        'image/heic',
        'image/heif',
        'text/plain',
        'text/csv',
        'application/zip',
        'application/x-zip-compressed'
      ];
      
      if (allowedMimes.includes(file.mimetype)) {
        cb(null, true);
      } else {
        console.log(`[UPLOAD] Rejected file type: ${file.mimetype} for file: ${file.originalname}`);
        cb(new Error(`Invalid file type: ${file.mimetype}. Allowed: PDF, Word, Excel, images, text, CSV, ZIP.`));
      }
    }
  });
  
