      const businessSettings = await storage.getBusinessSettings();
      
      console.log('BusinessSettings raw:', JSON.stringify(businessSettings, null, 2));
      
      // Helper function to safely parse JSON fields
      const safeParseJsonField = (field: any): any[] => {
        if (Array.isArray(field)) return field;
        if (typeof field === 'string') {
          try {
            const parsed = JSON.parse(field);
            return Array.isArray(parsed) ? parsed : [];
          } catch {
            return [];
          }
        }
        return [];
      };
      
      // Enhanced field parser that handles both arrays and JSON strings
      const safeParseField = (field: any): any[] => {
        if (Array.isArray(field)) {
          console.log('DEBUG: Field is already array, length:', field.length);
          return field;
        }
        if (typeof field === 'string') {
          try {
            const parsed = JSON.parse(field);
            console.log('DEBUG: Parsed JSON string, length:', Array.isArray(parsed) ? parsed.length : 0);
            return Array.isArray(parsed) ? parsed : [];
          } catch {
            console.log('DEBUG: Failed to parse JSON string, returning empty array');
            return [];
          }
        }
        console.log('DEBUG: Field is neither array nor string, returning empty array');
        return [];
      };

      // Debug logging for template parsing
      console.log('DEBUG: Raw emailTemplates type:', typeof (businessSettings as any)?.emailTemplates);
      console.log('DEBUG: Raw emailTemplates array check:', Array.isArray((businessSettings as any)?.emailTemplates));
      console.log('DEBUG: Raw emailTemplates length:', (businessSettings as any)?.emailTemplates?.length);
      
      const parsedEmailTemplates = safeParseField((businessSettings as any)?.emailTemplates);
      const parsedSmsTemplates = safeParseField((businessSettings as any)?.smsTemplates);
      
