  // IMPORT TEMPLATES - Upload JSON file to restore templates
  app.post('/api/templates/import', isAuthenticated, async (req: any, res) => {
    try {
      const user = req.user;
      const userEmail = user?.email || '';
      
      // Only allow super admin
      if (userEmail !== 'jack@apexresi.com') {
        return res.status(403).json({ message: "Unauthorized - Super admin access required" });
      }

      const { emailTemplates, smsTemplates, mergeMode } = req.body;
      
      if (!emailTemplates && !smsTemplates) {
        return res.status(400).json({ error: 'No templates provided' });
      }

      const businessSettings = await storage.getBusinessSettings();
      
      let finalEmailTemplates = emailTemplates || [];
      let finalSmsTemplates = smsTemplates || [];
      
      // If merge mode, combine with existing templates (avoid duplicates by event name)
      if (mergeMode === 'merge') {
        const existingEmailTemplates = (businessSettings as any)?.emailTemplates || [];
        const existingEmailEvents = new Set(existingEmailTemplates.map((t: any) => t.event));
        
        // Add new templates that don't exist
        const newEmailTemplates = emailTemplates.filter((t: any) => !existingEmailEvents.has(t.event));
        finalEmailTemplates = [...existingEmailTemplates, ...newEmailTemplates];
        
        const existingSmsTemplates = (businessSettings as any)?.smsTemplates || [];
        const existingSmsEvents = new Set(existingSmsTemplates.map((t: any) => t.event));
        
        const newSmsTemplates = smsTemplates.filter((t: any) => !existingSmsEvents.has(t.event));
        finalSmsTemplates = [...existingSmsTemplates, ...newSmsTemplates];
      }

      await storage.updateBusinessSettings({
        emailTemplates: finalEmailTemplates,
        smsTemplates: finalSmsTemplates
      });

      res.json({
        success: true,
        message: 'Templates imported successfully',
        imported: {
          email: finalEmailTemplates.length,
          sms: finalSmsTemplates.length
        }
      });

      console.log(`✅ Imported ${finalEmailTemplates.length} email templates and ${finalSmsTemplates.length} SMS templates (mode: ${mergeMode || 'replace'})`);
    } catch (error: any) {
      console.error('Error importing templates:', error);
      res.status(500).json({ error: 'Failed to import templates' });
    }
  });

