  app.get('/api/gamification/stats', isAuthenticated, async (req: any, res) => {
    try {
      const userId = req.user?.id;
      const broker = await storage.getBrokerByUserId(userId);
      
      if (!broker) {
        return res.status(404).json({ message: 'Broker not found' });
      }

      // Calculate rank based on total points
      const allBrokers = await storage.getAllBrokers();
      const brokerAny = broker as any;
      const sortedBrokers = allBrokers
        .filter(b => (b as any).totalPoints && (b as any).totalPoints > 0)
        .sort((a, b) => ((b as any).totalPoints || 0) - ((a as any).totalPoints || 0));
      
      const rank = sortedBrokers.findIndex(b => b.id === broker.id) + 1;
      
      // Calculate referral count
      const referralCount = allBrokers.filter(b => (b as any).referredBy === broker.id).length;
      
      // Calculate next level threshold
      const LEVEL_THRESHOLDS = [0, 100, 250, 500, 1000, 2000, 4000, 8000, 15000, 30000];
      const nextLevelThreshold = LEVEL_THRESHOLDS[brokerAny.currentLevel || 1] || 50000;
      const pointsToNextLevel = Math.max(0, nextLevelThreshold - (brokerAny.totalPoints || 0));

      const stats = {
        totalPoints: brokerAny.totalPoints || 0,
        currentLevel: brokerAny.currentLevel || 1,
        shareCount: brokerAny.shareCount || 0,
        consecutiveDeals: brokerAny.consecutiveDeals || 0,
        referralCount,
        rank: rank || 999,
        pointsToNextLevel,
        nextLevelThreshold,
        referralCode: brokerAny.referralCode || broker.id.slice(0, 8).toUpperCase()
      };

      res.json(stats);
    } catch (error) {
      console.error('Error fetching gamification stats:', error);
      res.status(500).json({ message: 'Failed to fetch stats' });
    }
  });

