      const averageRentPerUnit = hellodataRent?.metadata?.averageRent || 
        (comparables?.length > 0 
          ? Math.round(comparables.reduce((sum: number, comp: any) => sum + (comp.averageRent || 0), 0) / comparables.length)
          : null);

      // Build OPTIMIZED response focused on rental comparables only
      const propertyAnalysis = {
        deal: deal,
        propertyData: {
          property: {
            address: deal.address,
            city: 'Unknown', // deal.city not available in schema
            state: 'Unknown', // deal.state not available in schema  
            zipCode: 'Unknown', // deal.zipCode not available in schema
            lotSize: lotSizeAcres * 43560, // Convert acres to sq ft
            marketValue: parseFloat((deal as any).askingPrice || '0'),
            propertyType: (deal.productTypes as string[])?.[0] || 'Unknown'
          },
          rentEstimate: {
            averageRent: averageRentPerUnit,
            confidence: hellodataRent?.comparables?.length > 0 ? 85 : 50
          },
          rentComparables: comparables
        },
        marketAnalysis: {
          comparables: hellodataRent?.comparables || [],
          metadata: {
            averageRent: averageRentPerUnit,
            searchRadius: 3,
            totalComparables: hellodataRent?.comparables?.length || 0
          },
          note: hellodataRent?.comparables?.length > 0 
            ? `Found ${hellodataRent.comparables.length} HelloData rental comparables (optimized)`
            : "No rental comparables found - optimized for fast loading"
        },
        developmentAnalysis: null, // Remove for performance
        dataQuality: hellodataRent ? 'good' : 'limited',
        dataSource: 'hellodata_comparables_optimized',
        analysisTimestamp: new Date().toISOString(),
        note: `OPTIMIZED HelloData analysis - Rental focus: ${!!hellodataRent}, Comparables=${hellodataRent?.comparables?.length || 0}`
      };

      console.log(`🚀 OPTIMIZED Property Analysis completed in <15s for ${deal.address} - Rental comparables: ${hellodataRent?.comparables?.length || 0}`);
      res.json(propertyAnalysis);
