  app.post("/api/valuation/analyze", async (req, res) => {
    try {
      // For demo purposes, use a default user ID if not authenticated
      let userId = (req.user as any)?.id;
      if (!userId) {
        userId = "demo-user-id"; // Demo user for unauthenticated access
      }

      const { address, sizeAcres, zoning, marketComps, notes } = req.body;

      if (!address || !sizeAcres) {
        return res.status(400).json({ message: "Address and size are required" });
      }

      // Get broker profile or create demo broker
      let broker = await storage.getBrokerByUserId(userId);
      if (!broker) {
        if (userId === "demo-user-id") {
          // Create or get demo broker for unauthenticated access
          const existingDemoBroker = await storage.getBrokerByEmail("demo@landvaluation.com");
          if (existingDemoBroker) {
            broker = existingDemoBroker;
          } else {
            broker = await storage.createBroker({
              firstName: "Demo",
              lastName: "User", 
              email: "demo@landvaluation.com",
              phone: "555-0123",
              marketsCovered: "Demo Market",
              preferredContact: "email"
            } as any);
          }
        } else {
          const user = await storage.getUser(userId);
          if (user) {
            broker = await storage.createBrokerWithUserId({
              userId: user.id,
              firstName: user.firstName || "New",
              lastName: user.lastName || "Broker",
              email: user.email || "",
              phone: "",
              marketsCovered: "Not specified",
              preferredContact: "email",
            } as any);
          } else {
            return res.status(404).json({ message: "User not found" });
          }
        }
      }

      // Calculate valuation (simplified AI algorithm)
      const acres = parseFloat(sizeAcres);
      let basePrice = 75000; // Base price per acre

      // Adjust for zoning
      const zoningMultipliers: Record<string, number> = {
        "R-4": 1.5,   // Multi-family premium
        "R-2": 1.3,   // Duplex premium  
        "R-1": 1.0,   // Single family base
        "C-1": 2.0,   // Commercial premium
        "I-1": 1.8,   // Industrial premium
        "A-1": 0.6,   // Agricultural discount
      };

      if (zoning && zoningMultipliers[zoning]) {
        basePrice *= zoningMultipliers[zoning];
      }

      // Size efficiency (larger lots get slight discount per acre)
      if (acres > 10) basePrice *= 0.95;
      if (acres > 50) basePrice *= 0.9;

      const pricePerAcre = Math.round(basePrice);
      const totalValue = Math.round(pricePerAcre * acres);

      // Create valuation record
      const valuation = await storage.createValuation({
        brokerId: broker.id,
        address,
        sizeAcres,
        zoning: zoning || "",
        marketComps: marketComps || "",
        notes: notes || "",
        pricePerAcre,
        totalValue,
      });

      res.json({
        id: valuation.id,
        address,
        sizeAcres,
        zoning,
        pricePerAcre,
        totalValue,
        marketComps,
        notes,
      });
    } catch (error) {
      console.error("Error analyzing valuation:", error);
      res.status(500).json({ message: "Failed to analyze valuation" });
    }
  });

  app.post("/api/valuation/share", async (req, res) => {
    try {
      // For demo purposes, use a default user ID if not authenticated
      let userId = (req.user as any)?.id;
      if (!userId) {
        userId = "demo-user-id"; // Demo user for unauthenticated access
      }

      const { valuationId, taggedEmails } = req.body;

      if (!valuationId || !taggedEmails || taggedEmails.length === 0) {
        return res.status(400).json({ message: "Valuation ID and emails are required" });
      }

      // Get broker profile
      const broker = await storage.getBrokerByUserId(userId);
      if (!broker) {
        return res.status(404).json({ message: "Broker not found" });
      }

      // Get valuation
      const valuation = await storage.getValuationById(valuationId);
      if (!valuation || valuation.brokerId !== broker.id) {
        return res.status(404).json({ message: "Valuation not found" });
      }

      // Create shares for each email
      const shares = [];
      for (const email of taggedEmails) {
        if (email.trim()) {
          const share = await storage.createValuationShare({
            valuationId: valuation.id,
            sharedByBrokerId: broker.id,
            sharedWithEmail: email.trim(),
          });
          shares.push(share);
        }
      }

      // Mark valuation as shared
      await storage.updateValuation(valuation.id, { isShared: true });

      // Send email notifications to tagged contacts
      for (const email of taggedEmails) {
        if (email.trim()) {
          try {
            // emailService doesn't have sendValuationShareEmail method
            console.log(`Would send valuation share email to ${email.trim()}`);
          } catch (error) {
            console.error(`Failed to send valuation email to ${email}:`, error);
          }
        }
      }

      res.json({
        success: true,
        sharesCreated: shares.length,
        message: `Valuation shared with ${shares.length} contacts`,
      });
    } catch (error) {
      console.error("Error sharing valuation:", error);
      res.status(500).json({ message: "Failed to share valuation" });
    }
  });

