  // POST /api/email-intake/bulk-reparse — re-run AI on ALL pending items
  app.post('/api/email-intake/bulk-reparse', isAuthenticated, async (req, res) => {
    try {
      const { emailIntakeQueue } = await import('../shared/schema.js');
      const { eq } = await import('drizzle-orm');
      const { EmailIntakeService } = await import('./emailIntakeService.js');
      const pending = await db.select().from(emailIntakeQueue).where(eq(emailIntakeQueue.status, 'pending'));
      if (pending.length === 0) return res.json({ success: true, processed: 0 });

      res.json({ success: true, processing: pending.length, message: `Re-parsing ${pending.length} emails in background` });

      // Process in background after responding
      (async () => {
        let success = 0, failed = 0;
        for (const row of pending) {
          try {
            const parseResult = await (EmailIntakeService as any).aiParseEmail(
              row.emailBody || '',
              row.fromEmail || '',
              row.subject || '',
              undefined
            );
            const f = parseResult.fields;
            await db.update(emailIntakeQueue).set({
              parsedDealType: f.dealType,
              parsedPropertyName: f.propertyName ?? null,
              parsedAddress: f.address ?? null,
              parsedCity: f.city ?? null,
              parsedState: f.state ?? null,
              parsedZip: f.zip ?? null,
              parsedAcres: f.acres ?? null,
              parsedPrice: f.price ?? null,
              parsedUnitCount: f.unitCount ?? null,
              parsedVintage: f.vintage ?? null,
              parsedBrokerName: f.brokerName ?? null,
              parsedBrokerEmail: f.brokerEmail ?? null,
              parsedBrokerPhone: f.brokerPhone ?? null,
              parsedNotes: f.notes ?? null,
              parsedZoning: f.zoning ?? null,
              fieldConfidences: parseResult.confidences,
              overallConfidence: parseResult.overallConfidence,
            }).where(eq(emailIntakeQueue.id, row.id));
            success++;
          } catch (e) {
            console.error(`[bulk-reparse] Failed for ${row.id}:`, e);
            failed++;
          }
        }
        console.log(`✅ [BULK-REPARSE] Done: ${success} success, ${failed} failed`);
      })();
    } catch (err: any) {
      return res.status(500).json({ message: err.message });
    }
  });

