  // Email Webhook Handler for SendGrid Inbound Parse (with SECURE signature verification and rate limiting)
  app.post('/api/webhooks/email-inbound', express.raw({type: '*/*', limit: '10mb'}), webhookRateLimit, async (req, res) => {
    // EMAIL SCRAPING DISABLED — return 200 so SendGrid does not retry
    console.log('📧 [DISABLED] /api/webhooks/email-inbound received but email-to-deal scraping is turned off.');
    return res.status(200).json({ message: 'Email received. Automatic deal creation is currently disabled.' });
    try {
      console.log('\n' + '='.repeat(100));
      console.log('📧 INBOUND EMAIL WEBHOOK RECEIVED');
      console.log('='.repeat(100));
      console.log('⏰ Timestamp:', new Date().toISOString());
      console.log('📍 Source IP:', req.ip || req.connection?.remoteAddress || req.headers['x-forwarded-for'] || 'unknown');
      console.log('🌐 User Agent:', req.get('user-agent') || 'unknown');
      console.log('📦 Content-Type:', req.get('content-type') || 'unknown');
      console.log('🔐 Signature Header:', req.get('x-twilio-email-event-webhook-signature') ? 'PRESENT' : 'MISSING');
      console.log('📨 Raw Body Length:', Buffer.isBuffer(req.body) ? req.body.length : 'NOT BUFFER');
      console.log('=' + '='.repeat(100) + '\n');
      
      // ⚠️ ENHANCED DEBUGGING: Track source of automated duplicate submissions
      console.log('🔍 [DUPLICATE-DEBUG] Webhook source details:', {
        sourceIP: req.ip || req.connection?.remoteAddress || req.headers['x-forwarded-for'] || 'unknown',
        userAgent: req.get('user-agent') || 'unknown', 
        contentType: req.get('content-type') || 'unknown',
        sendgridEventType: req.get('x-twilio-email-event-webhook-signature') ? 'SendGrid-signed' : 'unsigned',
        timestamp: new Date().toISOString(),
        headers: JSON.stringify({
          'x-forwarded-for': req.get('x-forwarded-for'),
          'x-real-ip': req.get('x-real-ip'),
          'user-agent': req.get('user-agent'),
          'referer': req.get('referer')
        })
      });
      
      // PROCESSING ORDER:
      // 1. Verify signature FIRST
      // 2. Check deduplication
      // 3. Parse message and extract data  
      // 4. Create/find broker
      // 5. Store communication record
      // 6. Mark as processed LAST
      
      const contentType = req.get('content-type') || '';
      
      console.log('📧 Content-Type:', contentType);
      console.log('📧 Body type:', typeof req.body);
      console.log('📧 Body is Buffer:', Buffer.isBuffer(req.body));
      
      // CRITICAL FIX: Pass raw Buffer directly to EmailInboundService.parseInboundEmail
      // This allows mailparser to extract PDF attachments properly
      let emailData: any;
      try {
        console.log('📧 Parsing email with EmailInboundService.parseInboundEmail...');
        emailData = await EmailInboundService.parseInboundEmail(req.body);
        console.log('📧 Email parsed successfully');
        console.log('📧 Attachments found:', emailData.attachments?.length || 0);
        if (emailData.attachments?.length > 0) {
          console.log('📧 First attachment:', {
            filename: emailData.attachments[0].filename,
            contentType: emailData.attachments[0].contentType,
            size: emailData.attachments[0].content?.length || 0
          });
        }
      } catch (parseError) {
        console.error('❌ Failed to parse email with EmailInboundService:', parseError);
        return res.status(400).json({ error: 'Failed to parse email' });
      }
      
      if (!emailData.text && !emailData.html) {
        return res.status(400).json({ error: 'No email content found' });
      }
      
      // Get deterministic provider message ID (BEFORE deduplication check)
      // Use content-based hash if provider ID is not available (prevents random IDs on webhook retries)
      const messageId = getProviderMessageId(emailData, 'email') || generateDeterministicEmailId(emailData);
      
      // 1. SIGNATURE VERIFICATION - TEMPORARILY DISABLED TO ALLOW EMAIL PROCESSING
      // Note: Webhook verification temporarily bypassed due to missing SENDGRID_WEBHOOK_PUBLIC_KEY
      const hasSignatureVerification = !!process.env.SENDGRID_WEBHOOK_PUBLIC_KEY;
      console.log('⚠️ WEBHOOK VERIFICATION TEMPORARILY DISABLED - EMAILS WILL PROCESS WITHOUT SIGNATURE CHECK');
      if (hasSignatureVerification) {
        console.log('📧 Attempting webhook signature verification...');
        try {
          const eventWebhook = new EventWebhook();
          const publicKey = process.env.SENDGRID_WEBHOOK_PUBLIC_KEY;
          const signature = req.headers['x-twilio-email-event-webhook-signature'] as string;
          const timestamp = req.headers['x-twilio-email-event-webhook-timestamp'] as string;
          const rawBody = req.body;
        
          if (!eventWebhook.verifySignature(rawBody, signature, timestamp, publicKey || '')) {
            console.log('❌ Webhook signature verification failed');
            return res.status(401).send('Invalid signature');
          }
          console.log('✅ Webhook signature verified successfully');
        } catch (verificationError) {
          console.log('⚠️ Webhook signature verification error:', verificationError);
          // For Inbound Parse, continue processing even if verification fails
          console.log('📧 Continuing with email processing (Inbound Parse doesn\'t require signature verification)');
        }
      } else {
        console.log('📧 No signature verification configured - processing email directly (normal for Inbound Parse)');
      }
      
      // 2. CHECK DEDUPLICATION AFTER signature verification
      if (isMessageAlreadyProcessed(messageId)) {
        console.log(`📧 Duplicate message detected: ${messageId}`);
        return res.json({ 
          success: true, 
          message: 'Message already processed',
          duplicate: true 
        });
      }

      // Extract sender email address
      const emailMatch = emailData.from.match(/<([^>]+)>|([^<\s]+@[^>\s]+)/);
      const senderEmail = emailMatch ? (emailMatch[1] || emailMatch[2]) : emailData.from;
      
      console.log(`📧 Processing email from: ${senderEmail}`);

      // Find or create broker
      let broker = await storage.getBrokerByEmail(senderEmail);
      
      if (!broker) {
        // Auto-register new broker from email
        const nameParts = emailData.from.split(' ');
        const firstName = nameParts[0] || senderEmail.split('@')[0];
        const lastName = nameParts.slice(1).join(' ') || 'User';
        
        const brokerData = {
          firstName,
          lastName,
          email: senderEmail,
          phone: "Unknown",
          marketsCovered: ["Unknown"],
          preferredContact: "email",
        };
        
        try {
          console.log('📧 Attempting to create broker with data:', JSON.stringify(brokerData, null, 2));
          broker = await storage.createBroker(brokerData as any);
          console.log(`📧 Created new broker: ${broker.id} (${senderEmail})`);
        } catch (error) {
          console.error('❌ Failed to create broker:', error);
          console.error('❌ Broker data that failed:', JSON.stringify(brokerData, null, 2));
          return res.status(400).json({ error: "Could not create broker profile" });
        }
      }

      // STEP 3: CHECK IF THIS IS A RESPONSE TO EXISTING THREAD
      const emailContent = emailData.text || emailData.html;
      console.log(`📧 Analyzing message for response patterns...`);
      
      const responseAnalysis = await ResolutionService.analyzeInboundMessage(
        emailContent,
        senderEmail,
        undefined,
        'email'
      );
      
      if (responseAnalysis.isResponse && responseAnalysis.threadKey) {
        console.log(`🔄 Message identified as response to thread: ${responseAnalysis.threadKey}`);
        
        // Process as response to existing thread
        const resolutionResult = await ResolutionService.processResponse(responseAnalysis, {
          brokerId: broker.id,
          content: emailContent,
          channel: 'email',
          providerMessageId: messageId
        });
        
        // Mark message as processed
        markMessageAsProcessed(messageId);
        
        if (resolutionResult.resolved) {
          console.log(`✅ Thread resolved successfully. Fields updated: ${resolutionResult.fieldsResolved.join(', ')}`);
          return res.json({
            success: true,
            message: 'Response processed and thread resolved',
            resolved: true,
            fieldsResolved: resolutionResult.fieldsResolved,
            dealUpdated: resolutionResult.dealUpdated,
            dealId: resolutionResult.updatedDeal?.id
          });
        } else {
          console.log(`⚠️ Response processing failed: ${resolutionResult.errors?.join(', ')}`);
          return res.status(400).json({
            error: 'Failed to process response',
            details: resolutionResult.errors
          });
        }
      }
      
      // CONTINUE AS NEW SUBMISSION if not a response
      console.log(`📧 Processing as new deal submission...`);
      
      // Parse deal information from email content
      const parsedDeal = await parseDealFromText(emailContent, "email");
      
      // Determine missing fields
      const missingFields: string[] = [];
      if (!parsedDeal.address) missingFields.push('address');
      if (!parsedDeal.userSizeAcres) missingFields.push('acreage');
      if (!parsedDeal.userAskingPrice) missingFields.push('price');
      
      // 5. STORE COMMUNICATION RECORD - VISIBLE IMPLEMENTATION AS REQUESTED
      const communication = await storage.createCommunication({
        brokerId: broker.id,
        email: senderEmail,
        phone: null,
        channel: 'email',
        direction: 'inbound',
        rawText: emailContent,
        parsedJson: JSON.stringify(parsedDeal),
        missingFields: parsedDeal.missingFields || missingFields,
        relatedDealId: null, // Will be updated if deal is created
        status: missingFields.length > 0 ? 'pending_followup' : 'resolved',
        providerMessageId: messageId,
        threadKey: `email_${senderEmail}_${emailData.subject?.replace(/\s+/g, '_')}`,
        subject: emailData.subject
      } as any);

      console.log(`📧 Created communication record: ${communication.id}`);
      
      // 6. MARK AS PROCESSED LAST - only AFTER successful persistence
      markMessageAsProcessed(messageId);

      // CRITICAL FIX: Respond to SendGrid FIRST (within 1 second) to prevent retries
      // Then queue the job asynchronously without blocking the response
      res.status(200).json({
        success: true,
        message: 'Email received and queued for processing',
        communicationId: communication.id
      });
      
      // INSTANT SMS CONFIRMATION - Send BEFORE background processing for immediate broker feedback
      if (broker.phone && broker.phone !== 'Unknown' && parsedDeal.address) {
        setImmediate(async () => {
          try {
            const { sendSMS: sendSMSFromService } = await import('./smsService');
            const quickConfirmation = `✅ Deal received! ${parsedDeal.address}. Processing now - you'll get full details in ~10 seconds. -LandLinq`;
            await sendSMSFromService({
              to: broker.phone!,
              message: quickConfirmation
            });
            console.log(`📱 INSTANT SMS confirmation sent to ${broker.phone}`);
          } catch (smsError) {
            console.error('⚠️ Failed to send instant SMS:', smsError);
            // Don't block processing if SMS fails
          }
        });
      }
      
      // ASYNC PROCESSING: Queue job AFTER responding (fire-and-forget)
      // This prevents SendGrid timeouts (34+ second processing triggers webhook retries)
      setImmediate(async () => {
        try {
          // Process deal if we have ADDRESS (price/acreage are OPTIONAL for HelloData)
          if (parsedDeal.address) {
            console.log('⚡ Queueing email for async processing...');
            
            // CRITICAL: Attach providerMessageId to emailData so emailInboundService can find the communication
            const emailDataWithMessageId = {
              ...emailData,
              providerMessageId: messageId  // This matches the communication's providerMessageId
            };
            
            const job = await storage.createBackgroundJob({
              jobType: 'process_email',
              payload: {
                emailData: emailDataWithMessageId,  // Pass with providerMessageId attached
                parsedDeal,
                dealData: parsedDeal,  // Also as dealData for compatibility
                broker,
                senderEmail,
                contactEmail: senderEmail,
                communicationId: communication.id,
                providerMessageId: messageId  // Also at top level for easy access
              },
              status: 'pending',
              scheduledFor: new Date(), // Process immediately
              maxAttempts: 3,
              attempts: 0
            });
            
            console.log(`✅ Email queued for processing (job ID: ${job.id})`);
          } else {
            // NO ADDRESS - record communication for manual follow-up
            console.log(`📧 Email missing ADDRESS - cannot process without it`);
          }
        } catch (jobError) {
          console.error('❌ Failed to queue email job:', jobError);
          // Don't throw - we already responded 200 to SendGrid
        }
      });

    } catch (error) {
      console.error('❌ Error processing inbound email:', error);
      res.status(500).json({ error: 'Internal server error processing email' });
    }
  });

  // SENDGRID EVENT WEBHOOK - Track opens, clicks, bounces for engagement analytics
  // Configure in SendGrid: Settings > Mail Settings > Event Webhook
  // URL: https://landlinq.replit.app/webhooks/sendgrid-events
  app.post('/webhooks/sendgrid-events', express.json(), async (req, res) => {
    try {
      const events = Array.isArray(req.body) ? req.body : [req.body];
      console.log(`📊 [SENDGRID-EVENTS] Received ${events.length} event(s)`);
      
      // Process each event
      for (const event of events) {
        const eventType = event.event;
        const email = event.email;
        const sgMessageId = event.sg_message_id;
        
        console.log(`📊 [SENDGRID-EVENTS] Event: ${eventType} for ${email}`);
        
        // Track engagement in our safeguard service
        if (['delivered', 'open', 'click', 'bounce', 'spamreport'].includes(eventType)) {
          try {
            // Find the sender from the message if available
            const senderId = event.senderId || null;
            
            // Map SendGrid events to our event types
            const mappedEvent = eventType === 'open' ? 'opened' 
                             : eventType === 'click' ? 'clicked'
                             : eventType === 'bounce' ? 'bounced'
                             : eventType === 'spamreport' ? 'complained'
                             : 'delivered';
            
            // Record in our stats (if we have sender info)
            if (senderId) {
              const { outreachSafeguardService } = await import('./outreachSafeguardService');
              await outreachSafeguardService.recordSendOutcome(
                senderId, 
                eventType !== 'bounce' && eventType !== 'spamreport',
                mappedEvent as any,
                'email'
              );
            }
            
            // Update broker engagement stats in our database
            if ((eventType === 'open' || eventType === 'click') && email) {
              try {
                await db.execute(sql`
                  UPDATE brokers 
                  SET 
                    last_email_opened_at = CASE WHEN ${eventType} = 'open' THEN now() ELSE last_email_opened_at END,
                    email_opens_count = CASE WHEN ${eventType} = 'open' THEN COALESCE(email_opens_count, 0) + 1 ELSE email_opens_count END,
                    last_email_clicked_at = CASE WHEN ${eventType} = 'click' THEN now() ELSE last_email_clicked_at END,
                    email_clicks_count = CASE WHEN ${eventType} = 'click' THEN COALESCE(email_clicks_count, 0) + 1 ELSE email_clicks_count END,
                    updated_at = now()
                  WHERE email = ${email}
                `);
              } catch (dbErr) {
                // Columns might not exist yet - that's ok
                console.log(`📊 [SENDGRID-EVENTS] Could not update broker stats (columns may not exist)`);
              }
            }
            
          } catch (processErr) {
            console.error(`❌ [SENDGRID-EVENTS] Error processing ${eventType} event:`, processErr);
          }
        }
      }
      
      // Always return 200 to acknowledge receipt (SendGrid will retry on non-2xx)
      res.status(200).json({ received: events.length });
    } catch (error) {
      console.error('❌ [SENDGRID-EVENTS] Webhook error:', error);
      res.status(200).json({ error: 'Processing error', received: 0 });
    }
  });

  // SENDGRID INBOUND PARSE WEBHOOK - Proper multipart handling for catalyst@landlinq.ai
  // Configure proper multer middleware for SendGrid's multipart/form-data format
  const sendgridWebhookUpload = multer({ 
    storage: multer.memoryStorage(),
    limits: { fileSize: 50 * 1024 * 1024 } // 50MB for attachments
  });
  
  app.post('/webhooks/landlinq-inbound', sendgridWebhookUpload.any(), webhookRateLimit, async (req, res) => {
    try {
      console.log('📧 Received SendGrid inbound email webhook');
      console.log('📧 Content-Type:', req.get('Content-Type') || 'Unknown');
      console.log('📧 Body fields:', Object.keys(req.body));
      console.log('📧 Files received:', req.files?.length || 0);
      
      // HELPER: Extract body from raw MIME email when text/html fields are empty
      // This handles cases where SendGrid puts raw MIME in the 'email' field
      const extractBodyFromRawMime = (rawMime: string): string => {
        if (!rawMime) return '';
        
        // Find the double newline that separates headers from body
        const headerBodySplit = rawMime.search(/\r?\n\r?\n/);
        if (headerBodySplit === -1) return '';
        
        let body = rawMime.substring(headerBodySplit).trim();
        
        // Remove remaining MIME boundary markers and headers
        body = body
          .replace(/--[a-zA-Z0-9_=+\/-]+--?/g, '') // Remove boundary markers
          .replace(/^Content-Type:.*$/gim, '')
          .replace(/^Content-Transfer-Encoding:.*$/gim, '')
          .replace(/^Content-Disposition:.*$/gim, '')
          .replace(/^MIME-Version:.*$/gim, '')
          .replace(/^X-[A-Za-z-]+:.*$/gim, '')
          .replace(/^\s*[\n\r]+/gm, '\n')
          .trim();
        
        console.log(`📧 [MIME-PARSE] Extracted body from raw MIME: ${body.length} chars`);
        return body;
      };
      
      // SendGrid Inbound Parse sends data as multipart/form-data
      // Fields: from, to, subject, text, html, attachments as files
      // CRITICAL: Sometimes SendGrid puts raw MIME in 'email' field with empty text/html
      const headers = req.body.headers ? JSON.parse(req.body.headers) : {};
      
      // Try to get text content, falling back to parsing raw MIME if needed
      let textContent = req.body.text || '';
      let htmlContent = req.body.html || '';
      
      // If text and html are empty, try to extract from raw MIME in 'email' field
      if (!textContent && !htmlContent && req.body.email) {
        console.log('📧 [MIME-PARSE] text/html empty, extracting from raw MIME email field');
        textContent = extractBodyFromRawMime(req.body.email);
      }
      
      const emailData = {
        from: req.body.from || '',
        to: req.body.to || 'catalyst@landlinq.ai',
        subject: req.body.subject || 'No Subject',
        text: textContent,
        html: htmlContent,
        rawMime: req.body.email || '', // Store raw MIME for backup
        attachments: (Array.isArray(req.files) ? req.files : []).map((file: any) => ({
          filename: file.originalname || file.fieldname,
          content: file.buffer,
          contentType: file.mimetype,
          size: file.size
        })),
        headers,
        // CRITICAL FIX: Extract Message-ID for communication deduplication
        providerMessageId: getProviderMessageId({ headers, ...req.body }, 'email') || undefined
      };
      
      console.log(`📧 Extracted Message-ID for deduplication: ${emailData.providerMessageId || 'NOT FOUND'}`);

      console.log(`📧 Processing SendGrid email from ${emailData.from} to ${emailData.to} - Subject: ${emailData.subject}`);
      
      // SMART ROUTING: Accept emails to landlinq.ai domains
      const recipientEmail = emailData.to.toLowerCase();
      const isLandLinqEmail = recipientEmail.includes('@landlinq.ai') || recipientEmail.includes('@catalyst.landlinq.ai');
      
      if (!isLandLinqEmail) {
        console.log(`⏭️ Skipping email - not addressed to landlinq.ai domain (received: ${emailData.to})`);
        return res.status(200).json({ 
          success: true, 
          message: 'Email received but not processed (not for landlinq.ai domain)' 
        });
      }
      
      console.log(`✅ Email addressed to landlinq.ai domain (${emailData.to}) - processing with instant confirmation`);
      
      // CRITICAL FIX: Create background job BEFORE responding to SendGrid
      // This ensures the email is persisted to the database even if the workflow restarts
      let jobId: string | undefined;
      let communicationId: string | undefined;
      
      // STEP 1: Find or create broker - uses SMART MERGE to prevent duplicates
      let broker;
      try {
        const emailPrefix = emailData.from.split('@')[0].replace(/[^a-zA-Z0-9]/g, '') || 'Email';
        const { broker: foundBroker, isNew, wasUpdated } = await storage.findOrCreateBroker({
          email: emailData.from,
          firstName: emailPrefix,
          lastName: 'Submission'
        });
        broker = foundBroker;
        
        if (isNew) {
          console.log(`📧 [WEBHOOK] Created new broker: ${broker.id} for email: ${emailData.from}`);
        } else if (wasUpdated) {
          console.log(`🔗 [WEBHOOK] Updated existing broker: ${broker.id} with email: ${emailData.from}`);
        } else {
          console.log(`📧 [WEBHOOK] Found existing broker: ${broker.id} for email: ${emailData.from}`);
        }
      } catch (brokerError) {
        console.error(`❌ [WEBHOOK] Failed to find/create broker:`, brokerError);
      }
      
      // STEP 2: Create communication record FIRST with explicit error handling
      // CRITICAL FIX (Nov 29, 2025): ALWAYS create communication even if broker creation failed
      // This ensures we never lose the original email content
      const commProviderMsgId = emailData.providerMessageId || `email_${Date.now()}_${Math.random().toString(36).substr(2, 6)}`;
      console.log(`📧 [WEBHOOK] Creating communication with providerMessageId: ${commProviderMsgId}`);
      
      // Capture the FULL original email content
      const originalEmailContent = emailData.text || emailData.html || '';
      console.log(`📧 [WEBHOOK] Original email content length: ${originalEmailContent.length} chars`);
      
      try {
        const communication = await storage.createCommunication({
          brokerId: broker?.id || null, // Use broker ID if available, null otherwise
          email: emailData.from,
          phone: null,
          channel: 'email',
          direction: 'inbound',
          rawText: originalEmailContent || 'No content',
          subject: emailData.subject,
          relatedDealId: null, // Will be linked when deal is created
          status: 'pending_followup',
          providerMessageId: commProviderMsgId
        });
        
        communicationId = communication.id;
        console.log(`✅ [WEBHOOK] Communication CREATED successfully: ${communicationId}`);
        console.log(`📧 [WEBHOOK] Communication details: brokerId=${broker?.id || 'NULL'}, providerMsgId=${commProviderMsgId}, rawTextLength=${originalEmailContent.length}`);
      } catch (commError) {
        console.error(`❌ [WEBHOOK] FAILED to create communication:`, commError);
        console.error(`❌ [WEBHOOK] Communication error details:`, JSON.stringify(commError, Object.getOwnPropertyNames(commError)));
        // Don't throw - continue with background job creation
      }
      
      // STEP 3: Create background job
      // CRITICAL: Include original email content in payload as backup
      // This ensures we can recover if communication creation failed
      try {
        // CRITICAL FIX (Dec 2, 2025): Use the SAME providerMessageId as the communication
        // Previous bug: Generated a different providerMsgId here, causing linking to fail
        const job = await storage.createBackgroundJob({
          jobType: 'process_email',
          payload: {
            emailData: {
              ...emailData,
              providerMessageId: commProviderMsgId // Use SAME ID as communication
            },
            dealData: {
              contactEmail: emailData.from,
              address: null,
              city: null,
              state: null,
              zip: null,
              acres: null,
              price: null
            },
            contactEmail: emailData.from,
            communicationId,
            providerMessageId: commProviderMsgId, // Use SAME ID as communication
            // BACKUP: Store original email content in case communication wasn't created
            originalEmailContent,
            originalSubject: emailData.subject
          },
          status: 'pending',
          scheduledFor: new Date(),
          maxAttempts: 3,
          attempts: 0
        });
        jobId = job.id;
        console.log(`✅ [WEBHOOK] Background job created: ${jobId} with communicationId=${communicationId}, emailContentLength=${originalEmailContent.length}`);
      } catch (jobError) {
        console.error('❌ [WEBHOOK] Failed to create background job:', jobError);
      }
      
      // Respond to SendGrid AFTER job is persisted
      res.status(200).json({
        success: true,
        message: 'Email received and queued for processing',
        jobId
      });
      
      // INSTANT CONFIRMATION: Send confirmation email asynchronously (optional enhancement)
      // This runs after response is sent, but job is already persisted in database
      setImmediate(async () => {
        try {
          console.log('⚡ Starting instant confirmation email...');
          
          // Quick address parse for confirmation message
          const { parseOrFallback } = await import('./smsAddressParser');
          const quickParse = await parseOrFallback(emailData.text || '');
          
          if (quickParse && quickParse.street) {
            console.log(`✅ Quick parse found address: ${quickParse.street}, ${quickParse.city}, ${quickParse.state}`);
            
            // Send instant confirmation email
            const { sendNotificationEmail } = await import('./emailService');
            await sendNotificationEmail({
              to: emailData.from,
              subject: '✅ Deal Received - Processing Now',
              html: `
                <div style="font-family: Arial, sans-serif; max-width: 600px; margin: 0 auto;">
                  <h2 style="color: #2563eb;">Deal Received!</h2>
                  <p>Thanks for submitting the property at:</p>
                  <p style="font-size: 18px; font-weight: bold; color: #1e40af;">
                    ${quickParse.street}<br>
                    ${quickParse.city}, ${quickParse.state} ${quickParse.zip || ''}
                  </p>
                  <p>We're analyzing this deal now. You'll receive the full classification results shortly.</p>
                  <p style="color: #64748b; font-size: 14px; margin-top: 30px;">
                    - Catalyst Acquisitions Team
                  </p>
                </div>
              `,
              text: `Deal Received! Processing ${quickParse.street}, ${quickParse.city}, ${quickParse.state}. Full results coming shortly.`,
              type: 'deal_received',
              priority: 'high'
            } as any);
            
            console.log('✅ Instant confirmation email sent!');
            
            // Update the job payload with parsed address data
            // CRITICAL FIX (Dec 2, 2025): Preserve ALL existing payload fields when updating
            // Previous bug: Replacing entire payload lost providerMessageId and originalEmailContent
            if (jobId) {
              try {
                await db.update(backgroundJobs)
                  .set({
                    payload: {
                      emailData: {
                        ...emailData,
                        providerMessageId: commProviderMsgId // Preserve providerMessageId
                      },
                      dealData: {
                        contactEmail: emailData.from,
                        address: quickParse.street,
                        city: quickParse.city,
                        state: quickParse.state,
                        zip: quickParse.zip,
                        acres: null,
                        price: null
                      },
                      contactEmail: emailData.from,
                      communicationId,
                      providerMessageId: commProviderMsgId, // Preserve for linking
                      originalEmailContent, // Preserve backup content
                      originalSubject: emailData.subject // Preserve subject
                    }
                  })
                  .where(eq(backgroundJobs.id, jobId));
                console.log(`📧 Updated job ${jobId} with parsed address data (preserved providerMessageId: ${commProviderMsgId})`);
              } catch (updateError) {
                console.error('⚠️ Failed to update job with parsed data:', updateError);
                // Job will still process with full AI parsing
              }
            }
          } else {
            console.log('⚠️ Quick parse did not find address - confirmation email skipped, full AI parsing will run');
          }
        } catch (error) {
          console.error('⚠️ Instant confirmation failed (non-critical):', error);
          // Job is already persisted - background processor will handle full processing
        }
      });
      
    } catch (error) {
      console.error('❌ SendGrid webhook processing error:', error);
      res.status(500).json({ error: 'Failed to process SendGrid webhook' });
    }
  });

