  // SMS Webhook Handler for Twilio (with SECURE signature verification and rate limiting)
  // UPDATED: Use new SMSInboundService with property detection and conversation routing
  app.post('/api/webhooks/sms-inbound', express.urlencoded({extended: true}), webhookRateLimit, async (req, res) => {
    // CRITICAL SECURITY: Verify Twilio signature BEFORE processing
    if (process.env.TWILIO_AUTH_TOKEN) {
      const authToken = process.env.TWILIO_AUTH_TOKEN;
      const twilioSignature = req.headers['x-twilio-signature'] as string;
      const fullUrl = `${req.protocol}://${req.get('host')}${req.originalUrl}`;
      const isValid = twilio.validateRequest(authToken, twilioSignature, fullUrl, req.body);
      
      if (!isValid) {
        console.error('❌ Invalid Twilio signature - rejecting request');
        return res.status(401).send('<?xml version="1.0" encoding="UTF-8"?><Response></Response>');
      }
      
      console.log('✅ Twilio signature verified successfully');
    }
    
    // Delegate to SMSInboundService for property detection and conversation routing
    const { SMSInboundService } = await import('./smsInboundService');
    return SMSInboundService.handleInboundSMS(req, res);
  });

