  // Admin endpoint to cleanup orphaned dedup entries (hashes that reference non-existent deals)
  // CRITICAL FIX (Dec 9, 2025): This clears phantom hashes that block email reprocessing
  app.post("/api/admin/cleanup-orphan-dedup", isAuthenticated, async (req, res) => {
    try {
      const user = req.user as any;
      const userEmail = user?.email || '';
      
      // Only allow @apexresi.com emails to run cleanup
      if (!userEmail.endsWith('@apexresi.com')) {
        return res.status(403).json({ message: "Admin access required" });
      }
      
      // Find and delete dedup entries where deal_id references a non-existent deal
      const result = await db.execute(sql`
        WITH orphans AS (
          SELECT pe.email_hash, pe.deal_id, pe."from", pe.subject, pe.processed_at
          FROM processed_emails pe
          LEFT JOIN deals d ON pe.deal_id::uuid = d.id
          WHERE pe.deal_id IS NOT NULL 
            AND pe.deal_id != '' 
            AND d.id IS NULL
        )
        DELETE FROM processed_emails 
        WHERE email_hash IN (SELECT email_hash FROM orphans)
        RETURNING *
      `);
      
      const deletedCount = result.rowCount || 0;
      console.log(`🧹 [CLEANUP] Removed ${deletedCount} orphaned dedup entries by ${userEmail}`);
      
      res.json({
        success: true,
        message: `Cleaned up ${deletedCount} orphaned dedup entries - blocked emails can now be reprocessed`,
        deletedCount
      });
      
    } catch (error) {
      console.error("Error cleaning up orphan dedup entries:", error);
      res.status(500).json({ message: "Failed to cleanup orphan dedup entries", error: String(error) });
    }
  });

