  // Admin endpoint to rebuild acceptance reasoning with concise AI reasoning
  // Feb 9, 2026: Builds concise acceptance reasoning from deal data (subject + comparable summary)
  app.post("/api/admin/update-acceptance-reasoning", isAuthenticated, async (req, res) => {
    try {
      const user = req.user as any;
      const userEmail = user?.email || '';
      
      if (!userEmail.endsWith('@apexresi.com')) {
        return res.status(403).json({ message: "Admin access required" });
      }
      
      console.log('📝 Rebuilding concise acceptance reasoning for all yellow/green deals...');
      
      const allDeals = await storage.getAllDeals();
      const targetDeals = allDeals.filter((d: any) => d.classification === 'yellow' || d.classification === 'green');
      
      let updatedCount = 0;
      for (const deal of targetDeals) {
        const criteriaParts: string[] = [];
        if (deal.vintage) criteriaParts.push(`${deal.vintage} vintage`);
        if (deal.unitCount) criteriaParts.push(`${deal.unitCount} units`);
        if (deal.msaName) criteriaParts.push(`MSA: ${deal.msaName}`);
        const productTypes = (deal.productTypes as string[]) || [];
        criteriaParts.push(`Product: ${productTypes[0] || 'Conventional Apartments'}`);
        
        const subjectSummary = `SUBJECT PROPERTY: ${criteriaParts.join(' | ')}. `;
        
        let comparableSummary = '';
        const compCount = deal.comparableCount || 0;
        if (compCount > 0) {
          const rentParts: string[] = [];
          if (deal.topRentPsf) rentParts.push(`${Number(deal.topRentPsf).toFixed(2)}/sqft top rent`);
          if (deal.avgRentPsf) rentParts.push(`${Number(deal.avgRentPsf).toFixed(2)}/sqft avg`);
          if (deal.topRentPerUnit) rentParts.push(`${Math.round(Number(deal.topRentPerUnit))}/unit top`);
          if (deal.avgRentPerUnit) rentParts.push(`${Math.round(Number(deal.avgRentPerUnit))}/unit avg`);
          const rentDisplay = rentParts.length > 0 ? ` (${rentParts.join(', ')})` : '';
          comparableSummary = `${deal.classification === 'green' ? 'GREEN' : 'YELLOW'}: ${compCount} qualifying comparable${compCount > 1 ? 's' : ''} found${rentDisplay}. Needs senior analyst review.`;
        } else {
          comparableSummary = `${deal.classification === 'green' ? 'GREEN' : 'YELLOW'}: Classified for review.`;
        }
        
        const conciseReasoning = subjectSummary + comparableSummary;
        
        await storage.updateDeal(deal.id, {
          aiExplanatoryNotes: conciseReasoning
        });
        updatedCount++;
      }
      
      console.log(`✅ Updated ${updatedCount} deals with concise acceptance reasoning`);
      
      res.json({
        success: true,
        message: `Updated ${updatedCount} deals with concise acceptance reasoning`,
        updatedCount
      });
      
    } catch (error) {
      console.error("Error updating acceptance reasoning:", error);
      res.status(500).json({ message: "Failed to update acceptance reasoning", error: String(error) });
    }
  });

  // Admin endpoint to REVERT classification changes - restores yellow/green deals
