  app.post("/api/admin/revert-classification", isAuthenticated, async (req, res) => {
    try {
      const user = req.user as any;
      const userEmail = user?.email || '';
      
      if (!userEmail.endsWith('@apexresi.com')) {
        return res.status(403).json({ message: "Admin access required" });
      }
      
      console.log('🔄 Reverting classification changes...');
      
      // Step 1: Restore deals that have "Classification: REVIEWING (YELLOW)" in their notes back to yellow
      const yellowResult = await db.execute(sql`
        UPDATE deals
        SET classification = 'yellow'
        WHERE classification = 'red'
          AND comparable_notes LIKE '%Classification: REVIEWING (YELLOW)%'
      `);
      
      // Step 2: Restore deals that have "Classification: HIGH PRIORITY (GREEN)" in their notes back to green
      const greenResult = await db.execute(sql`
        UPDATE deals
        SET classification = 'green'
        WHERE classification = 'red'
          AND comparable_notes LIKE '%Classification: HIGH PRIORITY (GREEN)%'
      `);
      
      // Step 3: Strip the "SUBJECT PROPERTY: ..." prefix from all comparable_notes
      const stripResult = await db.execute(sql`
        UPDATE deals
        SET comparable_notes = REGEXP_REPLACE(
          comparable_notes,
          '^SUBJECT PROPERTY: [^.]*\. ',
          ''
        )
        WHERE comparable_notes LIKE 'SUBJECT PROPERTY:%'
      `);
      
      console.log(`✅ Restored ${yellowResult.rowCount} deals to yellow, ${greenResult.rowCount} deals to green, stripped prefix from ${stripResult.rowCount} deals`);
      
      res.json({
        success: true,
        message: `Restored ${yellowResult.rowCount} to yellow, ${greenResult.rowCount} to green, cleaned ${stripResult.rowCount} notes`,
        yellowRestored: yellowResult.rowCount,
        greenRestored: greenResult.rowCount,
        notesCleaned: stripResult.rowCount
      });
      
    } catch (error) {
      console.error("Error reverting classification:", error);
      res.status(500).json({ message: "Failed to revert", error: String(error) });
    }
  });

