  // Get all flagged deals for analyst dashboard
  app.get("/api/deals/flagged", isAuthenticated, async (req, res) => {
    try {
      const user = req.user as any;
      const isAnalyst = (user?.claims?.email || user?.email || '').endsWith('@apexresi.com');
      
      if (!isAnalyst) {
        return res.status(403).json({ message: "Access denied. Analyst privileges required." });
      }

      const { 
        page = 1, 
        limit = 25, 
        riskLevel, 
        analystReviewStatus,
        sortBy = 'flaggedAt',
        sortOrder = 'desc' 
      } = req.query;

      const offset = (Number(page) - 1) * Number(limit);

      // Build query conditions
      const conditions = [eq(deals.flagged, true)];
      
      if (riskLevel && riskLevel !== 'all') {
        conditions.push(eq(deals.riskLevel, riskLevel as any));
      }
      
      if (analystReviewStatus && analystReviewStatus !== 'all') {
        conditions.push(eq(deals.analystReviewStatus, analystReviewStatus as string));
      }

      // Query flagged deals with broker information
      const flaggedDeals = await db
        .select({
          id: deals.id,
          dealNumber: deals.dealNumber,
          address: deals.address,
          classification: deals.classification,
          status: deals.status,
          flagged: deals.flagged,
          riskLevel: deals.riskLevel,
          confidenceScore: deals.confidenceScore,
          dataQualityIssues: deals.dataQualityIssues,
          specificWarnings: deals.specificWarnings,
          sourceConflicts: deals.sourceConflicts,
          flaggedAt: deals.flaggedAt,
          flaggedBy: deals.flaggedBy,
          flaggingReason: deals.flaggingReason,
          estimatedReviewTime: deals.estimatedReviewTime,
          analystReviewStatus: deals.analystReviewStatus,
          reviewStartedAt: deals.reviewStartedAt,
          reviewCompletedAt: deals.reviewCompletedAt,
          reviewNotes: deals.reviewNotes,
          lastValidationAt: deals.lastValidationAt,
          brokerId: deals.brokerId,
          assignedAnalyst: deals.assignedAnalyst,
          createdAt: deals.createdAt,
          updatedAt: deals.updatedAt
        })
        .from(deals)
        .where(and(...conditions))
        .orderBy(sortOrder === 'desc' ? desc(deals.createdAt) : deals.createdAt)
        .limit(Number(limit))
        .offset(offset);

      // Get total count for pagination
      const totalResult = await db
        .select({ count: sql<number>`count(*)` })
        .from(deals)
        .where(and(...conditions));
      
      const total = totalResult[0]?.count || 0;

      res.json({
        deals: flaggedDeals,
        pagination: {
          page: Number(page),
          limit: Number(limit),
          total,
          totalPages: Math.ceil(total / Number(limit))
        }
      });

    } catch (error) {
      console.error("Error fetching flagged deals:", error);
      res.status(500).json({ message: "Failed to fetch flagged deals" });
    }
  });

