  app.patch("/api/deals/:id/review", isAuthenticated, async (req, res) => {
    try {
      const user = req.user as any;
      const isAnalyst = (user?.claims?.email || user?.email || '').endsWith('@apexresi.com');
      
      if (!isAnalyst) {
        return res.status(403).json({ message: "Access denied. Analyst privileges required." });
      }

      const { id } = req.params;
      const { 
        reviewStatus, 
        reviewNotes, 
        timeSpentMinutes, 
        dataCorrections,
        keepFlagged = false 
      } = req.body;

      if (!reviewStatus) {
        return res.status(400).json({ message: "Review status is required" });
      }

      const updateData: any = {
        analystReviewStatus: reviewStatus,
        reviewNotes: reviewNotes,
        updatedAt: new Date()
      };

      // Set timestamps based on status
      if (reviewStatus === 'in_review') {
        updateData.reviewStartedAt = new Date();
      } else if (reviewStatus === 'completed') {
        updateData.reviewCompletedAt = new Date();
        
        // Unless explicitly keeping flagged, mark as clean when review is completed
        if (!keepFlagged) {
          updateData.flagged = false;
          updateData.riskLevel = 'clean';
        }
      }

      // Store data corrections if provided
      if (dataCorrections) {
        updateData.dataCorrections = dataCorrections;
      }

      await db
        .update(deals)
        .set(updateData)
        .where(eq(deals.id, id));

      // Log the review activity
      await logAuditTrail({
        userId: user.id,
        action: `Reviewed flagged deal ${id}`,
        entityType: 'DEAL',
        tableName: 'deals', 
        recordId: id,
        changedBy: user.id,
        entityId: id,
        details: {
          dealId: id,
          reviewStatus,
          timeSpentMinutes,
          hasCorrections: !!dataCorrections,
          reviewNotes: reviewNotes?.substring(0, 100) // Truncate for logging
        }
      });

      res.json({ 
        success: true, 
        message: `Deal review marked as ${reviewStatus}`,
        reviewedBy: `${user.firstName || ''} ${user.lastName || ''}`.trim()
      });

    } catch (error) {
      console.error("Error updating deal review:", error);
      res.status(500).json({ message: "Failed to update deal review" });
    }
  });

  // Bulk review operations on flagged deals
  app.post("/api/analyst/deals/bulk-review", isAuthenticated, async (req, res) => {
    try {
      const user = req.user as any;
      const isAnalyst = (user?.claims?.email || user?.email || '').endsWith('@apexresi.com');
      
      if (!isAnalyst) {
        return res.status(403).json({ message: "Access denied. Analyst privileges required." });
      }

      const { dealIds, operation, data } = req.body;
      
      if (!dealIds || !Array.isArray(dealIds) || !operation) {
        return res.status(400).json({ message: "Deal IDs array and operation are required" });
      }

      let updateData: any = {
        updatedAt: new Date()
      };

      switch (operation) {
        case 'mark_reviewed':
          updateData.analystReviewStatus = 'completed';
          updateData.reviewCompletedAt = new Date();
          updateData.flagged = false;
          updateData.riskLevel = 'clean';
          if (data?.reviewNotes) updateData.reviewNotes = data.reviewNotes;
          break;

        case 'assign_analyst':
          if (!data?.assignedAnalyst) {
            return res.status(400).json({ message: "Assigned analyst is required" });
          }
          updateData.assignedAnalyst = data.assignedAnalyst;
          updateData.analystReviewStatus = 'assigned';
          break;

        case 'change_risk_level':
          if (!data?.riskLevel) {
            return res.status(400).json({ message: "Risk level is required" });
          }
          updateData.riskLevel = data.riskLevel;
          break;

        case 'unflag':
          updateData.flagged = false;
          updateData.riskLevel = 'clean';
          updateData.analystReviewStatus = 'completed';
          updateData.reviewCompletedAt = new Date();
          break;

        default:
          return res.status(400).json({ message: "Invalid operation" });
      }

      // Perform bulk update
      await db
        .update(deals)
        .set(updateData)
        .where(inArray(deals.id, dealIds));

      // Log bulk operation
      await logAuditTrail({
        userId: user.id,
        action: `Bulk ${operation} on ${dealIds.length} flagged deals`,
        entityType: 'DEAL',
        tableName: 'deals',
        recordId: dealIds[0], // Log first deal ID as reference
        changedBy: user.id,
        entityId: dealIds.join(','),
        details: {
          operation,
          dealCount: dealIds.length,
          dealIds: dealIds,
          operationData: data
        }
      });

      res.json({ 
        success: true, 
        message: `Bulk ${operation} completed on ${dealIds.length} deals`,
        processedDeals: dealIds.length
      });

    } catch (error) {
      console.error("Error in bulk review operation:", error);
      res.status(500).json({ message: "Failed to perform bulk review operation" });
    }
  });

  // Get flagging statistics for dashboard
  app.get("/api/deals/flagging-stats", isAuthenticated, async (req, res) => {
    try {
      const user = req.user as any;
      const isAnalyst = (user?.claims?.email || user?.email || '').endsWith('@apexresi.com');
      
      if (!isAnalyst) {
        return res.status(403).json({ message: "Access denied. Analyst privileges required." });
      }

      // Get flagging statistics
      const stats = await db
        .select({
          riskLevel: deals.riskLevel,
          analystReviewStatus: deals.analystReviewStatus,
          count: sql<number>`count(*)`
        })
        .from(deals)
        .where(eq(deals.flagged, true))
        .groupBy(deals.riskLevel, deals.analystReviewStatus);

      // Calculate summary metrics
      let totalFlagged = 0;
      let pendingReview = 0;
      let inReview = 0;
      let completed = 0;
      let highRisk = 0;
      let mediumRisk = 0;
      let lowRisk = 0;

      stats.forEach(stat => {
        const count = Number(stat.count);
        totalFlagged += count;
        
        // Count by review status
        if (stat.analystReviewStatus === 'pending') pendingReview += count;
        else if (stat.analystReviewStatus === 'in_review') inReview += count;
        else if (stat.analystReviewStatus === 'completed') completed += count;
        
        // Count by risk level
        if (stat.riskLevel === 'high') highRisk += count;
        else if (stat.riskLevel === 'medium') mediumRisk += count;
        else if (stat.riskLevel === 'low') lowRisk += count;
      });

      res.json({
        summary: {
          totalFlagged,
          pendingReview,
          inReview,
          completed,
          highRisk,
          mediumRisk,
          lowRisk
        },
        breakdown: stats,
        lastUpdated: new Date().toISOString()
      });

    } catch (error) {
      console.error("Error fetching flagging stats:", error);
      res.status(500).json({ message: "Failed to fetch flagging statistics" });
    }
  });
  
