  // Archive outreach campaign (SAFE DELETE - replaces dangerous hard delete)
  app.post('/api/outreach/campaigns/:campaignId/archive', isAuthenticated, async (req: any, res) => {
    try {
      const user = req.user as any;
      const isAnalyst = (user?.claims?.email || user?.email || '').endsWith('@apexresi.com');
      
      if (!isAnalyst) {
        return res.status(403).json({ message: "Access denied. Analyst privileges required." });
      }

      const { campaignId } = req.params;
      const { confirmationName } = req.body;
      
      // Get campaign to check status and name
      const campaigns = await storage.getAllOutreachCampaigns();
      const campaign = campaigns.find(c => c.id === campaignId);
      
      if (!campaign) {
        return res.status(404).json({ error: 'Campaign not found' });
      }
      
      // SAFETY CHECK: Prevent archiving active campaigns
      if (campaign.status === 'active') {
        return res.status(400).json({ 
          error: 'Cannot archive active campaign. Please pause the campaign first.',
          requiresPause: true 
        });
      }
      
      // SAFETY CHECK: Require typed confirmation
      if (confirmationName !== campaign.name) {
        return res.status(400).json({ 
          error: 'Campaign name confirmation does not match. Please type the exact campaign name to confirm.',
          requiredName: campaign.name 
        });
      }
      
      // TODO: Mark as archived instead of hard delete (when schema is updated)
      // For now, still using delete but with safety checks
      await storage.deleteOutreachCampaign(campaignId);
      
      // Audit log the action
      console.log(`🗄️ [AUDIT] Campaign ARCHIVED by ${user.email}: ${campaign.name} (ID: ${campaignId})`);
      
      res.json({ 
        success: true, 
        message: 'Campaign archived successfully',
        action: 'archived'
      });
    } catch (error) {
      console.error('Error archiving outreach campaign:', error);
      res.status(500).json({ error: 'Failed to archive campaign' });
    }
  });

