  // Update a campaign template step
  app.patch('/api/outreach/campaign-templates/:templateId/steps/:stepId', isAuthenticated, async (req: any, res) => {
    try {
      const { stepId, templateId } = req.params;
      const { sequenceIndex, dayNumber, channel, subject, content, isActive, attachments } = req.body;

      console.log(`[STEP-PATCH] Updating step ${stepId} (tpl: ${templateId}) day=${dayNumber} channel=${channel} active=${isActive} contentLen=${content?.length}`);

      // Fetch current values so we can merge — avoids any type-cast issues with COALESCE
      const current = await db.execute(sql`
        SELECT sequence_index, day_number, channel, subject, content, is_active, attachments
        FROM outreach_campaign_template_steps WHERE id = ${stepId}
      `);

      if (!current.rows?.length) {
        console.error(`[STEP-PATCH] 404 — step ${stepId} not found`);
        return res.status(404).json({ error: 'Campaign template step not found' });
      }

      const cur = current.rows[0] as any;

      // Merge: use incoming value if provided, fall back to existing DB value
      const newSeqIdx  = sequenceIndex !== undefined  ? Number(sequenceIndex) : Number(cur.sequence_index);
      const newDayNum  = dayNumber     !== undefined  ? Number(dayNumber)     : Number(cur.day_number);
      const newChannel = channel       !== undefined  ? String(channel)       : String(cur.channel);
      const newSubject = subject       !== undefined  ? String(subject)       : (cur.subject ?? null);
      const newContent = content       !== undefined  ? String(content)       : String(cur.content);
      const newActive  = isActive      !== undefined  ? Boolean(isActive)     : Boolean(cur.is_active);
      const newAtts    = attachments   !== undefined
        ? (typeof attachments === 'string' ? attachments : JSON.stringify(attachments))
        : (cur.attachments ?? null);

      const result = await db.execute(sql`
        UPDATE outreach_campaign_template_steps
        SET 
          sequence_index = ${newSeqIdx},
          day_number     = ${newDayNum},
          channel        = ${newChannel},
          subject        = ${newSubject},
          content        = ${newContent},
          is_active      = ${newActive},
          attachments    = ${newAtts},
          updated_at     = NOW()
        WHERE id = ${stepId}
        RETURNING 
          id, template_id as "templateId",
          sequence_index as "sequenceIndex",
          day_number as "dayNumber",
          channel, subject, content,
          is_active as "isActive", attachments
      `);
      
      console.log(`[STEP-PATCH] Updated successfully: ${stepId}`);
      res.json(result.rows[0]);
    } catch (error: any) {
      console.error('[STEP-PATCH] Error:', error.message);
      res.status(500).json({ error: error.message });
    }
  });

