  // =====================================================
  // DRIP CAMPAIGN ENROLLMENTS (Queue-Based Outreach)
  // =====================================================
  
  // Get enrollment statistics
  // GET /api/outreach/email-analytics — per-sender email stats sourced from drip_campaign_enrollments
  // NOTE: actual sends are tracked by updating last_sent_at + total_steps_sent in drip_campaign_enrollments,
  // NOT in outreach_messages. Microsoft Graph drip worker never inserts into outreach_messages.
  app.get('/api/outreach/email-analytics', isAuthenticated, async (req: any, res) => {
    try {
      const period = (req.query.period as string) || 'month';
      let fromDate: string;
      const now = new Date();
      if (period === 'day') {
        fromDate = now.toISOString().slice(0, 10);
      } else if (period === 'week') {
        const d = new Date(now); d.setDate(d.getDate() - 7);
        fromDate = d.toISOString().slice(0, 10);
      } else if (period === 'month') {
        const d = new Date(now); d.setDate(d.getDate() - 30);
        fromDate = d.toISOString().slice(0, 10);
      } else { // ytd
        fromDate = `${now.getFullYear()}-01-01`;
      }

      // Overall totals — count of contacts that received at least one email in the period
      const totalsResult = await db.execute(sql`
        SELECT
          COUNT(*) as total,
          COUNT(*) FILTER (WHERE status != 'failed') as sent,
          COUNT(*) FILTER (WHERE status = 'failed') as failed,
          COALESCE(SUM(total_steps_sent), 0) as total_steps_sent
        FROM drip_campaign_enrollments
        WHERE last_sent_at >= ${fromDate}::date
      `);
      const t = ((totalsResult.rows || totalsResult) as any[])[0] || {};

      // Per-sender breakdown — join with outreach_senders
      const bySenderResult = await db.execute(sql`
        SELECT
          COALESCE(s.name, 'Unassigned') as sender_name,
          COUNT(*) as total,
          COUNT(*) FILTER (WHERE e.status != 'failed') as sent,
          COUNT(*) FILTER (WHERE e.status = 'failed') as failed,
          0 as opened,
          0 as replied
        FROM drip_campaign_enrollments e
        LEFT JOIN outreach_senders s ON s.id = e.sender_id
        WHERE e.last_sent_at >= ${fromDate}::date
        GROUP BY COALESCE(s.name, 'Unassigned')
        ORDER BY sent DESC
      `);
      const bySender = ((bySenderResult.rows || bySenderResult) as any[]).map(r => ({
        senderName: r.sender_name,
        total: parseInt(r.total || 0),
        sent: parseInt(r.sent || 0),
        failed: parseInt(r.failed || 0),
        opened: parseInt(r.opened || 0),
        replied: parseInt(r.replied || 0),
      }));

      // Daily volume chart — how many contacts received a step each day
      const dailyResult = await db.execute(sql`
        SELECT
          DATE(last_sent_at) as date,
          COUNT(*) FILTER (WHERE status != 'failed') as sent,
          COUNT(*) FILTER (WHERE status = 'failed') as failed
        FROM drip_campaign_enrollments
        WHERE last_sent_at >= ${fromDate}::date
        GROUP BY DATE(last_sent_at)
        ORDER BY date ASC
      `);
      const dailyVolume = ((dailyResult.rows || dailyResult) as any[]).map(r => ({
        date: r.date,
        sent: parseInt(r.sent || 0),
        failed: parseInt(r.failed || 0),
      }));

      // Sender health info
      const sendersResult = await db.execute(sql`
        SELECT name, email, daily_limit_override, warmup_stage, is_active, sending_paused
        FROM outreach_senders WHERE is_active = true ORDER BY name
      `);
      const senders = ((sendersResult.rows || sendersResult) as any[]).map(s => ({
        name: s.name,
        email: s.email,
        dailyLimit: s.daily_limit_override || 150,
        warmupStage: s.warmup_stage,
        paused: s.sending_paused,
      }));

      // Today's send count per sender
      const todayResult = await db.execute(sql`
        SELECT COALESCE(s.name, 'Unassigned') as sender_name, COUNT(*) as count
        FROM drip_campaign_enrollments e
        LEFT JOIN outreach_senders s ON s.id = e.sender_id
        WHERE DATE(e.last_sent_at) = CURRENT_DATE AND e.status != 'failed'
        GROUP BY COALESCE(s.name, 'Unassigned')
      `);
      const sentTodayMap: Record<string, number> = {};
      ((todayResult.rows || todayResult) as any[]).forEach((r: any) => {
        sentTodayMap[r.sender_name] = parseInt(r.count);
      });

      res.json({
        period,
        fromDate,
        summary: {
          total: parseInt(t.total || 0),
          sent: parseInt(t.sent || 0),
          failed: parseInt(t.failed || 0),
          opened: 0,
          replied: 0,
          totalStepsSent: parseInt(t.total_steps_sent || 0),
        },
        bySender,
        dailyVolume,
        senders: senders.map(s => ({ ...s, sentToday: sentTodayMap[s.name] || 0 })),
      });
    } catch (error: any) {
      console.error('Email analytics error:', error);
      res.status(500).json({ error: error.message });
    }
  });

