  // Update outreach sender
  app.patch('/api/outreach/senders/:senderId', isAuthenticated, async (req: any, res) => {
    try {
      const user = req.user as any;
      const userEmail = (user?.claims?.email || user?.email || '').toLowerCase();
      const isAnalyst = userEmail.endsWith('@apexresi.com');
      
      // Also allow registered outreach senders to update their own settings
      let isOutreachSender = false;
      if (!isAnalyst && userEmail) {
        const { senderId: senderIdForCheck } = req.params;
        const senderCheck = await db.execute(sql`
          SELECT id FROM outreach_senders WHERE email = ${userEmail} AND id = ${senderIdForCheck} AND is_active = true LIMIT 1
        `);
        isOutreachSender = ((senderCheck.rows || senderCheck) as any[]).length > 0;
      }
      
      if (!isAnalyst && !isOutreachSender) {
        return res.status(403).json({ message: "Access denied. Analyst privileges required." });
      }

      const { senderId } = req.params;
      const { 
        name, email, role, smsFollowupEnabled, smsFollowupDays, isActive, hubspotOwnerId,
        hubspotTriggerTag, hubspotTriggerTags, welcomeTemplateKey, deliveryMethod, delayAfterTagging, signatureHtml,
        dailyLimitOverride
      } = req.body;

      console.log(`📝 Updating sender ${senderId}:`, { 
        hasSignature: signatureHtml !== undefined, 
        signatureLength: signatureHtml?.length,
        hubspotTriggerTags: hubspotTriggerTags?.length 
      });

      // Convert undefined to null for SQL COALESCE to work correctly
      const safeSignatureHtml = signatureHtml === undefined ? null : signatureHtml;
      // Filter out empty trigger tags and format for PostgreSQL array
      const filteredTags = hubspotTriggerTags?.filter((t: string) => t && t.trim()) || null;
      // PostgreSQL array literal format: {"item1","item2"}
      const safeTriggerTags = filteredTags ? `{${filteredTags.map((t: string) => `"${t.replace(/"/g, '\\"')}"`).join(',')}}` : null;

      const result = await db.execute(sql`
        UPDATE outreach_senders
        SET 
          name = COALESCE(${name}, name),
          email = COALESCE(${email}, email),
          role = COALESCE(${role}, role),
          sms_followup_enabled = COALESCE(${smsFollowupEnabled}, sms_followup_enabled),
          sms_followup_days = COALESCE(${smsFollowupDays}, sms_followup_days),
          is_active = COALESCE(${isActive}, is_active),
          hubspot_owner_id = COALESCE(${hubspotOwnerId}, hubspot_owner_id),
          hubspot_trigger_tag = COALESCE(${hubspotTriggerTag}, hubspot_trigger_tag),
          hubspot_trigger_tags = CASE WHEN ${safeTriggerTags}::text IS NOT NULL THEN ${safeTriggerTags}::text[] ELSE hubspot_trigger_tags END,
          welcome_template_key = COALESCE(${welcomeTemplateKey}, welcome_template_key),
          delivery_method = COALESCE(${deliveryMethod}, delivery_method),
          delay_after_tagging = COALESCE(${delayAfterTagging}, delay_after_tagging),
          signature_html = COALESCE(${safeSignatureHtml}, signature_html),
          daily_limit_override = COALESCE(${dailyLimitOverride ?? null}, daily_limit_override),
          updated_at = now()
        WHERE id = ${senderId}
        RETURNING id, name, email, role, outlook_connected as "outlookConnected",
                  sms_followup_enabled as "smsFollowupEnabled",
                  sms_followup_days as "smsFollowupDays",
                  is_active as "isActive",
                  hubspot_owner_id as "hubspotOwnerId",
                  hubspot_trigger_tag as "hubspotTriggerTag",
                  hubspot_trigger_tags as "hubspotTriggerTags",
                  welcome_template_key as "welcomeTemplateKey",
                  delivery_method as "deliveryMethod",
                  delay_after_tagging as "delayAfterTagging",
                  signature_html as "signatureHtml",
                  daily_limit_override as "dailyLimitOverride"
      `);

      if (!result.rows?.length) {
        return res.status(404).json({ error: 'Sender not found' });
      }

      // Auto-create/update Campaign Templates for each trigger tag
      if (filteredTags && filteredTags.length > 0) {
        for (const tag of filteredTags) {
          try {
            // Check if template exists for this tag
            const existingTemplate = await db.execute(sql`
              SELECT id FROM outreach_campaign_templates 
              WHERE hubspot_trigger_tag = ${tag}
            `);
            
            if (!existingTemplate.rows?.length) {
              // Create new campaign template with this trigger tag
              await db.execute(sql`
                INSERT INTO outreach_campaign_templates (name, hubspot_trigger_tag, is_active, team_id)
                VALUES (${tag}, ${tag}, true, (SELECT team_id FROM outreach_senders WHERE id = ${senderId}))
              `);
              console.log(`📋 Auto-created campaign template for tag: ${tag}`);
            }
          } catch (templateErr) {
            console.error(`Failed to auto-create template for tag ${tag}:`, templateErr);
            // Don't fail the whole request if template creation fails
          }
        }
      }

      console.log(`✅ Updated outreach sender: ${senderId}`);
      res.json(result.rows[0]);
    } catch (error) {
      console.error('Error updating outreach sender:', error);
      res.status(500).json({ error: 'Failed to update sender' });
    }
  });

  // Update sender signature only (simpler query to avoid SQL issues)
