  // Create a new campaign step (syncs to template if available)
  app.post('/api/outreach/senders/:senderId/campaign-steps', isAuthenticated, async (req: any, res) => {
    try {
      const user = req.user as any;
      const isAnalyst = (user?.claims?.email || user?.email || '').endsWith('@apexresi.com');
      
      if (!isAnalyst) {
        return res.status(403).json({ message: "Access denied. Analyst privileges required." });
      }

      const { senderId } = req.params;
      const { dayNumber, channel, subject, content, templateKey, attachments } = req.body;

      if (!dayNumber || !channel || !content) {
        return res.status(400).json({ error: 'Day number, channel, and content are required' });
      }
      
      const attsJson = attachments ? JSON.stringify(attachments) : null;

      // Check if sender has hubspot trigger tags - if so, create in template instead
      const senderResult = await db.execute(sql`
        SELECT hubspot_trigger_tags FROM outreach_senders WHERE id = ${senderId}
      `);
      const senderTags = (senderResult.rows?.[0] as any)?.hubspot_trigger_tags;
      
      if (senderTags && senderTags.length > 0) {
        const firstTag = senderTags[0];
        const templateResult = await db.execute(sql`
          SELECT id FROM outreach_campaign_templates WHERE hubspot_trigger_tag = ${firstTag}
        `);
        
        if (templateResult.rows?.length > 0) {
          const templateId = (templateResult.rows[0] as any).id;
          
          // Get next sequence_index for template
          const countResult = await db.execute(sql`
            SELECT COALESCE(MAX(sequence_index), -1) + 1 as next_index
            FROM outreach_campaign_template_steps
            WHERE template_id = ${templateId}
          `);
          const nextIndex = (countResult.rows?.[0] as any)?.next_index || 0;

          const result = await db.execute(sql`
            INSERT INTO outreach_campaign_template_steps (template_id, sequence_index, day_number, channel, subject, content, attachments)
            VALUES (${templateId}, ${nextIndex}, ${dayNumber}, ${channel}, ${subject || null}, ${content}, ${attsJson})
            RETURNING id, template_id as "templateId", sequence_index as "sequenceIndex",
                      day_number as "dayNumber", channel, subject, content,
                      is_active as "isActive", attachments, 'template' as "stepSource"
          `);

          console.log(`✅ Created template step for sender ${senderId} (template: ${templateId}): Day ${dayNumber} - ${channel}`);
          return res.status(201).json(result.rows?.[0]);
        }
      }

      // Fallback: create in sender's own steps
      const countResult = await db.execute(sql`
        SELECT COALESCE(MAX(sequence_index), -1) + 1 as next_index
        FROM outreach_campaign_steps
        WHERE sender_id = ${senderId}
      `);
      const nextIndex = (countResult.rows?.[0] as any)?.next_index || 0;

      const result = await db.execute(sql`
        INSERT INTO outreach_campaign_steps (sender_id, sequence_index, day_number, channel, subject, content, template_key, attachments)
        VALUES (${senderId}, ${nextIndex}, ${dayNumber}, ${channel}, ${subject || null}, ${content}, ${templateKey || null}, ${attsJson})
        RETURNING id, sender_id as "senderId", sequence_index as "sequenceIndex",
                  day_number as "dayNumber", channel, subject, content,
                  template_key as "templateKey", is_active as "isActive", attachments, 'sender' as "stepSource"
      `);

      console.log(`✅ Created sender campaign step for ${senderId}: Day ${dayNumber} - ${channel}`);
      res.status(201).json(result.rows?.[0]);
    } catch (error) {
      console.error('Error creating campaign step:', error);
      res.status(500).json({ error: 'Failed to create campaign step' });
    }
  });
  // Update a campaign step (handles both template and sender steps)
  app.patch('/api/outreach/campaign-steps/:stepId', isAuthenticated, async (req: any, res) => {
    try {
      const user = req.user as any;
      const isAnalyst = (user?.claims?.email || user?.email || '').endsWith('@apexresi.com');
      
      if (!isAnalyst) {
        return res.status(403).json({ message: "Access denied. Analyst privileges required." });
      }

      const { stepId } = req.params;
      const { dayNumber, channel, subject, content, templateKey, isActive, attachments, stepSource } = req.body;

      const dayNum = dayNumber !== undefined ? dayNumber : null;
      const chan = channel !== undefined ? channel : null;
      const subj = subject !== undefined ? subject : null;
      const cont = content !== undefined ? content : null;
      const tplKey = templateKey !== undefined ? templateKey : null;
      const active = isActive !== undefined ? isActive : null;
      const atts = attachments !== undefined ? (typeof attachments === 'string' ? attachments : JSON.stringify(attachments)) : null;

      // Check if this is a template step or sender step
      const templateCheck = await db.execute(sql`
        SELECT id FROM outreach_campaign_template_steps WHERE id = ${stepId}
      `);
      
      if (templateCheck.rows?.length > 0) {
        // Update template step
        const result = await db.execute(sql`
          UPDATE outreach_campaign_template_steps
          SET 
            day_number = CASE WHEN ${dayNum}::int IS NOT NULL THEN ${dayNum}::int ELSE day_number END,
            channel = CASE WHEN ${chan}::text IS NOT NULL THEN ${chan}::text ELSE channel END,
            subject = CASE WHEN ${subj}::text IS NOT NULL THEN ${subj}::text ELSE subject END,
            content = CASE WHEN ${cont}::text IS NOT NULL THEN ${cont}::text ELSE content END,
            is_active = CASE WHEN ${active}::boolean IS NOT NULL THEN ${active}::boolean ELSE is_active END,
            attachments = CASE WHEN ${atts}::text IS NOT NULL THEN ${atts}::text ELSE attachments END,
            updated_at = now()
          WHERE id = ${stepId}
          RETURNING id, template_id as "templateId", sequence_index as "sequenceIndex",
                    day_number as "dayNumber", channel, subject, content,
                    is_active as "isActive", attachments, 'template' as "stepSource"
        `);
        console.log(`✅ Updated template step: ${stepId}`);
        return res.json(result.rows?.[0]);
      }

      // Update sender step
      const result = await db.execute(sql`
        UPDATE outreach_campaign_steps
        SET 
          day_number = CASE WHEN ${dayNum}::int IS NOT NULL THEN ${dayNum}::int ELSE day_number END,
          channel = CASE WHEN ${chan}::text IS NOT NULL THEN ${chan}::text ELSE channel END,
          subject = CASE WHEN ${subj}::text IS NOT NULL THEN ${subj}::text ELSE subject END,
          content = CASE WHEN ${cont}::text IS NOT NULL THEN ${cont}::text ELSE content END,
          template_key = CASE WHEN ${tplKey}::text IS NOT NULL THEN ${tplKey}::text ELSE template_key END,
          is_active = CASE WHEN ${active}::boolean IS NOT NULL THEN ${active}::boolean ELSE is_active END,
          attachments = CASE WHEN ${atts}::text IS NOT NULL THEN ${atts}::text ELSE attachments END,
          updated_at = now()
        WHERE id = ${stepId}
        RETURNING id, sender_id as "senderId", sequence_index as "sequenceIndex",
                  day_number as "dayNumber", channel, subject, content,
                  template_key as "templateKey", is_active as "isActive", attachments, 'sender' as "stepSource"
      `);

      if (!result.rows?.length) {
        return res.status(404).json({ error: 'Campaign step not found' });
      }

      console.log(`✅ Updated sender step: ${stepId}`);
      res.json(result.rows[0]);
    } catch (error) {
      console.error('Error updating campaign step:', error);
      res.status(500).json({ error: 'Failed to update campaign step' });
    }
  });

  // Delete a campaign step (handles both template and sender steps)
  app.delete('/api/outreach/campaign-steps/:stepId', isAuthenticated, async (req: any, res) => {
    try {
      const user = req.user as any;
      const isAnalyst = (user?.claims?.email || user?.email || '').endsWith('@apexresi.com');
      
      if (!isAnalyst) {
        return res.status(403).json({ message: "Access denied. Analyst privileges required." });
      }

      const { stepId } = req.params;

      // Check if this is a template step
      const templateCheck = await db.execute(sql`
        SELECT id, template_id FROM outreach_campaign_template_steps WHERE id = ${stepId}
      `);
      
      if (templateCheck.rows?.length > 0) {
        const templateId = (templateCheck.rows[0] as any).template_id;
        
        await db.execute(sql`
          DELETE FROM outreach_campaign_template_steps WHERE id = ${stepId}
        `);
        
        // Re-index remaining template steps
        await db.execute(sql`
          WITH numbered AS (
            SELECT id, ROW_NUMBER() OVER (ORDER BY sequence_index) - 1 as new_index
            FROM outreach_campaign_template_steps
            WHERE template_id = ${templateId}
          )
          UPDATE outreach_campaign_template_steps
          SET sequence_index = numbered.new_index
          FROM numbered
          WHERE outreach_campaign_template_steps.id = numbered.id
        `);
        
        console.log(`✅ Deleted template step: ${stepId}`);
        return res.json({ success: true, deleted: stepId, stepSource: 'template' });
      }

      // Delete sender step
      const result = await db.execute(sql`
        DELETE FROM outreach_campaign_steps WHERE id = ${stepId}
        RETURNING id, sender_id as "senderId"
      `);

      if (!result.rows?.length) {
        return res.status(404).json({ error: 'Campaign step not found' });
      }

      // Re-index remaining sender steps
      const senderId = (result.rows[0] as any).senderId;
      await db.execute(sql`
        WITH numbered AS (
          SELECT id, ROW_NUMBER() OVER (ORDER BY sequence_index) - 1 as new_index
          FROM outreach_campaign_steps
          WHERE sender_id = ${senderId}
        )
        UPDATE outreach_campaign_steps
        SET sequence_index = numbered.new_index
        FROM numbered
        WHERE outreach_campaign_steps.id = numbered.id
      `);

      console.log(`✅ Deleted sender step: ${stepId}`);
      res.json({ success: true, deleted: stepId, stepSource: 'sender' });
    } catch (error) {
      console.error('Error deleting campaign step:', error);
      res.status(500).json({ error: 'Failed to delete campaign step' });
    }
  });

  // Reorder campaign steps
