  // TEST DRIP CAMPAIGN - Send a test email using a sender's drip campaign step
  app.post('/api/outreach/senders/:senderId/test-drip-email', isAuthenticated, async (req: any, res) => {
    try {
      const user = req.user as any;
      const userEmail = user?.claims?.email || user?.email || '';
      const isAuthorized = userEmail.endsWith('@apexresi.com') || userEmail === 'jack@apexresi.com';
      
      if (!isAuthorized) {
        return res.status(403).json({ message: "Access denied. Admin privileges required." });
      }

      const { senderId } = req.params;
      const { testRecipientEmail, stepIndex = 0, subject: directSubject, content: directContent, attachments: directAttachments } = req.body;

      if (!testRecipientEmail) {
        return res.status(400).json({ error: 'testRecipientEmail is required' });
      }

      // Get sender details including signature
      let senderResult = await db.execute(sql`
        SELECT id, name, email, microsoft_access_token as "microsoftAccessToken",
               signature_html as "signatureHtml"
        FROM outreach_senders WHERE id::text = ${senderId}
      `);

      // Fallback: if the ID is stale/wrong, look up by the logged-in user's own email
      if (!senderResult.rows?.length) {
        console.log(`⚠️ [TEST-DRIP] Sender not found by ID ${senderId}, trying email fallback: ${userEmail}`);
        senderResult = await db.execute(sql`
          SELECT id, name, email, microsoft_access_token as "microsoftAccessToken",
                 signature_html as "signatureHtml"
          FROM outreach_senders WHERE email = ${userEmail}
        `);
      }

      if (!senderResult.rows?.length) {
        return res.status(404).json({ error: 'Sender not found' });
      }

      const sender = senderResult.rows[0] as any;

      // Support direct content from template editor OR lookup from campaign steps
      let step: any;
      if (directSubject || directContent) {
        // Use content passed directly from template editor (Step 4: Campaign Templates)
        step = {
          subjectLine: directSubject || '',
          messageContent: directContent || '',
          method: 'email',
          dayOffset: 0,
          attachments: directAttachments || []
        };
      } else {
        // Get the campaign step from database (legacy sender-specific drip)
        const stepResult = await db.execute(sql`
          SELECT id, subject as "subjectLine", content as "messageContent", 
                 channel as method, day_number as "dayOffset", attachments
          FROM outreach_campaign_steps 
          WHERE sender_id = ${senderId}
          ORDER BY sequence_index
          LIMIT 1 OFFSET ${stepIndex}
        `);

        if (!stepResult.rows?.length) {
          return res.status(404).json({ error: 'No campaign steps found for this sender' });
        }

        step = stepResult.rows[0] as any;
      }

      // Helper function to convert markdown-style content to HTML (same as client-side preview)
      function convertContentToHtml(content: string): string {
        if (!content) return '';
        
        // DETECT HTML CONTENT from rich text editor
        // Rich text editor outputs content with tags like <p>, <ul>, <li>, <strong>, etc.
        const isHtmlContent = /<(p|ul|ol|li|strong|em|u|br|div|span)\b/i.test(content);
        
        if (isHtmlContent) {
          // Keep bold and bullets but strip the newsletter-style indentation and spacing.
          let htmlContent = content;

          // Strip ProseMirror editor-only trailing break markers (inside paragraphs, not real line breaks)
          htmlContent = htmlContent.replace(/<br\s[^>]*class="ProseMirror-trailingBreak"[^>]*>/gi, '');

          // Lists: match native Outlook bullet styling — no extra block margins
          htmlContent = htmlContent.replace(/<ul([^>]*)>/gi, '<ul$1 style="margin: 0; padding: 0 0 0 20px; list-style-type: disc;">');
          htmlContent = htmlContent.replace(/<ol([^>]*)>/gi, '<ol$1 style="margin: 0; padding: 0 0 0 20px;">');
          htmlContent = htmlContent.replace(/<li([^>]*)>/gi, '<li$1 style="margin: 0; padding: 0; line-height: 1.2;">');

          // Empty paragraphs → blank-line spacer (natural line-height, like Outlook's blank paragraph)
          htmlContent = htmlContent.replace(/<p[^>]*>\s*(<br[^>]*>)?\s*<\/p>/gi, '<p style="margin: 0; line-height: 1.2;">&nbsp;</p>');
          // Paragraphs: zero bottom margin so consecutive paragraphs flow like native Outlook
          htmlContent = htmlContent.replace(/<p([^>]*)>/gi, '<p$1 style="margin: 0; line-height: 1.2;">');
          // <p> inside <li> — no extra margin
          htmlContent = htmlContent.replace(/(<li[^>]*>)\s*<p[^>]*>/gi, '$1<p style="margin: 0; line-height: 1.2;">');

          // Strip trailing empty nodes (bare <br>, empty <p>, spacer <div>, empty span-only <p>) from rich-text editor output
          // The span variant catches ProseMirror's <p><span> </span></p> empty paragraphs
          let prev = '';
          while (prev !== htmlContent) {
            prev = htmlContent;
            htmlContent = htmlContent
              .replace(/(\s*<br\s*\/?>\s*)+$/gi, '')
              .replace(/<div[^>]*>\s*<\/div>\s*$/gi, '')
              .replace(/<p[^>]*>(\s|&nbsp;|<br[^>]*>|<span[^>]*>(?:\s|&nbsp;)*<\/span>)*<\/p>\s*$/gi, '');
          }
          htmlContent = htmlContent.trimEnd();

          // Strip bottom margin from the very last paragraph so there is no gap before the signature
          const lastPIdx = htmlContent.lastIndexOf('<p');
          if (lastPIdx !== -1) {
            const endTagIdx = htmlContent.indexOf('>', lastPIdx);
            if (endTagIdx !== -1) {
              const tag = htmlContent.substring(lastPIdx, endTagIdx + 1);
              const fixedTag = tag.replace(/margin:\s*0\s+0\s+[\d.]+px\s+0/i, 'margin: 0');
              htmlContent = htmlContent.substring(0, lastPIdx) + fixedTag + htmlContent.substring(endTagIdx + 1);
            }
          }

          return htmlContent;
        }
        
        // ========================================
        // LEGACY MARKDOWN PROCESSING FOR OLD CONTENT
        // ========================================
        
        // STEP 0: Normalize |> sub-bullet markers and Tab indentation to space markers
        let html = content.replace(/^\|>\s*/gm, '  - ');
        html = html.replace(/\n\|>\s*/g, '\n  - ');
        // Also convert Tab-indented bullets to use space indentation
        html = html.replace(/^\t+([•\-–—])/gm, (match, bullet) => {
          const tabCount = (match.match(/\t/g) || []).length;
          return '  '.repeat(tabCount) + bullet;
        });
        html = html.replace(/\n\t+([•\-–—])/g, (match, bullet) => {
          const tabCount = (match.match(/\t/g) || []).length;
          return '\n' + '  '.repeat(tabCount) + bullet;
        });
        
        // PRE-PROCESSING: Normalize dash-bullet formatting BEFORE markdown processing
        // Fix "-**Bold**" → "- **Bold**" (add space after dash when missing)
        html = html.replace(/^(\s*)-(\*\*)/gm, '$1- $2');
        html = html.replace(/\n(\s*)-(\*\*)/g, '\n$1- $2');
        
        // Handle inline bullet items mashed together (e.g., "**text- **Next:**" → "**text**\n- **Next:**")
        html = html.replace(/(\*\*[^*]+)- \*\*([A-Z])/g, '$1**\n- **$2');
        
        // Convert standalone bold headings to bullet points
        // This handles lines like "**Complexity:** text" → "- **Complexity:** text"
        // Match both: "**Criteria:**" (colon inside) and "**Criteria**:" (colon outside)
        // Pattern 1: **text:** - colon inside the bold markers
        // Pattern 2: **text**: - colon outside the bold markers
        html = html.replace(/^(\s*)(\*\*[^*]*:\*\*)/gm, '$1- $2');  // colon inside: **text:**
        html = html.replace(/^(\s*)(\*\*[^*]+\*\*:)/gm, '$1- $2');  // colon outside: **text**:
        html = html.replace(/\n(\s*)(\*\*[^*]*:\*\*)(?!\s*\n)/gm, '\n$1- $2');  // colon inside after newline
        html = html.replace(/\n(\s*)(\*\*[^*]+\*\*:)(?!\s*\n)/gm, '\n$1- $2');  // colon outside after newline
        
        // Handle bold headings that appear inline (after other text on same line)
        html = html.replace(/([^\n])(\*\*[A-Z][^*]+\*\*:)/g, '$1\n- $2');
        
        // Apply text formatting (bold, italic, underline, links)
        html = html
          .replace(/\*\*(.*?)\*\*/g, '<strong>$1</strong>')
          .replace(/\*(.*?)\*/g, '<em>$1</em>')
          .replace(/__(.*?)__/g, '<u>$1</u>')
          .replace(/\[([^\]]+)\]\(([^)]+)\)/g, '<a href="$2" style="color: #0078D4; text-decoration: underline;">$1</a>');
        
        // Handle inline dashes/bullets that start a new bullet
        html = html.replace(/([^\n\s])[-•]<strong>/g, '$1\n- <strong>');
        html = html.replace(/([^\n\s])•([A-Z])/g, '$1\n• $2');
        
        // STEP 1: Handle inline bullets BEFORE normalizing to dash
        // First, detect inline bullets (•BoldWord:) and add line breaks before them
        html = html.replace(/([^\n\s])•\s*(?=[A-Z][a-z]*:)/g, '$1\n• ');
        html = html.replace(/([^\n\s])•\s+(?=[A-Z])/g, '$1\n• ');
        
        // STEP 2: Add space after bullets directly followed by letters (before normalization)
        while (html.match(/•(?=[A-Za-z<])/)) {
          html = html.replace(/•(?=[A-Za-z<])/g, '• ');
        }
        
        // STEP 3: Now normalize bullet characters at LINE START to dash for list matching
        // Only convert bullets at the beginning of lines, not in the middle of text
        html = html.replace(/^•\s*/gm, '- ');
        html = html.replace(/\n•\s*/g, '\n- ');
        
        // STEP 4: Also normalize other bullet Unicode characters at line start
        html = html.replace(/^[●○◦▪▫■□▸▹►▻‣⦿⦾◉◎★☆✦✧◆◇·∙※\u2022\u2023\u2043\u204C\u204D\u2219\u25AA\u25AB\u25CF\u25CB\u25E6\u2B24]\s*/gm, '- ');
        html = html.replace(/\n[●○◦▪▫■□▸▹►▻‣⦿⦾◉◎★☆✦✧◆◇·∙※\u2022\u2023\u2043\u204C\u204D\u2219\u25AA\u25AB\u25CF\u25CB\u25E6\u2B24]\s*/g, '\n- ');
        
        // Normalize dash bullets at start of lines
        html = html.replace(/(^|\n)(\s*)-\s*(?=\S)/gm, '$1$2- ');
        
        // For bullets/dashes followed by <strong>, ensure proper spacing
        html = html.replace(/•\s*<strong>/g, '• <strong>');
        html = html.replace(/(^|\n)(\s*)-\s*<strong>/gm, '$1$2- <strong>');
        
        // Common bullet characters for regex patterns
        const bulletCharsWithDash = '•\\-';
        
        // Parse lines to handle nested bullets with EMAIL-SAFE inline styles
        // Use individual table for each bullet with margin-left for indentation
        const lines = html.split('\n');
        let result: string[] = [];
        
        // Use consistent filled bullet (•) for ALL levels
        const bulletSymbol = '•';
        
        for (let i = 0; i < lines.length; i++) {
          const line = lines[i];
          // Match any leading whitespace before a bullet/dash
          const bulletMatch = line.match(/^(\s*)[•\-–—]\s*(.+)$/);
          
          if (bulletMatch) {
            const rawPrefix = bulletMatch[1] || '';
            
            // Count whitespace for indentation level (2 spaces = 1 level)
            let wsIndent = 0;
            for (let j = 0; j < rawPrefix.length; j++) {
              const ch = rawPrefix[j];
              if (ch === '\t') {
                wsIndent += 4; // Tab = 4 spaces equivalent
              } else {
                wsIndent += 1; // Each space = 1
              }
            }
            
            // Calculate level: 2 spaces = 1 level of indentation
            const level = Math.min(Math.floor(wsIndent / 2), 4);
            
            // Strip any leading bullet/dash characters and whitespace from the captured text
            let text = bulletMatch[2].replace(/^[•\-–—\s]+/, '');
            const marginLeft = level * 24; // 24px per indentation level
            
            // Each bullet is its own table for maximum email client compatibility
            result.push(`<table border="0" cellpadding="0" cellspacing="0" style="margin-left: ${marginLeft}px; margin-bottom: 2px;">`);
            result.push(`<tr><td valign="top" style="padding-right: 8px; font-size: 14px; line-height: 1;">${bulletSymbol}</td><td style="font-size: 14px; line-height: 1;">${text}</td></tr>`);
            result.push('</table>');
          } else {
            result.push(line ? `<p style="margin: 0; font-size: 14px; line-height: 1.2;">${line}</p>` : `<p style="margin: 0; font-size: 14px; line-height: 1.2;">&nbsp;</p>`);
          }
        }
        
        let finalHtml = result.join('');
        
        // Final cleanup: ensure any remaining bullet characters have proper spacing
        finalHtml = finalHtml.replace(/•(?=[A-Za-z<])/g, '• ');
        finalHtml = finalHtml.replace(/-(?=<strong>)/g, '- ');
        
        return finalHtml;
      }

      // Replace tokens in the message
      let personalizedMessage = (step.messageContent || "")
        .replace(/\{\{Broker\.firstname\}\}/gi, 'Test')
        .replace(/\{\{broker\.firstname\}\}/gi, 'Test')
        .replace(/\{\{firstname\}\}/gi, 'Test');
      
      // DEBUG: Log raw content before conversion
      console.log(`📧 [TEST-EMAIL-DEBUG] Raw content (first 500 chars):`, personalizedMessage.substring(0, 500));
      console.log(`📧 [TEST-EMAIL-DEBUG] Content has bullet chars:`, /[•●○◦▪▫‣·∙]/.test(personalizedMessage));
      
      // Convert markdown-style content to HTML for proper email rendering
      personalizedMessage = convertContentToHtml(personalizedMessage);
      
      // DEBUG: Log converted content
      console.log(`📧 [TEST-EMAIL-DEBUG] Converted content (first 500 chars):`, personalizedMessage.substring(0, 500));
      
      // Always trim trailing empty nodes so body ends cleanly regardless of signature presence.
      // This prevents block-level margins (from last <p>) creating a larger gap than <br/><br/>
      // when Exchange auto-appends a native account signature for senders with no stored signature.
      {
        let _b = personalizedMessage;
        let _p = '';
        while (_p !== _b) { _p = _b; _b = _b.replace(/(\s*<br[^>]*>\s*)+$/gi, '').replace(/<p[^>]*>(\s|&nbsp;|<br[^>]*>)*<\/p>\s*$/gi, ''); }
        personalizedMessage = _b.trimEnd();
      }
      if (sender.signatureHtml) {
        console.log(`📝 Appending sender signature (${sender.signatureHtml.length} chars)`);
        personalizedMessage += `<br/><br/>${sender.signatureHtml}`;
      } else {
        // No DB signature — add nothing; Exchange appends the native card with its own spacing.
        // Adding <br/> here stacks on top of Exchange's separator and makes the gap much larger.
        console.log(`ℹ️ No DB signature for ${sender.email} — no trailing added, Exchange controls gap`);
      }
      
      // Wrap with minimal font styling — no centering column or heavy padding for a personal look
      personalizedMessage = (
        '<div style="font-family: Arial, Helvetica, sans-serif; font-size: 14px; line-height: 1.2; color: #333333;">' +
        personalizedMessage +
        '</div>'
      );
      
      const personalizedSubject = (step.subjectLine || "Test Email")
        .replace(/\{\{Broker\.firstname\}\}/gi, 'Test')
        .replace(/\{\{broker\.firstname\}\}/gi, 'Test');

      // Check if sender has Microsoft OAuth connected
      if (sender.microsoftAccessToken) {
        // Send via Microsoft Graph API
        try {
          // Check if token needs refresh (get full sender data)
          const fullSenderResult = await db.execute(sql`
            SELECT microsoft_access_token, microsoft_refresh_token, microsoft_token_expiry
            FROM outreach_senders WHERE id = ${senderId}
          `);
          const fullSender = fullSenderResult.rows?.[0] as any;
          
          let accessToken = fullSender?.microsoft_access_token;
          const refreshToken = fullSender?.microsoft_refresh_token;
          const tokenExpiry = fullSender?.microsoft_token_expiry;
          
          // Refresh token if expired or expiring within 5 minutes
          if (tokenExpiry && refreshToken && new Date(tokenExpiry) <= new Date(Date.now() + 5 * 60 * 1000)) {
            console.log('🔄 Microsoft token expired, attempting refresh...');
            const clientId = process.env.MICROSOFT_CLIENT_ID;
            const clientSecret = process.env.MICROSOFT_CLIENT_SECRET;
            const tenantId = process.env.MICROSOFT_TENANT_ID || 'common';
            
            if (clientId && clientSecret && refreshToken) {
              try {
                const tokenController = new AbortController();
                const tokenTimeout = setTimeout(() => tokenController.abort(), 20000); // 20s timeout
                const tokenResponse = await fetch(`https://login.microsoftonline.com/${tenantId}/oauth2/v2.0/token`, {
                  method: 'POST',
                  headers: { 'Content-Type': 'application/x-www-form-urlencoded' },
                  signal: tokenController.signal,
                  body: new URLSearchParams({
                    client_id: clientId,
                    client_secret: clientSecret,
                    refresh_token: refreshToken,
                    grant_type: 'refresh_token',
                    scope: 'https://graph.microsoft.com/Mail.Send offline_access'
                  })
                });
                clearTimeout(tokenTimeout);
                
                if (tokenResponse.ok) {
                  const tokens = await tokenResponse.json();
                  accessToken = tokens.access_token;
                  
                  // Update tokens in database
                  await db.execute(sql`
                    UPDATE outreach_senders
                    SET microsoft_access_token = ${tokens.access_token},
                        microsoft_refresh_token = ${tokens.refresh_token || refreshToken},
                        microsoft_token_expiry = ${new Date(Date.now() + tokens.expires_in * 1000)},
                        updated_at = now()
                    WHERE id = ${senderId}
                  `);
                  console.log('✅ Microsoft token refreshed successfully');
                } else {
                  const errorText = await tokenResponse.text();
                  console.error('❌ Token refresh failed:', errorText);
                  
                  // Send alert email to Jack about expired token
                  const { sendNotificationEmail } = await import('./emailService.js');
                  await sendNotificationEmail({
                    to: 'jack@catalystcp.com',
                    subject: `⚠️ Microsoft Outlook Token Expired - ${sender.email}`,
                    html: `<h2>Microsoft Outlook Connection Expired</h2>
                           <p>The Microsoft Outlook connection for <strong>${sender.email}</strong> has expired and could not be automatically refreshed.</p>
                           <p><strong>Error:</strong> ${errorText}</p>
                           <p><strong>Action Required:</strong> Please reconnect the Outlook account in the Outreach Setup page.</p>`,
                    text: `Microsoft Outlook Token Expired for ${sender.email}. Please reconnect in Outreach Setup.`,
                    type: 'api_failure_alert',
                    priority: 'high'
                  });
                  
                  return res.status(401).json({ 
                    error: 'Microsoft token expired', 
                    message: 'Please reconnect Outlook in Outreach Setup. An alert has been sent to the admin.',
                    action: 'reconnect_outlook'
                  });
                }
              } catch (refreshError) {
                console.error('Token refresh error:', refreshError);
              }
            }
          }
          
          // Note: Token identity was verified during OAuth callback, so we proceed directly to send
          
          // Process attachments if any
          let graphAttachments: any[] = [];
          if (step.attachments) {
            try {
              const attachmentList = typeof step.attachments === 'string' 
                ? JSON.parse(step.attachments) 
                : step.attachments;
              
              if (Array.isArray(attachmentList) && attachmentList.length > 0) {
                console.log(`📎 Processing ${attachmentList.length} attachment(s) for test email...`);
                const { ObjectStorageService } = await import('./objectStorage');
                const objectStorage = new ObjectStorageService();
                
                for (const att of attachmentList) {
                  try {
                    // Fetch file content from object storage
                    const fileBuffer = await objectStorage.getFileAsBuffer(att.url);
                    const base64Content = fileBuffer.toString('base64');
                    
                    graphAttachments.push({
                      '@odata.type': '#microsoft.graph.fileAttachment',
                      name: att.filename,
                      contentType: att.contentType || 'application/octet-stream',
                      contentBytes: base64Content
                    });
                    console.log(`✅ Attachment prepared: ${att.filename}`);
                  } catch (attError) {
                    console.error(`❌ Failed to fetch attachment ${att.filename}:`, attError);
                  }
                }
              }
            } catch (parseError) {
              console.error('Failed to parse attachments:', parseError);
            }
          }
          
          // Debug: log the last 600 chars of the final HTML body so we can confirm
          // what Exchange actually receives and diagnose any trailing-whitespace gap
          console.log(`📧 [HTML-TAIL] Final body tail (last 600 chars):\n${personalizedMessage.slice(-600)}`);

          const graphController = new AbortController();
          const graphTimeout = setTimeout(() => graphController.abort(), 30000); // 30s timeout — prevents infinite spinner
          try {
            const graphResponse = await fetch('https://graph.microsoft.com/v1.0/me/sendMail', {
              method: 'POST',
              headers: {
                'Authorization': `Bearer ${accessToken}`,
                'Content-Type': 'application/json'
              },
              signal: graphController.signal,
              body: JSON.stringify({
                message: {
                  subject: `[TEST] ${personalizedSubject}`,
                  body: {
                    contentType: 'HTML',
                    content: personalizedMessage
                  },
                  toRecipients: [{
                    emailAddress: { address: testRecipientEmail }
                  }],
                  ...(graphAttachments.length > 0 && { attachments: graphAttachments })
                }
              })
            });
            clearTimeout(graphTimeout);

            if (graphResponse.ok) {
              console.log(`✅ Test drip email sent from ${sender.email} to ${testRecipientEmail}`);
              return res.json({ 
                success: true, 
                message: `Test email sent from ${sender.email} to ${testRecipientEmail}`,
                method: 'microsoft_outlook',
                step: {
                  day: step.dayOffset,
                  subject: personalizedSubject
                }
              });
            } else {
              const errorText = await graphResponse.text();
              console.error('Microsoft Graph API error:', errorText);
              return res.status(500).json({ error: 'Failed to send via Outlook', details: errorText });
            }
          } catch (msError: any) {
            clearTimeout(graphTimeout);
            const isTimeout = msError.name === 'AbortError';
            console.error(isTimeout ? '⏱️ Microsoft Graph timeout (30s)' : '❌ Microsoft API error:', msError.message);
            return res.status(500).json({ 
              error: isTimeout ? 'Microsoft Graph timed out — email may still send. Try again.' : 'Microsoft API error', 
              details: msError.message 
            });
          }
        } catch (outerErr: any) {
          console.error('❌ Unexpected error in Microsoft Graph send path:', outerErr);
          return res.status(500).json({ error: 'Unexpected error sending email', details: String(outerErr) });
        }
      } else {
        // Fall back to SendGrid — fetch attachments from object storage the same way
        // the Microsoft Graph path does, so files are always included regardless of sender type.
        const { sendNotificationEmail } = await import('./emailService.js');
        const sgAttachments: { content: string; filename: string; type: string; disposition: 'attachment' }[] = [];

        if (step.attachments) {
          try {
            const attachmentList = typeof step.attachments === 'string'
              ? JSON.parse(step.attachments)
              : step.attachments;

            if (Array.isArray(attachmentList) && attachmentList.length > 0) {
              console.log(`📎 Processing ${attachmentList.length} attachment(s) for SendGrid test email...`);
              const { ObjectStorageService } = await import('./objectStorage');
              const objectStorage = new ObjectStorageService();

              for (const att of attachmentList) {
                try {
                  const fileBuffer = await objectStorage.getFileAsBuffer(att.url);
                  sgAttachments.push({
                    content: fileBuffer.toString('base64'),
                    filename: att.filename,
                    type: att.contentType || 'application/octet-stream',
                    disposition: 'attachment'
                  });
                  console.log(`✅ Attachment prepared for SendGrid: ${att.filename}`);
                } catch (attError) {
                  console.error(`❌ Failed to fetch attachment ${att.filename}:`, attError);
                }
              }
            }
          } catch (parseError) {
            console.error('Failed to parse attachments for SendGrid:', parseError);
          }
        }

        await sendNotificationEmail({
          to: testRecipientEmail,
          subject: `[TEST] ${personalizedSubject}`,
          html: personalizedMessage,
          type: 'test_drip_email',
          ...(sgAttachments.length > 0 && { attachments: sgAttachments })
        });

        console.log(`✅ Test drip email sent via SendGrid from ${sender.name} to ${testRecipientEmail}`);
        return res.json({ 
          success: true, 
          message: `Test email sent from ${sender.name} to ${testRecipientEmail}`,
          method: 'sendgrid',
          step: {
            day: step.dayOffset,
            subject: personalizedSubject
          }
        });
      }
    } catch (error: any) {
      console.error('Error sending test drip email:', error);
      res.status(500).json({ error: 'Failed to send test drip email', details: error.message });
    }
  });

  // Initiate Microsoft OAuth for Outlook connection
  app.post('/api/outreach/senders/:senderId/connect-outlook', isAuthenticated, async (req: any, res) => {
    try {
      const user = req.user as any;
      const isAnalyst = (user?.claims?.email || user?.email || '').endsWith('@apexresi.com');
      const isDeveloper = String(user?.role || '').toUpperCase() === 'DEVELOPER' && !!user?.developerProfileId;
      
      if (!isAnalyst && !isDeveloper) {
        return res.status(403).json({ message: "Access denied. Analyst privileges required." });
      }

      const { senderId } = req.params;
      let returnUrl = '/outreach-onboarding';
      if (isDeveloper) {
        const senderCheck = await db.execute(sql`
          SELECT s.id, p.slug
          FROM outreach_senders s
          JOIN developer_profiles p ON p.id = s.developer_profile_id
          WHERE s.id = ${senderId}
            AND s.developer_profile_id = ${user.developerProfileId}
            AND p.is_active = true
          LIMIT 1
        `);
        const ownedSender = senderCheck.rows?.[0] as any;
        if (!ownedSender) return res.status(404).json({ error: 'Sender not found' });
        returnUrl = `/developer/${ownedSender.slug}/outreach`;
      }

      // Check if required env vars are set
      console.log(`🔑 [CONNECT-OUTLOOK] Starting OAuth for sender ID: ${senderId}`);
      const clientId = process.env.MICROSOFT_CLIENT_ID;
      const tenantId = process.env.MICROSOFT_TENANT_ID;
      
      // Build redirect URI from request host (works in both dev and production)
      const protocol = req.headers['x-forwarded-proto'] || 'https';
      const host = req.headers['host'] || req.headers['x-forwarded-host'];
      const redirectUri = `${protocol}://${host}/api/oauth/microsoft/callback`;
      
      console.log('🔑 Microsoft OAuth - Redirect URI:', redirectUri);

      if (!clientId || !tenantId) {
        return res.status(501).json({ 
          error: 'Microsoft OAuth not configured',
          message: 'Please configure MICROSOFT_CLIENT_ID, MICROSOFT_CLIENT_SECRET, and MICROSOFT_TENANT_ID in your environment secrets.',
          setupRequired: true
        });
      }

      // Generate OAuth URL for Microsoft Graph API
      const scope = 'openid profile email offline_access User.Read Mail.Send Mail.Read';
      let state: string;
      if (isDeveloper) {
        const stateToken = randomBytes(32).toString('hex');
        developerMicrosoftOAuthStates.set(stateToken, {
          senderId,
          developerProfileId: user.developerProfileId,
          returnUrl,
          expiresAt: Date.now() + 10 * 60 * 1000,
        });
        state = `developer:${stateToken}`;
      } else {
        state = Buffer.from(JSON.stringify({ senderId, returnUrl })).toString('base64');
      }
      
      const authUrl = `https://login.microsoftonline.com/${tenantId}/oauth2/v2.0/authorize?` +
        `client_id=${clientId}` +
        `&response_type=code` +
        `&redirect_uri=${encodeURIComponent(redirectUri)}` +
        `&response_mode=query` +
        `&scope=${encodeURIComponent(scope)}` +
        `&state=${state}`
        + '&prompt=select_account';

      res.json({ authUrl });
    } catch (error) {
      console.error('Error initiating Outlook connection:', error);
      res.status(500).json({ error: 'Failed to initiate Outlook connection' });
    }
  });

  // Microsoft OAuth callback (will be used when Azure app is registered)
  app.get('/api/oauth/microsoft/callback', isAuthenticated, async (req: any, res) => {
    console.log('🔑 [OAUTH-CALLBACK] Microsoft OAuth callback hit!');
    console.log('🔑 [OAUTH-CALLBACK] Query params:', JSON.stringify(req.query));
    console.log('🔑 [OAUTH-CALLBACK] Host:', req.headers['host']);
    try {
      const { code, state, error, error_description } = req.query;

      if (error) {
        console.error('Microsoft OAuth error:', error, error_description);
        const msError = encodeURIComponent(String(error));
        const msDesc = encodeURIComponent(String(error_description || 'none'));
        return res.redirect(`/outreach-onboarding?error=oauth_failed&ms_error=${msError}&ms_desc=${msDesc}`);
      }

      if (!code || !state) {
        return res.redirect('/outreach-onboarding?error=missing_params');
      }

      let stateData: any;
      const rawState = String(state);
      if (rawState.startsWith('developer:')) {
        const token = rawState.slice('developer:'.length);
        stateData = developerMicrosoftOAuthStates.get(token);
        developerMicrosoftOAuthStates.delete(token);
        if (!stateData || stateData.expiresAt < Date.now()) {
          return res.redirect('/?error=oauth_state_invalid');
        }
      } else {
        stateData = JSON.parse(Buffer.from(rawState, 'base64').toString());
        if (String(req.user?.role || '').toUpperCase() === 'DEVELOPER') {
          return res.redirect('/?error=oauth_state_invalid');
        }
      }
      const { senderId, returnUrl, developerProfileId } = stateData;
      if (developerProfileId) {
        const callbackUser = (req as any).user;
        if (
          String(callbackUser?.role || '').toUpperCase() !== 'DEVELOPER'
          || callbackUser?.developerProfileId !== developerProfileId
        ) {
          return res.redirect(`${returnUrl || '/'}?error=oauth_session_mismatch`);
        }
      }

      // Exchange code for tokens
      const clientId = process.env.MICROSOFT_CLIENT_ID;
      const clientSecret = process.env.MICROSOFT_CLIENT_SECRET;
      const tenantId = process.env.MICROSOFT_TENANT_ID;
      
      // Build redirect URI from request host (must match the one used in authorize request)
      const protocol = req.headers['x-forwarded-proto'] || 'https';
      const host = req.headers['host'] || req.headers['x-forwarded-host'];
      const redirectUri = `${protocol}://${host}/api/oauth/microsoft/callback`;

      const tokenResponse = await fetch(`https://login.microsoftonline.com/${tenantId}/oauth2/v2.0/token`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/x-www-form-urlencoded' },
        body: new URLSearchParams({
          client_id: clientId!,
          client_secret: clientSecret!,
          code: code as string,
          redirect_uri: redirectUri,
          grant_type: 'authorization_code',
        }),
      });

      if (!tokenResponse.ok) {
        console.error('Token exchange failed:', await tokenResponse.text());
        return res.redirect('/outreach-onboarding?error=token_exchange_failed');
      }

      const tokens = await tokenResponse.json();
      const { access_token, refresh_token, expires_in } = tokens;

      // Get user info from Microsoft Graph
      const userInfoResponse = await fetch('https://graph.microsoft.com/v1.0/me', {
        headers: { Authorization: `Bearer ${access_token}` },
      });

      const userInfo = userInfoResponse.ok ? await userInfoResponse.json() : null;
      
      // Get the sender's configured email to verify it matches the Microsoft account
      const senderResult = await db.execute(sql`
        SELECT email, name, developer_profile_id
        FROM outreach_senders
        WHERE id = ${senderId}
      `);
      const senderRecord = senderResult.rows?.[0] as any;
      if (!senderRecord) {
        console.error(`❌ [OAUTH-ERROR] Sender not found in database: ${senderId}`);
        return res.redirect(`${returnUrl || "/outreach-onboarding"}?error=sender_not_found&message=Sender+ID+no+longer+exists`);
      }
      if (developerProfileId && senderRecord.developer_profile_id !== developerProfileId) {
        return res.redirect(`${returnUrl || '/'}?error=sender_not_owned`);
      }
      const senderEmail = senderRecord?.email?.toLowerCase() || '';
      const senderName = senderRecord?.name || 'Unknown';
      
      // Microsoft Graph returns email in 'mail' or 'userPrincipalName' field
      const microsoftEmail = (userInfo?.mail || userInfo?.userPrincipalName || '').toLowerCase();
      const microsoftDisplayName = userInfo?.displayName || 'Unknown';
      
      // SECURITY CHECK: Verify Microsoft account matches sender's configured email
      if (senderEmail && microsoftEmail && senderEmail !== microsoftEmail) {
        console.error(`❌ [OAUTH-MISMATCH] Microsoft account email (${microsoftEmail}) does not match sender email (${senderEmail})`);
        console.error(`   Microsoft user: ${microsoftDisplayName}, Sender: ${senderName}`);
        return res.redirect(`${returnUrl || '/outreach-onboarding'}?error=email_mismatch&expected=${encodeURIComponent(senderEmail)}&actual=${encodeURIComponent(microsoftEmail)}`);
      }

      // Update sender with tokens
      await db.execute(sql`
        UPDATE outreach_senders
        SET 
          outlook_connected = true,
          microsoft_access_token = ${access_token},
          microsoft_refresh_token = ${refresh_token},
          microsoft_token_expiry = ${new Date(Date.now() + expires_in * 1000)},
          microsoft_user_id = ${userInfo?.id || null},
          updated_at = now()
        WHERE id = ${senderId}
          AND (${developerProfileId || null}::text IS NULL OR developer_profile_id = ${developerProfileId || null})
      `);

      console.log(`✅ Microsoft Outlook connected for sender: ${senderId} (${microsoftEmail})`);
      // Always add success parameter to the redirect URL
      const successUrl = returnUrl 
        ? `${returnUrl}${returnUrl.includes('?') ? '&' : '?'}success=outlook_connected`
        : '/outreach-onboarding?success=outlook_connected';
      res.redirect(successUrl);
    } catch (error) {
      console.error('Error in Microsoft OAuth callback:', error);
      res.redirect('/outreach-onboarding?error=callback_failed');
    }
  });

