  // SMS Opt-In Endpoint - Public endpoint for brokers to opt-in to SMS notifications
  app.post("/api/sms-opt-in", async (req, res) => {
    try {
      const { phone, email, name } = req.body;
      
      if (!phone || !email || !name) {
        return res.status(400).json({ error: "Phone, email, and name are required" });
      }
      
      console.log(`📱 SMS opt-in request: ${name} (${email}) - ${phone}`);
      
      // Find or create broker by email
      let broker = await db.select().from(brokers).where(and(
        eq(brokers.email, email),
        isNull(brokers.ownerDeveloperProfileId),
      )).limit(1);
      
      if (broker && broker.length > 0) {
        // Update existing broker - clear opt-out date when opting back in
        await db.update(brokers)
          .set({
            smsOptIn: true,
            smsOptInDate: new Date(),
            smsOptOutDate: null, // Clear opt-out date when opting back in
            phone: phone,
            firstName: name.split(' ')[0] || name,
            lastName: name.split(' ').slice(1).join(' ') || '',
            updatedAt: new Date()
          })
          .where(eq(brokers.id, broker[0].id));
        
        console.log(`✅ Updated existing broker ${broker[0].id} - SMS opt-in enabled, opt-out date cleared`);
      } else {
        // Create new broker with SMS opt-in
        const [newBroker] = await db.insert(brokers).values({
          email,
          phone,
          firstName: name.split(' ')[0] || name,
          lastName: name.split(' ').slice(1).join(' ') || '',
          smsOptIn: true,
          smsOptInDate: new Date(),
          isActive: true
        }).returning();
        
        console.log(`✅ Created new broker ${newBroker.id} with SMS opt-in enabled`);
      }
      
      // Send confirmation SMS
      try {
        const smsResult = await sendSMS({
          to: phone,
          message: `Welcome to LandLinq SMS notifications! 🎉 You'll receive updates about your property deals. Reply STOP to opt-out anytime. Questions? Call ${process.env.SUPPORT_PHONE || '(704) 610-1549'}`
        });
        
        if (smsResult.success && smsResult.delivered) {
          console.log(`✅ SMS opt-in confirmation sent to ${phone} (SID: ${smsResult.sid})`);
        } else if (smsResult.success && !smsResult.delivered) {
          console.log(`⏭️ SMS opt-in confirmation not delivered - ${smsResult.reason || smsResult.mode}`);
        } else {
          console.log(`❌ SMS opt-in confirmation failed - ${smsResult.error}`);
        }
      } catch (smsError) {
        console.error(`⚠️ Failed to send SMS confirmation:`, smsError);
        // Don't fail the request if SMS fails - opt-in was still recorded
      }
      
      res.json({ 
        success: true, 
        message: "Successfully opted into SMS notifications" 
      });
      
    } catch (error) {
      console.error('❌ Error processing SMS opt-in:', error);
      res.status(500).json({ error: 'Failed to process SMS opt-in request' });
    }
  });

  // Verify ZIP Codes - Admin endpoint to check and fix incorrect ZIP codes
  app.post("/api/deals/verify-zip-codes", isAuthenticated, async (req, res) => {
    try {
      const user = req.user as any;
      const userRole = user?.role || '';
      const userEmail = user?.email || '';
      
      // Admin only
      const isAdmin = userRole === 'ADMIN' || userRole === 'SUPER_ADMIN';
      const isLegacyAdmin = userEmail.endsWith('@apexresi.com');
      
      if (!isAdmin && !isLegacyAdmin) {
        return res.status(403).json({ error: 'Access denied - ADMIN privileges required' });
      }

      const { GeocodioService } = await import('./geocodioService');
      const geocodio = new GeocodioService();
      
      const allDeals = await db.select().from(deals);
      
      const results = {
        total: allDeals.length,
        verified: 0,
        issuesFound: 0,
        updated: 0,
        failed: 0,
        details: [] as any[]
      };
      
      for (const deal of allDeals) {
        if (!deal.address) {
          results.failed++;
          continue;
        }
        
        try {
          const geocodeResult = await geocodio.geocodeAddress(deal.address);
          
          if (geocodeResult.success && geocodeResult.zipCode) {
            results.verified++;
            
            const correctZip = geocodeResult.zipCode;
            const correctState = geocodeResult.state;
            const storedZip = deal.zip;
            const storedState = deal.state;
            
            const zipMismatch = storedZip && storedZip !== correctZip;
            const stateMismatch = storedState && correctState && storedState !== correctState;
            
            if (zipMismatch || stateMismatch) {
              results.issuesFound++;
              
              const issues = [];
              if (zipMismatch) issues.push(`ZIP should be ${correctZip} (not ${storedZip})`);
              if (stateMismatch) issues.push(`State should be ${correctState} (not ${storedState})`);
              
              const comment = `⚠️ ADDRESS VERIFICATION: ${issues.join('; ')}`;
              
              const existingComment = (deal as any).internalComment || '';
              const newComment = existingComment 
                ? `${existingComment}\n\n${comment}`
                : comment;
              
              await db.update(deals)
                .set({ internalComment: newComment } as any)
                .where(eq(deals.id, deal.id));
              
              results.updated++;
              results.details.push({
                dealNumber: deal.dealNumber,
                address: deal.address,
                issues,
                comment
              });
            }
          } else {
            results.failed++;
          }
          
          // Rate limit protection
          await new Promise(resolve => setTimeout(resolve, 200));
          
        } catch (error) {
          console.error(`Error verifying deal #${deal.dealNumber}:`, error);
          results.failed++;
        }
      }
      
      res.json(results);
      
    } catch (error) {
      console.error('Error verifying ZIP codes:', error);
      res.status(500).json({ error: 'Failed to verify ZIP codes' });
    }
  });

