  // News API - Marketaux real estate news
  app.get('/api/executive/news', isAuthenticated, async (req: any, res) => {
    try {
      const NEWS_API_KEY = process.env.NEWS_API_KEY;
      if (!NEWS_API_KEY) {
        console.warn('[NEWS-API] NEWS_API_KEY not configured');
        return res.json({ articles: [], error: 'News API key not configured' });
      }
      
      const limit = parseInt(req.query.limit as string) || 5;
      
      // Load news preferences from business settings
      const businessSettingsData = await storage.getBusinessSettings();
      const newsPrefs = (businessSettingsData as any)?.newsPreferences || {
        keywords: ['interest rates', 'charlotte nc', 'multifamily real estate', 'commercial real estate', 'apartment'],
        excludedDomains: [],
        sentiment: 'all',
        enabled: true
      };
      
      // Build search query from keywords
      const keywords = Array.isArray(newsPrefs.keywords) ? newsPrefs.keywords : [];
      const searchQuery = keywords.length > 0 
        ? keywords.map((k: string) => encodeURIComponent(k)).join('+OR+')
        : 'real+estate+OR+multifamily+OR+apartment';
      
      // Fetch real estate and land development news from Marketaux
      let response;
      try {
        response = await fetch(
          `https://api.marketaux.com/v1/news/all?` + 
          `filter_entities=true&language=en&` +
          `search=${searchQuery}&` +
          `limit=${limit}&api_token=${NEWS_API_KEY}`,
          { signal: AbortSignal.timeout(10000) }
        );
      } catch (fetchError: any) {
        console.error('[NEWS-API] Network error fetching from Marketaux:', fetchError.message);
        return res.json({ articles: [], error: 'Unable to fetch news - network error' });
      }
      
      if (!response.ok) {
        const errorText = await response.text().catch(() => 'Unknown error');
        console.error('[NEWS-API] Marketaux API error:', response.status, errorText);
        return res.json({ articles: [], error: `News API returned ${response.status}` });
      }
      
      let data;
      try {
        data = await response.json();
      } catch (parseError) {
        console.error('[NEWS-API] Failed to parse Marketaux response');
        return res.json({ articles: [], error: 'Invalid response from news API' });
      }
      
      // Safely transform with null guards
      const rawArticles = Array.isArray(data?.data) ? data.data : [];
      const articles = rawArticles.map((article: any) => ({
        title: article?.title || 'Untitled',
        description: article?.description || '',
        url: article?.url || '#',
        source: article?.source || 'Unknown',
        publishedAt: article?.published_at || null,
        imageUrl: article?.image_url || null,
        sentiment: article?.entities?.[0]?.sentiment_score ?? null,
      })).filter((a: any) => a.title !== 'Untitled');
      
      res.json({ articles });
    } catch (error: any) {
      console.error('[NEWS-API] Unexpected error:', error.message);
      res.json({ articles: [], error: 'Unexpected error fetching news' });
    }
  });
  
  // Executive Dashboard Statistics
  app.get('/api/executive/stats', isAuthenticated, async (req: any, res) => {
    try {
      const user = req.user as any;
      const isAnalyst = (user?.claims?.email || user?.email || '').endsWith('@apexresi.com');
      
      if (!isAnalyst) {
        return res.status(403).json({ error: 'Access denied - Analyst access required' });
      }
      
      // Get deal statistics
      const dealStats = await db.execute(sql`
        SELECT 
          COUNT(*) as total_deals,
          COUNT(*) FILTER (WHERE classification = 'green') as green_deals,
          COUNT(*) FILTER (WHERE classification = 'yellow') as yellow_deals,
          COUNT(*) FILTER (WHERE classification = 'red') as red_deals,
          COUNT(*) FILTER (WHERE classification IS NULL OR classification = 'pending') as pending_deals,
          COUNT(*) FILTER (WHERE created_at >= NOW() - INTERVAL '7 days') as deals_this_week,
          COUNT(*) FILTER (WHERE created_at >= NOW() - INTERVAL '30 days') as deals_this_month,
          COUNT(DISTINCT broker_id) as unique_brokers
        FROM deals
      `);
      
      // Get broker statistics
      const brokerStats = await db.execute(sql`
        SELECT 
          COUNT(*) as total_brokers,
          COUNT(*) FILTER (WHERE created_at >= NOW() - INTERVAL '30 days') as new_brokers_this_month,
          COUNT(*) FILTER (WHERE sms_opt_in = true) as sms_opted_in
        FROM brokers
      `);
      
      // Get communication statistics
      const commStats = await db.execute(sql`
        SELECT 
          COUNT(*) FILTER (WHERE type = 'email' AND created_at >= NOW() - INTERVAL '30 days') as emails_sent,
          COUNT(*) FILTER (WHERE type = 'sms' AND created_at >= NOW() - INTERVAL '30 days') as sms_sent
        FROM communications
        WHERE direction = 'outbound'
      `);
      
      // Get deals by classification over time (last 6 months)
      const dealsTrend = await db.execute(sql`
        SELECT 
          DATE_TRUNC('month', created_at) as month,
          COUNT(*) as total,
          COUNT(*) FILTER (WHERE classification = 'green') as green,
          COUNT(*) FILTER (WHERE classification = 'yellow') as yellow,
          COUNT(*) FILTER (WHERE classification = 'red') as red
        FROM deals
        WHERE created_at >= NOW() - INTERVAL '6 months'
        GROUP BY DATE_TRUNC('month', created_at)
        ORDER BY month ASC
      `);
      
      // Get top markets by deal count
      const topMarkets = await db.execute(sql`
        SELECT 
          state,
          COUNT(*) as deal_count,
          COUNT(*) FILTER (WHERE classification = 'green') as green_count
        FROM deals
        WHERE state IS NOT NULL
        GROUP BY state
        ORDER BY deal_count DESC
        LIMIT 10
      `);
      
      // Get API cost summary (last 30 days)
      const apiCosts = await db.execute(sql`
        SELECT 
          SUM(estimated_cost) as total_cost,
          COUNT(*) as total_calls,
          COUNT(*) FILTER (WHERE success = true) as successful_calls
        FROM api_call_logs
        WHERE created_at >= NOW() - INTERVAL '30 days'
      `);
      
      const stats: any = dealStats.rows?.[0] || (dealStats as any)[0] || {};
      const brokersData: any = brokerStats.rows?.[0] || (brokerStats as any)[0] || {};
      const comms: any = commStats.rows?.[0] || (commStats as any)[0] || {};
      const costs: any = apiCosts.rows?.[0] || (apiCosts as any)[0] || {};
      
      res.json({
        deals: {
          total: parseInt(String(stats.total_deals)) || 0,
          green: parseInt(String(stats.green_deals)) || 0,
          yellow: parseInt(String(stats.yellow_deals)) || 0,
          red: parseInt(String(stats.red_deals)) || 0,
          pending: parseInt(String(stats.pending_deals)) || 0,
          thisWeek: parseInt(String(stats.deals_this_week)) || 0,
          thisMonth: parseInt(String(stats.deals_this_month)) || 0,
          uniqueBrokers: parseInt(String(stats.unique_brokers)) || 0,
        },
        brokers: {
          total: parseInt(String(brokersData.total_brokers)) || 0,
          newThisMonth: parseInt(String(brokersData.new_brokers_this_month)) || 0,
          smsOptedIn: parseInt(String(brokersData.sms_opted_in)) || 0,
        },
        communications: {
          emailsSent: parseInt(String(comms.emails_sent)) || 0,
          smsSent: parseInt(String(comms.sms_sent)) || 0,
        },
        api: {
          totalCost: parseFloat(String(costs.total_cost)) || 0,
          totalCalls: parseInt(String(costs.total_calls)) || 0,
          successRate: parseInt(String(costs.total_calls)) > 0 
            ? Math.round((parseInt(String(costs.successful_calls)) / parseInt(String(costs.total_calls))) * 100) 
            : 0,
        },
        trends: {
          dealsByMonth: (dealsTrend.rows || dealsTrend || []).map((row: any) => ({
            month: row.month,
            total: parseInt(row.total) || 0,
            green: parseInt(row.green) || 0,
            yellow: parseInt(row.yellow) || 0,
            red: parseInt(row.red) || 0,
          })),
        },
        topMarkets: (topMarkets.rows || topMarkets || []).map((row: any) => ({
          state: row.state,
          dealCount: parseInt(row.deal_count) || 0,
          greenCount: parseInt(row.green_count) || 0,
        })),
      });
    } catch (error: any) {
      console.error('Executive stats error:', error);
      res.status(500).json({ error: error.message });
    }
  });

