  // ==========================================
  // AFFORDABLE HOUSING LIHTC SCORING API
  // ==========================================
  app.post("/api/affordable-housing/score", isAuthenticated, async (req, res) => {
    try {
      const { evaluateSite } = await import('./siteEvaluationService.js');
      
      const { 
        address, 
        countyIncomeLevel, 
        redevelopment, 
        neighborhoodQuality, 
        negativeSiteFeatures, 
        incompatibleUses,
        units30AMI,
        units40AMI,
        units50AMI
      } = req.body;

      if (!address) {
        return res.status(400).json({ error: "Address is required" });
      }

      // Geocode address using Geocodio with census fields
      let lat: number | null = null;
      let lng: number | null = null;
      let geocodedAddress: string | null = null;
      let censusTract: string | null = null;
      let isQCT = false; // Qualified Census Tract
      let medianIncome: number | null = null;
      let povertyRate: number | null = null;
      let county: string | null = null;
      let state: string | null = null;
      let city: string | null = null;

      try {
        const geocodioApiKey = process.env.GEOCODIO_API_KEY;
        if (geocodioApiKey) {
          const geocodeUrl = `https://api.geocod.io/v1.7/geocode?q=${encodeURIComponent(address)}&fields=census,acs-economics&api_key=${geocodioApiKey}`;
          const geocodeRes = await fetch(geocodeUrl);
          const geocodeData = await geocodeRes.json();
          
          if (geocodeData.results && geocodeData.results.length > 0) {
            const result = geocodeData.results[0];
            const location = result.location;
            lat = location.lat;
            lng = location.lng;
            geocodedAddress = result.formatted_address;
            
            city = result.address_components?.city;
            state = result.address_components?.state;
            county = result.address_components?.county;
            
            if (result.fields?.census?.census_year) {
              censusTract = result.fields.census['2020']?.tract || result.fields.census.tract;
            }
            
            // Check for QCT designation
            if (result.fields?.census?.['2020']?.source === 'QCT' || 
                result.fields?.census?.source === 'QCT') {
              isQCT = true;
            }
            
            if (result.fields?.acs?.economics) {
              medianIncome = result.fields.acs.economics.median_household_income?.total?.value;
              povertyRate = result.fields.acs.economics.poverty?.poverty_rate?.total?.value;
            }
          }
        }
      } catch (geocodeError) {
        console.error("Geocoding error:", geocodeError);
      }

      // =========================================
      // INTERNAL DATA: Check similar deals in our database
      // =========================================
      let marketInsights: any = null;
      let similarDeals: any[] = [];
      
      try {
        const allDeals = await storage.getAllDeals();
        
        if (city && state) {
          const cityDeals = allDeals.filter((d: any) => 
            d.city?.toLowerCase() === city?.toLowerCase() && 
            d.state?.toUpperCase() === state?.toUpperCase()
          );
          
          if (cityDeals.length > 0) {
            const greenDeals = cityDeals.filter((d: any) => d.classification === 'green');
            const affordableDeals = cityDeals.filter((d: any) => 
              d.productTypes?.some((pt: string) => pt.toLowerCase().includes('affordable'))
            );
            
            let avgPricePerAcre = 0;
            let priceCount = 0;
            cityDeals.forEach((d: any) => {
              if (d.pricePerAcre) {
                avgPricePerAcre += parseFloat(d.pricePerAcre);
                priceCount++;
              }
            });
            
            marketInsights = {
              totalDealsInMarket: cityDeals.length,
              greenDealsInMarket: greenDeals.length,
              affordableDealsInMarket: affordableDeals.length,
              successRate: cityDeals.length > 0 ? Math.round((greenDeals.length / cityDeals.length) * 100) : 0,
              avgPricePerAcre: priceCount > 0 ? Math.round(avgPricePerAcre / priceCount) : null
            };
            
            similarDeals = affordableDeals.slice(0, 5).map((d: any) => ({
              propertyName: d.propertyName || d.address,
              classification: d.classification,
              pricePerAcre: d.pricePerAcre ? parseFloat(d.pricePerAcre) : null,
              proposedUnits: d.proposedUnits,
              acreage: d.acreage ? parseFloat(d.acreage) : null
            }));
          }
        }
      } catch (dbError) {
        console.error("Database lookup error:", dbError);
      }

      // QAP Scoring Rules (2026 NC LIHTC)
      const PRIMARY_AMENITIES: Record<string, { points: number[]; distances: number[] }> = {
        "Grocery": { points: [12, 10, 8, 6], distances: [2, 2.5, 3, 4] },
        "Shopping": { points: [7, 6, 5, 4], distances: [2, 2.5, 3, 4] },
        "Pharmacy": { points: [7, 6, 5, 4], distances: [2, 2.5, 3, 4] }
      };

      const SECONDARY_AMENITIES: Record<string, { points: number[]; distances: number[] }> = {
        "Healthcare": { points: [3, 2, 1, 0], distances: [2, 2.5, 3, 4] },
        "Public Facility": { points: [3, 2, 1, 0], distances: [2, 2.5, 3, 4] },
        "School": { points: [3, 2, 1, 0], distances: [2, 2.5, 3, 4] },
        "Service": { points: [3, 2, 1, 0], distances: [2, 2.5, 3, 4] },
        "Restaurant": { points: [3, 2, 1, 0], distances: [2, 2.5, 3, 4] },
        "Bank": { points: [3, 2, 1, 0], distances: [2, 2.5, 3, 4] }
      };

      // Haversine distance calculation
      const haversine = (lon1: number, lat1: number, lon2: number, lat2: number): number => {
        const toRad = (deg: number) => deg * Math.PI / 180;
        const dLon = toRad(lon2 - lon1);
        const dLat = toRad(lat2 - lat1);
        const a = Math.sin(dLat/2)**2 + Math.cos(toRad(lat1)) * Math.cos(toRad(lat2)) * Math.sin(dLon/2)**2;
        const c = 2 * Math.asin(Math.sqrt(a));
        return 3956 * c; // miles
      };

      // Score amenity based on distance
      const scoreAmenity = (distance: number | null, pointsList: number[], distThresholds: number[]): number => {
        if (distance === null) return 0;
        for (let i = 0; i < distThresholds.length; i++) {
          if (distance <= distThresholds[i]) return pointsList[i];
        }
        return 0;
      };

      // Calculate amenity scores using Google Places API if available
      let primaryScore = 0;
      let secondaryScore = 0;
      const amenityDetails: { name: string; distance: number | null; points: number }[] = [];

      const googleApiKey = process.env.VITE_GOOGLE_MAPS_API_KEY || process.env.GOOGLE_MAPS_API_KEY;

      // Valid Google Places API type mapping (NC QAP amenity name → Places API type)
      // Notes on type choices (calibrated to 2026 NC QAP definitions):
      //   Shopping  → department_store catches Walmart, Target, Costco, strip malls
      //               (shopping_mall missed every rural general-merchandise store)
      //   Healthcare → doctor catches urgent care, clinics, and doctor offices
      //               (hospital missed all outpatient and primary care facilities)
      //   Service   → beauty_salon is present in virtually every small NC town
      //               (laundry was rare and caused consistent zero-scoring)
      //   Public Facility → library is correct per QAP and exists in every county seat
      const PLACES_TYPE_MAP: Record<string, string> = {
        "Grocery":        "grocery_or_supermarket",
        "Shopping":       "department_store",
        "Pharmacy":       "pharmacy",
        "Healthcare":     "doctor",
        "Public Facility":"library",
        "School":         "school",
        "Service":        "beauty_salon",
        "Restaurant":     "restaurant",
        "Bank":           "bank"
      };
      
      if (lat && lng && googleApiKey) {
        // Search for primary amenities
        for (const [amenity, vals] of Object.entries(PRIMARY_AMENITIES)) {
          try {
            const placeType = PLACES_TYPE_MAP[amenity] || amenity.toLowerCase().replace(/ /g, '_');
            const placesUrl = `https://maps.googleapis.com/maps/api/place/nearbysearch/json?location=${lat},${lng}&radius=6437&type=${placeType}&key=${googleApiKey}`;
            const placesRes = await fetch(placesUrl, { signal: AbortSignal.timeout(10000) });
            const placesData = await placesRes.json();
            
            let distance: number | null = null;
            if (placesData.status === 'OK' && placesData.results?.length > 0) {
              const place = placesData.results[0].geometry.location;
              distance = haversine(lng, lat, place.lng, place.lat);
            } else if (placesData.status && placesData.status !== 'ZERO_RESULTS') {
              console.warn(`[LIHTC] Places API ${placeType} status: ${placesData.status}`);
            }
            
            const points = scoreAmenity(distance, vals.points, vals.distances);
            primaryScore += points;
            amenityDetails.push({ name: amenity, distance, points });
          } catch (error) {
            console.error(`[LIHTC] Primary amenity ${amenity} error:`, error);
            amenityDetails.push({ name: amenity, distance: null, points: 0 });
          }
        }

        // Search for secondary amenities
        for (const [amenity, vals] of Object.entries(SECONDARY_AMENITIES)) {
          try {
            const placeType = PLACES_TYPE_MAP[amenity] || amenity.toLowerCase().replace(/ /g, '_');
            const placesUrl = `https://maps.googleapis.com/maps/api/place/nearbysearch/json?location=${lat},${lng}&radius=6437&type=${placeType}&key=${googleApiKey}`;
            const placesRes = await fetch(placesUrl, { signal: AbortSignal.timeout(10000) });
            const placesData = await placesRes.json();
            
            let distance: number | null = null;
            if (placesData.status === 'OK' && placesData.results?.length > 0) {
              const place = placesData.results[0].geometry.location;
              distance = haversine(lng, lat, place.lng, place.lat);
            } else if (placesData.status && placesData.status !== 'ZERO_RESULTS') {
              console.warn(`[LIHTC] Places API ${placeType} status: ${placesData.status}`);
            }
            
            const points = scoreAmenity(distance, vals.points, vals.distances);
            secondaryScore += points;
            amenityDetails.push({ name: amenity, distance, points });
          } catch (error) {
            console.error(`[LIHTC] Secondary amenity ${amenity} error:`, error);
            amenityDetails.push({ name: amenity, distance: null, points: 0 });
          }
        }
      }

      // Neighborhood Character (10 pts) — hardcoded to 10 (Well Maintained) per team standard.
      // NC QAP 2026 §IV(A)(1)(b)(i) requires physical inspection; we default to full points.
      const neighborhoodCharacter = 10;

      // =========================================
      // SITE EVALUATION: Call government APIs (FEMA, EPA, USGS) + Google Transit
      // =========================================
      let siteEvaluation = null;
      let transitScore = 0;
      let autoDetectedIncompatibleUses = false;
      let autoDetectedNegativeFeatures = false;
      
      if (lat && lng) {
        try {
          const googleApiKey = process.env.VITE_GOOGLE_MAPS_API_KEY || process.env.GOOGLE_MAPS_API_KEY;
          siteEvaluation = await evaluateSite(lat, lng, googleApiKey, false);
          
          // Auto-detect from API results
          autoDetectedIncompatibleUses = siteEvaluation.incompatibleUses.hasIncompatibleUses || 
                                          siteEvaluation.hazardousSites.hasNearbyHazards;
          autoDetectedNegativeFeatures = siteEvaluation.floodZone.isInFloodZone || 
                                          siteEvaluation.slope.hasSteepSlope;
          transitScore = siteEvaluation.transit.transitScore;
        } catch (evalError) {
          console.error("Site evaluation error:", evalError);
        }
      }

      // Site Suitability (12 pts) - Use API results if available, otherwise user input
      let siteSuitability = 0;
      const hasIncompatibleUses = autoDetectedIncompatibleUses || incompatibleUses;
      const hasNegativeFeatures = autoDetectedNegativeFeatures || negativeSiteFeatures;
      
      if (!hasIncompatibleUses) siteSuitability += 3;
      if (!hasNegativeFeatures) siteSuitability += 3;
      siteSuitability += 3; // Assume visibility ok
      siteSuitability += 3; // Assume traffic safe

      // Negative points
      const negativePoints = hasNegativeFeatures ? -3 : 0;

      // Income targeting / RPP (2 pts)
      const totalUnits = (units30AMI || 0) + (units40AMI || 0) + (units50AMI || 0);
      let incomeRPP = 0;
      
      if (totalUnits > 0) {
        if (countyIncomeLevel === "High") {
          if (units30AMI / totalUnits >= 0.25) incomeRPP = 2;
          else if (units30AMI / totalUnits >= 0.15) incomeRPP = 1;
        } else if (countyIncomeLevel === "Moderate") {
          if (units40AMI / totalUnits >= 0.25) incomeRPP = 2;
          else if (units40AMI / totalUnits >= 0.15) incomeRPP = 1;
        } else {
          if (units50AMI / totalUnits >= 0.25) incomeRPP = 2;
          else if (units50AMI / totalUnits >= 0.15) incomeRPP = 1;
        }
      }

      // Total Score (now includes transit points)
      const totalScore = neighborhoodCharacter + primaryScore + secondaryScore + siteSuitability + transitScore + negativePoints + incomeRPP;

      // Build the response object
      const scoreResult = {
        neighborhoodCharacter,
        primaryAmenities: primaryScore,
        secondaryAmenities: secondaryScore,
        siteSuitability,
        transitPoints: transitScore,
        negativePoints,
        incomeRPP,
        totalScore,
        amenityDetails,
        geocodedAddress,
        coordinates: lat && lng ? { lat, lng } : null,
        censusData: {
          tract: censusTract,
          isQCT,
          medianIncome,
          povertyRate,
          county,
          state,
          city
        },
        marketInsights,
        similarDeals,
        siteEvaluation: siteEvaluation ? {
          floodZone: siteEvaluation.floodZone,
          hazardousSites: siteEvaluation.hazardousSites,
          slope: siteEvaluation.slope,
          transit: siteEvaluation.transit,
          incompatibleUses: siteEvaluation.incompatibleUses
        } : null
      };

      // Save the evaluation to database if dealId is provided
      const dealId = req.body.dealId;
      try {
        const evaluationData = {
          dealId: dealId || null,
          address: address,
          latitude: lat ? String(lat) : null,
          longitude: lng ? String(lng) : null,
          scoreTotal: totalScore,
          scoreNeighborhood: neighborhoodCharacter,
          scorePrimaryAmenities: primaryScore,
          scoreSecondaryAmenities: secondaryScore,
          scoreSiteSuitability: siteSuitability,
          scoreTransit: transitScore,
          scoreNegativePoints: negativePoints,
          scoreIncomeRPP: incomeRPP,
          amenityDetails: amenityDetails as any,
          floodZoneData: siteEvaluation?.floodZone || null,
          hazardsData: siteEvaluation?.hazardousSites || null,
          slopeData: siteEvaluation?.slope || null,
          transitData: siteEvaluation?.transit || null,
          incompatibleUsesData: siteEvaluation?.incompatibleUses || null,
          censusData: scoreResult.censusData as any,
          marketInsights: marketInsights || null,
          evaluatedAt: new Date(),
        };
        
        // If dealId provided, check for existing evaluation and update or create
        if (dealId) {
          const existing = await storage.getSiteEvaluationByDealId(dealId);
          if (existing) {
            await storage.updateSiteEvaluation(existing.id, evaluationData);
          } else {
            await storage.createSiteEvaluation(evaluationData);
          }
        } else {
          // Quick Score (no dealId) - still save for history
          await storage.createSiteEvaluation(evaluationData);
        }
      } catch (saveError) {
        console.error("Error saving site evaluation:", saveError);
        // Don't fail the request if save fails
      }

      res.json(scoreResult);

    } catch (error: any) {
      console.error("Affordable housing scoring error:", error);
      res.status(500).json({ error: error.message || "Failed to calculate score" });
    }
  });

  // ==========================================
  // SITE EVALUATION FETCH APIs
  // ==========================================
  
