  // Trigger a new site evaluation for a deal
  // Auto-detect LIHTC inputs from Census API (county income tier, neighborhood quality)
  app.get("/api/deals/:dealId/lihtc-auto-detect", isAuthenticated, async (req, res) => {
    try {
      const { dealId } = req.params;
      const deal = await storage.getDeal(dealId);
      if (!deal) return res.status(404).json({ error: "Deal not found" });

      const dealAny = deal as any;
      let lat = dealAny.latitude ? parseFloat(dealAny.latitude) : null;
      let lng = dealAny.longitude ? parseFloat(dealAny.longitude) : null;
      
      // Try to get county FIPS from existing censusTractFips field (format: SSCCC...)
      let stateFips: string | null = null;
      let countyFips: string | null = null;
      if (dealAny.censusTractFips && dealAny.censusTractFips.length >= 5) {
        stateFips = dealAny.censusTractFips.substring(0, 2);
        countyFips = dealAny.censusTractFips.substring(2, 5);
      }
      
      // If no FIPS from tract, use Census geocoder with coordinates
      if ((!stateFips || !countyFips) && lat && lng) {
        try {
          const geoUrl = `https://geocoding.geo.census.gov/geocoder/geographies/coordinates?x=${lng}&y=${lat}&benchmark=Public_AR_Current&vintage=Current_Current&layers=Counties&format=json`;
          const geoResp = await fetch(geoUrl, { signal: AbortSignal.timeout(8000) });
          const geoData = await geoResp.json();
          const county = geoData?.result?.geographies?.Counties?.[0];
          if (county) {
            stateFips = county.STATE;
            countyFips = county.COUNTY;
          }
        } catch (geoErr) {
          console.warn('[LIHTC-AUTO] Census geocoder failed:', geoErr);
        }
      }
      
      if (!stateFips || !countyFips) {
        return res.status(400).json({ error: "Could not determine county FIPS. Make sure the deal has been geocoded." });
      }
      
      // Fetch ACS 5-year county data: median household income + poverty
      const censusApiKey = process.env.CENSUS_API_KEY;
      const acsUrl = `https://api.census.gov/data/2022/acs/acs5?get=B19013_001E,B17001_002E,B17001_001E,NAME&for=county:${countyFips}&in=state:${stateFips}&key=${censusApiKey}`;
      
      let medianIncome: number | null = null;
      let povertyRate: number | null = null;
      let countyName = '';
      
      try {
        const acsResp = await fetch(acsUrl, { signal: AbortSignal.timeout(10000) });
        const acsData = await acsResp.json();
        if (Array.isArray(acsData) && acsData.length > 1) {
          // Row 0 is headers: [B19013_001E, B17001_002E, B17001_001E, NAME, state, county]
          // Row 1 is data
          const row = acsData[1];
          medianIncome = parseInt(row[0]) || null;
          const belowPoverty = parseInt(row[1]) || 0;
          const totalPop = parseInt(row[2]) || 1;
          povertyRate = totalPop > 0 ? Math.round((belowPoverty / totalPop) * 100 * 10) / 10 : null;
          countyName = row[3] || '';
        }
      } catch (acsErr) {
        console.warn('[LIHTC-AUTO] ACS API failed:', acsErr);
        return res.status(500).json({ error: "Census ACS API call failed. Check CENSUS_API_KEY." });
      }
      
      // Classify county income tier based on median household income
      // NC LIHTC QAP tiers (approximate based on HUD AMI thresholds)
      let countyIncomeTier: string | null = null;
      let incomeTierReason = '';
      if (medianIncome !== null) {
        if (medianIncome >= 70000) {
          countyIncomeTier = 'High';
          incomeTierReason = `County MHI ${medianIncome.toLocaleString()} ≥ $70,000 → High AMI county (targets 30% AMI for bonus pts)`;
        } else if (medianIncome >= 52000) {
          countyIncomeTier = 'Moderate';
          incomeTierReason = `County MHI ${medianIncome.toLocaleString()} $52k-$70k → Moderate AMI county (targets 40% AMI for bonus pts)`;
        } else {
          countyIncomeTier = 'Low';
          incomeTierReason = `County MHI ${medianIncome.toLocaleString()} < $52,000 → Low AMI county (targets 50% AMI for bonus pts)`;
        }
      }
      
      // Neighborhood quality: reference data only — poverty rate CANNOT auto-assign QAP points
      // QAP requires physical inspection of structures within 0.5 miles (analyst must assess)
      let neighborhoodReason = '';
      if (povertyRate !== null) {
        neighborhoodReason = `County poverty rate ${povertyRate}% (reference only — neighborhood score must reflect physical condition of structures within 0.5 miles, not poverty rate)`;
      }
      
      // Suggest AMI unit mix from deal's unit count
      const totalUnits = (dealAny.unitCount || dealAny.estimatedUnits || 0);
      let units30AMI = 0, units40AMI = 0, units50AMI = 0;
      if (totalUnits > 0 && countyIncomeTier) {
        const targetCount = Math.round(totalUnits * 0.25); // 25% at target AMI for max score
        if (countyIncomeTier === 'High') units30AMI = targetCount;
        else if (countyIncomeTier === 'Moderate') units40AMI = targetCount;
        else units50AMI = targetCount;
      }
      
      res.json({
        countyName,
        medianIncome,
        povertyRate,
        suggestions: {
          countyIncomeTier,
          incomeTierReason,
          neighborhoodQuality: null,
          neighborhoodReason,
          units30AMI: units30AMI || null,
          units40AMI: units40AMI || null,
          units50AMI: units50AMI || null,
          amiNote: totalUnits > 0
            ? `Suggested: 25% of ${totalUnits} units (${Math.round(totalUnits * 0.25)}) at target AMI tier for max score`
            : 'Enter deal unit count first to get AMI unit suggestions'
        }
      });
    } catch (error: any) {
      console.error('[LIHTC-AUTO] Error:', error);
      res.status(500).json({ error: error.message });
    }
  });

    // Save LIHTC analyst overrides (neighborhood quality, income tier, AMI units, amenity overrides, cost/unit, redevelopment)
  app.patch("/api/deals/:dealId/lihtc-overrides", isAuthenticated, async (req, res) => {
    try {
      const { dealId } = req.params;
      const { neighborhoodQuality, countyIncomeTier, units30AMI, units40AMI, units50AMI, amenityOverrides, costPerUnit, isRedevelopment, units1BR, isDHHSPriorityCounty, isSection1602Penalty, section1602Status, isAgencyDiscretionPenalty, isQDPrincipalEligible, isBondProject } = req.body;

      const updates: any = {};
      if (neighborhoodQuality !== undefined) updates.lihtcNeighborhoodQuality = neighborhoodQuality || null;
      if (countyIncomeTier !== undefined) updates.lihtcCountyIncomeTier = countyIncomeTier || null;
      if (units30AMI !== undefined) updates.lihtcUnits30AMI = units30AMI !== '' ? Number(units30AMI) : null;
      if (units40AMI !== undefined) updates.lihtcUnits40AMI = units40AMI !== '' ? Number(units40AMI) : null;
      if (units50AMI !== undefined) updates.lihtcUnits50AMI = units50AMI !== '' ? Number(units50AMI) : null;
      if (amenityOverrides !== undefined) updates.lihtcAmenityOverrides = amenityOverrides || null;
      if (costPerUnit !== undefined) updates.lihtcCostPerUnit = costPerUnit !== '' && costPerUnit !== null ? Number(costPerUnit) : null;
      if (isRedevelopment !== undefined) updates.lihtcIsRedevelopment = !!isRedevelopment;
      if (units1BR !== undefined) updates.lihtcUnits1BR = units1BR !== '' && units1BR !== null ? Number(units1BR) : null;
      if (isDHHSPriorityCounty !== undefined) updates.lihtcDHHSPriorityCounty = !!isDHHSPriorityCounty;
      // Section 1602: tri-state — 'yes'=penalty, 'unknown'=yellow flag, 'no'=no flag
      if (section1602Status !== undefined) {
        (updates as any).lihtcSection1602Status = section1602Status || null;
        updates.lihtcSection1602Penalty = section1602Status === 'yes';
      } else if (isSection1602Penalty !== undefined) {
        updates.lihtcSection1602Penalty = !!isSection1602Penalty;
      }
      if (isAgencyDiscretionPenalty !== undefined) updates.lihtcAgencyDiscretionPenalty = !!isAgencyDiscretionPenalty;
      if (isQDPrincipalEligible !== undefined) updates.lihtcQDPrincipalEligible = isQDPrincipalEligible === null ? null : !!isQDPrincipalEligible;
      if (isBondProject !== undefined) updates.lihtcIsBondProject = !!isBondProject;

      await storage.updateDeal(dealId, updates as any);
      res.json({ success: true });
    } catch (error: any) {
      console.error("Error saving LIHTC overrides:", error);
      res.status(500).json({ error: error.message });
    }
  });

    app.post("/api/site-evaluations/score-deal/:dealId", isAuthenticated, async (req, res) => {
    try {
      const { dealId } = req.params;
      const { forceRefresh } = req.body;

      // Get the deal
      const deal = await storage.getDealById(dealId);
      if (!deal) {
        return res.status(404).json({ error: "Deal not found" });
      }

      // Check if we already have a recent evaluation (within 24 hours)
      const existing = await storage.getSiteEvaluationByDealId(dealId);
      if (existing && !forceRefresh) {
        const hoursSinceEval = (Date.now() - new Date(existing.evaluatedAt!).getTime()) / (1000 * 60 * 60);
        if (hoursSinceEval < 24) {
          return res.json({ 
            cached: true, 
            evaluation: existing,
            message: "Using cached evaluation (less than 24 hours old)"
          });
        }
      }

      // Build the address from deal data
      const addressParts = [
        deal.address,
        deal.city,
        deal.state,
        deal.zip
      ].filter(Boolean);
      const fullAddress = addressParts.join(', ');

      if (!fullAddress) {
        return res.status(400).json({ error: "Deal has no address information" });
      }

      // Trigger the scoring endpoint internally
      const { evaluateSite } = await import('./siteEvaluationService.js');
      
      let lat = deal.latitude ? parseFloat(deal.latitude) : null;
      let lng = deal.longitude ? parseFloat(deal.longitude) : null;
      
      // If no coordinates, geocode the address
      if (!lat || !lng) {
        try {
          const geocodioApiKey = process.env.GEOCODIO_API_KEY;
          if (geocodioApiKey) {
            const geocodeUrl = `https://api.geocod.io/v1.7/geocode?q=${encodeURIComponent(fullAddress)}&api_key=${geocodioApiKey}`;
            const geocodeRes = await fetch(geocodeUrl);
            const geocodeData = await geocodeRes.json();
            if (geocodeData.results?.[0]) {
              lat = geocodeData.results[0].location.lat;
              lng = geocodeData.results[0].location.lng;
            }
          }
        } catch (e) {
          console.error("Geocoding error:", e);
        }
      }

      if (!lat || !lng) {
        return res.status(400).json({ error: "Could not geocode deal address" });
      }

      // Call site evaluation (FEMA, EPA, USGS, Google Transit)
      const googleApiKey = process.env.VITE_GOOGLE_MAPS_API_KEY || process.env.GOOGLE_MAPS_API_KEY;
      console.log(`🏗️ [LIHTC] Running full site evaluation for deal ${dealId} at ${fullAddress}`);
      const siteEvaluation = await evaluateSite(lat, lng, googleApiKey, false); // isSmallTown applied post-hoc below
      console.log(`✅ [LIHTC] Site eval: flood=${siteEvaluation.floodZone?.isInFloodZone}, hazards=${siteEvaluation.hazardousSites?.hasNearbyHazards}, slope=${siteEvaluation.slope?.hasSteepSlope}, transit=${siteEvaluation.transit?.transitScore}`);

      // NC 2026 QAP LIHTC SCORING
      let transitScore = siteEvaluation.transit?.transitScore ?? 0; // may be adjusted for small towns below
      const hasIncompatibleUses = siteEvaluation.incompatibleUses?.hasIncompatibleUses || siteEvaluation.hazardousSites?.hasNearbyHazards;
      const hasNegativeFeatures = siteEvaluation.floodZone?.isInFloodZone || siteEvaluation.slope?.hasSteepSlope;

      // Site suitability: up to 12pts (NC QAP 2026: 3pts each for 4 criteria)
      let siteSuitability = 0;
      if (!hasIncompatibleUses) siteSuitability += 3;   // No incompatible uses within half-mile
      if (!hasNegativeFeatures) siteSuitability += 3;   // No negative features (flood/slope/barriers)
      siteSuitability += 3;  // Visibility: assumed (within 500ft of residential/commercial)
      siteSuitability += 3;  // Traffic safety: assumed (controlled access)
      // Negative points start at 0 — flood/slope presence is handled by removing the +3 suitability check above
      // (hasNegativeFeatures → siteSuitability gets 0 pts for that check, not a separate -3 deduction)
      // The Agency discretion -3 is a manual analyst flag only (lihtcAgencyDiscretionPenalty), not auto-triggered
      let negativePoints = 0;

      // PDC Cost Check (QAP §IV(C)(1)): if construction cost per unit > $135,000 → -10 pts
      const lihtcCostPerUnit = (deal as any).lihtcCostPerUnit as number | null;
      const pdcThreshold = 135000; // Chart A standard threshold
      const pdcNegative = lihtcCostPerUnit !== null && lihtcCostPerUnit > pdcThreshold ? -10 : 0;
      negativePoints += pdcNegative;
      if (pdcNegative < 0) {
        console.log(`💸 [LIHTC] PDC negative points: ${pdcNegative} (cost per unit: ${lihtcCostPerUnit?.toLocaleString()} > ${pdcThreshold.toLocaleString()} threshold)`);
      }

      // Section 1602 Penalty: tri-state — 'yes' = -40 pts, 'unknown' = yellow flag (0 pts), 'no'/null = no flag
      const section1602Status = (deal as any).lihtcSection1602Status as string | null;
      const lihtcSection1602Penalty = section1602Status === 'yes' || (!section1602Status && !!(deal as any).lihtcSection1602Penalty);
      if (lihtcSection1602Penalty) {
        negativePoints -= 40;
        console.log(`⚠️ [LIHTC] Section 1602 noncompliance penalty: -40 pts`);
      } else if (section1602Status === 'unknown') {
        console.log(`⚠️ [LIHTC] Section 1602 status: UNKNOWN — yellow flag, no point deduction`);
      }

      // Agency Discretion Penalty: -3 pts — manual analyst flag only, not auto-triggered by flood zone
      const lihtcAgencyDiscretionPenalty = !!(deal as any).lihtcAgencyDiscretionPenalty;
      if (lihtcAgencyDiscretionPenalty) {
        negativePoints -= 3;
        console.log(`⚠️ [LIHTC] Agency discretion penalty: -3 pts`);
      }

      // AUTO-DETECT: Neighborhood Quality & County Income Tier from Census ACS 5-year
      // Uses manual analyst overrides if set, otherwise auto-detects from Census data
      let autoDetectedMHI: number | null = null;
      let autoDetectedPovertyRate: number | null = null;
      let autoDetectedCountyName = '';
      let autoStateFips: string | null = null;
      let autoCountyFips: string | null = null;

      // Step 1: Get county FIPS (from deal's censusTractFips or Census geocoder)
      const dealCensusFips = (deal as any).censusTractFips as string | null;
      if (dealCensusFips && dealCensusFips.length >= 5) {
        autoStateFips = dealCensusFips.substring(0, 2);
        autoCountyFips = dealCensusFips.substring(2, 5);
        console.log(`🔍 [LIHTC-AUTO] Got county FIPS from censusTractFips: ${autoStateFips}-${autoCountyFips}`);
      } else {
        try {
          const geoUrl = `https://geocoding.geo.census.gov/geocoder/geographies/coordinates?x=${lng}&y=${lat}&benchmark=Public_AR_Current&vintage=Current_Current&layers=Counties&format=json`;
          const geoResp = await fetch(geoUrl, { signal: AbortSignal.timeout(8000) });
          const geoData = await geoResp.json();
          const countyGeo = geoData?.result?.geographies?.Counties?.[0];
          if (countyGeo) {
            autoStateFips = countyGeo.STATE;
            autoCountyFips = countyGeo.COUNTY;
            console.log(`🔍 [LIHTC-AUTO] Got county FIPS from geocoder: ${autoStateFips}-${autoCountyFips}`);
          }
        } catch (geoErr) {
          console.warn('[LIHTC-AUTO] Census geocoder failed:', geoErr);
        }
      }

      // Step 2: Fetch ACS 5-year county data (median income + poverty rate)
      if (autoStateFips && autoCountyFips) {
        try {
          const censusKey = process.env.CENSUS_API_KEY;
          const acsUrl = `https://api.census.gov/data/2022/acs/acs5?get=B19013_001E,B17001_002E,B17001_001E,NAME&for=county:${autoCountyFips}&in=state:${autoStateFips}&key=${censusKey}`;
          const acsResp = await fetch(acsUrl, { signal: AbortSignal.timeout(10000) });
          const acsData = await acsResp.json();
          if (Array.isArray(acsData) && acsData.length > 1) {
            const row = acsData[1];
            autoDetectedMHI = parseInt(row[0]) || null;
            const belowPoverty = parseInt(row[1]) || 0;
            const totalForPoverty = parseInt(row[2]) || 1;
            autoDetectedPovertyRate = totalForPoverty > 0 ? Math.round((belowPoverty / totalForPoverty) * 1000) / 10 : null;
            autoDetectedCountyName = row[3] || '';
            console.log(`📊 [LIHTC-AUTO] ${autoDetectedCountyName}: MHI=${autoDetectedMHI?.toLocaleString()} poverty=${autoDetectedPovertyRate}%`);
          }
        } catch (acsErr) {
          console.warn('[LIHTC-AUTO] ACS API failed:', acsErr);
        }
      }

      // Step 3: Neighborhood Quality — manual analyst assessment ONLY
      // QAP requires physical inspection of structures within 0.5 miles — cannot be auto-scored from any API.
      // Poverty rate is fetched above as reference data only — it MUST NOT be used to auto-assign points.
      // REDEVELOPMENT EXCEPTION: QAP §IV(A)(1)(b)(i) — Redevelopment Projects auto-qualify as "Well Maintained" (10 pts)
      const isRedevelopment = !!(deal as any).lihtcIsRedevelopment;
      const manualNeighborhoodQuality = (deal as any).lihtcNeighborhoodQuality as string | null;
      if (isRedevelopment) {
        console.log('🏗️ [LIHTC-AUTO] Redevelopment Project → Neighborhood = Well Maintained (10pts per QAP exception)');
      }
      // No auto-fallback from poverty rate — redevelopment exception is the only auto path
      const effectiveNeighborhoodQuality = isRedevelopment ? 'Well Maintained' : manualNeighborhoodQuality;
      // Neighborhood score hardcoded to 10 (Well Maintained) per team standard.
      // NC QAP 2026 §IV(A)(1)(b)(i) requires physical inspection; we default to full points.
      const neighborhoodScore = 10;
      const neighborhoodIsManual = !!manualNeighborhoodQuality || isRedevelopment;
      console.log(`🏘️ [LIHTC-AUTO] Neighborhood: hardcoded to 10pts (Well Maintained per team standard)`);

      // Step 3b: Detect if property is in a Small Town (<10,000 pop) for wider amenity thresholds
      // Uses Census Geocoding API (Incorporated Places layer) → ACS 2023 5-Year population lookup
      // No API key required. Applies ONLY to affordable_lihtc product type.
      let isSmallTown = false;
      let municipalityInfo: { name: string; population: number | null; smallTown: boolean; bandNote: string } | null = null;
      const dealCity = ((deal as any).city || '').trim();
      const dealStreet = ((deal as any).address || '').trim();
      const muniCacheKey = dealCity.toLowerCase().trim();

      if (muniCacheKey && municipalityPopCache[muniCacheKey] !== undefined) {
        // Cache hit — reuse previous lookup result
        const cached = municipalityPopCache[muniCacheKey];
        isSmallTown = cached.smallTown;
        municipalityInfo = {
          name: dealCity,
          population: cached.population,
          smallTown: cached.smallTown,
          bandNote: cached.population === null
            ? 'Population data unavailable — standard distance bands applied. Verify municipality status manually.'
            : cached.smallTown
              ? `Small town classification applied (population: ${cached.population.toLocaleString()} per ACS 2023 5-Year Estimates)`
              : `Standard distance bands applied (population: ${cached.population.toLocaleString()} per ACS 2023 5-Year Estimates)`
        };
        console.log(`🏙️ [LIHTC] Municipality cache hit: "${muniCacheKey}" pop=${cached.population} smallTown=${cached.smallTown}`);
      } else if (dealStreet && dealCity) {
        try {
          // Step 1: Census Geocoding API — identify Incorporated Place GEOID
          const geoUrl = `https://geocoding.geo.census.gov/geocoder/geographies/address?street=${encodeURIComponent(dealStreet)}&city=${encodeURIComponent(dealCity)}&state=NC&benchmark=Public_AR_Current&vintage=Current_Current&layers=Incorporated+Places&format=json`;
          const geoResp = await fetch(geoUrl, { signal: AbortSignal.timeout(12000) });
          const geoData = await geoResp.json();

          const addressMatches = geoData?.result?.addressMatches || [];
          const incPlace = addressMatches[0]?.geographies?.['Incorporated Places']?.[0];

          if (incPlace) {
            const placeGEOID = incPlace.GEOID || '';
            const placeName = incPlace.NAME || dealCity;
            const placeFips = placeGEOID.slice(-5); // GEOID is 7 digits: 2 state + 5 place FIPS

            // Step 2: ACS 5-Year population for this exact incorporated place
            const acsUrl = `https://api.census.gov/data/2023/acs/acs5?get=NAME,B01003_001E&for=place:${placeFips}&in=state:37`;
            const acsResp = await fetch(acsUrl, { signal: AbortSignal.timeout(10000) });
            const acsData = await acsResp.json();

            if (Array.isArray(acsData) && acsData.length > 1) {
              const population = parseInt(acsData[1][1]) || 0;
              isSmallTown = population > 0 && population < 10000;
              municipalityPopCache[muniCacheKey] = { population, smallTown: isSmallTown };
              municipalityInfo = {
                name: placeName,
                population,
                smallTown: isSmallTown,
                bandNote: isSmallTown
                  ? `Small town classification applied (population: ${population.toLocaleString()} per ACS 2023 5-Year Estimates)`
                  : `Standard distance bands applied (population: ${population.toLocaleString()} per ACS 2023 5-Year Estimates)`
              };
              console.log(`🏙️ [LIHTC] Municipality "${placeName}" GEOID=${placeGEOID} pop=${population.toLocaleString()} → ${isSmallTown ? 'SMALL TOWN (wider thresholds)' : 'standard'}`);
            } else {
              // ACS returned no data for this place
              municipalityPopCache[muniCacheKey] = { population: null, smallTown: false };
              municipalityInfo = {
                name: placeName,
                population: null,
                smallTown: false,
                bandNote: 'Population data unavailable — standard distance bands applied. Verify municipality status manually.'
              };
              console.warn(`[LIHTC] ACS returned no data for place FIPS ${placeFips} — using standard bands`);
            }
          } else {
            // No incorporated place found — unincorporated address
            municipalityPopCache[muniCacheKey] = { population: null, smallTown: false };
            municipalityInfo = {
              name: dealCity,
              population: null,
              smallTown: false,
              bandNote: 'Address appears to be unincorporated — standard amenity distance bands applied. Verify small town status manually if needed.'
            };
            console.log(`🏙️ [LIHTC] "${dealCity}" appears unincorporated — standard distance bands applied`);
          }
        } catch (placeErr) {
          console.warn('[LIHTC] Municipality population lookup failed:', placeErr);
          municipalityPopCache[muniCacheKey] = { population: null, smallTown: false };
          municipalityInfo = {
            name: dealCity,
            population: null,
            smallTown: false,
            bandNote: 'Population data unavailable — standard distance bands applied. Verify municipality status manually.'
          };
        }
      }

      // QAP 2026 §IV(A)(1)(b)(ii): Transit threshold is ALWAYS 0.25 miles WALKING.
      // Small-town distance expansion applies ONLY to driving-distance amenities, NOT transit.
      // 6 pts = covered shelter; 2 pts = no shelter. Google Places can't detect shelter coverage,
      // so we conservatively score 2 pts — analyst can upgrade to 6 pts via manual override.
      if (siteEvaluation?.transit) {
        const nearestStop = siteEvaluation.transit.nearestStopDistance;
        if (nearestStop !== null && nearestStop <= 0.25) {
          transitScore = 2; // conservative uncovered; analyst override → 6 pts if sheltered
        } else {
          transitScore = 0;
        }
        console.log(`🚌 [LIHTC] Transit: nearest=${nearestStop?.toFixed(2) ?? 'none'} mi → ${transitScore}pts (0.25mi walking QAP threshold; +4pts if covered shelter)`);
      }

      // ============================================================
      // PRIMARY & SECONDARY AMENITIES: NC QAP 2026 (Section II(B)(2)(b)(ii))
      // Distances are DRIVING miles via Google Maps Distance Matrix API
      // Primary max: 26pts | Secondary max: 20pts | Total amenities: 46pts
      // ============================================================

      // Helper: get DRIVING distance in miles using Google Distance Matrix API
      const getDrivingDistance = async (destLat: number, destLng: number): Promise<number|null> => {
        try {
          const url = `https://maps.googleapis.com/maps/api/distancematrix/json?origins=${lat},${lng}&destinations=${destLat},${destLng}&mode=driving&units=imperial&key=${googleApiKey}`;
          const r = await fetch(url, { signal: AbortSignal.timeout(8000) });
          const d = await r.json();
          if (d.status === 'OK' && d.rows?.[0]?.elements?.[0]?.status === 'OK') {
            return d.rows[0].elements[0].distance.value / 1609.344; // meters → miles
          }
        } catch {}
        return null;
      };

      // Helper: find nearest place of given type, optionally filtered by QAP whitelist
      // whitelist = array of lowercase name fragments; ALL results are checked until a match is found
      const findNearestDriving = async (placeType: string, radiusMeters = 10000, keyword?: string, whitelist?: string[], blacklistKeywords?: string[]): Promise<{ name: string; address: string; drivingMiles: number|null; lat?: number; lng?: number }|null> => {
        try {
          // Use rankby=distance (no radius param) so Google returns results sorted by straight-line distance.
          // This ensures we evaluate the nearest stores first rather than the most prominent/highly-rated.
          let url = `https://maps.googleapis.com/maps/api/place/nearbysearch/json?location=${lat},${lng}&rankby=distance&type=${placeType}&key=${googleApiKey}`;
          if (keyword) url += `&keyword=${encodeURIComponent(keyword)}`;
          const r = await fetch(url, { signal: AbortSignal.timeout(10000) });
          const d = await r.json();
          if (d.status === 'OK' && d.results?.length > 0) {
            // Known gas station / petroleum brands that Google misclassifies as grocery_or_supermarket
            const GAS_STATION_NAMES = ['bp','shell','exxon','mobil','chevron','sunoco','marathon','citgo','valero','speedway','casey','wawa','kwik','circle k','pilot','loves','7-eleven','7eleven','kangaroo','sheetz'];
            let pool = d.results;
            // When searching grocery type, filter out gas stations (they have gas_station in their types array
            // or their name matches a known petroleum brand)
            if (placeType === 'grocery_or_supermarket') {
              pool = pool.filter((pl: any) => {
                const plTypes: string[] = pl.types || [];
                const hasGasType = plTypes.includes('gas_station') || plTypes.includes('petroleum');
                const nameLower = pl.name.toLowerCase();
                const isKnownGas = GAS_STATION_NAMES.some(g => nameLower === g || nameLower.startsWith(g + ' '));
                return !hasGasType && !isKnownGas;
              });
            }
            // Apply caller-supplied blacklist — excludes places whose name contains any blacklisted keyword
            if (blacklistKeywords && blacklistKeywords.length > 0) {
              pool = pool.filter((pl: any) => {
                const nameLower = pl.name.toLowerCase();
                return !blacklistKeywords.some(kw => nameLower.includes(kw.toLowerCase()));
              });
            }
            const candidates = whitelist
              ? pool.filter((pl: any) => whitelist.some(w => pl.name.toLowerCase().includes(w)))
              : pool;
            // When a whitelist is provided and nothing matches, return null — never score a non-QAP-approved store
            if (candidates.length === 0) return null;
            // Candidates are now sorted by straight-line distance (rankby=distance).
            // Try up to 5 nearest candidates for driving distance — pick the closest by driving miles.
            const top5 = candidates.slice(0, 5);
            const results = await Promise.all(top5.map(async (pl: any) => {
              const p = pl.geometry.location;
              const drivingMiles = await getDrivingDistance(p.lat, p.lng);
              return { name: pl.name, address: pl.vicinity || '', drivingMiles, lat: p.lat as number, lng: p.lng as number };
            }));
            const best = results
              .filter(x => x.drivingMiles !== null)
              .sort((a, b) => (a.drivingMiles ?? 999) - (b.drivingMiles ?? 999))[0] ?? results[0];
            return best;
          }
        } catch {}
        return null;
      };

      // QAP scoring helper: score a distance against the threshold table
      const scoreQAP = (miles: number|null, pts: number[], thresholds: number[]) => {
        if (miles === null) return 0;
        for (let i = 0; i < thresholds.length; i++) if (miles <= thresholds[i]) return pts[i];
        return 0;
      };

      // NC QAP 2026 official store whitelists (Section IV(A)(1)(b)(ii))
      const QAP_GROCERY_LIST = ["aldi","bestway","bi-lo","compare foods","earth fare","family foods","food lion","food matters","fresh market","galaxy food","harris teeter","hopey","iga","ingle","just $ave","lidl","lowes foods","piggly wiggly","publix","red & white","sav-mor","save-a-lot","sprouts","super target","trader joe","walmart","weaver street","wegmans","whole foods","fairvalue","bo's food"];
      const QAP_SHOPPING_LIST = ["big lots","dollar general","dgx","dg market","dollar tree","family dollar","fred's super dollar","maxway","ollie's","ollie's bargain outlet","roses","roses express","target","super target","walmart"];
      // Pharmacy: any with non-medical general merchandise (CVS, Walgreens, Rite Aid qualify; specialty/hospital pharmacies don't)
      const QAP_PHARMACY_LIST = ["cvs","walgreens","rite aid","walmart","sam's club","costco","kroger","harris teeter pharmacy","publix pharmacy","food lion pharmacy"];

      // Read analyst amenity overrides from the deal (set via override panel in LIHTC modal)
      const amenityOverrides: Record<string, {name:string;distance:number}|null> = (deal as any).lihtcAmenityOverrides || {};
      const isManualOverride = (key: string) => !!amenityOverrides[key];

      let primaryAmenities = 0, secondaryAmenities = 0;
      const amenityDetailsSD: { name: string; category: string; placeName?: string; distance: number|null; points: number; isManual?: boolean; placeLat?: number; placeLng?: number }[] = [];

      if (googleApiKey) {
        // ---- PRIMARY AMENITIES (max 26 pts) ----
        // NC QAP 2026: Standard thresholds ≤2, ≤2.5, ≤3, ≤4 miles driving
        // Small Town (<10,000 pop) thresholds: ≤3.5, ≤4, ≤4.5, ≤5.5 miles driving
        const STD = isSmallTown ? [3.5, 4, 4.5, 5.5] : [2, 2.5, 3, 4];
        // Secondary amenities use tighter thresholds — no points beyond 3.0mi (standard) or 4.5mi (small town)
        // Standard: ≤2.0=3pts, ≤2.5=2pts, ≤3.0=1pt, >3.0=0pts
        // Small Town: ≤3.5=3pts, ≤4.0=2pts, ≤4.5=1pt, >4.5=0pts
        const STD_SEC = isSmallTown ? [3.5, 4.0, 4.5] : [2.0, 2.5, 3.0];
        // Search radius: wider for small towns to catch stores near the 5.5-mile scoring edge (~18km driving ≈ 11 miles)
        const radiusM = isSmallTown ? 18000 : 14000;
        console.log(`📏 [LIHTC] Using ${isSmallTown ? 'Small Town' : 'Standard'} distance thresholds: primary=${STD.join(',')}mi secondary=${STD_SEC.join(',')}mi | search radius: ${radiusM}m`);

        // Grocery: QAP-approved chains only
        const groceryOverride = amenityOverrides['grocery'];
        const groceryData = groceryOverride ? groceryOverride : await findNearestDriving('grocery_or_supermarket', radiusM, undefined, QAP_GROCERY_LIST);
        const groceryDist = groceryOverride ? groceryOverride.distance : (groceryData as any)?.drivingMiles ?? null;
        const groceryName = groceryOverride ? groceryOverride.name : (groceryData as any)?.name;
        const groceryPts = scoreQAP(groceryDist, [12, 10, 8, 6], STD);
        primaryAmenities += groceryPts;
        amenityDetailsSD.push({ name: 'Grocery', category: 'primary', placeName: groceryName, distance: groceryDist, points: groceryPts, isManual: isManualOverride('grocery'), placeLat: (groceryData as any)?.lat, placeLng: (groceryData as any)?.lng });

        // Shopping: QAP-approved chains only.
        // Google Places classifies stores differently depending on format:
        // - 'department_store': Target, Walmart, Big Lots
        // - 'convenience_store': Dollar General, Dollar Tree, Family Dollar (standard format)
        // - 'grocery_or_supermarket': Dollar General Market / DG Market (grocery-format DG stores)
        // We must search ALL three types and take the nearest by driving distance.
        const shoppingOverride = amenityOverrides['shopping'];
        let shoppingData: any = null;
        if (shoppingOverride) {
          shoppingData = shoppingOverride;
        } else {
          const [deptResult, convResult, grocShopResult] = await Promise.all([
            findNearestDriving('department_store', 14000, undefined, QAP_SHOPPING_LIST),
            findNearestDriving('convenience_store', 14000, undefined, QAP_SHOPPING_LIST),
            // Catches 'Dollar General Market', 'DG Market' — the grocery-format DG stores
            findNearestDriving('grocery_or_supermarket', 14000, undefined, QAP_SHOPPING_LIST),
          ]);
          const shopCandidates = [deptResult, convResult, grocShopResult]
            .filter(Boolean) as { name: string; address: string; drivingMiles: number|null }[];
          shoppingData = shopCandidates.sort((a, b) => (a.drivingMiles ?? 999) - (b.drivingMiles ?? 999))[0] ?? null;
        }
        const shoppingDist = shoppingOverride ? shoppingOverride.distance : (shoppingData as any)?.drivingMiles ?? null;
        const shoppingName = shoppingOverride ? shoppingOverride.name : (shoppingData as any)?.name;
        const shoppingPts = scoreQAP(shoppingDist, [7, 6, 5, 4], STD);
        primaryAmenities += shoppingPts;
        amenityDetailsSD.push({ name: 'Shopping', category: 'primary', placeName: shoppingName, distance: shoppingDist, points: shoppingPts, isManual: isManualOverride('shopping'), placeLat: (shoppingData as any)?.lat, placeLng: (shoppingData as any)?.lng });

        // Pharmacy: must have non-medical general merchandise (not hospital/specialty)
        const pharmacyOverride = amenityOverrides['pharmacy'];
        // QAP: pharmacy = any licensed pharmacist + non-medical general merchandise (not hospital/specialty/compounding-only)
        // Blacklist: veterinary clinics, animal hospitals, COVID testing sites, specialty/compounding-only pharmacies
        const PHARMACY_BLACKLIST = [
          'animal hospital','veterinary','vet clinic','animal clinic','pet hospital','animal health','animal care','animal medical',
          'covid','drive-thru test','drive thru test','testing site','testing center','testing at','covid-19',
          'specialty pharmacy','compounding pharmacy','infusion pharmacy','oncology pharmacy','nuclear pharmacy',
        ];
        const pharmacyData = pharmacyOverride ? pharmacyOverride : await findNearestDriving('pharmacy', radiusM, undefined, undefined, PHARMACY_BLACKLIST);
        const pharmacyDist = pharmacyOverride ? pharmacyOverride.distance : (pharmacyData as any)?.drivingMiles ?? null;
        const pharmacyName = pharmacyOverride ? pharmacyOverride.name : (pharmacyData as any)?.name;
        const pharmacyPts = scoreQAP(pharmacyDist, [7, 6, 5, 4], STD);
        primaryAmenities += pharmacyPts;
        amenityDetailsSD.push({ name: 'Pharmacy', category: 'primary', placeName: pharmacyName, distance: pharmacyDist, points: pharmacyPts, isManual: isManualOverride('pharmacy'), placeLat: (pharmacyData as any)?.lat, placeLng: (pharmacyData as any)?.lng, needsVerification: !isManualOverride('pharmacy') });

        primaryAmenities = Math.min(primaryAmenities, 26); // cap at 26

        // ---- SECONDARY AMENITIES (max 20 pts) ----
        // Track which primary types were already used so "Other Primary" is genuinely different
        const usedPrimaryNames = new Set([groceryName, shoppingName, pharmacyName].filter(Boolean));

        // Other Primary Amenity: a SECOND QAP-approved grocery, shopping, or pharmacy not already used
        let otherPrimaryDist: number|null = null;
        let otherPrimaryName = '';
        let bestOtherPrimary: any = null;
        const otherPrimaryOverride = amenityOverrides['otherPrimary'];
        if (otherPrimaryOverride) {
          otherPrimaryDist = otherPrimaryOverride.distance;
          otherPrimaryName = otherPrimaryOverride.name;
        } else {
          try {
            // Use findNearestDriving (rankby=distance) to get the nearest QAP-approved store
            // not already used as a primary amenity. Also check shopping type for DG Market / Target etc.
            const altGroceryList = QAP_GROCERY_LIST.filter(s => !Array.from(usedPrimaryNames).some(n => n.toLowerCase().includes(s)));
            const altShoppingList = QAP_SHOPPING_LIST.filter(s => !Array.from(usedPrimaryNames).some(n => n.toLowerCase().includes(s)));
            const altPharmacyList = QAP_PHARMACY_LIST.filter(s => !Array.from(usedPrimaryNames).some(n => n.toLowerCase().includes(s)));
            // Blacklist stale/non-qualifying Google Places entries for Other Primary search
            const OTHER_PRIMARY_BLACKLIST = ['covid','drive-thru test','drive thru test','testing site','testing center','testing at','covid-19','specialty pharmacy','compounding','animal hospital','veterinary'];
            const [g2, sh2, ph2] = await Promise.all([
              altGroceryList.length > 0 ? findNearestDriving('grocery_or_supermarket', 14000, undefined, altGroceryList) : null,
              altShoppingList.length > 0 ? findNearestDriving('department_store', 14000, undefined, altShoppingList) : null,
              altPharmacyList.length > 0 ? findNearestDriving('pharmacy', 14000, undefined, altPharmacyList, OTHER_PRIMARY_BLACKLIST) : null,
            ]);
            // Also search convenience_store and grocery for shopping-format DG stores
            const sh2b = altShoppingList.length > 0 ? await findNearestDriving('convenience_store', 14000, undefined, altShoppingList) : null;
            const sh2c = altShoppingList.length > 0 ? await findNearestDriving('grocery_or_supermarket', 14000, undefined, altShoppingList) : null;
            // Deduplicate: exclude candidates whose brand name overlaps with an already-counted primary
            // (e.g. "Publix Pharmacy" when "Publix Super Market" is already the primary grocery)
            const primaryBrandWords = new Set(
              Array.from(usedPrimaryNames)
                .flatMap(n => n.toLowerCase().split(/\s+/).filter(w => w.length >= 5))
            );
            const otherPrimaryCandidates = [g2, sh2, sh2b, sh2c, ph2]
              .filter(Boolean)
              .filter(c => !usedPrimaryNames.has(c!.name))
              .filter(c => !c!.name.toLowerCase().split(/\s+/).some(w => w.length >= 5 && primaryBrandWords.has(w))) as { name: string; address: string; drivingMiles: number|null }[];
            bestOtherPrimary = otherPrimaryCandidates
              .sort((a, b) => (a.drivingMiles ?? 999) - (b.drivingMiles ?? 999))[0] ?? null;
            if (bestOtherPrimary) {
              otherPrimaryDist = bestOtherPrimary.drivingMiles;
              otherPrimaryName = bestOtherPrimary.name;
            }
          } catch {}
        }
        // Other Primary Amenity is a SECONDARY category — uses secondary thresholds (3.0 mi max), not primary (4.0 mi max)
        const otherPrimaryPts = scoreQAP(otherPrimaryDist, [5, 4, 3], STD_SEC);
        secondaryAmenities += otherPrimaryPts;
        amenityDetailsSD.push({ name: 'Other Primary Amenity', category: 'secondary', placeName: otherPrimaryName || undefined, distance: otherPrimaryDist, points: otherPrimaryPts, isManual: isManualOverride('otherPrimary'), placeLat: (bestOtherPrimary as any)?.lat, placeLng: (bestOtherPrimary as any)?.lng });

        // Service: restaurant, bank/credit union, gas station with convenience store
        // NC QAP requires a permanent hard-stand establishment — food trucks/carts/trailers do NOT qualify
        const FOOD_TRUCK_EXCLUSIONS = ['truck', 'cart', 'trailer', 'mobile food', 'food stand', 'pop-up', 'pop up', 'food bus', 'rolling', 'on wheels'];
        const serviceOverride = amenityOverrides['service'];
        let serviceDist: number|null = null, servicePlace: any = null;
        if (serviceOverride) {
          serviceDist = serviceOverride.distance;
          servicePlace = { name: serviceOverride.name };
        } else {
          const restaurant = await findNearestDriving('restaurant', 14000, undefined, undefined, FOOD_TRUCK_EXCLUSIONS);
          const bank = await findNearestDriving('bank', 14000);
          const gasStation = await findNearestDriving('gas_station', 14000);
          serviceDist = [restaurant?.drivingMiles, bank?.drivingMiles, gasStation?.drivingMiles]
            .filter((d): d is number => d !== null && d !== undefined)
            .sort((a, b) => a - b)[0] ?? null;
          servicePlace = [restaurant, bank, gasStation].filter(Boolean).sort((a, b) => (a!.drivingMiles ?? 999) - (b!.drivingMiles ?? 999))[0];
        }
        const servicePts = scoreQAP(serviceDist, [3, 2, 1], STD_SEC);
        secondaryAmenities += servicePts;
        amenityDetailsSD.push({ name: 'Service', category: 'secondary', placeName: servicePlace?.name, distance: serviceDist, points: servicePts, isManual: isManualOverride('service'), placeLat: servicePlace?.lat, placeLng: servicePlace?.lng });

        // Healthcare: hospital, urgent care, general/family practice, general dentist
        const healthcareOverride = amenityOverrides['healthcare'];
        let healthDist: number|null = null, healthPlace: any = null;
        if (healthcareOverride) {
          healthDist = healthcareOverride.distance;
          healthPlace = { name: healthcareOverride.name };
        } else {
          // QAP healthcare = hospital, urgent care, physician, dentist, optometrist, physical therapy
          // Excludes: plasma/blood donation centers, testing sites, veterinary, cosmetic-only
          const HEALTHCARE_BLACKLIST = [
            'plasma','donation center','blood donation','plasma center','grifols','biomat','talecris','octapharma','csl plasma','kedplasma',
            'covid','testing site','testing center','drive-thru test','drive thru test',
            'veterinary','animal hospital','vet clinic','animal clinic',
            'spa','salon','massage','tattoo','cosmetic surgery','botox','med spa',
          ];
          const hospital = await findNearestDriving('hospital', 14000, undefined, undefined, HEALTHCARE_BLACKLIST);
          const doctor = await findNearestDriving('doctor', 14000, undefined, undefined, HEALTHCARE_BLACKLIST);
          healthDist = [hospital?.drivingMiles, doctor?.drivingMiles]
            .filter((d): d is number => d !== null && d !== undefined)
            .sort((a, b) => a - b)[0] ?? null;
          healthPlace = [hospital, doctor].filter(Boolean).sort((a, b) => (a!.drivingMiles ?? 999) - (b!.drivingMiles ?? 999))[0];
        }
        const healthPts = scoreQAP(healthDist, [3, 2, 1], STD_SEC);
        secondaryAmenities += healthPts;
        amenityDetailsSD.push({ name: 'Healthcare', category: 'secondary', placeName: healthPlace?.name, distance: healthDist, points: healthPts, isManual: isManualOverride('healthcare'), placeLat: healthPlace?.lat, placeLng: healthPlace?.lng });

        // Public Facility: local gov park with playground/trails, library (5+ days), senior/rec center
        // NC QAP: funeral homes, mortuaries, and similar establishments do NOT count as public facilities
        // QAP public facility = park w/ playground/trails, library, senior/rec center, gov building, post office
        // Excludes: funeral homes, dog clubs/parks, cemeteries/memorial parks, private clubs, golf courses
        const FUNERAL_HOME_EXCLUSIONS = [
          'funeral','mortuary','cremation','crematorium','memorial chapel','mortician','funeral home','funeral parlor',
          'dog club','dog park','dog run','canine club','kennel','pet park',
          'cemetery','memorial park','memorial gardens','burial','mausoleum',
          'country club','golf club','yacht club','hunt club','polo club',
          'animal shelter','animal control',
        ];
        const publicFacilityOverride = amenityOverrides['publicFacility'];
        let pubFacilityDist: number|null = null, pubFacilityPlace: any = null;
        if (publicFacilityOverride) {
          pubFacilityDist = publicFacilityOverride.distance;
          pubFacilityPlace = { name: publicFacilityOverride.name };
        } else {
          const park = await findNearestDriving('park', 14000, undefined, undefined, FUNERAL_HOME_EXCLUSIONS);
          const library = await findNearestDriving('library', 14000, undefined, undefined, FUNERAL_HOME_EXCLUSIONS);
          const communityCenter = await findNearestDriving('community_center', 14000, 'senior center recreation center', undefined, FUNERAL_HOME_EXCLUSIONS);
          pubFacilityDist = [park?.drivingMiles, library?.drivingMiles, communityCenter?.drivingMiles]
            .filter((d): d is number => d !== null && d !== undefined)
            .sort((a, b) => a - b)[0] ?? null;
          pubFacilityPlace = [park, library, communityCenter].filter(Boolean).sort((a, b) => (a!.drivingMiles ?? 999) - (b!.drivingMiles ?? 999))[0];
        }
        const pubFacilityPts = scoreQAP(pubFacilityDist, [3, 2, 1], STD_SEC);
        secondaryAmenities += pubFacilityPts;
        amenityDetailsSD.push({ name: 'Public Facility', category: 'secondary', placeName: pubFacilityPlace?.name, distance: pubFacilityDist, points: pubFacilityPts, isManual: isManualOverride('publicFacility'), placeLat: pubFacilityPlace?.lat, placeLng: pubFacilityPlace?.lng });

        // Public School: non-alternative elementary, middle, high school (charter/magnet OK)
        const publicSchoolOverride = amenityOverrides['publicSchool'];
        let schoolDist: number|null = null, schoolName: string|undefined;
        let schoolPlace: { name: string; address: string; drivingMiles: number|null; lat?: number; lng?: number }|null = null;
        if (publicSchoolOverride) {
          schoolDist = publicSchoolOverride.distance;
          schoolName = publicSchoolOverride.name;
        } else {
          // QAP requires K-12 school (elementary/middle/high, charter OK). Daycares/preschools don't qualify.
          // QAP = K-12 school (elementary/middle/high, public charter/magnet OK)
          // Excludes: daycares, preschools, colleges/universities, adult/continuing ed, trade schools, corporate
          const SCHOOL_BLACKLIST = [
            'daycare','day care','preschool','pre-school','pre k','prek','childcare','child care',
            'early childhood','early learning','nursery','infant','toddler',
            'university','college','community college','institute','lifelong learning',
            'adult education','adult ed','continuing education','workforce','vocational','trade school',
            'children\'s academy','kids academy','learning center',
          ];
          schoolPlace = await findNearestDriving('school', 14000, undefined, undefined, SCHOOL_BLACKLIST);
          schoolDist = schoolPlace?.drivingMiles ?? null;
          schoolName = schoolPlace?.name;
        }
        const schoolPts = scoreQAP(schoolDist, [3, 2, 1], STD_SEC);
        secondaryAmenities += schoolPts;
        amenityDetailsSD.push({ name: 'Public School', category: 'secondary', placeName: schoolName, distance: schoolDist, points: schoolPts, isManual: isManualOverride('publicSchool'), placeLat: schoolPlace?.lat, placeLng: schoolPlace?.lng });

        // Other Retail: QAP §IV(A)(1)(a)(iv) — any Grocery or Shopping NOT already used as Primary
        // or Other Primary Amenity; also includes any grocery or general merchandise establishment.
        // This is a THIRD tier: excludes both Primary AND Other Primary store names.
        const otherRetailOverride = amenityOverrides['otherRetail'];
        let otherRetailDist: number|null = null, otherRetailPlace: any = null;
        if (otherRetailOverride) {
          otherRetailDist = otherRetailOverride.distance;
          otherRetailPlace = { name: otherRetailOverride.name };
        } else {
          // Exclude stores already counted as Primary or Other Primary Amenity
          const excludedRetailNames = new Set(
            [groceryName, shoppingName, pharmacyName, otherPrimaryName]
              .filter(Boolean)
              .map(n => n!.toLowerCase())
          );
          const groceryExclude = groceryName?.toLowerCase() || '';
          const shoppingExclude = shoppingName?.toLowerCase() || '';
          const altGroceryList = QAP_GROCERY_LIST.filter(s => !groceryExclude.includes(s));
          const altShoppingList = QAP_SHOPPING_LIST.filter(s => !shoppingExclude.includes(s));
          // Search 1: QAP-approved chains not already counted
          const qapGrocery = altGroceryList.length > 0
            ? await findNearestDriving('grocery_or_supermarket', radiusM, undefined, altGroceryList)
            : null;
          let qapShopping = altShoppingList.length > 0
            ? await findNearestDriving('department_store', radiusM, undefined, altShoppingList)
            : null;
          if (!qapShopping && altShoppingList.length > 0) {
            qapShopping = await findNearestDriving('convenience_store', radiusM, undefined, altShoppingList);
          }
          // Search 2: Any grocery or general merchandise per QAP broad 'Other Retail' definition.
          // Catches local grocers, co-ops, variety stores not on the QAP approved chains list.
          const anyGrocery = await findNearestDriving('grocery_or_supermarket', radiusM);
          const candidates2 = [qapGrocery, qapShopping, anyGrocery]
            .filter(Boolean)
            .filter(c => !excludedRetailNames.has(c!.name.toLowerCase())) as { name: string; address: string; drivingMiles: number|null }[];
          const best2 = candidates2.sort((a, b) => (a.drivingMiles ?? 999) - (b.drivingMiles ?? 999))[0] ?? null;
          otherRetailDist = best2?.drivingMiles ?? null;
          otherRetailPlace = best2;
        }
        const otherRetailPts = scoreQAP(otherRetailDist, [3, 2, 1], STD_SEC);
        secondaryAmenities += otherRetailPts;
        amenityDetailsSD.push({ name: 'Other Retail', category: 'secondary', placeName: otherRetailPlace?.name, distance: otherRetailDist, points: otherRetailPts, isManual: isManualOverride('otherRetail'), placeLat: otherRetailPlace?.lat, placeLng: otherRetailPlace?.lng });

        secondaryAmenities = Math.min(secondaryAmenities, 20); // cap at 20
        console.log(`🏪 [LIHTC] Amenities (driving dist): primary=${primaryAmenities}/26 secondary=${secondaryAmenities}/20`);
        amenityDetailsSD.forEach(a => console.log(`  → ${a.name}: ${a.placeName || 'not found'} ${a.distance !== null ? a.distance.toFixed(2)+'mi' : 'N/A'} = ${a.points}pts`));
      }

      // Step 4: Auto-classify County Income Tier using OFFICIAL NC QAP 2026 county designations
      // Source: NC Housing Finance Agency 2026 QAP, Section II(F)(2) - NOT derived from Census MHI
      const QAP_HIGH_COUNTIES = new Set([
        'brunswick','johnston','buncombe','lincoln','cabarrus','madison','mecklenburg','moore',
        'chatham','new hanover','currituck','orange','dare','pender','durham','union',
        'franklin','wake','gaston','watauga','henderson','iredell'
      ]);
      const QAP_MODERATE_COUNTIES = new Set([
        'alamance','alexander','avery','macon','beaufort','mitchell','burke','nash',
        'caldwell','onslow','camden','pamlico','carteret','pasquotank','caswell','perquimans',
        'catawba','person','clay','pitt','craven','polk','cumberland','randolph',
        'davidson','rockingham','davie','rowan','edgecombe','stanly','forsyth','stokes',
        'gates','swain','granville','transylvania','guilford','wilson','harnett','yadkin',
        'haywood','yancey','hoke','jackson'
      ]);
      // Low = all remaining NC counties not in High or Moderate (34 counties total)
      const manualIncomeTier = (deal as any).lihtcCountyIncomeTier as string | null;
      let autoIncomeTier: string | null = null;
      if (autoDetectedCountyName) {
        const countyRaw = autoDetectedCountyName.split(',')[0].replace(/ county$/i,'').trim().toLowerCase();
        if (QAP_HIGH_COUNTIES.has(countyRaw)) autoIncomeTier = 'High';
        else if (QAP_MODERATE_COUNTIES.has(countyRaw)) autoIncomeTier = 'Moderate';
        else autoIncomeTier = 'Low';
        console.log(`💰 [LIHTC-AUTO] County "${countyRaw}" → QAP 2026 tier: ${autoIncomeTier} (Census MHI=${autoDetectedMHI?.toLocaleString()} for reference)`);
      } else if (autoDetectedMHI !== null) {
        // Fallback only if county name not resolved
        if (autoDetectedMHI >= 70000) autoIncomeTier = 'High';
        else if (autoDetectedMHI >= 52000) autoIncomeTier = 'Moderate';
        else autoIncomeTier = 'Low';
        console.log(`💰 [LIHTC-AUTO] Income tier from Census MHI fallback: ${autoIncomeTier}`);
      }
      const effectiveIncomeTier = manualIncomeTier || autoIncomeTier;
      console.log(`💰 [LIHTC-AUTO] Effective: ${manualIncomeTier ? 'MANUAL OVERRIDE' : 'QAP auto'}=${effectiveIncomeTier}`);

      // Step 5: AMI unit targeting — use manual values if set, otherwise auto-suggest 25% at target tier
      const manualUnits30AMI = (deal as any).lihtcUnits30AMI as number | null;
      const manualUnits40AMI = (deal as any).lihtcUnits40AMI as number | null;
      const manualUnits50AMI = (deal as any).lihtcUnits50AMI as number | null;
      const hasManualAMI = manualUnits30AMI != null || manualUnits40AMI != null || manualUnits50AMI != null;
      
      let effectiveUnits30AMI = manualUnits30AMI || 0;
      let effectiveUnits40AMI = manualUnits40AMI || 0;
      let effectiveUnits50AMI = manualUnits50AMI || 0;
      
      if (!hasManualAMI && effectiveIncomeTier) {
        const totalUnits = (deal as any).unitCount || (deal as any).estimatedUnits || 0;
        if (totalUnits > 0) {
          const targetCount = Math.round(totalUnits * 0.25);
          if (effectiveIncomeTier === 'High') effectiveUnits30AMI = targetCount;
          else if (effectiveIncomeTier === 'Moderate') effectiveUnits40AMI = targetCount;
          else effectiveUnits50AMI = targetCount;
          console.log(`🏠 [LIHTC-AUTO] AMI units auto-suggested: 25% of ${totalUnits} = ${targetCount} at ${effectiveIncomeTier} tier`);
        }
      }

      // Calculate Income/RPP score
      const totalAMIUnits = effectiveUnits30AMI + effectiveUnits40AMI + effectiveUnits50AMI;
      let incomeRPP = 0;
      if (totalAMIUnits > 0 && effectiveIncomeTier) {
        if (effectiveIncomeTier === 'High') {
          if (effectiveUnits30AMI / totalAMIUnits >= 0.25) incomeRPP = 2;
          else if (effectiveUnits30AMI / totalAMIUnits >= 0.15) incomeRPP = 1;
        } else if (effectiveIncomeTier === 'Moderate') {
          if (effectiveUnits40AMI / totalAMIUnits >= 0.25) incomeRPP = 2;
          else if (effectiveUnits40AMI / totalAMIUnits >= 0.15) incomeRPP = 1;
        } else {
          if (effectiveUnits50AMI / totalAMIUnits >= 0.25) incomeRPP = 2;
          else if (effectiveUnits50AMI / totalAMIUnits >= 0.15) incomeRPP = 1;
        }
      } else {
        incomeRPP = 0; // No AMI units specified → no RPP points (analyst must enter unit targeting)
      }
      
      // Save auto-detected values back to deal if they weren't manually set (so edit panel shows what was used)
      const detectedUpdates: any = {};
      if (!manualNeighborhoodQuality && effectiveNeighborhoodQuality) detectedUpdates.lihtcNeighborhoodQuality = effectiveNeighborhoodQuality;
      if (!manualIncomeTier && effectiveIncomeTier) detectedUpdates.lihtcCountyIncomeTier = effectiveIncomeTier;
      if (!hasManualAMI && effectiveUnits30AMI) detectedUpdates.lihtcUnits30AMI = effectiveUnits30AMI;
      if (!hasManualAMI && effectiveUnits40AMI) detectedUpdates.lihtcUnits40AMI = effectiveUnits40AMI;
      if (!hasManualAMI && effectiveUnits50AMI) detectedUpdates.lihtcUnits50AMI = effectiveUnits50AMI;
      if (Object.keys(detectedUpdates).length > 0) {
        try { await storage.updateDeal(dealId, detectedUpdates as any); } catch {}
      }

      // DHHS Priority County auto-detection (QAP §IV(F)(5)) — used for Olmstead +1 pt
      const DHHS_PRIORITY_COUNTIES = new Set([
        'alamance','buncombe','burke','cabarrus','cumberland','durham','forsyth','gaston',
        'guilford','henderson','iredell','mecklenburg','new hanover','orange','pitt',
        'robeson','wake','wayne','wilson'
      ]);
      const manualDHHS = (deal as any).lihtcDHHSPriorityCounty as boolean | null;
      let effectiveDHHS = !!manualDHHS;
      if (manualDHHS == null || manualDHHS === false) {
        // Auto-detect: only override if not manually set to false
        if (autoDetectedCountyName) {
          const rawCounty = autoDetectedCountyName.split(',')[0].replace(/ county$/i,'').trim().toLowerCase();
          effectiveDHHS = DHHS_PRIORITY_COUNTIES.has(rawCounty);
          if (effectiveDHHS && !manualDHHS) {
            // Save auto-detected value back so it shows in the UI
            try { await storage.updateDeal(dealId, { lihtcDHHSPriorityCounty: true } as any); } catch {}
          }
        }
      }
      console.log(`🏥 [LIHTC] DHHS priority county: ${effectiveDHHS ? 'YES (+1pt)' : 'no'} (county: ${autoDetectedCountyName || 'unknown'}, manual=${manualDHHS})`);

      // Olmstead Score (QAP §IV(F)(5)): 1BR units as % of total — max 4 pts
      const lihtcUnits1BR = (deal as any).lihtcUnits1BR as number | null;
      const totalDealUnits = (deal as any).unitCount || (deal as any).estimatedUnits || 0;
      let olmsteadScore = 0;
      if (lihtcUnits1BR !== null && lihtcUnits1BR >= 0 && totalDealUnits > 0) {
        const pct1BR = lihtcUnits1BR / totalDealUnits;
        if (pct1BR >= 0.15) olmsteadScore = 3;
        else if (pct1BR >= 0.10) olmsteadScore = 2;
        else if (pct1BR >= 0.075) olmsteadScore = 1;
        if (effectiveDHHS) olmsteadScore = Math.min(olmsteadScore + 1, 4);
      }
      console.log(`🏡 [LIHTC] Olmstead: ${lihtcUnits1BR ?? 'n/a'}/${totalDealUnits} units 1BR (${totalDealUnits > 0 && lihtcUnits1BR !== null ? ((lihtcUnits1BR / totalDealUnits) * 100).toFixed(1) : '?'}%) DHHS=${effectiveDHHS} → ${olmsteadScore}pts`);

      const totalScore = neighborhoodScore + primaryAmenities + secondaryAmenities + transitScore + siteSuitability + incomeRPP + olmsteadScore + negativePoints;
      console.log(`📊 [LIHTC] TOTAL=${totalScore} (neighborhood=${neighborhoodScore} primary=${primaryAmenities} secondary=${secondaryAmenities} transit=${transitScore} site=${siteSuitability} income=${incomeRPP} olmstead=${olmsteadScore} neg=${negativePoints})`);

      // Save evaluation with all sub-score columns now available in schema
      const evaluationData: any = {
        dealId,
        address: fullAddress,
        latitude: String(lat),
        longitude: String(lng),
        scoreNeighborhood: neighborhoodScore,
        scorePrimaryAmenities: primaryAmenities,
        scoreSecondaryAmenities: secondaryAmenities,
        scoreSiteSuitability: siteSuitability,
        scoreTransit: transitScore,
        scoreNegativePoints: negativePoints,
        scoreIncomeRPP: incomeRPP,
        scoreOlmstead: olmsteadScore,
        scoreTotal: totalScore,
        floodZoneData: siteEvaluation.floodZone ?? null,
        hazardsData: siteEvaluation.hazardousSites ?? null,
        slopeData: siteEvaluation.slope ?? null,
        transitData: siteEvaluation.transit ?? null,
        incompatibleUsesData: siteEvaluation.incompatibleUses ?? null,
        amenityDetails: amenityDetailsSD as any,
        censusData: null,
        marketInsights: municipalityInfo ? { municipalityInfo } : null,
        evaluatedAt: new Date(),
      };

      let savedEval;
      if (existing) {
        savedEval = await storage.updateSiteEvaluation(existing.id, evaluationData);
      } else {
        savedEval = await storage.createSiteEvaluation(evaluationData);
      }

      // Sync score → deals table so LIHTC column in pipeline shows the number
      try {
        await storage.updateDeal(dealId, { lihtcScoreTotal: totalScore, lihtcScorePreliminary: true, lihtcScoredAt: new Date() } as any);
        console.log(`✅ [LIHTC] Synced lihtcScoreTotal=${totalScore} to deal ${dealId}`);
      } catch (syncErr: any) {
        console.warn(`⚠️ [LIHTC] Could not sync score to deal: ${syncErr.message}`);
      }

      res.json({ 
        cached: false, 
        evaluation: savedEval,
        message: "Site evaluation completed"
      });
    } catch (error: any) {
      console.error("Error scoring deal:", error);
      res.status(500).json({ error: error.message });
    }
  });

  // Real Estate Market Metrics for Launchpad - Uses FREE NY Fed API (no key required)
  app.get('/api/market-metrics', async (req, res) => {
    try {
      const metrics: any = {
        lastUpdated: new Date().toISOString(),
        rates: []
      };

      // Use NY Fed Markets API (FREE, no key required) for SOFR and Fed Funds
      // Use Treasury Fiscal Data API (FREE, no key required) for Treasury rates
      try {
        const fredApiKey = process.env.FRED_API_KEY;
        console.log(`[FRED-DEBUG] API key present: ${fredApiKey ? 'YES' : 'NO'}`);
        
        const [sofrRes, fedFundsRes, treasuryRes] = await Promise.allSettled([
          fetch('https://markets.newyorkfed.org/api/rates/secured/sofr/last/1.json', { signal: AbortSignal.timeout(5000) }),
          fetch('https://markets.newyorkfed.org/api/rates/unsecured/effr/last/1.json', { signal: AbortSignal.timeout(5000) }),
          fredApiKey ? fetch(`https://api.stlouisfed.org/fred/series/observations?series_id=DGS10&api_key=${fredApiKey}&file_type=json&limit=1&sort_order=desc`, { signal: AbortSignal.timeout(5000) }) : Promise.resolve(null)
        ]);

        console.log(`[FRED-DEBUG] Treasury fetch status: ${treasuryRes.status}`);
        if (treasuryRes.status === 'rejected') {
          console.error(`[FRED-DEBUG] Treasury fetch rejected:`, treasuryRes.reason);
        }

        // Parse 10-Year Treasury from FRED
        if (treasuryRes.status === 'fulfilled' && treasuryRes.value) {
          try {
            const response = treasuryRes.value as Response;
            console.log(`[FRED-DEBUG] Treasury response ok: ${response.ok}, status: ${response.status}`);
            const data = await response.json();
            console.log(`[FRED-DEBUG] Treasury data:`, JSON.stringify(data).substring(0, 200));
            if (data.observations?.[0]) {
              const val = data.observations[0].value;
              console.log(`[FRED-DEBUG] 10-Year Treasury value: ${val}, date: ${data.observations[0].date}`);
              metrics.rates.push({
                name: '10-Year Treasury',
                value: val !== '.' ? parseFloat(val) : null,
                date: data.observations[0].date,
                unit: '%',
                link: 'https://fred.stlouisfed.org/series/DGS10',
                source: 'FRED (Daily)'
              });
            } else if (data.error_message) {
              console.error(`[FRED-DEBUG] FRED API error: ${data.error_message}`);
            }
          } catch (e) {
            console.error(`[FRED-DEBUG] Treasury parse error:`, e);
          }
        }

        // Parse SOFR from NY Fed
        if (sofrRes.status === 'fulfilled' && sofrRes.value.ok) {
          try {
            const data = await sofrRes.value.json();
            if (data?.refRates?.[0]) {
              metrics.rates.push({
                name: 'SOFR',
                value: parseFloat(data.refRates[0].percentRate) || null,
                date: data.refRates[0].effectiveDate,
                unit: '%',
                link: 'https://www.newyorkfed.org/markets/reference-rates/sofr',
                source: 'NY Fed (Daily)'
              });
            }
          } catch (e) {
            console.warn('[MARKET-METRICS] SOFR parse error:', e);
          }
        }

        // Parse Fed Funds (EFFR) from NY Fed
        if (fedFundsRes.status === 'fulfilled' && fedFundsRes.value.ok) {
          try {
            const data = await fedFundsRes.value.json();
            if (data?.refRates?.[0]) {
              metrics.rates.push({
                name: 'Fed Funds Rate',
                value: parseFloat(data.refRates[0].percentRate) || null,
                date: data.refRates[0].effectiveDate,
                unit: '%',
                link: 'https://www.newyorkfed.org/markets/reference-rates/effr',
                source: 'NY Fed (Daily)'
              });
            }
          } catch (e) {
            console.warn('[MARKET-METRICS] Fed Funds parse error:', e);
          }
        }

        // Try FRED for 30-Year Mortgage (weekly data)
        if (fredApiKey) {
          try {
            console.log(`[FRED-DEBUG] Fetching 30-Year Mortgage rate...`);
            const mortgageRes = await fetch(`https://api.stlouisfed.org/fred/series/observations?series_id=MORTGAGE30US&api_key=${fredApiKey}&file_type=json&limit=1&sort_order=desc`, { signal: AbortSignal.timeout(5000) });
            console.log(`[FRED-DEBUG] Mortgage response ok: ${mortgageRes.ok}, status: ${mortgageRes.status}`);
            if (mortgageRes.ok) {
              const data = await mortgageRes.json();
              console.log(`[FRED-DEBUG] Mortgage data:`, JSON.stringify(data).substring(0, 200));
              if (data.observations?.[0]) {
                const val = data.observations[0].value;
                console.log(`[FRED-DEBUG] 30-Year Mortgage value: ${val}, date: ${data.observations[0].date}`);
                metrics.rates.push({
                  name: '30-Year Mortgage',
                  value: val !== '.' ? parseFloat(val) : null,
                  date: data.observations[0].date,
                  unit: '%',
                  link: 'https://fred.stlouisfed.org/series/MORTGAGE30US',
                  source: 'Freddie Mac (Weekly)'
                });
              }
            }
          } catch (e) {
            console.warn('[MARKET-METRICS] FRED mortgage error:', e);
          }
        }
      } catch (fetchError) {
        console.warn('[MARKET-METRICS] Fetch error:', fetchError);
      }

      // Fill in any missing rates with links
      const rateNames = ['10-Year Treasury', 'SOFR', 'Fed Funds Rate', '30-Year Mortgage'];
      const existingNames = metrics.rates.map((r: any) => r.name);
      for (const name of rateNames) {
        if (!existingNames.includes(name)) {
          const links: any = {
            '10-Year Treasury': 'https://fred.stlouisfed.org/series/DGS10',
            'SOFR': 'https://www.newyorkfed.org/markets/reference-rates/sofr',
            'Fed Funds Rate': 'https://www.newyorkfed.org/markets/reference-rates/effr',
            '30-Year Mortgage': 'https://fred.stlouisfed.org/series/MORTGAGE30US'
          };
          metrics.rates.push({ name, value: null, date: null, unit: '%', status: 'unavailable', link: links[name], source: 'Click for live data' });
        }
      }

      // Sort rates in preferred order
      const order = ['10-Year Treasury', 'SOFR', 'Fed Funds Rate', '30-Year Mortgage'];
      metrics.rates.sort((a: any, b: any) => order.indexOf(a.name) - order.indexOf(b.name));

      res.json(metrics);
    } catch (error: any) {
      console.error('Error fetching market metrics:', error);
      res.status(500).json({ error: 'Failed to fetch market metrics' });
    }
  });

  // MSA (Metropolitan Statistical Area) Routes
  const { msaRouter } = await import('./msaRoutes.js');
  app.use('/api/msa', msaRouter);

  // Seed Data Routes (SUPER_ADMIN only - for bulk importing rejection reasons & MSAs)
  const { seedRouter } = await import('./seedDataRoutes.js');
  app.use('/api/seed', seedRouter);

  // API Safety Guard Routes (SUPER_ADMIN only - for API cost protection)
  const apiSafetyRouter = await import('./apiSafetyRoutes.js');
  app.use('/api/safety', apiSafetyRouter.default);

  // ========================================
  // FRONTEND ERROR LOGGING ENDPOINT
  // Must be BEFORE the /api/* catch-all below
  // ========================================
  // ─── Underwriting Excel Generator ──────────────────────────────────────────
  app.post("/api/underwriting/generate-excel", isAuthenticated, async (req: any, res) => {
    try {
      const XLSX = require('xlsx');
      const path = require('path');

      const {
        templateType,
        propertyName, address, cityState, zip, market, county,
        totalUnits, unitMix,
        landCost,
        // Hard cost inputs (derived from preset)
        constructionCostPSF,  // cost per rentable SF (apartment templates only)
        siteworkPU,           // sitework per unit
      } = req.body;

      const TEMPLATE_MAP: Record<string, string> = {
        '3story-conventional':  'attached_assets/3-Story_Apartment_Template_1773172858262.xlsx',
        '3story-attainable':    'attached_assets/3-Story_Apartment_Attainable_Template_1773172855916.xlsx',
        '4story-conventional':  'attached_assets/4-Story_Apartment_Template_1773172861507.xlsx',
        '4story-active-adult':  'attached_assets/4-Story_Active-Adult_Apartment_Template_1773172859780.xlsx',
        '3story-active-adult':  'attached_assets/3-Story_Active-Adult_Apartment_Template_(1)_1773242355813.xlsx',
        'aa-cottages':          'attached_assets/AA_Cottage_Development_Template_1773242388015.xlsx',
        'btr':                  'attached_assets/BTR_Development_Template_1773172900169.xlsx',
        'sfr':                  'attached_assets/SFR_Development_Template_1773172889682.xlsx',
      };

      // Per-template cell config (verified against actual template cell inspection)
      const TEMPLATE_CONFIG: Record<string, {
        unitMixTotalUnitsCell: string;
        pctCol: string; sfCol: string; rentCol: string;
        mixRows: number[];
        constructionPSFCell: string | null;  // F67 or F69 depending on template
        siteworkPUCell: string | null;       // E70 or E72 depending on template
        landPUCell: string;                  // always E8 (raw input per unit)
        isBTRSFR: boolean;
      }> = {
        '3story-conventional': {
          unitMixTotalUnitsCell: 'D4', pctCol: 'E', sfCol: 'F', rentCol: 'G',
          mixRows: [7, 8, 9, 10, 11],
          constructionPSFCell: 'F67', siteworkPUCell: 'E70',
          landPUCell: 'E8', isBTRSFR: false,
        },
        '3story-attainable': {
          unitMixTotalUnitsCell: 'D4', pctCol: 'E', sfCol: 'F', rentCol: 'G',
          mixRows: [7, 8, 9, 10, 11],
          constructionPSFCell: 'F67', siteworkPUCell: 'E70',
          landPUCell: 'E8', isBTRSFR: false,
        },
        '4story-conventional': {
          unitMixTotalUnitsCell: 'D4', pctCol: 'E', sfCol: 'F', rentCol: 'G',
          mixRows: [7, 8, 9, 10, 11],
          constructionPSFCell: 'F67', siteworkPUCell: 'E70',
          landPUCell: 'E8', isBTRSFR: false,
        },
        '4story-active-adult': {
          unitMixTotalUnitsCell: 'D4', pctCol: 'E', sfCol: 'F', rentCol: 'G',
          mixRows: [7, 8, 9, 10, 11],
          // 4-Story AA Budget rows are shifted by 2 (hard costs at row 69, sitework at 72)
          constructionPSFCell: 'F69', siteworkPUCell: 'E72',
          landPUCell: 'E8', isBTRSFR: false,
        },
        '3story-active-adult': {
          // Same cell layout as 4-Story AA (D4 units, E/F/G mix cols, F69 PSF, E72 sitework)
          // but uses the 3-Story AA file (PSF=160, DUA=25 vs PSF=180, DUA=35 for 4-story)
          unitMixTotalUnitsCell: 'D4', pctCol: 'E', sfCol: 'F', rentCol: 'G',
          mixRows: [7, 8, 9, 10, 11],
          constructionPSFCell: 'F69', siteworkPUCell: 'E72',
          landPUCell: 'E8', isBTRSFR: false,
        },
        'aa-cottages': {
          // AA Cottages uses G4 total units (not D4), H/I/J columns (not E/F/G),
          // and F67/E70 for construction costs (Budget rows NOT shifted like 4-story AA)
          unitMixTotalUnitsCell: 'G4', pctCol: 'H', sfCol: 'I', rentCol: 'J',
          mixRows: [7, 8, 9, 10, 11],
          constructionPSFCell: 'F67', siteworkPUCell: 'E70',
          landPUCell: 'E8', isBTRSFR: false,
        },
        'btr': {
          // BTR uses different columns: G4=total units, H=pct, I=SF, J=rent
          unitMixTotalUnitsCell: 'G4', pctCol: 'H', sfCol: 'I', rentCol: 'J',
          mixRows: [7, 8, 9, 10, 11],
          // BTR construction cost is formula-driven from a cost schedule (O67-O69) — skip
          constructionPSFCell: null, siteworkPUCell: null,
          landPUCell: 'E8', isBTRSFR: true,
        },
        'sfr': {
          // SFR uses same column layout as BTR
          unitMixTotalUnitsCell: 'G4', pctCol: 'H', sfCol: 'I', rentCol: 'J',
          mixRows: [7, 8, 9, 10, 11],
          constructionPSFCell: null, siteworkPUCell: null,
          landPUCell: 'E8', isBTRSFR: true,
        },
      };

      const templatePath = TEMPLATE_MAP[templateType];
      const config = TEMPLATE_CONFIG[templateType];
      if (!templatePath || !config) {
        return res.status(400).json({ error: 'Unknown template type' });
      }

      const wb = XLSX.readFile(path.resolve(templatePath));

      // Helper: set a raw cell value, removing any formula
      function setCell(sheetName: string, ref: string, value: any) {
        const ws = wb.Sheets[sheetName];
        if (!ws) return;
        if (!ws[ref]) ws[ref] = {};
        ws[ref].v = value;
        ws[ref].t = typeof value === 'number' ? 'n' : 's';
        delete ws[ref].f;
      }

      // ── Global sheet ──
      if (propertyName) setCell('Global', 'C7', propertyName);
      if (market)       setCell('Global', 'C9', market);
      if (address)      setCell('Global', 'C11', address);
      if (cityState)    setCell('Global', 'C12', cityState);
      if (zip)          setCell('Global', 'C13', zip);
      if (county)       setCell('Global', 'C14', county);

      // ── Unit Mix sheet ──
      if (totalUnits) setCell('Unit Mix_vm', config.unitMixTotalUnitsCell, Number(totalUnits));

      if (unitMix && Array.isArray(unitMix)) {
        unitMix.forEach((row: any, i: number) => {
          const r = config.mixRows[i];
          if (!r) return;
          setCell('Unit Mix_vm', `${config.pctCol}${r}`, Number(row.pct) || 0);
          setCell('Unit Mix_vm', `${config.sfCol}${r}`, Number(row.avgSF) || 0);
          setCell('Unit Mix_vm', `${config.rentCol}${r}`, Number(row.monthlyRent) || 0);
        });
      }

      // ── Budget sheet: land cost (per unit) ──
      if (landCost && totalUnits && Number(totalUnits) > 0) {
        const landPerUnit = Math.round(Number(landCost) / Number(totalUnits));
        setCell('Budget_vm', config.landPUCell, landPerUnit);
      }

      // ── Budget sheet: construction cost per SF (apartment templates only) ──
      if (config.constructionPSFCell && constructionCostPSF && Number(constructionCostPSF) > 0) {
        setCell('Budget_vm', config.constructionPSFCell, Math.round(Number(constructionCostPSF) * 100) / 100);
      }

      // ── Budget sheet: sitework per unit ──
      if (config.siteworkPUCell && siteworkPU !== undefined) {
        setCell('Budget_vm', config.siteworkPUCell, Number(siteworkPU) || 0);
      }

      const buffer = XLSX.write(wb, { type: 'buffer', bookType: 'xlsx' });

      const safeName = (propertyName || 'Underwriting').replace(/[^a-zA-Z0-9\s-]/g, '').trim().replace(/\s+/g, '_');
      res.setHeader('Content-Disposition', `attachment; filename="${safeName}_Underwriting.xlsx"`);
      res.setHeader('Content-Type', 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet');
      res.send(buffer);
    } catch (err: any) {
      console.error('Excel generation error:', err);
      res.status(500).json({ error: 'Failed to generate Excel file', details: err.message });
    }
  });

