      if (url !== undefined) updates.url = url;
      if (enabled !== undefined) updates.enabled = enabled;
      if (minAcres !== undefined) updates.minAcres = minAcres ? String(minAcres) : null;
      if (targetStates !== undefined) updates.targetStates = targetStates;
      if (pollIntervalHours !== undefined) updates.pollIntervalHours = pollIntervalHours;
      const [updated] = await db.update(rssFeedSources).set(updates).where(eq(rssFeedSources.id, req.params.id)).returning();
      res.json(updated);
